INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38145, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公園", "is_correct": true, "explanation": "見出し語「こうえん」で、これが正解です。"}, {"text": "公営", "is_correct": false, "explanation": "「こうえい」は最後の一拍が「い」で、別の語です。"}, {"text": "公益", "is_correct": false, "explanation": "「こうえき」は最後の一拍が「き」で、別の語です。"}, {"text": "貢献", "is_correct": false, "explanation": "「こうけん」は三拍目が「け」で、別の語です。"}, {"text": "好天", "is_correct": false, "explanation": "「こうてん」は三拍目が「て」で、別の語です。"}], "explanations": {"公園": "見出し語「こうえん」で、これが正解です。", "公営": "「こうえい」は最後の一拍が「い」で、別の語です。", "公益": "「こうえき」は最後の一拍が「き」で、別の語です。", "貢献": "「こうけん」は三拍目が「け」で、別の語です。", "好天": "「こうてん」は三拍目が「て」で、別の語です。"}, "sentence_index": null, "correct_answer": "公園"}, "level_3": {"options": [{"text": "公園", "is_correct": true, "explanation": "少年がレモネードを売る場所として、文意に合います。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「入り方」とは意味が合わない。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、入り方がある場所を表さず意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、入り方がある場所を表さず意味が合わない。"}], "explanations": {"公園": "少年がレモネードを売る場所として、文意に合います。", "季節": "形は合うが、「入り方」とは意味が合わない。", "気温": "形は合うが、入り方がある場所を表さず意味が合わない。", "天気": "形は合うが、入り方がある場所を表さず意味が合わない。"}, "sentence_index": 0, "correct_answer": "公園"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園を食べて、お腹がいっぱいになりました。", "explanation": "公園は場所であり、食べるものではないので誤用です。"}, {"text": "私は公園に乗って学校へ行きます。", "explanation": "公園は乗り物ではないので、「乗る」と合わず誤用です。"}, {"text": "公園を引き出しにしまいました。", "explanation": "公園は大きな場所なので、引き出しにしまうことはできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38145, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公園", "is_correct": true, "explanation": "見出し語「こうえん」で、これが正解です。"}, {"text": "校閲", "is_correct": false, "explanation": "「こうえつ」は最後の一拍が「つ」で、別の語です。"}, {"text": "交換", "is_correct": false, "explanation": "「こうかん」は三拍目が「か」で、別の語です。"}, {"text": "降参", "is_correct": false, "explanation": "「こうさん」は三拍目が「さ」で、別の語です。"}, {"text": "光線", "is_correct": false, "explanation": "「こうせん」は三拍目が「せ」で、別の語です。"}], "explanations": {"公園": "見出し語「こうえん」で、これが正解です。", "校閲": "「こうえつ」は最後の一拍が「つ」で、別の語です。", "交換": "「こうかん」は三拍目が「か」で、別の語です。", "降参": "「こうさん」は三拍目が「さ」で、別の語です。", "光線": "「こうせん」は三拍目が「せ」で、別の語です。"}, "sentence_index": null, "correct_answer": "公園"}, "level_3": {"options": [{"text": "公園", "is_correct": true, "explanation": "散歩に行く場所として、文意に合います。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、散歩に行く先として意味が合わない。"}, {"text": "意見", "is_correct": false, "explanation": "形は合うが、散歩に行く先として意味が合わない。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが、散歩に行く先として意味が合わない。"}], "explanations": {"公園": "散歩に行く場所として、文意に合います。", "時間": "形は合うが、散歩に行く先として意味が合わない。", "意見": "形は合うが、散歩に行く先として意味が合わない。", "昨日": "形は合うが、散歩に行く先として意味が合わない。"}, "sentence_index": 6, "correct_answer": "公園"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、公園を飲みました。", "explanation": "公園は場所であり、飲むものではないので誤用です。"}, {"text": "公園は五人で歌いました。", "explanation": "公園は歌う主体にならないので誤用です。"}, {"text": "公園をかばんに入れて持ってきました。", "explanation": "公園は大きな場所なので、かばんに入れて運ぶことはできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38145, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼ごはんを公園を食べた。", "corrected_sentence": "昼ごはんを公園で食べた。", "error_description": "場所を示す助詞は「を」ではなく「で」が正しいです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38145, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園に本を読んでいます。", "corrected_sentence": "公園で本を読んでいます。", "error_description": "動作の場所を示す助詞は「に」ではなく「で」が正しいです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5a30e95-140b-4f0b-af5e-4d35b664424c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38146, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「家の前」の形で、家に付く連体修飾の「の」。場所を示す。"}, {"text": "が", "is_correct": false, "explanation": "「家が前の道」では主語を示すことになり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "場所や方向を示すが、「家に前の道」では文の関係が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示すが、「家で前の道」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「家の前」の形で、家に付く連体修飾の「の」。場所を示す。", "が": "「家が前の道」では主語を示すことになり、意味が通らない。", "に": "場所や方向を示すが、「家に前の道」では文の関係が成り立たない。", "で": "手段や場所を示すが、「家で前の道」では意味が通らない。"}, "error_tags": {"が": "主語", "に": "場所", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38146, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「家は、今はもう取り壊されている」の形で、家を話題にする文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「家へ取り壊されている」では意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、取り壊される対象との比較にならず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示すが、「家と取り壊されている」では意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「家は、今はもう取り壊されている」の形で、家を話題にする文になる。", "へ": "方向を示すが、「家へ取り壊されている」では意味が通らない。", "より": "比較を示すが、取り壊される対象との比較にならず、文が成り立たない。", "と": "並列を示すが、「家と取り壊されている」では意味が通らない。"}, "error_tags": {"へ": "方向", "より": "比較", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38146, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が住むための建物。", "primary_collocate": null, "pronunciation": "いえ", "ipa": "ie", "syllable_count": 2, "sentences": [{"text": "駅から歩いて五分のところに、白い壁の家がある。", "target_word": "家", "complexity_tier": "T3", "furigana": "駅[えき]から歩[ある]いて五分[ごふん]のところに、白[しろ]い壁[かべ]の家[いえ]がある。", "sentence_source": "generated"}, {"text": "母は毎朝、家の前の道をきれいに掃いている。", "target_word": "家", "complexity_tier": "T3", "furigana": "母[はは]は毎朝[まいあさ]、家[いえ]の前[まえ]の道[みち]をきれいに掃[は]いている。", "sentence_source": "generated"}, {"text": "兄は結婚して、公園の隣に新しい家を建てた。", "target_word": "家", "complexity_tier": "T3", "furigana": "兄[あに]は結婚[けっこん]して、公園[こうえん]の隣[となり]に新[あたら]しい家[いえ]を建[た]てた。", "sentence_source": "generated"}, {"text": "木でできた家は、夏でも風が通って涼しい。", "target_word": "家", "complexity_tier": "T3", "furigana": "木[き]でできた家[いえ]は、夏[なつ]でも風[かぜ]が通[とお]って涼[すず]しい。", "sentence_source": "generated"}, {"text": "引っ越しの日、家の鍵を不動産会社に返した。", "target_word": "家", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]、家[いえ]の鍵[かぎ]を不動産会社[ふどうさんがいしゃ]に返[かえ]した。", "sentence_source": "generated"}, {"text": "地震が起きても倒れないように、丈夫な家を作る必要がある。", "target_word": "家", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きても倒[たお]れないように、丈夫[じょうぶ]な家[いえ]を作[つく]る必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "川のそばの家は、大雨のときに水が入りやすい。", "target_word": "家", "complexity_tier": "T3", "furigana": "川[かわ]のそばの家[いえ]は、大雨[おおあめ]のときに水[みず]が入[はい]りやすい。", "sentence_source": "generated"}, {"text": "私が子どものころ住んでいた家は、今はもう取り壊されている。", "target_word": "家", "complexity_tier": "T3", "furigana": "私[わたし]が子[こ]どものころ住[す]んでいた家[いえ]は、今[いま]はもう取[と]り壊[こわ]されている。", "sentence_source": "generated"}, {"text": "庭に桜の木がある家を探しているが、なかなか見つからない。", "target_word": "家", "complexity_tier": "T3", "furigana": "庭[にわ]に桜[さくら]の木[き]がある家[いえ]を探[さが]しているが、なかなか見[み]つからない。", "sentence_source": "generated"}, {"text": "雪が積もって、家の屋根が白くなった。", "target_word": "家", "complexity_tier": "T3", "furigana": "雪[ゆき]が積[つ]もって、家[いえ]の屋根[やね]が白[しろ]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "人が住むための建物そのもの。建てる・買う・探す対象としての家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7012c6de-6897-46e9-9295-f4be4ed38c8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38146, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家", "is_correct": true, "explanation": "白い壁の建物として存在する家を表し、「駅から歩いて五分」とも自然につながる。"}, {"text": "空", "is_correct": false, "explanation": "白い壁を持つ空はなく、建物の説明としては不自然。"}, {"text": "音", "is_correct": false, "explanation": "白い壁の音がある、という文は意味が通らない。"}, {"text": "雨", "is_correct": false, "explanation": "白い壁の雨がある、という文は成り立たない。"}], "explanations": {"家": "白い壁の建物として存在する家を表し、「駅から歩いて五分」とも自然につながる。", "空": "白い壁を持つ空はなく、建物の説明としては不自然。", "音": "白い壁の音がある、という文は意味が通らない。", "雨": "白い壁の雨がある、という文は成り立たない。"}, "sentence_index": 0, "correct_answer": "家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は由緒ある家の出身で、昔からの格式を大切にしている。", "explanation": "ここは〈家柄・家系〉の意味。建物ではなく、代々続く家系を指す。"}, {"text": "うちの家はみんな朝が早い。", "explanation": "ここは〈家族〉の意味。建物ではなく、家に住む人々を指す。"}, {"text": "兄が家を継いで、店の経営を任された。", "explanation": "ここは〈家督〉の意味。建物ではなく、家の跡取りという立場を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38146, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家", "is_correct": true, "explanation": "大雨で水が入るという、建物としての家の説明に合う。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いに水が入るという意味にはならず、文が成り立たない。"}, {"text": "花", "is_correct": false, "explanation": "花に水が入るという説明は不自然で、建物の話題に合わない。"}, {"text": "声", "is_correct": false, "explanation": "声に水が入るという文は意味が通らない。"}], "explanations": {"家": "大雨で水が入るという、建物としての家の説明に合う。", "匂い": "匂いに水が入るという意味にはならず、文が成り立たない。", "花": "花に水が入るという説明は不自然で、建物の話題に合わない。", "声": "声に水が入るという文は意味が通らない。"}, "sentence_index": 6, "correct_answer": "家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの家の者は皆、礼儀正しい。", "explanation": "ここは〈一族・家族〉の意味。建物ではなく、そこに属する人々を指す。"}, {"text": "名門の家に生まれた彼は、格式を重んじて育った。", "explanation": "ここは〈家柄〉の意味。建物ではなく、家の格式を指す。"}, {"text": "父は家を継ぐよう彼に言ったが、彼は絵の道へ進んだ。", "explanation": "ここは〈家督〉の意味。建物ではなく、家の跡取りという立場を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38146, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は雨の日、家を前の道で傘をさして歩いた。", "corrected_sentence": "私は雨の日、家の前の道で傘をさして歩いた。", "error_description": "「家の前」は場所を示す連体修飾の「の」が必要。「家を」は目的語を示すので、「家を前」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38146, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年、私たちは駅の近くの家が買う予定だ。", "corrected_sentence": "来年、私たちは駅の近くの家を買う予定だ。", "error_description": "「買う」の目的語は「を」で示す。「が」は主語を示すため、「家が買う」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5fdf7e-84de-4db4-ae61-c81bedd001fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38148, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「学校の建物」と所属を表す。"}, {"text": "を", "is_correct": false, "explanation": "「学校を建物は」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「学校へ建物は」は名詞をつなげられない。"}, {"text": "から", "is_correct": false, "explanation": "「学校から建物は」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「学校の建物」と所属を表す。", "を": "「学校を建物は」は文法的に成り立たない。", "へ": "「学校へ建物は」は名詞をつなげられない。", "から": "「学校から建物は」は意味が通らない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38148, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "待つ動作の場所を示す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「建物の前を待って」は場所の表し方として誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「前へ待って」は動作の場所として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「前の待って」は動詞に続けられない。"}], "correct_answer": "で", "explanations": {"で": "待つ動作の場所を示す「で」。", "を": "「建物の前を待って」は場所の表し方として誤り。", "へ": "「前へ待って」は動作の場所として成り立たない。", "の": "「前の待って」は動詞に続けられない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38148, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が すんだり つかったり するために たてた もの。いえや ビルや 学校など。", "primary_collocate": null, "pronunciation": "たてもの", "ipa": "tatemono", "syllable_count": 4, "sentences": [{"text": "学校の建物は新しいです。", "target_word": "建物", "complexity_tier": "T2", "furigana": "学校[がっこう]の建物[たてもの]は新[あたら]しいです。", "sentence_source": "generated"}, {"text": "建物に入る。", "target_word": "建物", "complexity_tier": "T1", "furigana": "建物[たてもの]に入[はい]る。", "sentence_source": "generated"}, {"text": "大きな建物が見えます。", "target_word": "建物", "complexity_tier": "T2", "furigana": "大[おお]きな建物[たてもの]が見[み]えます。", "sentence_source": "generated"}, {"text": "建物の中で友だちと遊んだ。", "target_word": "建物", "complexity_tier": "T3", "furigana": "建物[たてもの]の中[なか]で友[とも]だちと遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "この建物に住んでいる人は多い。", "target_word": "建物", "complexity_tier": "T3", "furigana": "この建物[たてもの]に住[す]んでいる人[ひと]は多[おお]い。", "sentence_source": "generated"}, {"text": "建物を出て、バスに乗った。", "target_word": "建物", "complexity_tier": "T3", "furigana": "建物[たてもの]を出[で]て、バスに乗[の]った。", "sentence_source": "generated"}, {"text": "白い建物が私の学校です。", "target_word": "建物", "complexity_tier": "T2", "furigana": "白[しろ]い建物[たてもの]が私[わたし]の学校[がっこう]です。", "sentence_source": "generated"}, {"text": "建物の前で待っていてください。", "target_word": "建物", "complexity_tier": "T3", "furigana": "建物[たてもの]の前[まえ]で待[ま]っていてください。", "sentence_source": "generated"}, {"text": "雨が降るので、建物の中にいよう。", "target_word": "建物", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]るので、建物[たてもの]の中[なか]にいよう。", "sentence_source": "generated"}, {"text": "あの建物は何ですか。", "target_word": "建物", "complexity_tier": "T2", "furigana": "あの建物[たてもの]は何[なん]ですか。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建物内", "label": "派生"}, {"form": "建物群", "label": "派生"}, {"form": "建物名", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が住んだり使ったりするために建てた構造物（家・ビル・学校など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38148, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建物", "is_correct": true, "explanation": "学校の建物が新しいという意味で自然。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、学校の天気が新しいという意味が合わない。"}, {"text": "返事", "is_correct": false, "explanation": "形は合うが、学校の返事が新しいという意味が合わない。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが、学校の病気が新しいという意味が合わない。"}], "explanations": {"建物": "学校の建物が新しいという意味で自然。", "天気": "形は合うが、学校の天気が新しいという意味が合わない。", "返事": "形は合うが、学校の返事が新しいという意味が合わない。", "病気": "形は合うが、学校の病気が新しいという意味が合わない。"}, "sentence_index": 0, "correct_answer": "建物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜、建物を読んで眠った。", "explanation": "建物は読むものではなく、動詞との組み合わせが誤り。"}, {"text": "建物は毎日学校に歩いて通っている。", "explanation": "建物は動いて通うものではなく、意味が合わない。"}, {"text": "私は建物と一緒に昼ごはんを食べた。", "explanation": "建物は人と同じように一緒に食事をする相手にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38148, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建物", "is_correct": true, "explanation": "白い建物が学校だという意味で自然。"}, {"text": "花", "is_correct": false, "explanation": "形は合うが、白い花が学校だという意味が合わない。"}, {"text": "本", "is_correct": false, "explanation": "形は合うが、白い本が学校だという意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、白い靴が学校だという意味が合わない。"}], "explanations": {"建物": "白い建物が学校だという意味で自然。", "花": "形は合うが、白い花が学校だという意味が合わない。", "本": "形は合うが、白い本が学校だという意味が合わない。", "靴": "形は合うが、白い靴が学校だという意味が合わない。"}, "sentence_index": 6, "correct_answer": "建物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "建物を食べ過ぎて、お腹が痛い。", "explanation": "建物は食べるものではなく、意味が合わない。"}, {"text": "建物は私の兄で、先生です。", "explanation": "建物は人ではないので、兄や先生として使うのは誤り。"}, {"text": "昨日、建物が風邪をひいた。", "explanation": "建物は人のように風邪をひかず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
