INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38149, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が住んだり、仕事をしたりするために建てられた、屋根と壁のある構造物。", "primary_collocate": null, "pronunciation": "たてもの", "ipa": "tatemono", "syllable_count": 4, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "建物", "complexity_tier": "T6", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だっこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "あの建物は百年前に建てられた。", "target_word": "建物", "complexity_tier": "T4", "furigana": "あの建物[たてもの]は百年前[ひゃくねんまえ]に建[た]てられた。", "sentence_source": "generated"}, {"text": "駅の前に大きな建物があります。", "target_word": "建物", "complexity_tier": "T2", "furigana": "駅[えき]の前[まえ]に大[おお]きな建物[たてもの]があります。", "sentence_source": "generated"}, {"text": "建物の中は静かでした。", "target_word": "建物", "complexity_tier": "T2", "furigana": "建物[たてもの]の中[なか]は静[しず]かでした。", "sentence_source": "generated"}, {"text": "この建物には事務所が入っている。", "target_word": "建物", "complexity_tier": "T3", "furigana": "この建物[たてもの]には事務所[じむしょ]が入[はい]っている。", "sentence_source": "generated"}, {"text": "古い建物を修理する予定です。", "target_word": "建物", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]を修理[しゅうり]する予定[よてい]です。", "sentence_source": "generated"}, {"text": "建物が高すぎて、空が見えない。", "target_word": "建物", "complexity_tier": "T3", "furigana": "建物[たてもの]が高[たか]すぎて、空[そら]が見[み]えない。", "sentence_source": "generated"}, {"text": "地震で建物がたくさん壊れた。", "target_word": "建物", "complexity_tier": "T3", "furigana": "地震[じしん]で建物[たてもの]がたくさん壊[こわ]れた。", "sentence_source": "generated"}, {"text": "建物の周りに木を植えた。", "target_word": "建物", "complexity_tier": "T3", "furigana": "建物[たてもの]の周[まわ]りに木[き]を植[う]えた。", "sentence_source": "generated"}, {"text": "彼は建物に入って、受付に行った。", "target_word": "建物", "complexity_tier": "T3", "furigana": "彼[かれ]は建物[たてもの]に入[はい]って、受付[うけつけ]に行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "建物内", "label": "派生"}, {"form": "建物群", "label": "派生"}, {"form": "建物名", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 屋根と壁のある人が使う構造物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a6e59f-ea65-43a2-8a55-7ec9fc7d85ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38149, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建物", "is_correct": true, "explanation": "「建物に込められた作者の意図」と、構造物を指す意味で自然に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気に作者の意図が込められるという意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、野菜に作者の意図が込められるという意味が合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、砂糖に作者の意図が込められるという意味が合わない。"}], "explanations": {"建物": "「建物に込められた作者の意図」と、構造物を指す意味で自然に合う。", "天気": "形は合うが、天気に作者の意図が込められるという意味が合わない。", "野菜": "形は合うが、野菜に作者の意図が込められるという意味が合わない。", "砂糖": "形は合うが、砂糖に作者の意図が込められるという意味が合わない。"}, "sentence_index": 0, "correct_answer": "建物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、建物を飲んでから会社に行きます。", "explanation": "建物は飲むものではないので、動詞との組み合わせが誤り。"}, {"text": "彼の建物はとても優しくて、みんなに好かれている。", "explanation": "建物は構造物で、人の性格を表す語ではないので使い方が誤り。"}, {"text": "夏は建物がたくさん降るので、傘が必要だ。", "explanation": "建物は雨のように降るものではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38149, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建物", "is_correct": true, "explanation": "高すぎて空が見えないのは建物で、意味が合う。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段が高くても空が見えなくなる意味にならない。"}, {"text": "成績", "is_correct": false, "explanation": "形は合うが、成績が高くて空が見えないという意味が合わない。"}, {"text": "電話", "is_correct": false, "explanation": "形は合うが、電話が高すぎて空が見えないという意味が合わない。"}], "explanations": {"建物": "高すぎて空が見えないのは建物で、意味が合う。", "値段": "形は合うが、値段が高くても空が見えなくなる意味にならない。", "成績": "形は合うが、成績が高くて空が見えないという意味が合わない。", "電話": "形は合うが、電話が高すぎて空が見えないという意味が合わない。"}, "sentence_index": 6, "correct_answer": "建物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は建物を食べて、受付に行った。", "explanation": "建物は食べるものではなく、動詞との組み合わせが誤り。"}, {"text": "建物は昨日から熱があって、学校を休んだ。", "explanation": "建物は人のように熱が出たり学校を休んだりしない。"}, {"text": "彼は建物の気持ちを考えて、手紙を書いた。", "explanation": "建物は人ではなく、気持ちを持つ相手として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38149, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い建物に修理する予定です。", "corrected_sentence": "古い建物を修理する予定です。", "error_description": "「修理する」の対象を示す助詞は「に」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38149, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は建物を入って、受付に行った。", "corrected_sentence": "彼は建物に入って、受付に行った。", "error_description": "「入る」の場所を示す助詞は「を」ではなく「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc7f6ae-2049-4ae9-a296-3b28beaf5b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38152, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「育てる」を名詞化する「の」で、「育てるのは大変」と続く。"}, {"text": "を", "is_correct": false, "explanation": "「育てる」はすでに目的語「食べ物を」を持つため、ここで「を」を置くと不自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」では、後ろの「大変」に主語がなく誤り。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表す「で」は「育てる」に続けると文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「育てる」を名詞化する「の」で、「育てるのは大変」と続く。", "を": "「育てる」はすでに目的語「食べ物を」を持つため、ここで「を」を置くと不自然。", "が": "主語を示す「が」では、後ろの「大変」に主語がなく誤り。", "で": "手段や場所を表す「で」は「育てる」に続けると文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
