INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38152, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "たべものの やさいなどを そだてること。", "primary_collocate": null, "pronunciation": "たべものをそだてる", "ipa": "tabemono o sodateɾɯ", "syllable_count": 9, "sentences": [{"text": "田舎に引っ越して、自分で食べ物を育てる生活を始めました。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "いなかにひっこして、じぶんでたべものをそだてるせいかつをはじめました。", "sentence_source": "generated"}, {"text": "食べ物を育てるのは大変ですが、収穫の日はとても楽しみです。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "たべものをそだてるのはたいへんですが、しゅうかくのひはとてもたのしみです。", "sentence_source": "generated"}, {"text": "祖父は畑で食べ物を育てて、近所の人にも分けています。", "target_word": "食べ物を育てて", "complexity_tier": "T3", "furigana": "そふははたけでたべものをそだてて、きんじょのひとにもわけています。", "sentence_source": "generated"}, {"text": "雨が少ない年は、食べ物を育てるのに水がたくさん必要です。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "あめがすくないとしは、たべものをそだてるのにみずがたくさんひつようです。", "sentence_source": "generated"}, {"text": "私たちは学校の庭で食べ物を育てて、給食に使っています。", "target_word": "食べ物を育てて", "complexity_tier": "T3", "furigana": "わたしたちはがっこうのにわでたべものをそだてて、きゅうしょくにつかっています。", "sentence_source": "generated"}, {"text": "食べ物を育てる人たちのおかげで、毎日おいしいご飯が食べられます。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "たべものをそだてるひとたちのおかげで、まいにちおいしいごはんがたべられます。", "sentence_source": "generated"}, {"text": "食べ物を育てるには、土と太陽と時間が欠かせません。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "たべものをそだてるには、つちとたいようとじかんがかかせません。", "sentence_source": "generated"}, {"text": "農家の人は朝早くから、食べ物を育てるために働いています。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "のうかのひとはあさはやくから、たべものをそだてるためにはたらいています。", "sentence_source": "generated"}, {"text": "ベランダは小さいので、広い畑のように食べ物を育てることはできません。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "ベランダはちいさいので、ひろいはたけのようにたべものをそだてることはできません。", "sentence_source": "generated"}, {"text": "子どもと一緒に食べ物を育てると、野菜が好きになる子が多いです。", "target_word": "食べ物を育てる", "complexity_tier": "T3", "furigana": "こどもといっしょにたべものをそだてると、やさいがすきになるこがおおいです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "育てる", "label": "辞書形"}, {"form": "育てます", "label": "ます形"}, {"form": "育てて", "label": "て形"}, {"form": "育てた", "label": "た形"}, {"form": "育てない", "label": "ない形"}], "register": "丁寧", "sense_fingerprint": "畑や庭で野菜などの食べ物を作り育てること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38152, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食べ物を育てる", "is_correct": true, "explanation": "「自分で食べ物を育てる生活」と、名詞「生活」を修飾する辞書形で文脈に合う。"}, {"text": "食べ物を育てて", "is_correct": false, "explanation": "て形は名詞「生活」を直接修飾できず、文が続かない。"}, {"text": "食べ物を育てます", "is_correct": false, "explanation": "ます形は名詞を修飾できないため、「生活」につながらない。"}, {"text": "食べ物を育てよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、「生活」に続けると文法的に誤り。"}], "explanations": {"食べ物を育てる": "「自分で食べ物を育てる生活」と、名詞「生活」を修飾する辞書形で文脈に合う。", "食べ物を育てて": "て形は名詞「生活」を直接修飾できず、文が続かない。", "食べ物を育てます": "ます形は名詞を修飾できないため、「生活」につながらない。", "食べ物を育てよう": "意志形は名詞を修飾できず、「生活」に続けると文法的に誤り。"}, "sentence_index": 0, "correct_answer": "食べ物を育てる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎晩、夕食の食べ物を育てて、家族に出しています。", "explanation": "ここは〈作る／用意する〉の意味。育てるは植物や動物を大きくすることなので、料理や準備には合わない。"}, {"text": "週末は、近くのスーパーで食べ物を育てて帰ります。", "explanation": "ここは〈買う〉の意味。育てるは自分で大きくする行為で、店で手に入れることは表さないので合わない。"}, {"text": "冷蔵庫の中で食べ物を育てて、長く保存します。", "explanation": "ここは〈保存する〉の意味。育てるは生き物を大きくすることで、食べ物を長持ちさせる意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38152, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食べ物を育てる", "is_correct": true, "explanation": "「〜するには」の条件を表す形で、動詞の辞書形が必要。"}, {"text": "食べ物を育てた", "is_correct": false, "explanation": "た形は「には」に続かず、条件の文型に合わない。"}, {"text": "食べ物を育てません", "is_correct": false, "explanation": "否定のます形は「には」に続かず、文が成り立たない。"}, {"text": "食べ物を育てたい", "is_correct": false, "explanation": "たい形は「には」に続かず、不自然。"}], "explanations": {"食べ物を育てる": "「〜するには」の条件を表す形で、動詞の辞書形が必要。", "食べ物を育てた": "た形は「には」に続かず、条件の文型に合わない。", "食べ物を育てません": "否定のます形は「には」に続かず、文が成り立たない。", "食べ物を育てたい": "たい形は「には」に続かず、不自然。"}, "sentence_index": 6, "correct_answer": "食べ物を育てる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店で食べ物を育てて注文しました。", "explanation": "ここは〈注文する〉の意味。育てるは注文の行為を表さないので、店での注文には合わない。"}, {"text": "お腹がすいたので、食べ物を育てて、すぐに食べました。", "explanation": "ここは〈食べる〉の意味。育てるは食べることを表さないので、この文脈には合わない。"}, {"text": "熱くなった食べ物を育てて、少し冷ましました。", "explanation": "ここは〈冷ます〉の意味。育てるは温度を下げることを表さないので、冷ますには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38152, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "休みの日は、家族と一緒に畑で食べ物に育てています。", "corrected_sentence": "休みの日は、家族と一緒に畑で食べ物を育てています。", "error_description": "「育てる」の目的語は「を」で示す。「食べ物に」は誤りで、正しくは「食べ物を育てています」（助詞「に」を「を」に直す）。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "食べ物を育てる", "is_correct": true, "explanation": "「育てるのは大変」の形で、辞書形が「のは」に続く。"}, {"text": "食べ物を育てます", "is_correct": false, "explanation": "ます形は「のは」に続かず、文法的に成り立たない。"}, {"text": "食べ物を育てて", "is_correct": false, "explanation": "て形は「のは」に続かず、文が途切れる。"}, {"text": "食べ物を育てよう", "is_correct": false, "explanation": "意志形は「のは」に続かず、不自然。"}], "correct_form": "食べ物を育てる", "base_form": "食べ物を育てる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"食べ物を育てる": "「育てるのは大変」の形で、辞書形が「のは」に続く。", "食べ物を育てます": "ます形は「のは」に続かず、文法的に成り立たない。", "食べ物を育てて": "て形は「のは」に続かず、文が途切れる。", "食べ物を育てよう": "意志形は「のは」に続かず、不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38152, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みには、子どもたちが学校の庭で食べ物を育てるました。", "corrected_sentence": "夏休みには、子どもたちが学校の庭で食べ物を育てました。", "error_description": "「ました」を続けるには、ます形の「育て」に変える。「育てるました」は「る」が余分で誤り。正しくは「育てました」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "食べ物を育てる", "is_correct": true, "explanation": "目的を表す「ために」の前は辞書形で、文中の形と一致する。"}, {"text": "食べ物を育てました", "is_correct": false, "explanation": "過去の丁寧形は「ために」に直接つながらない。"}, {"text": "食べ物を育てれば", "is_correct": false, "explanation": "仮定形は「ために」の前に置けず、文が成り立たない。"}, {"text": "食べ物を育てたら", "is_correct": false, "explanation": "条件の形は「ために」に続かず、文が成立しない。"}], "correct_form": "食べ物を育てる", "base_form": "食べ物を育てる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"食べ物を育てる": "目的を表す「ために」の前は辞書形で、文中の形と一致する。", "食べ物を育てました": "過去の丁寧形は「ために」に直接つながらない。", "食べ物を育てれば": "仮定形は「ために」の前に置けず、文が成り立たない。", "食べ物を育てたら": "条件の形は「ために」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38154, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べる」の目的語になる「食べ物」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「食べ物が食べる」では主語と動詞が合わず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「食べ物に食べる」は不自然。「に」は相手や場所を示すため不適。"}, {"text": "と", "is_correct": false, "explanation": "「食べ物と食べる」は並列を示すが、食べる対象としては不自然。"}], "correct_answer": "を", "explanations": {"を": "「食べる」の目的語になる「食べ物」に「を」が付く。", "が": "「食べ物が食べる」では主語と動詞が合わず、文が成り立たない。", "に": "「食べ物に食べる」は不自然。「に」は相手や場所を示すため不適。", "と": "「食べ物と食べる」は並列を示すが、食べる対象としては不自然。"}, "error_tags": {"が": "主語", "に": "相手・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38154, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買う」の目的語になる「食べ物」に「を」が付く。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「食べ物へ買っておいた」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すため、「食べ物で買っておいた」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、食べ物を起点に買うとは言わない。"}], "correct_answer": "を", "explanations": {"を": "「買う」の目的語になる「食べ物」に「を」が付く。", "へ": "「へ」は方向を示すため、「食べ物へ買っておいた」は不自然。", "で": "「で」は手段を示すため、「食べ物で買っておいた」は不自然。", "から": "「から」は起点を示すが、食べ物を起点に買うとは言わない。"}, "error_tags": {"へ": "方向", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38154, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が食べるための食品の総称。", "primary_collocate": null, "pronunciation": "たべもの", "ipa": "tabemono", "syllable_count": 4, "sentences": [{"text": "遠足には、飲み物と食べ物を自分で用意して持って行く。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "遠足[えんそく]には、飲[の]み物[もの]と食[た]べ物[もの]を自分[じぶん]で用意[ようい]して持[も]って行[い]く。", "sentence_source": "generated"}, {"text": "外国で、はじめて見る食べ物を食べるのは少し緊張する。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "外国[がいこく]で、はじめて見[み]る食[た]べ物[もの]を食[た]べるのは少[すこ]し緊張[きんちょう]する。", "sentence_source": "generated"}, {"text": "冷たい食べ物ばかり食べたので、おなかが痛くなった。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "冷[つめ]たい食[た]べ物[もの]ばかり食[た]べたので、おなかが痛[いた]くなった。", "sentence_source": "generated"}, {"text": "食べ物の値段が上がって、毎日の買い物が大変だ。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]の値段[ねだん]が上[あ]がって、毎日[まいにち]の買[か]い物[もの]が大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "夜遅い時間の食べ物は、太りやすいと言われている。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "夜遅[よるおそ]い時間[じかん]の食[た]べ物[もの]は、太[ふと]りやすいと言[い]われている。", "sentence_source": "generated"}, {"text": "この国では、お米が一番大切な食べ物だ。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "この国[くに]では、お米[こめ]が一番[いちばん]大切[たいせつ]な食[た]べ物[もの]だ。", "sentence_source": "generated"}, {"text": "食べ物にアレルギーがある人は、先に店員に伝えてください。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]にアレルギーがある人[ひと]は、先[さき]に店員[てんいん]に伝[つた]えてください。", "sentence_source": "generated"}, {"text": "台風が来る前に、水と食べ物を多めに買っておいた。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "台風[たいふう]が来[く]る前[まえ]に、水[みず]と食[た]べ物[もの]を多[おお]めに買[か]っておいた。", "sentence_source": "generated"}, {"text": "私の国には、日本にはない珍しい食べ物がたくさんある。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "私[わたし]の国[くに]には、日本[にほん]にはない珍[めずら]しい食[た]べ物[もの]がたくさんある。", "sentence_source": "generated"}, {"text": "辛い食べ物が苦手なので、このカレーは食べられない。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "辛[から]い食[た]べ物[もの]が苦手[にがて]なので、このカレーは食[た]べられない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食べ物", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "食べるための物の総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38154, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食べ物", "is_correct": true, "explanation": "用意して持って行く対象として、食品を指すので文に合う。"}, {"text": "空腹", "is_correct": false, "explanation": "空腹は体の状態で、用意して持って行くものではない。"}, {"text": "満腹", "is_correct": false, "explanation": "満腹は体の状態で、用意して持って行くものではない。"}, {"text": "味覚", "is_correct": false, "explanation": "味覚は感じる力で、物として用意することはできない。"}], "explanations": {"食べ物": "用意して持って行く対象として、食品を指すので文に合う。", "空腹": "空腹は体の状態で、用意して持って行くものではない。", "満腹": "満腹は体の状態で、用意して持って行くものではない。", "味覚": "味覚は感じる力で、物として用意することはできない。"}, "sentence_index": 0, "correct_answer": "食べ物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この食べ物は蓋がついていて、水を入れて持ち運べる。", "explanation": "ここは〈水筒〉の意味。蓋つきで水を入れて持ち運ぶのは水筒で、食べ物には当てはまらない。"}, {"text": "年を取ると、食べ物が鈍くなる。", "explanation": "ここは〈味覚〉の意味。鈍くなるのは味を感じる力で、食べ物が鈍くなることはない。"}, {"text": "この食べ物は刃が鋭くて、野菜がよく切れる。", "explanation": "ここは〈包丁〉の意味。刃が鋭く野菜を切るのは包丁で、食べ物には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38154, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食べ物", "is_correct": true, "explanation": "アレルギーの原因となる食品を指すので文に合う。"}, {"text": "栄養", "is_correct": false, "explanation": "栄養はアレルギーの対象になる語ではなく、文の意味に合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食欲は感覚で、アレルギーの対象にはならない。"}, {"text": "消化", "is_correct": false, "explanation": "消化は体の働きで、アレルギーの対象にはならない。"}], "explanations": {"食べ物": "アレルギーの原因となる食品を指すので文に合う。", "栄養": "栄養はアレルギーの対象になる語ではなく、文の意味に合わない。", "食欲": "食欲は感覚で、アレルギーの対象にはならない。", "消化": "消化は体の働きで、アレルギーの対象にはならない。"}, "sentence_index": 6, "correct_answer": "食べ物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "食べ物の腕前が上がって、友達にほめられた。", "explanation": "ここは〈料理〉の意味。腕前は料理をする技術に対して言い、食べ物には使わない。"}, {"text": "この食べ物は便箋が三枚で、短くまとまっている。", "explanation": "ここは〈手紙〉の意味。便箋や文章のまとまりは手紙について言うもので、食べ物には当てはまらない。"}, {"text": "この食べ物は電気で動いて、庫内を冷やす。", "explanation": "ここは〈冷蔵庫〉の意味。電気で動き庫内を冷やすのは冷蔵庫で、食べ物には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38154, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お客さんのために、食べ物で温め直した。", "corrected_sentence": "お客さんのために、食べ物を温め直した。", "error_description": "「温め直す」の対象には「を」が必要。「で」は手段を示すため、「食べ物で温め直した」は誤り。正しくは「食べ物を温め直した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38154, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちのために、食べ物が買いに店へ行った。", "corrected_sentence": "子どもたちのために、食べ物を買いに店へ行った。", "error_description": "「買いに行く」の対象には「を」が必要。「が」は主語を示すため、「食べ物が買いに」は誤り。正しくは「食べ物を買いに」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38155, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買う」は他動詞で、目的語の「食べ物」に「を」が付く。"}, {"text": "が", "is_correct": false, "explanation": "「食べ物が買う」では主語と動詞が合わず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「食べ物に買う」は成り立たない。「に」は相手や場所を示すため不適。"}, {"text": "と", "is_correct": false, "explanation": "「食べ物と買う」は並列を示すが、買う対象としては不自然。"}], "correct_answer": "を", "explanations": {"を": "「買う」は他動詞で、目的語の「食べ物」に「を」が付く。", "が": "「食べ物が買う」では主語と動詞が合わず、文が成り立たない。", "に": "「食べ物に買う」は成り立たない。「に」は相手や場所を示すため不適。", "と": "「食べ物と買う」は並列を示すが、買う対象としては不自然。"}, "error_tags": {"が": "主語", "に": "相手・場所", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38155, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「なくなる」の主語になる「食べ物」に「が」が付く。"}, {"text": "を", "is_correct": false, "explanation": "「なくなる」は自動詞で目的語を取らないため、「を」は合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「食べ物へなくなる」は不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、食べ物を起点に「なくなる」とは言わない。"}], "correct_answer": "が", "explanations": {"が": "「なくなる」の主語になる「食べ物」に「が」が付く。", "を": "「なくなる」は自動詞で目的語を取らないため、「を」は合わない。", "へ": "「へ」は方向を示すため、「食べ物へなくなる」は不自然。", "から": "「から」は起点を示すが、食べ物を起点に「なくなる」とは言わない。"}, "error_tags": {"を": "目的語（他動詞用）", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38155, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が食べるもの。ごはん、くだもの、やさいなど。", "primary_collocate": null, "pronunciation": "たべもの", "ipa": "tabemono", "syllable_count": 4, "sentences": [{"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "この時間帯[じかんたい]に与[あた]える食[た]べ物[もの]は、地元[じもと]で採[と]れた新鮮[しんせん]な穀物[こくもつ]と野菜[やさい]を混[ま]ぜ合[あ]わせたものだ。", "sentence_source": "mined"}, {"text": "旅行に行く前に、持っていく食べ物を買っておいた。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "旅行[りょこう]に行[い]く前[まえ]に、持[も]っていく食[た]べ物[もの]を買[か]っておいた。", "sentence_source": "generated"}, {"text": "犬は人間の食べ物を食べると、体調を崩すことがある。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "犬[いぬ]は人間[にんげん]の食[た]べ物[もの]を食[た]べると、体調[たいちょう]を崩[くず]すことがある。", "sentence_source": "generated"}, {"text": "好きな食べ物は何ですかと聞かれて、すぐにカレーと答えた。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "好[す]きな食[た]べ物[もの]は何[なん]ですかと聞[き]かれて、すぐにカレーと答[こた]えた。", "sentence_source": "generated"}, {"text": "夏は食べ物が傷みやすいので、冷蔵庫に入れておく。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "夏[なつ]は食[た]べ物[もの]が傷[いた]みやすいので、冷蔵庫[れいぞうこ]に入[い]れておく。", "sentence_source": "generated"}, {"text": "食べ物を残さないように、食べられる量だけ注文した。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]を残[のこ]さないように、食[た]べられる量[りょう]だけ注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "この店は飲み物も食べ物も安くて、いつも学生でいっぱいだ。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "この店[みせ]は飲[の]み物[もの]も食[た]べ物[もの]も安[やす]くて、いつも学生[がくせい]でいっぱいだ。", "sentence_source": "generated"}, {"text": "山の中で食べ物がなくなり、みんな困ってしまった。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "山[やま]の中[なか]で食[た]べ物[もの]がなくなり、みんな困[こま]ってしまった。", "sentence_source": "generated"}, {"text": "母は、食べ物の好き嫌いが多い弟に野菜を食べさせようとした。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "母[はは]は、食[た]べ物[もの]の好[す]き嫌[きら]いが多[おお]い弟[おとうと]に野菜[やさい]を食[た]べさせようとした。", "sentence_source": "generated"}, {"text": "公園では、鳥に食べ物をあげないでくださいと書いてある。", "target_word": "食べ物", "complexity_tier": "T3", "furigana": "公園[こうえん]では、鳥[とり]に食[た]べ物[もの]をあげないでくださいと書[か]いてある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食べ物", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が食べる物の総称（ごはん・くだもの・やさいなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38155, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食べ物", "is_correct": true, "explanation": "与えるものとして、穀物と野菜を混ぜ合わせた食品を指すので文に合う。"}, {"text": "食器", "is_correct": false, "explanation": "食器は皿などの器具で、地元の穀物と野菜を混ぜ合わせたものとは合わない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は調理用の刃物で、与える対象としては文の内容に合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、混ぜ合わせた穀物と野菜を与えるという文には当てはまらない。"}], "explanations": {"食べ物": "与えるものとして、穀物と野菜を混ぜ合わせた食品を指すので文に合う。", "食器": "食器は皿などの器具で、地元の穀物と野菜を混ぜ合わせたものとは合わない。", "包丁": "包丁は調理用の刃物で、与える対象としては文の内容に合わない。", "冷蔵庫": "冷蔵庫は家電で、混ぜ合わせた穀物と野菜を与えるという文には当てはまらない。"}, "sentence_index": 0, "correct_answer": "食べ物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕食の食べ物は八時から始まる予定だ。", "explanation": "ここは〈食事〉の意味。始まるのは食べる時間である食事で、食べ物（物）は時間として始まらない。"}, {"text": "この食べ物は洗えば何度も使えて、割れにくい。", "explanation": "ここは〈食器〉の意味。洗って繰り返し使い、割れにくいのは食器で、食べ物には当てはまらない。"}, {"text": "この食べ物は底が厚くて、中で野菜を煮込める。", "explanation": "ここは〈鍋〉の意味。底が厚く中で野菜を煮込めるのは鍋で、食べ物はそのようには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38155, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食べ物", "is_correct": true, "explanation": "飲み物と並んで店で売られる食品を指すので文に合う。"}, {"text": "栄養", "is_correct": false, "explanation": "栄養は食品の成分で、値段が安いという文には合わない。"}, {"text": "食欲", "is_correct": false, "explanation": "食欲は体の感覚で、店が安いという説明とは合わない。"}, {"text": "消化", "is_correct": false, "explanation": "消化は体の働きで、店で安く売るものではない。"}], "explanations": {"食べ物": "飲み物と並んで店で売られる食品を指すので文に合う。", "栄養": "栄養は食品の成分で、値段が安いという文には合わない。", "食欲": "食欲は体の感覚で、店が安いという説明とは合わない。", "消化": "消化は体の働きで、店で安く売るものではない。"}, "sentence_index": 6, "correct_answer": "食べ物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は箸の食べ物がとても丁寧だ。", "explanation": "ここは〈食べ方〉の意味。「丁寧だ」は食べ方の様子に言うもので、食べ物（物）には使わない。"}, {"text": "この食べ物は木製で、家族五人が座れる大きさだ。", "explanation": "ここは〈食卓〉の意味。食卓は食事を並べる台で、食べ物は木製の家具ではない。"}, {"text": "この食べ物は字が大きくて、読みやすい。", "explanation": "ここは〈本〉の意味。字の大きさや読みやすさは本について言うもので、食べ物には当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38155, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りのために食べ物に買っておいた。", "corrected_sentence": "祭りのために食べ物を買っておいた。", "error_description": "「買う」の目的語には「を」が必要。「に」は相手や場所を示すため、「食べ物に買っておいた」は誤り。正しくは「食べ物を買っておいた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38155, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パーティーのために食べ物が大皿に盛りつけた。", "corrected_sentence": "パーティーのために食べ物を大皿に盛りつけた。", "error_description": "「盛りつける」の目的語には「を」が必要。「が」は主語を示すため、「食べ物が盛りつけた」は誤り。正しくは「食べ物を盛りつけた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
