INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38156, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "ほしいものや、おおいと おもう ぶんだけ あること。", "primary_collocate": null, "pronunciation": "たりる", "ipa": "taɾiɾɯ", "syllable_count": 3, "sentences": [{"text": "私はおにぎりが二つあれば足ります。", "target_word": "足ります", "complexity_tier": "T3", "furigana": "わたしはおにぎりがふたつあればたります。", "sentence_source": "generated"}, {"text": "このお菓子の数でみんなに足りるか、ちょっと心配です。", "target_word": "足りる", "complexity_tier": "T3", "furigana": "このおかしのかずでみんなにたりるか、ちょっとしんぱいです。", "sentence_source": "generated"}, {"text": "一日一回の食事では足りないので、おやつも食べます。", "target_word": "足りない", "complexity_tier": "T3", "furigana": "いちにちいっかいのしょくじではたりないので、おやつもたべます。", "sentence_source": "generated"}, {"text": "飲み物はこれで足りると思うので、買い物はもう終わりにしましょう。", "target_word": "足りる", "complexity_tier": "T3", "furigana": "のみものはこれでたりるとおもうので、かいものはもうおわりにしましょう。", "sentence_source": "generated"}, {"text": "弟はおかわりをしても足りないと言って、まだ食べています。", "target_word": "足りない", "complexity_tier": "T3", "furigana": "おとうとはおかわりをしてもたりないといって、まだたべています。", "sentence_source": "generated"}, {"text": "おこづかいが少なくて、ほしい本を買うには足りません。", "target_word": "足りません", "complexity_tier": "T3", "furigana": "おこづかいがすくなくて、ほしいほんをかうにはたりません。", "sentence_source": "generated"}, {"text": "五人分のカレーを作りましたから、家族みんなに足りるでしょう。", "target_word": "足りる", "complexity_tier": "T3", "furigana": "ごにんぶんのカレーをつくりましたから、かぞくみんなにたりるでしょう。", "sentence_source": "generated"}, {"text": "その量で足りるなら、これ以上は買わなくてもいいです。", "target_word": "足りる", "complexity_tier": "T3", "furigana": "そのりょうでたりるなら、これいじょうはかわなくてもいいです。", "sentence_source": "generated"}, {"text": "足りない分は、私のお弁当を少し分けてあげます。", "target_word": "足りない", "complexity_tier": "T3", "furigana": "たりないぶんは、わたしのおべんとうをすこしわけてあげます。", "sentence_source": "generated"}, {"text": "毎日の水が足りて、庭の花は元気に咲いています。", "target_word": "足りて", "complexity_tier": "T3", "furigana": "まいにちのみずがたりて、にわのはなはげんきにさいています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "足りる", "label": "辞書形"}, {"form": "足ります", "label": "ます形"}, {"form": "足りて", "label": "て形"}, {"form": "足りない", "label": "ない形"}, {"form": "足りた", "label": "た形"}], "register": "丁寧", "sense_fingerprint": "自分が十分だと思える量がそろっていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38156, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足ります", "is_correct": true, "explanation": "「二つあれば足ります」と文末に置く丁寧形で、この文の述語として合う。"}, {"text": "足りて", "is_correct": false, "explanation": "て形は文末に置けず、「あれば」の条件文の述語にならない。"}, {"text": "足りました", "is_correct": false, "explanation": "過去の丁寧形は「あれば」の条件文に続かず、不自然。"}, {"text": "足りなくて", "is_correct": false, "explanation": "なくて形は文末に置けず、文が成立しない。"}], "explanations": {"足ります": "「二つあれば足ります」と文末に置く丁寧形で、この文の述語として合う。", "足りて": "て形は文末に置けず、「あれば」の条件文の述語にならない。", "足りました": "過去の丁寧形は「あれば」の条件文に続かず、不自然。", "足りなくて": "なくて形は文末に置けず、文が成立しない。"}, "sentence_index": 0, "correct_answer": "足ります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "2と5が足りると、7になります。", "explanation": "ここは〈足す〉の意味。足りるは量が十分かを表し、数を加える意味にはならないので合わない。"}, {"text": "夜空の月が足りて、丸く輝いています。", "explanation": "ここは〈満ちる（丸くなる）〉の意味。月が丸くなることは「満ちる」で表し、「足りる」は量が十分かを表すので合わない。"}, {"text": "足が地面に足りて、つま先で立っています。", "explanation": "ここは〈届く〉の意味。足りるは量の十分さを表し、体の一部が届くことは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38156, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足りる", "is_correct": true, "explanation": "「家族みんなに足りるでしょう」と、「でしょう」の前に辞書形が自然に続く。"}, {"text": "足りよう", "is_correct": false, "explanation": "意志形は「でしょう」の前に続けると不自然で、文が成り立たない。"}, {"text": "足りますね", "is_correct": false, "explanation": "「ね」を含む形は「でしょう」に続かず、文が成り立たない。"}, {"text": "足りますか", "is_correct": false, "explanation": "疑問の「か」を含む形は「でしょう」に続かず、文が成り立たない。"}], "explanations": {"足りる": "「家族みんなに足りるでしょう」と、「でしょう」の前に辞書形が自然に続く。", "足りよう": "意志形は「でしょう」の前に続けると不自然で、文が成り立たない。", "足りますね": "「ね」を含む形は「でしょう」に続かず、文が成り立たない。", "足りますか": "疑問の「か」を含む形は「でしょう」に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "足りる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "予算がたくさん足りて、困っています。", "explanation": "ここは〈余る〉の意味。足りるは不十分でないことを表し、多すぎる状態には使わない。"}, {"text": "財布の中身が足りるので、買えないと困っています。", "explanation": "ここは〈不足する〉の意味。足りるは十分であることなので、足りないと困る文脈には合わない。"}, {"text": "宿題が足りて、もう終わりました。", "explanation": "ここは〈完成する〉の意味。足りるは作業の完了を表さないので、この文脈では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38156, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "予算を足りていれば、旅行に行けます。", "corrected_sentence": "予算が足りていれば、旅行に行けます。", "error_description": "「足りる」は主語を「が」で示す。「を」は誤りで、正しくは「予算が足りていれば」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "足りる", "is_correct": true, "explanation": "「足りるか心配です」の形で、辞書形が「か」に続く。"}, {"text": "足ります", "is_correct": false, "explanation": "丁寧形は「か」の前に置けず、不自然。"}, {"text": "足りて", "is_correct": false, "explanation": "て形は「か」に続かず、文が成り立たない。"}, {"text": "足りなくて", "is_correct": false, "explanation": "なくて形は「か」に続かず、文が成り立たない。"}], "correct_form": "足りる", "base_form": "足りる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"足りる": "「足りるか心配です」の形で、辞書形が「か」に続く。", "足ります": "丁寧形は「か」の前に置けず、不自然。", "足りて": "て形は「か」に続かず、文が成り立たない。", "足りなくて": "なくて形は「か」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38156, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人分の材料では、二人分には足りるません。", "corrected_sentence": "一人分の材料では、二人分には足りません。", "error_description": "「足りる」に「ません」は続かない。「る」が余分で誤り。正しくは「足りません」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "足りる", "is_correct": true, "explanation": "「その量で足りるなら」の形で、辞書形が「なら」に続く。"}, {"text": "足りよう", "is_correct": false, "explanation": "意志形は「なら」に続かず、文が成り立たない。"}, {"text": "足りません", "is_correct": false, "explanation": "否定の丁寧形は「なら」に続かず、不自然。"}, {"text": "足りまして", "is_correct": false, "explanation": "て形は「なら」に続かず、文が成り立たない。"}], "correct_form": "足りる", "base_form": "足りる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"足りる": "「その量で足りるなら」の形で、辞書形が「なら」に続く。", "足りよう": "意志形は「なら」に続かず、文が成り立たない。", "足りません": "否定の丁寧形は「なら」に続かず、不自然。", "足りまして": "て形は「なら」に続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
