INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38157, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "必要とする数量や程度に達していること。不足がないこと。", "primary_collocate": null, "pronunciation": "たりる", "ipa": "taɾiɾɯ", "syllable_count": 3, "sentences": [{"text": "参加者の数が足りて、試合を始めることができました。", "target_word": "足りて", "complexity_tier": "T3", "furigana": "さんかしゃのかずがたりて、しあいをはじめることができました。", "sentence_source": "generated"}, {"text": "材料が足りないので、実験は来週に延期します。", "target_word": "足りない", "complexity_tier": "T3", "furigana": "ざいりょうがたりないので、じっけんはらいしゅうにのばします。", "sentence_source": "generated"}, {"text": "この予算では、旅行の費用が足りません。", "target_word": "足りません", "complexity_tier": "T3", "furigana": "このよさんでは、りょこうのひようがたりません。", "sentence_source": "generated"}, {"text": "会議に必要な席は、十分足りています。", "target_word": "足りています", "complexity_tier": "T3", "furigana": "かいぎにひつようなせきは、じゅうぶんたりています。", "sentence_source": "generated"}, {"text": "人手が足りない部署に、新しい社員が配属されました。", "target_word": "足りない", "complexity_tier": "T3", "furigana": "ひとでがたりないぶしょに、あたらしいしゃいんがはいぞくされました。", "sentence_source": "generated"}, {"text": "睡眠時間が足りないと、昼間に集中できなくなります。", "target_word": "足りない", "complexity_tier": "T3", "furigana": "すいみんじかんがたりないと、ひるまにしゅうちゅうできなくなります。", "sentence_source": "generated"}, {"text": "書類の枚数が足りているか、提出する前に確認してください。", "target_word": "足りている", "complexity_tier": "T3", "furigana": "しょるいのまいすうがたりているか、ていしゅつするまえにかくにんしてください。", "sentence_source": "generated"}, {"text": "栄養が足りていれば、体は自然に元気になります。", "target_word": "足りていれば", "complexity_tier": "T3", "furigana": "えいようがたりていれば、からだはしぜんにげんきになります。", "sentence_source": "generated"}, {"text": "点数が一点足りなくて、試験に合格できませんでした。", "target_word": "足りなくて", "complexity_tier": "T3", "furigana": "てんすうがいちてんたりなくて、しけんにごうかくできませんでした。", "sentence_source": "generated"}, {"text": "冷蔵庫の食料はまだ足りているので、買いに行かなくて大丈夫です。", "target_word": "足りている", "complexity_tier": "T3", "furigana": "れいぞうこのしょくりょうはまだたりているので、かいにいかなくてだいじょうぶです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "足りる", "label": "辞書形"}, {"form": "足りています", "label": "ている形"}, {"form": "足りて", "label": "て形"}, {"form": "足りない", "label": "ない形"}, {"form": "足りなくて", "label": "なくて形"}, {"form": "足りていれば", "label": "仮定形"}], "register": "丁寧", "sense_fingerprint": "必要な数量や程度に達していて不足がないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38157, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足りて", "is_correct": true, "explanation": "て形で、読点の後に続く文へつながる。"}, {"text": "足りる", "is_correct": false, "explanation": "辞書形は読点の前に置くと文が途切れ、後の文へつながらない。"}, {"text": "足りよう", "is_correct": false, "explanation": "意志形は後の文へつながらず、文法的に不自然。"}, {"text": "足りました", "is_correct": false, "explanation": "過去の丁寧形は読点の前で文が切れ、後の文と成立しない。"}], "explanations": {"足りて": "て形で、読点の後に続く文へつながる。", "足りる": "辞書形は読点の前に置くと文が途切れ、後の文へつながらない。", "足りよう": "意志形は後の文へつながらず、文法的に不自然。", "足りました": "過去の丁寧形は読点の前で文が切れ、後の文と成立しない。"}, "sentence_index": 0, "correct_answer": "足りて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の資料は多すぎて、ほとんど足りています。", "explanation": "ここは〈余る〉の意味。多すぎる状態は「足りる」ではなく「余る」で表す。"}, {"text": "急いだので、なんとか始業時間に足りました。", "explanation": "ここは〈間に合う〉の意味。時間に遅れないことは「足りる」では表さないので合わない。"}, {"text": "千円と五百円が足りると、千五百円になります。", "explanation": "ここは〈足す〉の意味。足りるは量が十分かを表し、数を加える意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38157, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足りている", "is_correct": true, "explanation": "「足りているか」の形で、状態を確認する疑問として自然に続く。"}, {"text": "足りますよ", "is_correct": false, "explanation": "丁寧な言い切りに「よ」が付き、「か」に続かず成り立たない。"}, {"text": "足りなくて", "is_correct": false, "explanation": "なくて形は「か」に続かず、文が成り立たない。"}, {"text": "足りないで", "is_correct": false, "explanation": "否定の「ないで」形は「か」に続かず、文が成り立たない。"}], "explanations": {"足りている": "「足りているか」の形で、状態を確認する疑問として自然に続く。", "足りますよ": "丁寧な言い切りに「よ」が付き、「か」に続かず成り立たない。", "足りなくて": "なくて形は「か」に続かず、文が成り立たない。", "足りないで": "否定の「ないで」形は「か」に続かず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "足りている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お腹が足りて、もう何も食べられません。", "explanation": "ここは〈満腹〉の意味。お腹の状態には「いっぱい」を使い、「足りる」は合わない。"}, {"text": "連絡が足りて、すぐに返事をくれました。", "explanation": "ここは〈届く〉の意味。連絡が相手に届くことは「足りる」では表さない。"}, {"text": "友だちが足りて、週末は一緒に出かけました。", "explanation": "ここは〈そろう〉の意味。人数が揃う意味は「足りる」ではなく「そろう」で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38157, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "材料を足りていれば、すぐ作り始められます。", "corrected_sentence": "材料が足りていれば、すぐ作り始められます。", "error_description": "「足りる」は主語を「が」で示す。「を」は誤りで、正しくは「材料が足りていれば」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "足りない", "is_correct": true, "explanation": "ない形で「足りないので」と理由を述べ、文が成り立つ。"}, {"text": "足りなくて", "is_correct": false, "explanation": "なくて形は「ので」に続かず、文法的に不自然。"}, {"text": "足りよう", "is_correct": false, "explanation": "意志形は「ので」に続かず、文として成り立たない。"}, {"text": "足りず", "is_correct": false, "explanation": "連用形は「ので」に続けると文語的で不自然。"}], "correct_form": "足りない", "base_form": "足りる", "form_label": "ない形", "sentence_index": 1, "explanations": {"足りない": "ない形で「足りないので」と理由を述べ、文が成り立つ。", "足りなくて": "なくて形は「ので」に続かず、文法的に不自然。", "足りよう": "意志形は「ので」に続かず、文として成り立たない。", "足りず": "連用形は「ので」に続けると文語的で不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38157, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この箱の数は、生徒の人数に足るます。", "corrected_sentence": "この箱の数は、生徒の人数に足ります。", "error_description": "「足る」に「ます」は続かず、正しくは「足ります」。語尾の形が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "足りていれば", "is_correct": true, "explanation": "仮定形で「足りていれば」と条件を示し、文が成り立つ。"}, {"text": "足りた", "is_correct": false, "explanation": "過去形は仮定の「れば」に直接続かず、不自然。"}, {"text": "足りよう", "is_correct": false, "explanation": "意志形は条件の文に続かず、文として成り立たない。"}, {"text": "足りて", "is_correct": false, "explanation": "て形は「れば」に続かず、文として成立しない。"}], "correct_form": "足りていれば", "base_form": "足りる", "form_label": "仮定形", "sentence_index": 7, "explanations": {"足りていれば": "仮定形で「足りていれば」と条件を示し、文が成り立つ。", "足りた": "過去形は仮定の「れば」に直接続かず、不自然。", "足りよう": "意志形は条件の文に続かず、文として成り立たない。", "足りて": "て形は「れば」に続かず、文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
