INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38158, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「データを防ぐ」で、防ぐの目的語を示す助詞に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「データへ防ぐ」は方向の助詞で、防ぐの対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「消えるのが防ぐ」は目的語がなく、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「データと防ぐ」は並列の助詞で、防ぐの対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「データを防ぐ」で、防ぐの目的語を示す助詞に合う。", "へ": "「データへ防ぐ」は方向の助詞で、防ぐの対象を示せない。", "が": "「消えるのが防ぐ」は目的語がなく、文が成り立たない。", "と": "「データと防ぐ」は並列の助詞で、防ぐの対象にならない。"}, "error_tags": {"へ": "方向の誤り", "と": "並列の誤り", "が": "主語の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38158, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "わるいことが おこらないように する こと。", "primary_collocate": null, "pronunciation": "ふせぐ", "ipa": "ɸɯseɡɯ", "syllable_count": 3, "sentences": [{"text": "風邪を防ぐために、毎日うがいをします。", "target_word": "防ぐ", "complexity_tier": "T2", "furigana": "風邪[かぜ]を防[ふせ]ぐために、毎日[まいにち]うがいをします。", "sentence_source": "generated"}, {"text": "マスクをして、ウイルスが入るのを防ぐ。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "マスクをして、ウイルスが入[はい]るのを防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "窓に網戸をつけて、蚊が入るのを防ぎます。", "target_word": "防ぎます", "complexity_tier": "T3", "furigana": "窓[まど]に網戸[あみど]をつけて、蚊[か]が入[はい]るのを防[ふせ]ぎます。", "sentence_source": "generated"}, {"text": "転ぶのを防ぐため、階段に手すりを付けた。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "転[ころ]ぶのを防[ふせ]ぐため、階段[かいだん]に手[て]すりを付[つ]けた。", "sentence_source": "generated"}, {"text": "犯罪を防ぐために、町に防犯カメラが増えています。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "犯罪[はんざい]を防[ふせ]ぐために、町[まち]に防犯[ぼうはん]カメラが増[ふ]えています。", "sentence_source": "generated"}, {"text": "帽子は、強い日ざしを防ぐのに役立つ。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "帽子[ぼうし]は、強[つよ]い日[ひ]ざしを防[ふせ]ぐのに役立[やくだ]つ。", "sentence_source": "generated"}, {"text": "水道が凍るのを防ぐには、夜に少し水を出しておくといい。", "target_word": "防ぐ", "complexity_tier": "T4", "furigana": "水道[すいどう]が凍[こお]るのを防[ふせ]ぐには、夜[よる]に少[すこ]し水[みず]を出[だ]しておくといい。", "sentence_source": "generated"}, {"text": "データが消えるのを防ぐため、こまめに保存してください。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "データが消[き]えるのを防[ふせ]ぐため、こまめに保存[ほぞん]してください。", "sentence_source": "generated"}, {"text": "食べ物が腐るのを防ぐ方法を、母が教えてくれた。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]が腐[くさ]るのを防[ふせ]ぐ方法[ほうほう]を、母[はは]が教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "塀を高くして、犬が外に出るのを防いだ。", "target_word": "防いだ", "complexity_tier": "T3", "furigana": "塀[へい]を高[たか]くして、犬[いぬ]が外[そと]に出[で]るのを防[ふせ]いだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "防ぐ", "label": "辞書形"}, {"form": "防ぎます", "label": "丁寧形"}, {"form": "防いだ", "label": "過去形"}, {"form": "防いで", "label": "て形"}, {"form": "防がない", "label": "否定形"}, {"form": "防げば", "label": "仮定形"}, {"form": "防げる", "label": "可能形"}, {"form": "防ごう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "悪いことが起こらないように、あらかじめ何かをしておく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38158, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防ぐ", "is_correct": true, "explanation": "「風邪を防ぐために」で、風邪にならないよう前もって予防する意味になり、文に合う。"}, {"text": "数える", "is_correct": false, "explanation": "「風邪を数えるために」は意味が通らず、予防の目的に合わない。"}, {"text": "磨く", "is_correct": false, "explanation": "「風邪を磨くために」は不自然で、予防の目的にならない。"}, {"text": "眺める", "is_correct": false, "explanation": "「風邪を眺めるために」は意味が通らず、予防の目的に合わない。"}], "explanations": {"防ぐ": "「風邪を防ぐために」で、風邪にならないよう前もって予防する意味になり、文に合う。", "数える": "「風邪を数えるために」は意味が通らず、予防の目的に合わない。", "磨く": "「風邪を磨くために」は不自然で、予防の目的にならない。", "眺める": "「風邪を眺めるために」は意味が通らず、予防の目的に合わない。"}, "sentence_index": 0, "correct_answer": "防ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "贈り物が傷つかないように、紙でプレゼントを防いだ。", "explanation": "ここは〈包む〉（外側を覆う）の意味。〈防ぐ〉は悪いことを前もって起こさないことで、物を覆う動作には使わないので合わない。"}, {"text": "ぶつかりそうな自転車を防いで、道を渡った。", "explanation": "ここは〈避ける〉の意味。〈防ぐ〉は悪いことを起こさないことで、相手を避けて進む動きには使わない。"}, {"text": "足元がふらつかないように、手すりで体を防いだ。", "explanation": "ここは〈支える〉の意味。〈防ぐ〉は悪いことが起こらないようにすることで、体を支える動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38158, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防ぐ", "is_correct": true, "explanation": "「凍るのを防ぐ」で、凍結を前もって防ぐ意味になり、文に合う。"}, {"text": "試す", "is_correct": false, "explanation": "「凍るのを試す」は意味が通らず、防ぐ目的に合わない。"}, {"text": "促す", "is_correct": false, "explanation": "「凍るのを促す」は意味が逆になり、防ぐ意味にならない。"}, {"text": "任せる", "is_correct": false, "explanation": "「凍るのを任せる」は成り立たず、防ぐ意味にならない。"}], "explanations": {"防ぐ": "「凍るのを防ぐ」で、凍結を前もって防ぐ意味になり、文に合う。", "試す": "「凍るのを試す」は意味が通らず、防ぐ目的に合わない。", "促す": "「凍るのを促す」は意味が逆になり、防ぐ意味にならない。", "任せる": "「凍るのを任せる」は成り立たず、防ぐ意味にならない。"}, "sentence_index": 6, "correct_answer": "防ぐ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風で飛ばないように、帽子を手で防いだ。", "explanation": "ここは〈押さえる〉の意味。〈防ぐ〉は悪いことを前もって起こさないことで、物を手で押さえる動作には使わない。"}, {"text": "教室で、プリントを一人ずつ防いだ。", "explanation": "ここは〈配る〉（一人ずつ渡す）の意味。〈防ぐ〉は悪いことを前もって起こさないことで、物を渡す動作には使わないので合わない。"}, {"text": "散らかった部屋を、人に見せないように防いだ。", "explanation": "ここは〈隠す〉の意味。〈防ぐ〉は悪い事態を起こさないことで、物を見えないように隠す行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38158, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "虫刺されを防げるため、長袖を着る。", "corrected_sentence": "虫刺されを防ぐため、長袖を着る。", "error_description": "「ため」の前は辞書形が正しい。「防げる」は可能形で、目的を示す文には合わない。正しくは「防ぐため」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "防ぐ", "is_correct": true, "explanation": "辞書形で、ウイルスの侵入を止める動作を表し、文末に合う。"}, {"text": "防がない", "is_correct": false, "explanation": "否定形で、ウイルスの侵入を止めないという意味になり、文に合わない。"}, {"text": "防げば", "is_correct": false, "explanation": "仮定形で、文末の形として不完全であり、文の骨組みに合わない。"}, {"text": "防いで", "is_correct": false, "explanation": "て形で文を終えられず、文の骨組みに合わない。"}], "correct_form": "防ぐ", "base_form": "防ぐ", "form_label": "辞書形", "sentence_index": 1, "explanations": {"防ぐ": "辞書形で、ウイルスの侵入を止める動作を表し、文末に合う。", "防がない": "否定形で、ウイルスの侵入を止めないという意味になり、文に合わない。", "防げば": "仮定形で、文末の形として不完全であり、文の骨組みに合わない。", "防いで": "て形で文を終えられず、文の骨組みに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38158, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日射しが防ぐため、カーテンを閉めた。", "corrected_sentence": "日射しを防ぐため、カーテンを閉めた。", "error_description": "「防ぐ」の目的語は「日射し」なので「を」が必要。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "防ぐ", "is_correct": true, "explanation": "辞書形で、「消えるのを防ぐため」の目的を表す形に合う。"}, {"text": "防げる", "is_correct": false, "explanation": "可能形で、目的を示す「ため」の前には合わない。"}, {"text": "防ごう", "is_correct": false, "explanation": "意志形で、文の途中で目的を示すには合わない。"}, {"text": "防いで", "is_correct": false, "explanation": "て形で「ため」に続けると不自然で、目的表現に合わない。"}], "correct_form": "防ぐ", "base_form": "防ぐ", "form_label": "辞書形", "sentence_index": 7, "explanations": {"防ぐ": "辞書形で、「消えるのを防ぐため」の目的を表す形に合う。", "防げる": "可能形で、目的を示す「ため」の前には合わない。", "防ごう": "意志形で、文の途中で目的を示すには合わない。", "防いで": "て形で「ため」に続けると不自然で、目的表現に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38159, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「病気を防ぐ」で、防ぐの目的語に付く助詞で文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「病気に防ぐ」は成り立たず、防ぐの対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「病気で防ぐ」は手段の意味にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「病気へ防ぐ」は方向を表す助詞で、防ぐの対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "「病気を防ぐ」で、防ぐの目的語に付く助詞で文に合う。", "に": "「病気に防ぐ」は成り立たず、防ぐの対象を示せない。", "で": "「病気で防ぐ」は手段の意味にならず不自然。", "へ": "「病気へ防ぐ」は方向を表す助詞で、防ぐの対象には合わない。"}, "error_tags": {"に": "対象の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38159, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「けがを防いだ」で、防ぐの対象を表す助詞に合う。"}, {"text": "へ", "is_correct": false, "explanation": "「けがへ防いだ」は方向を表す助詞で、防ぐの対象には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「けがより防いだ」は比較の助詞で、防ぐの対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「けがと防いだ」は並列の助詞で、防ぐの対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「けがを防いだ」で、防ぐの対象を表す助詞に合う。", "へ": "「けがへ防いだ」は方向を表す助詞で、防ぐの対象には合わない。", "より": "「けがより防いだ」は比較の助詞で、防ぐの対象を示せない。", "と": "「けがと防いだ」は並列の助詞で、防ぐの対象を示せない。"}, "error_tags": {"へ": "方向の誤り", "より": "比較の誤り", "と": "並列の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38159, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "悪いことや困ったことが起こらないように、前もって防ぐこと。", "primary_collocate": null, "pronunciation": "ふせぐ", "ipa": "ɸɯseɡɯ", "syllable_count": 3, "sentences": [{"text": "この際、脂質の膜がジャムの水分浸透を防ぐバリアーとして機能するという科学的裏付けも無視できない。", "target_word": "防ぐ", "complexity_tier": "T5", "furigana": "この際[さい]、脂質[ししつ]の膜[まく]がジャムの水分[すいぶん]浸透[しんとう]を防[ふせ]ぐバリアーとして機能[きのう]するという科学的[かがくてき]裏付[うらづ]けも無視[むし]できない。", "sentence_source": "mined"}, {"text": "手洗いは、病気を防ぐいちばん簡単な方法です。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "手洗[てあら]いは、病気[びょうき]を防[ふせ]ぐいちばん簡単[かんたん]な方法[ほうほう]です。", "sentence_source": "generated"}, {"text": "日焼け止めを塗って、日焼けを防ぐ。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "日焼[ひや]け止[ど]めを塗[ぬ]って、日焼[ひや]けを防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "事故を防ぐために、毎朝車の点検をしています。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "事故[じこ]を防[ふせ]ぐために、毎朝[まいあさ]車[くるま]の点検[てんけん]をしています。", "sentence_source": "generated"}, {"text": "窓を二重にすると、冬の寒さを防ぐことができる。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "窓[まど]を二重[にじゅう]にすると、冬[ふゆ]の寒[さむ]さを防[ふせ]ぐことができる。", "sentence_source": "generated"}, {"text": "インフルエンザを防ぐために、予防接種を受けました。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "インフルエンザを防[ふせ]ぐために、予防接種[よぼうせっしゅ]を受[う]けました。", "sentence_source": "generated"}, {"text": "パスワードを変えれば、不正なアクセスを防げます。", "target_word": "防げます", "complexity_tier": "T3", "furigana": "パスワードを変[か]えれば、不正[ふせい]なアクセスを防[ふせ]げます。", "sentence_source": "generated"}, {"text": "先生の注意のおかげで、大きなけがを防いだ。", "target_word": "防いだ", "complexity_tier": "T3", "furigana": "先生[せんせい]の注意[ちゅうい]のおかげで、大[おお]きなけがを防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "火事を防ぐため、寝る前にストーブを消してください。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "火事[かじ]を防[ふせ]ぐため、寝[ね]る前[まえ]にストーブを消[け]してください。", "sentence_source": "generated"}, {"text": "木を植えて、山の土砂崩れを防ぐ。", "target_word": "防ぐ", "complexity_tier": "T3", "furigana": "木[き]を植[う]えて、山[やま]の土砂崩[どしゃくず]れを防[ふせ]ぐ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "防ぐ", "label": "辞書形"}, {"form": "防ぎます", "label": "丁寧形"}, {"form": "防いだ", "label": "過去形"}, {"form": "防いで", "label": "て形"}, {"form": "防がない", "label": "否定形"}, {"form": "防げば", "label": "仮定形"}, {"form": "防げる", "label": "可能形"}, {"form": "防ごう", "label": "意志形"}], "register": "中立", "sense_fingerprint": "悪い事態が起こる前に手を打って、起こらないようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b78d2d53-321c-4106-8d9f-0277da1b53d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38159, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防ぐ", "is_correct": true, "explanation": "「浸透を防ぐバリアー」で、水分の浸透を前もって止める意味になり、文に合う。"}, {"text": "眺める", "is_correct": false, "explanation": "「浸透を眺めるバリアー」は意味が通らず、防ぐ働きを表さないので合わない。"}, {"text": "焼く", "is_correct": false, "explanation": "「浸透を焼くバリアー」は不自然で、防ぐ意味にならない。"}, {"text": "叩く", "is_correct": false, "explanation": "「浸透を叩くバリアー」は成り立たず、防ぐ意味に合わない。"}], "explanations": {"防ぐ": "「浸透を防ぐバリアー」で、水分の浸透を前もって止める意味になり、文に合う。", "眺める": "「浸透を眺めるバリアー」は意味が通らず、防ぐ働きを表さないので合わない。", "焼く": "「浸透を焼くバリアー」は不自然で、防ぐ意味にならない。", "叩く": "「浸透を叩くバリアー」は成り立たず、防ぐ意味に合わない。"}, "sentence_index": 0, "correct_answer": "防ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ずれないように、髪の毛をピンで防いだ。", "explanation": "ここは〈留める〉（ピンなどで固定する）の意味。〈防ぐ〉は悪いことを前もって起こさないことで、物を固定する動作には使わないので合わない。"}, {"text": "人混みを防いで、遠回りして帰った。", "explanation": "ここは〈避ける〉の意味。〈防ぐ〉は悪いことが起こらないようにすることで、人混みを避けて進む行動は表さない。"}, {"text": "大切な人を防ぐために、毎朝声をかける。", "explanation": "ここは〈守る〉の意味。人を悪いことから守る場面では〈守る〉を使い、〈防ぐ〉は悪い出来事を起こさせないことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38159, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防げます", "is_correct": true, "explanation": "「不正なアクセスを防げます」で、起こらないようにできる意味になり、文に合う。"}, {"text": "数えます", "is_correct": false, "explanation": "「不正なアクセスを数えます」は意味が通らず、防ぐ内容に合わない。"}, {"text": "磨きます", "is_correct": false, "explanation": "「不正なアクセスを磨きます」は成り立たず、防ぐ意味にならない。"}, {"text": "測ります", "is_correct": false, "explanation": "「不正なアクセスを測ります」は不自然で、防ぐ意味にならない。"}], "explanations": {"防げます": "「不正なアクセスを防げます」で、起こらないようにできる意味になり、文に合う。", "数えます": "「不正なアクセスを数えます」は意味が通らず、防ぐ内容に合わない。", "磨きます": "「不正なアクセスを磨きます」は成り立たず、防ぐ意味にならない。", "測ります": "「不正なアクセスを測ります」は不自然で、防ぐ意味にならない。"}, "sentence_index": 6, "correct_answer": "防げます"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ブレーキを踏んで、車を防いだ。", "explanation": "ここは〈止める〉の意味。〈防ぐ〉は悪い事態を起こさないことで、動いている車を止める意味にはならない。"}, {"text": "紙が飛ばないように、紙を防いだ。", "explanation": "ここは〈押さえる〉の意味。〈防ぐ〉は悪い事態を前もって起こさないことで、物を手で押さえる動作には使わない。"}, {"text": "湯のみに、お茶をそっと防いだ。", "explanation": "ここは〈注ぐ〉の意味。〈防ぐ〉は悪いことを起こさないことで、飲み物を入れる動作には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38159, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ひざのけがに防ぐため、毎日ストレッチをする。", "corrected_sentence": "ひざのけがを防ぐため、毎日ストレッチをする。", "error_description": "「防ぐ」の目的語には「を」が必要。正しくは「を」で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "防ぐ", "is_correct": true, "explanation": "「方法」を修飾する辞書形で、文の骨組みに合う。"}, {"text": "防ごう", "is_correct": false, "explanation": "意志形で、名詞を修飾する形にならず「方法」に続かない。"}, {"text": "防いで", "is_correct": false, "explanation": "て形で名詞を修飾できず、「方法」に続かない。"}, {"text": "防げば", "is_correct": false, "explanation": "仮定形で、名詞を修飾できず、文の骨組みに合わない。"}], "correct_form": "防ぐ", "base_form": "防ぐ", "form_label": "辞書形", "sentence_index": 1, "explanations": {"防ぐ": "「方法」を修飾する辞書形で、文の骨組みに合う。", "防ごう": "意志形で、名詞を修飾する形にならず「方法」に続かない。", "防いで": "て形で名詞を修飾できず、「方法」に続かない。", "防げば": "仮定形で、名詞を修飾できず、文の骨組みに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38159, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの事故を防ぎますため、柵を付けた。", "corrected_sentence": "子どもの事故を防ぐため、柵を付けた。", "error_description": "「ため」の前は辞書形が必要。「防ぎます」は丁寧形で、ここでは使えない。正しくは「防ぐため」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "防いだ", "is_correct": true, "explanation": "過去形で、既に防げた出来事の文末に合う。"}, {"text": "防げる", "is_correct": false, "explanation": "可能形で、既に起きた事実を述べる過去の文末に合わない。"}, {"text": "防がない", "is_correct": false, "explanation": "否定形で、先生の注意のおかげで防げた出来事を述べる文と矛盾する。"}, {"text": "防ぎ", "is_correct": false, "explanation": "連用形で、文末に置けず「防ぎ。」では文として成り立たない。"}], "correct_form": "防いだ", "base_form": "防ぐ", "form_label": "過去形", "sentence_index": 7, "explanations": {"防いだ": "過去形で、既に防げた出来事の文末に合う。", "防げる": "可能形で、既に起きた事実を述べる過去の文末に合わない。", "防がない": "否定形で、先生の注意のおかげで防げた出来事を述べる文と矛盾する。", "防ぎ": "連用形で、文末に置けず「防ぎ。」では文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bed3930-1dc4-4c66-93c1-e1259d0e962b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38160, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「家族みんなが幸せに暮らせる」の主語を示す格助詞で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「暮らす」は目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "「家族みんなの幸せに暮らせる」となり、文の主語として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「家族みんなから」は起点になり、主語としては意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「家族みんなが幸せに暮らせる」の主語を示す格助詞で、正しい。", "を": "「暮らす」は目的語を取らない自動詞なので、「を」は合わない。", "の": "「家族みんなの幸せに暮らせる」となり、文の主語として成り立たない。", "から": "「家族みんなから」は起点になり、主語としては意味が通らない。"}, "error_tags": {"を": "目的語（自動詞には不要）", "の": "連体修飾（主語にならない）", "から": "起点（主語にならない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38160, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「国で幸せに暮らす」の場所を表す助詞で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "暮らすは目的語を取らない自動詞なので、「国を」では文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「国と幸せに暮らし」は並列の意味になり、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「国へ」は方向を表すので、この文で暮らす場所を示せない。"}], "correct_answer": "で", "explanations": {"で": "「国で幸せに暮らす」の場所を表す助詞で、正しい。", "を": "暮らすは目的語を取らない自動詞なので、「国を」では文が成り立たない。", "と": "「国と幸せに暮らし」は並列の意味になり、文が通らない。", "へ": "「国へ」は方向を表すので、この文で暮らす場所を示せない。"}, "error_tags": {"を": "目的語（自動詞には不要）", "と": "並列・共同", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38160, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "みんながいいきもちでくらすこと。", "primary_collocate": null, "pronunciation": "しあわせにくらす", "ipa": "ɕiawaseni kɯɾasɯ", "syllable_count": 8, "sentences": [{"text": "二人は小さな町で、幸せに暮らしている。", "target_word": "幸せに暮らして", "complexity_tier": "T3", "furigana": "二人[ふたり]は小[ちい]さな町[まち]で、幸[しあわ]せに暮[く]らしている。", "sentence_source": "generated"}, {"text": "家族みんなが幸せに暮らせる家を建てたい。", "target_word": "幸せに暮らせる", "complexity_tier": "T3", "furigana": "家族[かぞく]みんなが幸[しあわ]せに暮[く]らせる家[いえ]を建[た]てたい。", "sentence_source": "generated"}, {"text": "昔々、王様は国の人々と幸せに暮らしたそうだ。", "target_word": "幸せに暮らした", "complexity_tier": "T3", "furigana": "昔々[むかしむかし]、王様[おうさま]は国[くに]の人々[ひとびと]と幸[しあわ]せに暮[く]らしたそうだ。", "sentence_source": "generated"}, {"text": "お金がなくても、仲のよい家族は幸せに暮らす。", "target_word": "幸せに暮らす", "complexity_tier": "T3", "furigana": "お金[かね]がなくても、仲[なか]のよい家族[かぞく]は幸[しあわ]せに暮[く]らす。", "sentence_source": "generated"}, {"text": "祖父母は海の近くで、毎日幸せに暮らしている。", "target_word": "幸せに暮らして", "complexity_tier": "T3", "furigana": "祖父母[そふぼ]は海[うみ]の近[ちか]くで、毎日[まいにち]幸[しあわ]せに暮[く]らしている。", "sentence_source": "generated"}, {"text": "みんなが幸せに暮らすために、町のルールを作った。", "target_word": "幸せに暮らす", "complexity_tier": "T3", "furigana": "みんなが幸[しあわ]せに暮[く]らすために、町[まち]のルールを作[つく]った。", "sentence_source": "generated"}, {"text": "彼は犬と猫に囲まれて幸せに暮らしている。", "target_word": "幸せに暮らして", "complexity_tier": "T3", "furigana": "彼[かれ]は犬[いぬ]と猫[ねこ]に囲[かこ]まれて幸[しあわ]せに暮[く]らしている。", "sentence_source": "generated"}, {"text": "戦争のない国で幸せに暮らしたいと、彼女は話した。", "target_word": "幸せに暮らし", "complexity_tier": "T4", "furigana": "戦争[せんそう]のない国[くに]で幸[しあわ]せに暮[く]らしたいと、彼女[かのじょ]は話[はな]した。", "sentence_source": "generated"}, {"text": "物語の最後で、主人公は友達と幸せに暮らした。", "target_word": "幸せに暮らした", "complexity_tier": "T3", "furigana": "物語[ものがたり]の最後[さいご]で、主人公[しゅじんこう]は友達[ともだち]と幸[しあわ]せに暮[く]らした。", "sentence_source": "generated"}, {"text": "毎日笑って、幸せに暮らすことが私の夢だ。", "target_word": "幸せに暮らす", "complexity_tier": "T3", "furigana": "毎日[まいにち]笑[わら]って、幸[しあわ]せに暮[く]らすことが私[わたし]の夢[ゆめ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸せに暮らす", "label": "基本形"}, {"form": "幸せに暮らして", "label": "て形"}, {"form": "幸せに暮らした", "label": "過去形"}, {"form": "幸せに暮らせる", "label": "可能形"}, {"form": "幸せに暮らし", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "満ち足りた気持ちで毎日の生活を送ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38160, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幸せに暮らして", "is_correct": true, "explanation": "「いる」の前には て形が入るので、「幸せに暮らしている」で正しい。"}, {"text": "幸せに暮らす", "is_correct": false, "explanation": "辞書形は「いる」に直接続かないので、「暮らすいる」となり文が成り立たない。"}, {"text": "幸せに暮らした", "is_correct": false, "explanation": "過去形は「いる」の前に置けないので、この位置では不自然。"}, {"text": "幸せに暮らし", "is_correct": false, "explanation": "連用形だけでは「いる」に続かないので、文として完結しない。"}], "explanations": {"幸せに暮らして": "「いる」の前には て形が入るので、「幸せに暮らしている」で正しい。", "幸せに暮らす": "辞書形は「いる」に直接続かないので、「暮らすいる」となり文が成り立たない。", "幸せに暮らした": "過去形は「いる」の前に置けないので、この位置では不自然。", "幸せに暮らし": "連用形だけでは「いる」に続かないので、文として完結しない。"}, "sentence_index": 0, "correct_answer": "幸せに暮らして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "連休は友達と幸せに暮らした。", "explanation": "ここは〈楽しく過ごす〉の意味。幸せに暮らすは生活全体の長い期間を指すので、連休のような短い期間には合わない。"}, {"text": "花火を見て、みんなは幸せに暮らした。", "explanation": "ここは〈楽しむ〉の意味。幸せに暮らすは生活全体を指す言葉なので、一度の花火のような出来事には合わない。"}, {"text": "大好きなケーキを、彼は幸せに暮らした。", "explanation": "ここは〈味わう〉の意味。食べ物を楽しむ場面では味わうを使い、幸せに暮らすは生活全体を指すので物を目的語にとれず合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38160, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幸せに暮らして", "is_correct": true, "explanation": "「いる」の前には て形が入るので、「囲まれて幸せに暮らしている」で正しい。"}, {"text": "幸せに暮らさない", "is_correct": false, "explanation": "否定形は「いる」に続かないので、文として成り立たない。"}, {"text": "幸せに暮らそう", "is_correct": false, "explanation": "意志形は「いる」に続かないので、文が通らない。"}, {"text": "幸せに暮らせない", "is_correct": false, "explanation": "否定の可能形は「いる」の前に置けないので、この位置では不自然。"}], "explanations": {"幸せに暮らして": "「いる」の前には て形が入るので、「囲まれて幸せに暮らしている」で正しい。", "幸せに暮らさない": "否定形は「いる」に続かないので、文として成り立たない。", "幸せに暮らそう": "意志形は「いる」に続かないので、文が通らない。", "幸せに暮らせない": "否定の可能形は「いる」の前に置けないので、この位置では不自然。"}, "sentence_index": 6, "correct_answer": "幸せに暮らして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大地震の中で、彼は奇跡的に幸せに暮らした。", "explanation": "ここは〈生き延びる〉の意味。危機を切り抜けた場面では、平穏な生活を表す幸せに暮らすは合わない。"}, {"text": "給料が少ない月も、彼は家計を幸せに暮らした。", "explanation": "ここは〈やりくりする〉の意味。家計の工夫を言う場面では、生活全体の幸福を表す幸せに暮らすは合わない。"}, {"text": "事故のあと、彼の命は幸せに暮らした。", "explanation": "ここは〈助かる〉の意味。命が救われたことを言う場面で、生活の様子を表す幸せに暮らすは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38160, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は海辺の家で、幸せで暮らしている。", "corrected_sentence": "彼女は海辺の家で、幸せに暮らしている。", "error_description": "「幸せ」は形容動詞なので、動詞「暮らす」を修飾する副詞として使うには「幸せに」の形が必要。「幸せで」は誤りで、正しくは「幸せに」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "幸せに暮らせる", "is_correct": true, "explanation": "「家」を修飾する可能形で、家族が幸せに暮らせる家という意味になり正しい。"}, {"text": "幸せに暮らして", "is_correct": false, "explanation": "て形は名詞「家」を直接修飾できないので、この位置では成り立たない。"}, {"text": "幸せに暮らし", "is_correct": false, "explanation": "連用形だけでは「家」を修飾できないので、文が通らない。"}, {"text": "幸せに暮らせ", "is_correct": false, "explanation": "命令形なので、「家」を修飾する形としては不適切。"}], "correct_form": "幸せに暮らせる", "base_form": "幸せに暮らす", "form_label": "可能形", "sentence_index": 1, "explanations": {"幸せに暮らせる": "「家」を修飾する可能形で、家族が幸せに暮らせる家という意味になり正しい。", "幸せに暮らして": "て形は名詞「家」を直接修飾できないので、この位置では成り立たない。", "幸せに暮らし": "連用形だけでは「家」を修飾できないので、文が通らない。", "幸せに暮らせ": "命令形なので、「家」を修飾する形としては不適切。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38160, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は祖母と幸せに暮らされている。", "corrected_sentence": "彼女は祖母と幸せに暮らしている。", "error_description": "「暮らす」は自動詞なので受身にはできない。「暮らされている」は誤りで、正しくは「暮らしている」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "幸せに暮らし", "is_correct": true, "explanation": "「たい」の前は連用形なので、「暮らしたい」となり文が通る。"}, {"text": "幸せに暮らさない", "is_correct": false, "explanation": "否定形は「たい」の前に置けないので、文が成り立たない。"}, {"text": "幸せに暮らそう", "is_correct": false, "explanation": "意志形は「たい」に続かないので、この位置では合わない。"}, {"text": "幸せに暮らせない", "is_correct": false, "explanation": "否定の可能形は「たい」に続かないので、文として通らない。"}], "correct_form": "幸せに暮らし", "base_form": "幸せに暮らす", "form_label": "連用形", "sentence_index": 7, "explanations": {"幸せに暮らし": "「たい」の前は連用形なので、「暮らしたい」となり文が通る。", "幸せに暮らさない": "否定形は「たい」の前に置けないので、文が成り立たない。", "幸せに暮らそう": "意志形は「たい」に続かないので、この位置では合わない。", "幸せに暮らせない": "否定の可能形は「たい」に続かないので、文として通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38162, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「時間が知れる」の主語を示す格で、文の形に合う。"}, {"text": "と", "is_correct": false, "explanation": "「時間と知れます」は並列の「と」が入り、主語が立たず文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「時間に知れる」は場所や相手を表し、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は主語の位置に入らず、不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「時間が知れる」の主語を示す格で、文の形に合う。", "と": "「時間と知れます」は並列の「と」が入り、主語が立たず文が成り立たない。", "に": "「時間に知れる」は場所や相手を表し、主語を示せない。", "へ": "方向を表す「へ」は主語の位置に入らず、不自然になる。"}, "error_tags": {"と": "並列の格", "に": "位置・相手の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38162, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「社会の動きが知れる」の主語を示す格で、文の形に合う。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を表す「と」は、知れるの主語として不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は、動詞の主語の位置に入らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」は、この文の主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「社会の動きが知れる」の主語を示す格で、文の形に合う。", "と": "並列や引用を表す「と」は、知れるの主語として不自然。", "の": "連体修飾の「の」は、動詞の主語の位置に入らない。", "より": "比較を表す「より」は、この文の主語の位置には合わない。"}, "error_tags": {"と": "並列・引用の格", "の": "連体修飾の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38162, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "「知れる」は、「知る」という言葉の「できる」という形で、自分から知ることができるという意味です。", "primary_collocate": null, "pronunciation": "しれる", "ipa": "ɕiɾeɾɯ", "syllable_count": 3, "sentences": [{"text": "この本を読めば、昔の人の暮らしが知れます。", "target_word": "知れます", "complexity_tier": "T3", "furigana": "この本[ほん]を読[よ]めば、昔[むかし]の人[ひと]の暮[く]らしが知[し]れます。", "sentence_source": "generated"}, {"text": "ホームページを見ると、お店の場所や時間が知れます。", "target_word": "知れます", "complexity_tier": "T3", "furigana": "ホームページを見[み]ると、お店[みせ]の場所[ばしょ]や時間[じかん]が知[し]れます。", "sentence_source": "generated"}, {"text": "図書館に行けば、町の歴史が知れます。", "target_word": "知れます", "complexity_tier": "T3", "furigana": "図書館[としょかん]に行[い]けば、町[まち]の歴史[れきし]が知[し]れます。", "sentence_source": "generated"}, {"text": "このアプリを使えば、乗る電車の遅れがすぐ知れます。", "target_word": "知れます", "complexity_tier": "T3", "furigana": "このアプリを使[つか]えば、乗[の]る電車[でんしゃ]の遅[おく]れがすぐ知[し]れます。", "sentence_source": "generated"}, {"text": "本人に聞かなければ、本当の気持ちは知れません。", "target_word": "知れません", "complexity_tier": "T3", "furigana": "本人[ほんにん]に聞[き]かなければ、本当[ほんとう]の気持[きも]ちは知[し]れません。", "sentence_source": "generated"}, {"text": "名前だけでは、どんな人かは知れません。", "target_word": "知れません", "complexity_tier": "T3", "furigana": "名前[なまえ]だけでは、どんな人[ひと]かは知[し]れません。", "sentence_source": "generated"}, {"text": "インターネットのおかげで、世界のニュースが早く知れるようになりました。", "target_word": "知れる", "complexity_tier": "T3", "furigana": "インターネットのおかげで、世界[せかい]のニュースが早[はや]く知[し]れるようになりました。", "sentence_source": "generated"}, {"text": "毎日新聞を読むと、社会の動きが知れるようになりました。", "target_word": "知れる", "complexity_tier": "T3", "furigana": "毎日[まいにち]新聞[しんぶん]を読[よ]むと、社会[しゃかい]の動[うご]きが知[し]れるようになりました。", "sentence_source": "generated"}, {"text": "その報告書を読んで、会社の経営状況がよく知れました。", "target_word": "知れました", "complexity_tier": "T3", "furigana": "その報告書[ほうこくしょ]を読[よ]んで、会社[かいしゃ]の経営[けいえい]状況[じょうきょう]がよく知[し]れました。", "sentence_source": "generated"}, {"text": "説明書を読めば、使い方が知れます。", "target_word": "知れます", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を読[よ]めば、使[つか]い方[かた]が知[し]れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "知れる", "label": "辞書形"}, {"form": "知れます", "label": "丁寧形"}, {"form": "知れない", "label": "否定形"}, {"form": "知れた", "label": "過去形"}, {"form": "知れて", "label": "て形"}, {"form": "知れれば", "label": "仮定形"}], "register": "丁寧語", "sense_fingerprint": "調べたり読んだりして自分から知ることができる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '725786b7-83d1-4185-8797-adecf4153e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38162, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知れます", "is_correct": true, "explanation": "「自分から知ることができる」の意味で、本を読んで昔の暮らしが分かるという文脈に合う。"}, {"text": "乾きます", "is_correct": false, "explanation": "「暮らしが乾く」は意味が通らず、文脈に合わない。"}, {"text": "冷めます", "is_correct": false, "explanation": "「暮らしが冷める」は比喩としても成り立たず、文脈に合わない。"}, {"text": "濡れます", "is_correct": false, "explanation": "「暮らしが濡れる」は文脈に合わず、知るという意味にもならない。"}], "explanations": {"知れます": "「自分から知ることができる」の意味で、本を読んで昔の暮らしが分かるという文脈に合う。", "乾きます": "「暮らしが乾く」は意味が通らず、文脈に合わない。", "冷めます": "「暮らしが冷める」は比喩としても成り立たず、文脈に合わない。", "濡れます": "「暮らしが濡れる」は文脈に合わず、知るという意味にもならない。"}, "sentence_index": 0, "correct_answer": "知れます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店のパンは、地元でよく知れている。", "explanation": "ここは〈知られている（評判が広まっている）〉の意味。知れるは自分から調べて知る意味で、評判が広がる意味では使わない。"}, {"text": "名の知れた画家の絵が、安く売られていた。", "explanation": "ここは〈有名だ〉の意味（名の知れた＝有名な）。自分から調べて知る〈知れる〉の意味では使わない。"}, {"text": "探していた鍵が、やっと知れた。", "explanation": "ここは〈見つける〉の意味。知れるは物の所在を見つける意味ではなく、情報を得る意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38162, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知れる", "is_correct": true, "explanation": "情報が手に入るようになるという意味で、ニュースが早く届く文脈に合う。"}, {"text": "焦げる", "is_correct": false, "explanation": "「ニュースが焦げる」は意味が通らず、文脈に合わない。"}, {"text": "縮む", "is_correct": false, "explanation": "「ニュースが縮む」は文脈に合わず、早く届くという意味にならない。"}, {"text": "凍る", "is_correct": false, "explanation": "「ニュースが凍る」は比喩としても不自然で、文脈に合わない。"}], "explanations": {"知れる": "情報が手に入るようになるという意味で、ニュースが早く届く文脈に合う。", "焦げる": "「ニュースが焦げる」は意味が通らず、文脈に合わない。", "縮む": "「ニュースが縮む」は文脈に合わず、早く届くという意味にならない。", "凍る": "「ニュースが凍る」は比喩としても不自然で、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "知れる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの選手の実力は、たかが知れている。", "explanation": "ここは〈たかが知れている＝大したことがない〉の意味。自分から調べて知る〈知れる〉の意味ではない。"}, {"text": "遠くから、子どもの笑い声が知れた。", "explanation": "ここは〈聞こえる〉の意味。知れるは情報を得て知る意味で、音が耳に入る意味では使わない。"}, {"text": "彼の嘘は、とうとう家族に知れてしまった。", "explanation": "ここは〈ばれる・世間に知られる〉の意味。自分から調べて知る意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38162, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ネットで調べれば、ラーメン屋の値段が知れるない。", "corrected_sentence": "ネットで調べれば、ラーメン屋の値段が知れない。", "error_description": "誤り：「知れるない」。否定形は「知れない」とし、辞書形の「る」を重ねない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "知れます", "is_correct": true, "explanation": "丁寧な肯定形で、見ると分かるという習慣の文に合う。"}, {"text": "知れません", "is_correct": false, "explanation": "否定になり「分からない」という意味になるため、場所や時間が分かると述べる文脈に合わない。"}, {"text": "知れた", "is_correct": false, "explanation": "過去形になり、いつも見ると分かるという習慣の意味に合わない。"}, {"text": "知れて", "is_correct": false, "explanation": "て形は文を言い切れないため、文末の述語として成立しない。"}], "correct_form": "知れます", "base_form": "知れる", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"知れます": "丁寧な肯定形で、見ると分かるという習慣の文に合う。", "知れません": "否定になり「分からない」という意味になるため、場所や時間が分かると述べる文脈に合わない。", "知れた": "過去形になり、いつも見ると分かるという習慣の意味に合わない。", "知れて": "て形は文を言い切れないため、文末の述語として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38162, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎日ニュースを読めば、社会の動きが知れるます。", "corrected_sentence": "毎日ニュースを読めば、社会の動きが知れます。", "error_description": "誤り：「知れるます」。正しくは「知れます」。「ます」は連用形（知れ）に付くので、辞書形「知れる」にはそのまま付けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "知れる", "is_correct": true, "explanation": "辞書形で、「ようになる」の前に置ける形。"}, {"text": "知れます", "is_correct": false, "explanation": "ます形は「ようになる」に続けられず、文が成立しない。"}, {"text": "知れない", "is_correct": false, "explanation": "否定形になると「知れなくなった」の意味になり、早く分かるようになった文脈と逆になる。"}, {"text": "知れれば", "is_correct": false, "explanation": "仮定形は「ようになりました」に続かず、文が成立しない。"}], "correct_form": "知れる", "base_form": "知れる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"知れる": "辞書形で、「ようになる」の前に置ける形。", "知れます": "ます形は「ようになる」に続けられず、文が成立しない。", "知れない": "否定形になると「知れなくなった」の意味になり、早く分かるようになった文脈と逆になる。", "知れれば": "仮定形は「ようになりました」に続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c79bc46-19d9-45e5-9271-8227047950b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
