INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38166, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "存在するものを示す「が」。「地があると知って」で、場所が存在することを表す。"}, {"text": "を", "is_correct": false, "explanation": "動作の対象を示す「を」。「地をあると知って」は存在を表す「がある」と合わない。"}, {"text": "と", "is_correct": false, "explanation": "並べる・引用を示す「と」。「地とあると知って」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「地へあると」は存在を表せない。"}], "correct_answer": "が", "explanations": {"が": "存在するものを示す「が」。「地があると知って」で、場所が存在することを表す。", "を": "動作の対象を示す「を」。「地をあると知って」は存在を表す「がある」と合わない。", "と": "並べる・引用を示す「と」。「地とあると知って」は文が成り立たない。", "へ": "方向を示す「へ」。「地へあると」は存在を表せない。"}, "error_tags": {"を": "対象", "と": "引用・並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38166, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "緑や芝生などの植物でいっぱいの場所のことです。", "primary_collocate": null, "pronunciation": "ち", "ipa": "t͡ɕi", "syllable_count": 1, "sentences": [{"text": "芝生と花でいっぱいの地に、子どもたちの笑い声が響いていた。", "target_word": "地", "complexity_tier": "T3", "furigana": "芝生[しばふ]と花[はな]でいっぱいの地[ち]に、子[こ]どもたちの笑[わら]い声[ごえ]が響[ひび]いていた。", "sentence_source": "generated"}, {"text": "町の北には、木や草が広がる緑の地が残っている。", "target_word": "地", "complexity_tier": "T3", "furigana": "町[まち]の北[きた]には、木[き]や草[くさ]が広[ひろ]がる緑[みどり]の地[ち]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "緑あふれる地で暮らしたくて、彼は郊外へ引っ越した。", "target_word": "地", "complexity_tier": "T3", "furigana": "緑[みどり]あふれる地[ち]で暮[く]らしたくて、彼[かれ]は郊外[こうがい]へ引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "春になると、この地は一面の芝で青々とする。", "target_word": "地", "complexity_tier": "T3", "furigana": "春[はる]になると、この地[ち]は一面[いちめん]の芝[しば]で青々[あおあお]とする。", "sentence_source": "generated"}, {"text": "公園の奥に、手入れの行き届いた緑の地が広がっていた。", "target_word": "地", "complexity_tier": "T3", "furigana": "公園[こうえん]の奥[おく]に、手[て]入[い]れの行[い]き届[とど]いた緑[みどり]の地[ち]が広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "緑の多い地を選んで、新しい学校が建てられた。", "target_word": "地", "complexity_tier": "T3", "furigana": "緑[みどり]の多[おお]い地[ち]を選[えら]んで、新[あたら]しい学校[がっこう]が建[た]てられた。", "sentence_source": "generated"}, {"text": "空港のそばに、草と木に囲まれた静かな地がある。", "target_word": "地", "complexity_tier": "T3", "furigana": "空港[くうこう]のそばに、草[くさ]と木[き]に囲[かこ]まれた静[しず]かな地[ち]がある。", "sentence_source": "generated"}, {"text": "都会の真ん中にも、緑に満ちた地があると知って驚いた。", "target_word": "地", "complexity_tier": "T3", "furigana": "都会[とかい]の真[ま]ん中[なか]にも、緑[みどり]に満[み]ちた地[ち]があると知[し]って驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "芝が広がる地を、犬が嬉しそうに走り回っている。", "target_word": "地", "complexity_tier": "T3", "furigana": "芝[しば]が広[ひろ]がる地[ち]を、犬[いぬ]が嬉[うれ]しそうに走[はし]り回[まわ]っている。", "sentence_source": "generated"}, {"text": "緑豊かなこの地では、春に野の花がいっせいに咲く。", "target_word": "地", "complexity_tier": "T3", "furigana": "緑豊[みどりゆた]かなこの地[ち]では、春[はる]に野[の]の花[はな]がいっせいに咲[さ]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地", "label": "基本形（名詞）"}], "register": "書き言葉（やや文語的）", "sense_fingerprint": "緑や芝生などの植物が広がる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 芝生 (Zipf 3.6), 笑い声 (Zipf 3.45), 響い (Zipf 3.51)','sentence 3 above tier T1: contains vocabulary far above tier T1: 青々 (Zipf 2.49)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 芝 (Zipf 3.97), 嬉し (Zipf 3.87), 走り回っ (Zipf 3.36)']::text[], 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38166, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地", "is_correct": true, "explanation": "「芝生と花でいっぱいの地」の「地」。草花の広がる場所を指す。"}, {"text": "鍋", "is_correct": false, "explanation": "調理器具で、草花が広がる場所とは言えない。"}, {"text": "皿", "is_correct": false, "explanation": "料理や物を盛る器で、場所の意味では入らない。"}, {"text": "帽子", "is_correct": false, "explanation": "頭にかぶる物で、笑い声が響く場所にはならない。"}], "explanations": {"地": "「芝生と花でいっぱいの地」の「地」。草花の広がる場所を指す。", "鍋": "調理器具で、草花が広がる場所とは言えない。", "皿": "料理や物を盛る器で、場所の意味では入らない。", "帽子": "頭にかぶる物で、笑い声が響く場所にはならない。"}, "sentence_index": 0, "correct_answer": "地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は地を刈って、庭をきれいに整えた。", "explanation": "ここは〈草〉の意味の芝や草。地は場所を指すので、刈り取る対象にはならない。"}, {"text": "夏になると、この地は青い波で輝く。", "explanation": "ここは〈海〉の意味。地は陸の場所を指すので、波が立つ海には合わない。"}, {"text": "湖の地に小舟を浮かべて、静かに過ごした。", "explanation": "ここは〈水面〉の意味。地は水のない陸の場所を指すので、小舟を浮かべる水の上の文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38166, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地", "is_correct": true, "explanation": "「静かな地」の「地」。空港のそばの場所を指す。"}, {"text": "靴", "is_correct": false, "explanation": "履物で、場所の意味にはならない。"}, {"text": "柱", "is_correct": false, "explanation": "建物を支える材で、「静かな柱がある」では意味が通らない。"}, {"text": "薬", "is_correct": false, "explanation": "薬品で、場所の意味では入らない。"}], "explanations": {"地": "「静かな地」の「地」。空港のそばの場所を指す。", "靴": "履物で、場所の意味にはならない。", "柱": "建物を支える材で、「静かな柱がある」では意味が通らない。", "薬": "薬品で、場所の意味では入らない。"}, "sentence_index": 6, "correct_answer": "地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春になると、この地を花束にして配る。", "explanation": "ここは草花をまとめた贈り物の意味。地は草花の広がる場所を指すので、束にして配るものとしては合わない。"}, {"text": "部屋の中の地に、春になると野の花がいっせいに咲く。", "explanation": "ここは〈床〉の意味。地は屋外で草木が広がる場所を指すので、部屋の中の床には合わない。"}, {"text": "春になると、この地を鍋で煮て食卓に出す。", "explanation": "ここは〈食材〉の意味。地は草花の広がる場所を指すので、鍋で煮て食べるものとしては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38166, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "芝生が広がる地を、子どもたちが座っていた。", "corrected_sentence": "芝生が広がる地に、子どもたちが座っていた。", "error_description": "「座る」は場所に「に」を使う。「地を座っていた」は誤りで、「地に座っていた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38166, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緑豊かの地に、夏になると鳥が集まる。", "corrected_sentence": "緑豊かな地に、夏になると鳥が集まる。", "error_description": "「豊か」は形容動詞なので、名詞につなぐ時は「な」を使う。「緑豊かの」は誤りで、「緑豊かな地」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38167, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「〜として知られる」の「と」。立場や資格を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」。「地へ知られている」では成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点や出どころを示す「から」。「地から知られている」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す「より」。比べる相手がなく、文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「〜として知られる」の「と」。立場や資格を示す。", "へ": "方向を示す「へ」。「地へ知られている」では成り立たない。", "から": "起点や出どころを示す「から」。「地から知られている」は意味が通らない。", "より": "比較の基準を示す「より」。比べる相手がなく、文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38167, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「地を歩く」の「を」。歩いて通る場所を示す。"}, {"text": "に", "is_correct": false, "explanation": "場所や到着点を示す「に」。「地に歩いていた」は不自然で、歩く動作と合わない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ「の」。「地の羊の群れ」となり、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「地が歩いていた」では地が歩く主体になり、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「地を歩く」の「を」。歩いて通る場所を示す。", "に": "場所や到着点を示す「に」。「地に歩いていた」は不自然で、歩く動作と合わない。", "の": "名詞をつなぐ「の」。「地の羊の群れ」となり、文が成り立たない。", "が": "主語を示す「が」。「地が歩いていた」では地が歩く主体になり、意味が通らない。"}, "error_tags": {"に": "位置", "の": "連体修飾", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38167, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "草木が多く茂っている地面や、緑色の植物に覆われた土地のことを指します。", "primary_collocate": null, "pronunciation": "ち", "ipa": "t͡ɕi", "syllable_count": 1, "sentences": [{"text": "それは、草木の茂る安住の地からの離脱であり、新たな社会的文脈における自己の再構築を迫られる、極めて重要な通過儀礼なのである。", "target_word": "地", "complexity_tier": "T4", "furigana": "それは、草木[くさき]の茂[しげ]る安住[あんじゅう]の地[ち]からの離脱[りだつ]であり、新[あら]たな社会的文脈[しゃかいてきぶんみゃく]における自己[じこ]の再構築[さいこうちく]を迫[せま]られる、極[きわ]めて重要[じゅうよう]な通過儀礼[つうかぎれい]なのである。", "sentence_source": "generated"}, {"text": "この島は、古くから人々が暮らしてきた緑豊かな地として知られている。", "target_word": "地", "complexity_tier": "T3", "furigana": "この島[しま]は、古[ふる]くから人々[ひとびと]が暮[く]らしてきた緑豊[みどりゆた]かな地[ち]として知[し]られている。", "sentence_source": "generated"}, {"text": "彼らは森に囲まれた緑の地に小さな村をつくった。", "target_word": "地", "complexity_tier": "T3", "furigana": "彼[かれ]らは森[もり]に囲[かこ]まれた緑[みどり]の地[ち]に小[ちい]さな村[むら]をつくった。", "sentence_source": "generated"}, {"text": "長い旅の末、一行は草木の茂る未開の地にたどり着いた。", "target_word": "地", "complexity_tier": "T3", "furigana": "長[なが]い旅[たび]の末[すえ]、一行[いっこう]は草木[くさき]の茂[しげ]る未開[みかい]の地[ち]にたどり着[つ]いた。", "sentence_source": "generated"}, {"text": "緑におおわれた地では、夏でも風が涼しく感じられる。", "target_word": "地", "complexity_tier": "T3", "furigana": "緑[みどり]におおわれた地[ち]では、夏[なつ]でも風[かぜ]が涼[すず]しく感[かん]じられる。", "sentence_source": "generated"}, {"text": "戦争のあと、人々は荒れた土地を耕し、再び緑の地へと変えていった。", "target_word": "地", "complexity_tier": "T3", "furigana": "戦争[せんそう]のあと、人々[ひとびと]は荒[あ]れた土地[とち]を耕[たがや]し、再[ふたた]び緑[みどり]の地[ち]へと変[か]えていった。", "sentence_source": "generated"}, {"text": "山あいの緑深い地に、祖父は一軒の家を建てた。", "target_word": "地", "complexity_tier": "T3", "furigana": "山[やま]あいの緑深[みどりぶか]い地[ち]に、祖父[そふ]は一軒[いっけん]の家[いえ]を建[た]てた。", "sentence_source": "generated"}, {"text": "草が一面に生えた地を、羊の群れがゆっくり歩いていた。", "target_word": "地", "complexity_tier": "T3", "furigana": "草[くさ]が一面[いちめん]に生[は]えた地[ち]を、羊[ひつじ]の群[む]れがゆっくり歩[ある]いていた。", "sentence_source": "generated"}, {"text": "雨が多いこの地は、木々がよく育つので森が深い。", "target_word": "地", "complexity_tier": "T3", "furigana": "雨[あめ]が多[おお]いこの地[ち]は、木々[きぎ]がよく育[そだ]つので森[もり]が深[ふか]い。", "sentence_source": "generated"}, {"text": "旅人は水と緑にめぐまれた地を見つけ、そこで足を止めた。", "target_word": "地", "complexity_tier": "T3", "furigana": "旅人[たびびと]は水[みず]と緑[みどり]にめぐまれた地[ち]を見[み]つけ、そこで足[あし]を止[と]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地", "label": "基本形（名詞）"}], "register": "書き言葉（やや文語的）", "sense_fingerprint": "草木が茂り、緑におおわれた土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 茂る (Zipf 2.33)','sentence 3 above tier T1: contains vocabulary far above tier T1: 茂る (Zipf 2.33)','sentence 4 above tier T1: contains vocabulary far above tier T1: おおわれ (Zipf 1.5)','sentence 6 above tier T1: contains vocabulary far above tier T1: 山あい (Zipf 2.14)','sentence 9 above tier T1: contains vocabulary far above tier T1: めぐまれ (Zipf 1.84)']::text[], 'b908154a-741f-4e8b-8929-ea5b05c92a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38167, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地", "is_correct": true, "explanation": "「安住の地」の「地」。場所や土地を指し、この文の空所に入る。"}, {"text": "旗", "is_correct": false, "explanation": "布の標識で、「安住の旗からの離脱」では場所の意味にならない。"}, {"text": "芝", "is_correct": false, "explanation": "芝生という草で、「安住の芝からの離脱」は成り立たない。"}, {"text": "苗", "is_correct": false, "explanation": "植え付け用の若木で、場所を表さないためこの文脈では合わない。"}], "explanations": {"地": "「安住の地」の「地」。場所や土地を指し、この文の空所に入る。", "旗": "布の標識で、「安住の旗からの離脱」では場所の意味にならない。", "芝": "芝生という草で、「安住の芝からの離脱」は成り立たない。", "苗": "植え付け用の若木で、場所を表さないためこの文脈では合わない。"}, "sentence_index": 0, "correct_answer": "地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "畑の隅に新しい地を運び込み、苗を植えた。", "explanation": "ここは〈土〉の意味。地は草木の茂る土地を指すので、畑に運び入れる土の意味では合わない。"}, {"text": "ガラスの地に指紋がついた。", "explanation": "ここは〈表面〉の意味。地は草木の生える土地を指すので、ガラスの面には使わない。"}, {"text": "部屋の地に、ボールが転がっていた。", "explanation": "ここは〈床〉の意味。地は屋外の草木の茂る土地を指すので、室内の床には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38167, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地", "is_correct": true, "explanation": "「山あいの緑深い地」の「地」。家を建てる土地を指し、この文に合う。"}, {"text": "瓦", "is_correct": false, "explanation": "屋根に使う素焼きの板で、「緑深い瓦に家を建てた」は成り立たない。"}, {"text": "柱", "is_correct": false, "explanation": "建物を支える材で、家を建てる場所にはならない。"}, {"text": "板", "is_correct": false, "explanation": "薄い木や金属の板で、土地を表さないためこの文脈では合わない。"}], "explanations": {"地": "「山あいの緑深い地」の「地」。家を建てる土地を指し、この文に合う。", "瓦": "屋根に使う素焼きの板で、「緑深い瓦に家を建てた」は成り立たない。", "柱": "建物を支える材で、家を建てる場所にはならない。", "板": "薄い木や金属の板で、土地を表さないためこの文脈では合わない。"}, "sentence_index": 6, "correct_answer": "地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅人は勢いよく流れる地を、舟で下った。", "explanation": "ここは〈川〉の意味。地は陸の土地を指すので、流れる水の川には合わない。"}, {"text": "旅人は波の高い地を越えて、島へ渡った。", "explanation": "ここは〈海〉の意味。地は陸の土地を指すので、波の高い海には合わない。"}, {"text": "旅人は星のまたたく地を見上げ、夜道を歩いた。", "explanation": "ここは〈空〉の意味。地は地上の土地を指すので、見上げる星空には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38167, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕暮れ、一行は草木の茂る地を着いた。", "corrected_sentence": "夕暮れ、一行は草木の茂る地に着いた。", "error_description": "「着く」は到着する場所を「に」で示す。「地を着いた」は誤りで、「地に着いた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38167, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草木の茂る緑な地に、旅人がテントを張った。", "corrected_sentence": "草木の茂る緑の地に、旅人がテントを張った。", "error_description": "「緑」は名詞なので、地につなぐ時は「の」を使う。「緑な地」は誤りで、「緑の地」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a13be2f-ad0e-4d2c-8306-895614798668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38168, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「弾を込めて」で、込める対象の弾を示す。"}, {"text": "に", "is_correct": false, "explanation": "「銃に」で到達先がすでに示されており、「弾に込める」は到達先が二つ重なって不自然。"}, {"text": "で", "is_correct": false, "explanation": "「弾で込めて」は手段の意味になり、込める対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "込めるは他動詞で、弾を主語にできない。「弾が込めて」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「弾を込めて」で、込める対象の弾を示す。", "に": "「銃に」で到達先がすでに示されており、「弾に込める」は到達先が二つ重なって不自然。", "で": "「弾で込めて」は手段の意味になり、込める対象を示せない。", "が": "込めるは他動詞で、弾を主語にできない。「弾が込めて」は成り立たない。"}, "error_tags": {"を": "対象（目的語）", "に": "到達点の重複", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38168, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「玉を込める」で、込める対象の玉を示す。"}, {"text": "の", "is_correct": false, "explanation": "「玉の込める」は名詞同士をつなぐ「の」で、後ろに込める対象がなく成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「玉と込める」は共同や相手を表し、込める対象としては意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表すため、「玉より込める」では装填の対象が示せない。"}], "correct_answer": "を", "explanations": {"を": "正解。「玉を込める」で、込める対象の玉を示す。", "の": "「玉の込める」は名詞同士をつなぐ「の」で、後ろに込める対象がなく成り立たない。", "と": "「玉と込める」は共同や相手を表し、込める対象としては意味が通らない。", "より": "「より」は比較や起点を表すため、「玉より込める」では装填の対象が示せない。"}, "error_tags": {"を": "対象（目的語）", "の": "名詞修飾", "と": "共同・相手", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38168, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "銃や大砲などの筒の中に弾や火薬を入れること（装填）。", "primary_collocate": null, "pronunciation": "こめる", "ipa": "komeɾɯ", "syllable_count": 3, "sentences": [{"text": "弾を込めれば、この銃はすぐに撃てる状態になる。", "target_word": "込めれば", "complexity_tier": "T3", "furigana": "弾[たま]を込[こ]めれば、この銃[じゅう]はすぐに撃[う]てる状態[じょうたい]になる。", "sentence_source": "generated"}, {"text": "猟師は銃に弾を込めて、静かに獲物を待った。", "target_word": "込めて", "complexity_tier": "T3", "furigana": "猟師[りょうし]は銃[じゅう]に弾[たま]を込[こ]めて、静[しず]かに獲物[えもの]を待[ま]った。", "sentence_source": "generated"}, {"text": "兵士は命令を聞くと、すぐ大砲に弾を込めた。", "target_word": "込めた", "complexity_tier": "T3", "furigana": "兵士[へいし]は命令[めいれい]を聞[き]くと、すぐ大砲[たいほう]に弾[たま]を込[こ]めた。", "sentence_source": "generated"}, {"text": "古い鉄砲に火薬を込めるのは、時間がかかる。", "target_word": "込める", "complexity_tier": "T3", "furigana": "古[ふる]い鉄砲[てっぽう]に火薬[かやく]を込[こ]めるのは、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "射撃の練習では、係員の合図で弾を込める。", "target_word": "込める", "complexity_tier": "T3", "furigana": "射撃[しゃげき]の練習[れんしゅう]では、係員[かかりいん]の合図[あいず]で弾[たま]を込[こ]める。", "sentence_source": "generated"}, {"text": "彼は震える手で拳銃に最後の一発を込めた。", "target_word": "込めた", "complexity_tier": "T3", "furigana": "彼[かれ]は震[ふる]える手[て]で拳銃[けんじゅう]に最後[さいご]の一発[いっぱつ]を込[こ]めた。", "sentence_source": "generated"}, {"text": "弾を込めようとしたとき、手が滑って地面に落とした。", "target_word": "込めよう", "complexity_tier": "T3", "furigana": "弾[たま]を込[こ]めようとしたとき、手[て]が滑[すべ]って地面[じめん]に落[お]とした。", "sentence_source": "generated"}, {"text": "昔の鉄砲は、先から玉を込める仕組みだった。", "target_word": "込める", "complexity_tier": "T3", "furigana": "昔[むかし]の鉄砲[てっぽう]は、先[さき]から玉[たま]を込[こ]める仕組[しく]みだった。", "sentence_source": "generated"}, {"text": "弾を込めていない銃でも、人に向けてはいけない。", "target_word": "込めて", "complexity_tier": "T3", "furigana": "弾[たま]を込[こ]めていない銃[じゅう]でも、人[ひと]に向[む]けてはいけない。", "sentence_source": "generated"}, {"text": "猟師の祖父は、毎朝きちんと弾を込めてから山へ入った。", "target_word": "込めて", "complexity_tier": "T3", "furigana": "猟師[りょうし]の祖父[そふ]は、毎朝[まいあさ]きちんと弾[たま]を込[こ]めてから山[やま]へ入[はい]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "込める", "label": "辞書形"}, {"form": "込めた", "label": "過去形"}, {"form": "込めて", "label": "て形"}, {"form": "込めない", "label": "否定形"}, {"form": "込めれば", "label": "仮定形"}, {"form": "込めよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "銃や大砲などの筒の中に弾や火薬を入れること（装填）。「心を込める」「力を込める」の意味ではない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c082e026-6af3-4194-93c7-94860e00a12c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38168, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "込めれば", "is_correct": true, "explanation": "正解。仮定の「ば」で、「込めたら撃てる状態になる」と条件を示す。"}, {"text": "込める", "is_correct": false, "explanation": "辞書形のまま「、」で続けると、条件や順序の関係が成り立たず不自然。"}, {"text": "込めない", "is_correct": false, "explanation": "否定形では、撃てる状態になるための条件として意味が通らない。"}, {"text": "込めよう", "is_correct": false, "explanation": "意志形は「込めよう」と決意する形で、「この銃はすぐに撃てる」と結びつかない。"}], "explanations": {"込めれば": "正解。仮定の「ば」で、「込めたら撃てる状態になる」と条件を示す。", "込める": "辞書形のまま「、」で続けると、条件や順序の関係が成り立たず不自然。", "込めない": "否定形では、撃てる状態になるための条件として意味が通らない。", "込めよう": "意志形は「込めよう」と決意する形で、「この銃はすぐに撃てる」と結びつかない。"}, "sentence_index": 0, "correct_answer": "込めれば"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "皿の上に料理を込めて、きれいに盛りつけた。", "explanation": "ここは〈盛る〉の意味。料理を器の上に高く積むことは盛るといい、込めるは中に入れる意味なので合わない。"}, {"text": "壁の表面にペンキを込めて、一日で仕上げた。", "explanation": "ここは〈塗る〉の意味。表面に色を広げることは塗るといい、込めるは中に入れる意味なので合わない。"}, {"text": "焼いた肉の上から塩を込めて、香りを立たせた。", "explanation": "ここは〈振りかける〉の意味。料理の表面に粉をかけることは振りかけるといい、込めるは中に入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38168, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "込めよう", "is_correct": true, "explanation": "正解。「込めようとしたとき」で、まさに込めかけた瞬間を表す。"}, {"text": "込めて", "is_correct": false, "explanation": "「込めてとしたとき」という形は文法的に成り立たない。"}, {"text": "込めず", "is_correct": false, "explanation": "「込めずとしたとき」は文法的に成り立たず、否定の「ず」は「とした」に続かない。"}, {"text": "込めれば", "is_correct": false, "explanation": "仮定形の「ば」は「としたとき」と続かず、文法的に不自然。"}], "explanations": {"込めよう": "正解。「込めようとしたとき」で、まさに込めかけた瞬間を表す。", "込めて": "「込めてとしたとき」という形は文法的に成り立たない。", "込めず": "「込めずとしたとき」は文法的に成り立たず、否定の「ず」は「とした」に続かない。", "込めれば": "仮定形の「ば」は「としたとき」と続かず、文法的に不自然。"}, "sentence_index": 6, "correct_answer": "込めよう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "七夕の短冊に星の絵を込めて、笹に吊るした。", "explanation": "ここは〈描く〉の意味。紙の上に絵を描くことは描くといい、込めるは中に入れる意味なので合わない。"}, {"text": "腕に包帯を込めて、固く縛った。", "explanation": "ここは〈巻く〉の意味。腕のまわりに布を回すことは巻くといい、込めるは中に入れる意味なので合わない。"}, {"text": "メインの皿の端に野菜を込めて、彩りを添えた。", "explanation": "ここは〈添える〉の意味。料理の脇に別のものを添えることは添えるといい、込めるは中に入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38168, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猟師は銃に弾を込めよう、獲物の気配をうかがった。", "corrected_sentence": "猟師は銃に弾を込めて、獲物の気配をうかがった。", "error_description": "前後の動作をつなぐ「込めて」が正しいところを、意志形「込めよう」にした誤り。「込めよう、〜うかがった」は文として続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "込めて", "is_correct": true, "explanation": "正解。「弾を込めて、〜待った」の形で、前の動作と後ろの動作をつなぐ。"}, {"text": "込める", "is_correct": false, "explanation": "辞書形で止めると、後ろの「待った」へ続けられない。"}, {"text": "込めた", "is_correct": false, "explanation": "過去形は動作を完結させる形で、「て」のように連続する動作をつなげない。"}, {"text": "込めれば", "is_correct": false, "explanation": "仮定形で条件を表すため、「待った」と順に続く流れと合わない。"}], "correct_form": "込めて", "base_form": "込める", "form_label": "て形", "sentence_index": 1, "explanations": {"込めて": "正解。「弾を込めて、〜待った」の形で、前の動作と後ろの動作をつなぐ。", "込める": "辞書形で止めると、後ろの「待った」へ続けられない。", "込めた": "過去形は動作を完結させる形で、「て」のように連続する動作をつなげない。", "込めれば": "仮定形で条件を表すため、「待った」と順に続く流れと合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38168, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は狩りの前に、銃に火薬が込めて確かめた。", "corrected_sentence": "父は狩りの前に、銃に火薬を込めて確かめた。", "error_description": "込めるの目的語には「を」が必要。「火薬が」と主語にすると、他動詞「込める」が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "込める", "is_correct": true, "explanation": "正解。「仕組み」を修飾する辞書形で、今も続く仕組みを表す。"}, {"text": "込めよう", "is_correct": false, "explanation": "意志形で、仕組みを説明する文には合わない。"}, {"text": "込めない", "is_correct": false, "explanation": "否定形のため「込めない仕組み」となり、意味が逆になる。"}, {"text": "込めて", "is_correct": false, "explanation": "て形は名詞に直接続けられず、「仕組み」を修飾できない。"}], "correct_form": "込める", "base_form": "込める", "form_label": "辞書形（名詞修飾）", "sentence_index": 7, "explanations": {"込める": "正解。「仕組み」を修飾する辞書形で、今も続く仕組みを表す。", "込めよう": "意志形で、仕組みを説明する文には合わない。", "込めない": "否定形のため「込めない仕組み」となり、意味が逆になる。", "込めて": "て形は名詞に直接続けられず、「仕組み」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b6d0f9-c4f2-4f9c-9a5a-ffa5a8045a04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
