INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38169, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38169, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを包み込んだり、中に含めたりすることを表す動詞。", "primary_collocate": null, "pronunciation": "こめる", "ipa": "komeɾɯ", "syllable_count": 3, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "込められた", "complexity_tier": "T5", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だつこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "生徒たちが繊維の纹理に想いを込め、独自のプロットを紡ぎ出すとき、それは単なる被服製作ではなく、記号的な自己主張の確立へと昇華されるのである。", "target_word": "込め", "complexity_tier": "T5", "furigana": "生徒[せいと]たちが繊維[せんい]の纹理に想[おも]いを込[こ]め、独自[どくじ]のプロットを紡[つむ]ぎ出[だ]すとき、それは単[たん]なる被服製作[ひふくせいさく]ではなく、記号的[きごうてき]な自己主張[じこしゅちょう]の確立[かくりつ]へと昇華[しょうか]されるのである。", "sentence_source": "mined"}, {"text": "親である私にできるのは、その勇気ある第一歩を、ただ静かに、そして確かな祈りを込めて見守ることだけだ。", "target_word": "込めて", "complexity_tier": "T5", "furigana": "親[おや]である私[わたし]にできるのは、その勇気[ゆうき]ある第一歩[だいいっぽ]を、ただ静[しず]かに、そして確[たし]かな祈[いの]りを込[こ]めて見守[みまも]ることだけだ。", "sentence_source": "mined"}, {"text": "母は愛情を込めて、毎朝お弁当を作ってくれます。", "target_word": "込めて", "complexity_tier": "T3", "furigana": "母[はは]は愛情[あいじょう]を込[こ]めて、毎朝[まいあさ]お弁当[べんとう]を作[つく]ってくれます。", "sentence_source": "generated"}, {"text": "友だちへの手紙に、感謝の気持ちを込めました。", "target_word": "込め", "complexity_tier": "T3", "furigana": "友[とも]だちへの手紙[てがみ]に、感謝[かんしゃ]の気持[きも]ちを込[こ]めました。", "sentence_source": "generated"}, {"text": "力を込めてドアを押しましたが、開きませんでした。", "target_word": "込めて", "complexity_tier": "T3", "furigana": "力[ちから]を込[こ]めてドアを押[お]しましたが、開[あ]きませんでした。", "sentence_source": "generated"}, {"text": "この歌には、平和への願いが込められています。", "target_word": "込められて", "complexity_tier": "T3", "furigana": "この歌[うた]には、平和[へいわ]への願[ねが]いが込[こ]められています。", "sentence_source": "generated"}, {"text": "先生に心を込めて、お礼の手紙を書きました。", "target_word": "込めて", "complexity_tier": "T3", "furigana": "先生[せんせい]に心[こころ]を込[こ]めて、お礼[れい]の手紙[てがみ]を書[か]きました。", "sentence_source": "generated"}, {"text": "皮肉を込めた言い方に、みんなが黙ってしまった。", "target_word": "込めた", "complexity_tier": "T3", "furigana": "皮肉[ひにく]を込[こ]めた言[い]い方[かた]に、みんなが黙[だま]ってしまった。", "sentence_source": "generated"}, {"text": "そんなに気持ちを込めなくても、大丈夫ですよ。", "target_word": "込め", "complexity_tier": "T3", "furigana": "そんなに気持[きも]ちを込[こ]めなくても、大丈夫[だいじょうぶ]ですよ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "込める", "label": "終止形"}, {"form": "込めます", "label": "丁寧形"}, {"form": "込めない", "label": "否定形"}, {"form": "込めた", "label": "過去形"}, {"form": "込めて", "label": "て形"}, {"form": "込められる", "label": "受身形"}, {"form": "込めれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "気持ちや力などを中に含ませる動詞「込める」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38169, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "込められた", "is_correct": true, "explanation": "「建物に込められた作者の意図」の「込められた」。受け身の連体形で、この文の正解。"}, {"text": "込めて", "is_correct": false, "explanation": "て形で、名詞「意図」を修飾する形にならず文が続かない。"}, {"text": "込め", "is_correct": false, "explanation": "連用形で、名詞を修飾する形にならず文が成り立たない。"}, {"text": "込めれば", "is_correct": false, "explanation": "仮定形で、「作者の意図」を修飾する文脈に合わない。"}], "explanations": {"込められた": "「建物に込められた作者の意図」の「込められた」。受け身の連体形で、この文の正解。", "込めて": "て形で、名詞「意図」を修飾する形にならず文が続かない。", "込め": "連用形で、名詞を修飾する形にならず文が成り立たない。", "込めれば": "仮定形で、「作者の意図」を修飾する文脈に合わない。"}, "sentence_index": 0, "correct_answer": "込められた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前がとても込んでいます。", "explanation": "ここは〈込む〉（混み合う）の意味。〈込める〉の「中に含める」の意味とは別の語。"}, {"text": "彼は、自分が正しいと思い込んでいます。", "explanation": "ここは〈思い込む〉（そうだと信じ込む）の意味。〈込める〉の「中に含める」の意味とは別の語で、ここでは合わない。"}, {"text": "申し込みは来週の金曜日までです。", "explanation": "ここは〈申し込む〉の意味。正式に依頼する行為を指す別の動詞で、〈込める〉の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38169, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "込められて", "is_correct": true, "explanation": "「願いが込められています」の「込められて」。受け身のて形で、この文の正解。"}, {"text": "込め", "is_correct": false, "explanation": "連用形のみでは「います」に続かず、文が成り立たない。"}, {"text": "込める", "is_correct": false, "explanation": "終止形では「います」に続けられず、受け身の文脈に合わない。"}, {"text": "込めず", "is_correct": false, "explanation": "否定の中止形で、「います」と続けると文が成り立たない。"}], "explanations": {"込められて": "「願いが込められています」の「込められて」。受け身のて形で、この文の正解。", "込め": "連用形のみでは「います」に続かず、文が成り立たない。", "込める": "終止形では「います」に続けられず、受け身の文脈に合わない。", "込めず": "否定の中止形で、「います」と続けると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "込められて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の話は、事情が込み入っていて難しい。", "explanation": "ここは〈込み入る〉（複雑になる）の意味。〈込める〉の「中に含める」の意味ではないので合わない。"}, {"text": "コップに水を込めました。", "explanation": "ここは〈注ぐ〉の意味。液体を器に注ぐ動作を表す語で、〈込める〉は使わないので合わない。"}, {"text": "料理に調味料を込めました。", "explanation": "ここは〈加える〉の意味。付け足す動作を表す語で、〈込める〉の「中に含める」の意味とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38169, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その言葉には、深い感謝が込めています。", "corrected_sentence": "その言葉には、深い感謝が込められています。", "error_description": "「込める」の受け身「込められる」が必要。能動の「込めています」は感謝を主語にできず、ここでは不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "込め", "is_correct": true, "explanation": "「想いを込め、」の「込め」。連用形で、後に「紡ぎ出す」と続く中止形として正解。"}, {"text": "込めます", "is_correct": false, "explanation": "丁寧形で文を言い切るため、「込めます、」と続けると文が成り立たない。"}, {"text": "込めよう", "is_correct": false, "explanation": "意志形で、「込めよう、」と続けると文が成り立たず、後続の「紡ぎ出す」と結べない。"}, {"text": "込める", "is_correct": false, "explanation": "終止・連体の形で、「、」で続く中止の形にならない。"}], "correct_form": "込め", "base_form": "込める", "form_label": "連用形", "sentence_index": 1, "explanations": {"込め": "「想いを込め、」の「込め」。連用形で、後に「紡ぎ出す」と続く中止形として正解。", "込めます": "丁寧形で文を言い切るため、「込めます、」と続けると文が成り立たない。", "込めよう": "意志形で、「込めよう、」と続けると文が成り立たず、後続の「紡ぎ出す」と結べない。", "込める": "終止・連体の形で、「、」で続く中止の形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38169, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "そんなに力に込めないでください。", "corrected_sentence": "そんなに力を込めないでください。", "error_description": "「込める」の対象「力」は「を」で示すため、「に」は誤り。「力に込める」とは言わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "込めて", "is_correct": true, "explanation": "「心を込めて、」の「込めて」。て形で、後ろの「お礼の手紙を書きました」と続く形として正解。"}, {"text": "込めた", "is_correct": false, "explanation": "過去形で、「、」で続けると中止の形にならず、後の「お礼の手紙を書きました」と結べない。"}, {"text": "込められない", "is_correct": false, "explanation": "可能の否定形で、「、」で続く中止の形にならず、ここでは文が成り立たない。"}, {"text": "込められる", "is_correct": false, "explanation": "受け身・可能の形で、「心を込めて」の動作を表せず、ここでは意味が合わない。"}], "correct_form": "込めて", "base_form": "込める", "form_label": "て形", "sentence_index": 7, "explanations": {"込めて": "「心を込めて、」の「込めて」。て形で、後ろの「お礼の手紙を書きました」と続く形として正解。", "込めた": "過去形で、「、」で続けると中止の形にならず、後の「お礼の手紙を書きました」と結べない。", "込められない": "可能の否定形で、「、」で続く中止の形にならず、ここでは文が成り立たない。", "込められる": "受け身・可能の形で、「心を込めて」の動作を表せず、ここでは意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38170, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『食べる』の対象（おにぎり）を示す『を』。"}, {"text": "が", "is_correct": false, "explanation": "『おにぎりが食べた』は、おにぎりが食べる主体になり文の意味が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "『おにぎりに食べた』は対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は食べる対象にならず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『食べる』の対象（おにぎり）を示す『を』。", "が": "『おにぎりが食べた』は、おにぎりが食べる主体になり文の意味が崩れる。", "に": "『おにぎりに食べた』は対象を示せず、不自然。", "へ": "方向を示す『へ』は食べる対象にならず、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
