INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38170, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "口に入れて、のどを通して、おなかの中に入れること。", "primary_collocate": null, "pronunciation": "たべる", "ipa": "tabeɾɯ", "syllable_count": 3, "sentences": [{"text": "毎晩七時に夕食を食べる。", "target_word": "食べる", "complexity_tier": "T2", "furigana": "毎晩(まいばん)七時(しちじ)に夕食(ゆうしょく)を食(た)べる。", "sentence_source": "generated"}, {"text": "おなかがすいたので、おにぎりを食べた。", "target_word": "食べた", "complexity_tier": "T2", "furigana": "おなかがすいたので、おにぎりを食(た)べた。", "sentence_source": "generated"}, {"text": "今日はまだ何も食べていない。", "target_word": "食べて", "complexity_tier": "T2", "furigana": "今日(きょう)はまだ何(なに)も食(た)べていない。", "sentence_source": "generated"}, {"text": "赤ちゃんが初めてごはんを食べた。", "target_word": "食べた", "complexity_tier": "T2", "furigana": "赤(あか)ちゃんが初(はじ)めてごはんを食(た)べた。", "sentence_source": "generated"}, {"text": "彼女は野菜を食べないで、肉ばかり選ぶ。", "target_word": "食べない", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は野菜(やさい)を食(た)べないで、肉(にく)ばかり選(えら)ぶ。", "sentence_source": "generated"}, {"text": "病気のときは、やわらかいものを食べたほうがいい。", "target_word": "食べた", "complexity_tier": "T3", "furigana": "病気(びょうき)のときは、やわらかいものを食(た)べたほうがいい。", "sentence_source": "generated"}, {"text": "家族みんなでカレーを食べた。", "target_word": "食べた", "complexity_tier": "T2", "furigana": "家族(かぞく)みんなでカレーを食(た)べた。", "sentence_source": "generated"}, {"text": "たくさん食べたので、少し散歩をした。", "target_word": "食べた", "complexity_tier": "T3", "furigana": "たくさん食(た)べたので、少(すこ)し散歩(さんぽ)をした。", "sentence_source": "generated"}, {"text": "私は昼休みに公園で弁当を食べる。", "target_word": "食べる", "complexity_tier": "T3", "furigana": "私(わたし)は昼休(ひるやす)みに公園(こうえん)で弁当(べんとう)を食(た)べる。", "sentence_source": "generated"}, {"text": "犬が皿のえさを全部食べた。", "target_word": "食べた", "complexity_tier": "T3", "furigana": "犬(いぬ)が皿(さら)のえさを全部(ぜんぶ)食(た)べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食べる", "label": "終止形"}, {"form": "食べない", "label": "否定形"}, {"form": "食べます", "label": "丁寧形"}, {"form": "食べた", "label": "過去形"}, {"form": "食べて", "label": "て形"}, {"form": "食べれば", "label": "仮定形"}, {"form": "食べよう", "label": "意志形"}, {"form": "食べられる", "label": "可能形"}], "register": "中立（常体）", "sense_fingerprint": "食事として口からおなかに入れる日常の行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38170, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食べる", "is_correct": true, "explanation": "『毎晩七時に夕食を』に続く動詞として、夕食をとる行為に合う。"}, {"text": "読む", "is_correct": false, "explanation": "『夕食を読む』は成り立たず、食事の文脈と合わない。"}, {"text": "書く", "is_correct": false, "explanation": "『夕食を書く』は意味をなさず、日常の食事を表せない。"}, {"text": "歩く", "is_correct": false, "explanation": "『夕食を歩く』は文として成立せず、目的語と結びつかない。"}], "explanations": {"食べる": "『毎晩七時に夕食を』に続く動詞として、夕食をとる行為に合う。", "読む": "『夕食を読む』は成り立たず、食事の文脈と合わない。", "書く": "『夕食を書く』は意味をなさず、日常の食事を表せない。", "歩く": "『夕食を歩く』は文として成立せず、目的語と結びつかない。"}, "sentence_index": 0, "correct_answer": "食べる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "資料の整理に、思った以上に時間を食べた。", "explanation": "〈食う〉の慣用句『時間を食う』（時間がかかる）の意味。口に入れる意味の『食べる』では使えず、『時間を食べた』とは言わない。"}, {"text": "喉が渇いたので、お茶を食べた。", "explanation": "〈飲む〉の意味。お茶は飲むものであり、食べるとは言わない。"}, {"text": "食後に、たばこを食べた。", "explanation": "〈吸う〉の意味。たばこは吸うものであり、食べるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38170, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食べた", "is_correct": true, "explanation": "『家族みんなでカレーを』に続く過去形の動詞として自然。"}, {"text": "寝た", "is_correct": false, "explanation": "『カレーを寝た』は成り立たず、食事の文脈と合わない。"}, {"text": "投げた", "is_correct": false, "explanation": "『カレーを投げた』は不自然で、家族の食事の場面と合わない。"}, {"text": "走った", "is_correct": false, "explanation": "『カレーを走った』は意味をなさず、目的語と結びつかない。"}], "explanations": {"食べた": "『家族みんなでカレーを』に続く過去形の動詞として自然。", "寝た": "『カレーを寝た』は成り立たず、食事の文脈と合わない。", "投げた": "『カレーを投げた』は不自然で、家族の食事の場面と合わない。", "走った": "『カレーを走った』は意味をなさず、目的語と結びつかない。"}, "sentence_index": 6, "correct_answer": "食べた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花の香りを食べると、心が落ち着く。", "explanation": "〈嗅ぐ〉の意味。香りは嗅ぐものであり、食べるとは言わない。"}, {"text": "子猫は自分の足を食べて、きれいにする。", "explanation": "〈舐める〉の意味。足を舐めてきれいにするのであり、食べるとは言わない。"}, {"text": "病後は、栄養を食べるように心がけている。", "explanation": "〈摂る〉の意味。栄養は摂るものであり、食べるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38170, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎晩、家族と夕食に食べる。", "corrected_sentence": "毎晩、家族と夕食を食べる。", "error_description": "『食べる』の対象を示す助詞は『を』。『に』は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "食べた", "is_correct": true, "explanation": "過去形で、『おなかがすいたので、おにぎりを食べた』の過去の出来事に合う。"}, {"text": "食べない", "is_correct": false, "explanation": "否定形になり、実際に食べた事実と反する。"}, {"text": "食べて", "is_correct": false, "explanation": "て形は文を言い切れず、文末の形として不適切。"}, {"text": "食べれば", "is_correct": false, "explanation": "仮定形で、条件節のまま文が終わり、言い切れない。"}], "correct_form": "食べた", "base_form": "食べる", "form_label": "過去形", "sentence_index": 1, "explanations": {"食べた": "過去形で、『おなかがすいたので、おにぎりを食べた』の過去の出来事に合う。", "食べない": "否定形になり、実際に食べた事実と反する。", "食べて": "て形は文を言い切れず、文末の形として不適切。", "食べれば": "仮定形で、条件節のまま文が終わり、言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38170, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨夜、弟と二人でカレーを食べった。", "corrected_sentence": "昨夜、弟と二人でカレーを食べた。", "error_description": "『食べた』が正しい過去形。『食べった』は誤った活用。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "食べた", "is_correct": true, "explanation": "過去形で、『たくさん食べたので』の過去の行為に合う。"}, {"text": "食べろ", "is_correct": false, "explanation": "命令形で、「ので」に続けられず、文として成り立たない。"}, {"text": "食べよう", "is_correct": false, "explanation": "意志形は「ので」に続けられず、文が成り立たない。"}, {"text": "食べるな", "is_correct": false, "explanation": "禁止形で、「ので」に続かず、文として不成立になる。"}], "correct_form": "食べた", "base_form": "食べる", "form_label": "過去形", "sentence_index": 7, "explanations": {"食べた": "過去形で、『たくさん食べたので』の過去の行為に合う。", "食べろ": "命令形で、「ので」に続けられず、文として成り立たない。", "食べよう": "意志形は「ので」に続けられず、文が成り立たない。", "食べるな": "禁止形で、「ので」に続かず、文として不成立になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38171, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『食べる』の対象（パン）を示す『を』。"}, {"text": "に", "is_correct": false, "explanation": "『パンに食べる』は対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』は食べる対象にならず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は連体修飾で、『パンの食べる』は文として成立しない。"}], "correct_answer": "を", "explanations": {"を": "『食べる』の対象（パン）を示す『を』。", "に": "『パンに食べる』は対象を示せず、不自然。", "へ": "方向を示す『へ』は食べる対象にならず、文が成り立たない。", "の": "『の』は連体修飾で、『パンの食べる』は文として成立しない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
