INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38171, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "食物を口に入れて、かんで、のみこむこと。", "primary_collocate": null, "pronunciation": "たべる", "ipa": "tabeɾɯ", "syllable_count": 3, "sentences": [{"text": "子供は躊躇いなくその表皮に歯を立て、甘酸っぱい果汁を唇に伝わせながら貪るように食べる。", "target_word": "食べる", "complexity_tier": "T5", "furigana": "子供(こども)は躊躇(ためら)いなくその表皮(ひょうひ)に歯(は)を立(た)て、甘酸(あまず)っぱい果汁(かじゅう)を唇(くちびる)に伝(つた)わせながら貪(むさぼ)るように食(た)べる。", "sentence_source": "mined"}, {"text": "朝ごはんにパンを食べる。", "target_word": "食べる", "complexity_tier": "T2", "furigana": "朝(あさ)ごはんにパンを食(た)べる。", "sentence_source": "generated"}, {"text": "よくかんで食べる。", "target_word": "食べる", "complexity_tier": "T2", "furigana": "よくかんで食(た)べる。", "sentence_source": "generated"}, {"text": "熱いので、冷ましてから食べたほうがいい。", "target_word": "食べた", "complexity_tier": "T3", "furigana": "熱(あつ)いので、冷(さ)ましてから食(た)べたほうがいい。", "sentence_source": "generated"}, {"text": "昨日は友達と寿司を食べた。", "target_word": "食べた", "complexity_tier": "T2", "furigana": "昨日(きのう)は友達(ともだち)と寿司(すし)を食(た)べた。", "sentence_source": "generated"}, {"text": "辛いものは苦手で、あまり食べない。", "target_word": "食べない", "complexity_tier": "T3", "furigana": "辛(から)いものは苦手(にがて)で、あまり食(た)べない。", "sentence_source": "generated"}, {"text": "食べる前に、手を洗う。", "target_word": "食べる", "complexity_tier": "T2", "furigana": "食(た)べる前(まえ)に、手(て)を洗(あら)う。", "sentence_source": "generated"}, {"text": "時間がなかったので、歩きながら食べた。", "target_word": "食べた", "complexity_tier": "T3", "furigana": "時間(じかん)がなかったので、歩(ある)きながら食(た)べた。", "sentence_source": "generated"}, {"text": "弟は好き嫌いがなく、何でも食べる。", "target_word": "食べる", "complexity_tier": "T3", "furigana": "弟(おとうと)は好(す)き嫌(きら)いがなく、何(なん)でも食(た)べる。", "sentence_source": "generated"}, {"text": "この果物は皮をむいて食べるとおいしい。", "target_word": "食べる", "complexity_tier": "T3", "furigana": "この果物(くだもの)は皮(かわ)をむいて食(た)べるとおいしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食べる", "label": "終止形"}, {"form": "食べない", "label": "否定形"}, {"form": "食べます", "label": "丁寧形"}, {"form": "食べた", "label": "過去形"}, {"form": "食べて", "label": "て形"}, {"form": "食べれば", "label": "仮定形"}, {"form": "食べよう", "label": "意志形"}, {"form": "食べられる", "label": "可能形"}], "register": "中立（常体）", "sense_fingerprint": "食物を口に入れてかみ、のみこむ動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 6 words above tier T2 (max 3): 躊躇い (Zipf 2.5), 表皮 (Zipf 3.15), 甘酸っぱい (Zipf 2.99), 果汁 (Zipf 3.45), 伝わ (Zipf 2.78), 貪る (Zipf 2.82)']::text[], '1d830dd3-4726-462f-b993-0f6b9ed00287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38171, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食べる", "is_correct": true, "explanation": "「貪るように」の後に続き、食物を口に入れてかむ動作として文脈に合う。"}, {"text": "投げる", "is_correct": false, "explanation": "「貪るように投げる」は成り立たず、歯を立てて果汁を味わう文脈とも合わない。"}, {"text": "歩く", "is_correct": false, "explanation": "「貪るように歩く」は意味をなさず、表皮に歯を立てる動作と結びつかない。"}, {"text": "書く", "is_correct": false, "explanation": "「貪るように書く」は不自然で、果汁が唇に伝わる描写と合わない。"}], "explanations": {"食べる": "「貪るように」の後に続き、食物を口に入れてかむ動作として文脈に合う。", "投げる": "「貪るように投げる」は成り立たず、歯を立てて果汁を味わう文脈とも合わない。", "歩く": "「貪るように歩く」は意味をなさず、表皮に歯を立てる動作と結びつかない。", "書く": "「貪るように書く」は不自然で、果汁が唇に伝わる描写と合わない。"}, "sentence_index": 0, "correct_answer": "食べる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "準備にずいぶん時間を食べた。", "explanation": "〈食う〉の慣用句『時間を食う』（時間がかかる）の意味。口に入れる意味の『食べる』では使えず、『時間を食べた』とは言わない。"}, {"text": "のどが渇いて、水を食べた。", "explanation": "〈飲む〉の意味。水は飲むものであり、この定義の『食べる』とは言わない。"}, {"text": "仕事の合間に、たばこを食べた。", "explanation": "〈吸う〉の意味。たばこは吸うものであり、食べるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38171, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食べる", "is_correct": true, "explanation": "動詞の終止形で『食べる前に』と続き、手を洗う前の行為として合う。"}, {"text": "食べて", "is_correct": false, "explanation": "て形は『前に』に続かず、『食べて前に』は成り立たない。"}, {"text": "食べよう", "is_correct": false, "explanation": "意志形は『前に』の前に置けず、文が不成立になる。"}, {"text": "食べます", "is_correct": false, "explanation": "丁寧形は『前に』に直接続かず、不自然になる。"}], "explanations": {"食べる": "動詞の終止形で『食べる前に』と続き、手を洗う前の行為として合う。", "食べて": "て形は『前に』に続かず、『食べて前に』は成り立たない。", "食べよう": "意志形は『前に』の前に置けず、文が不成立になる。", "食べます": "丁寧形は『前に』に直接続かず、不自然になる。"}, "sentence_index": 6, "correct_answer": "食べる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コーヒーの香りを食べて、気分が落ち着いた。", "explanation": "〈嗅ぐ〉の意味。香りは嗅ぐものであり、食べるとは言わない。"}, {"text": "子猫が自分の手を食べて、毛づくろいした。", "explanation": "〈舐める〉の意味。手を舐めて毛づくろいするのであり、食べるとは言わない。"}, {"text": "毎朝、栄養を食べるように心がけている。", "explanation": "〈摂る〉の意味。栄養は摂るものであり、食べるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38171, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は毎朝、ご飯に食べる。", "corrected_sentence": "私は毎朝、ご飯を食べる。", "error_description": "『食べる』の対象を示す助詞は『を』。『に』は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "食べる", "is_correct": true, "explanation": "文を言い切る終止形で、『朝ごはんにパンを食べる。』の形に合う。"}, {"text": "食べたら", "is_correct": false, "explanation": "条件形で、文の途中で終わり、言い切れない。"}, {"text": "食べて", "is_correct": false, "explanation": "て形は文を言い切れず、文末の形として不適切。"}, {"text": "食べながら", "is_correct": false, "explanation": "ながら形で、文を言い切れず、文末の形として不適切。"}], "correct_form": "食べる", "base_form": "食べる", "form_label": "終止形", "sentence_index": 1, "explanations": {"食べる": "文を言い切る終止形で、『朝ごはんにパンを食べる。』の形に合う。", "食べたら": "条件形で、文の途中で終わり、言い切れない。", "食べて": "て形は文を言い切れず、文末の形として不適切。", "食べながら": "ながら形で、文を言い切れず、文末の形として不適切。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38171, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "たくさん食べって、眠くなった。", "corrected_sentence": "たくさん食べて、眠くなった。", "error_description": "『食べて』はて形。『食べって』は誤った活用。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "食べた", "is_correct": true, "explanation": "過去の出来事を常体で述べる過去形で、文の内容に合う。"}, {"text": "食べよう", "is_correct": false, "explanation": "意志形で、文末の過去の事実を述べる形にならず、文が成り立たない。"}, {"text": "食べろ", "is_correct": false, "explanation": "命令形で、過去の出来事を述べる文末に合わず、文として不自然。"}, {"text": "食べれば", "is_correct": false, "explanation": "仮定形になり、過去の事実を述べる文が成り立たない。"}], "correct_form": "食べた", "base_form": "食べる", "form_label": "過去形", "sentence_index": 7, "explanations": {"食べた": "過去の出来事を常体で述べる過去形で、文の内容に合う。", "食べよう": "意志形で、文末の過去の事実を述べる形にならず、文が成り立たない。", "食べろ": "命令形で、過去の出来事を述べる文末に合わず、文として不自然。", "食べれば": "仮定形になり、過去の事実を述べる文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ed29e7-964b-43ff-9f54-d5a2923c7be5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
