INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38172, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "程度が非常に高いさま。とても。", "primary_collocate": null, "pronunciation": "たいへん", "ipa": "taiheɴ", "syllable_count": 4, "sentences": [{"text": "昨日は大変疲れたので、早く寝ました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "昨日[きのう]は大変[たいへん]疲[つか]れたので、早[はや]く寝[ね]ました。", "sentence_source": "generated"}, {"text": "この本は大変おもしろいので、友達にも勧めたいです。", "target_word": "大変", "complexity_tier": "T3", "furigana": "この本[ほん]は大変[たいへん]おもしろいので、友達[ともだち]にも勧[すす]めたいです。", "sentence_source": "generated"}, {"text": "先生は大変親切な方で、いつも質問に答えてくれます。", "target_word": "大変", "complexity_tier": "T3", "furigana": "先生[せんせい]は大変[たいへん]親切[しんせつ]な方[かた]で、いつも質問[しつもん]に答[こた]えてくれます。", "sentence_source": "generated"}, {"text": "今日は大変暑いから、帽子をかぶって出かけましょう。", "target_word": "大変", "complexity_tier": "T3", "furigana": "今日[きょう]は大変[たいへん]暑[あつ]いから、帽子[ぼうし]をかぶって出[で]かけましょう。", "sentence_source": "generated"}, {"text": "京都の夜景は大変きれいで、写真をたくさん撮りました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "京都[きょうと]の夜景[やけい]は大変[たいへん]きれいで、写真[しゃしん]をたくさん撮[と]りました。", "sentence_source": "generated"}, {"text": "大変申し訳ありませんが、明日の会議には出られません。", "target_word": "大変", "complexity_tier": "T3", "furigana": "大変[たいへん]申[もう]し訳[わけ]ありませんが、明日[あした]の会議[かいぎ]には出[で]られません。", "sentence_source": "generated"}, {"text": "駅から遠いのに、この店は大変人気があります。", "target_word": "大変", "complexity_tier": "T3", "furigana": "駅[えき]から遠[とお]いのに、この店[みせ]は大変[たいへん]人気[にんき]があります。", "sentence_source": "generated"}, {"text": "母の料理は大変おいしくて、おかわりしました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "母[はは]の料理[りょうり]は大変[たいへん]おいしくて、おかわりしました。", "sentence_source": "generated"}, {"text": "試験の前の日は大変緊張して、あまり眠れませんでした。", "target_word": "大変", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]の日[ひ]は大変[たいへん]緊張[きんちょう]して、あまり眠[ねむ]れませんでした。", "sentence_source": "generated"}, {"text": "雨が降っていたので、道が大変滑りやすくなっていました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]っていたので、道[みち]が大変[たいへん]滑[すべ]りやすくなっていました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大変", "label": "基本形"}], "register": "polite", "sense_fingerprint": "程度が高いことを表す副詞。形容詞や動詞を修飾して「とても」の意味。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38172, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大変", "is_correct": true, "explanation": "「大変」はここで「とても」の意の副詞。「大変疲れた」と程度を強める。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す語。「ぐっすり疲れた」は意味が通らず、程度を表す語が必要な位置に合わない。"}, {"text": "わざわざ", "is_correct": false, "explanation": "手間をかけて行うの意。疲労の程度を表せず、「わざわざ疲れた」は文として成り立たない。"}, {"text": "さっそく", "is_correct": false, "explanation": "間を置かず行うの意。「さっそく疲れた」では時間の意味が文に合わない。"}], "explanations": {"大変": "「大変」はここで「とても」の意の副詞。「大変疲れた」と程度を強める。", "ぐっすり": "眠りの深さを表す語。「ぐっすり疲れた」は意味が通らず、程度を表す語が必要な位置に合わない。", "わざわざ": "手間をかけて行うの意。疲労の程度を表せず、「わざわざ疲れた」は文として成り立たない。", "さっそく": "間を置かず行うの意。「さっそく疲れた」では時間の意味が文に合わない。"}, "sentence_index": 0, "correct_answer": "大変"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電話をもらったら、大変行きます。", "explanation": "ここは〈すぐ〉（ただちに）の意味。〈大変〉は程度の強さを表すので、時間の速さを表す〈すぐ〉の代わりにはならない。"}, {"text": "宿題は大変終わった。", "explanation": "ここは〈ほとんど〉（ほぼ、大部分）の意味。〈大変〉は程度の強さを表し、〈ほとんど〉のように進み具合（ほぼ完了した）を表すことはできない。"}, {"text": "大変来てください。", "explanation": "ここは〈ぜひ〉（どうしても、強く望んで）の意味。〈大変〉は程度の強さを表すので、強い願いを表す〈ぜひ〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38172, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大変", "is_correct": true, "explanation": "「大変人気があります」の「大変」は、人気の程度を強める副詞。"}, {"text": "少しも", "is_correct": false, "explanation": "打ち消しの文と結ぶ語。肯定の「人気があります」には合わない。"}, {"text": "決して", "is_correct": false, "explanation": "打ち消しの文と結ぶ語。肯定の文では使えない。"}, {"text": "きっかり", "is_correct": false, "explanation": "時刻や数量がちょうどであることを表す。人気の程度を表す文脈には合わない。"}], "explanations": {"大変": "「大変人気があります」の「大変」は、人気の程度を強める副詞。", "少しも": "打ち消しの文と結ぶ語。肯定の「人気があります」には合わない。", "決して": "打ち消しの文と結ぶ語。肯定の文では使えない。", "きっかり": "時刻や数量がちょうどであることを表す。人気の程度を表す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "大変"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店のことは大変知らない。", "explanation": "ここは〈全然〉（まったく〜ない）の意味。〈大変〉は程度の強調で、打ち消しと結んで「まったく〜ない」の意味にはならない。"}, {"text": "足音を立てないよう、大変立ち上がった。", "explanation": "ここは〈そっと〉（静かに、人に気づかれないように）の意味。〈大変〉は程度の強さを表すので、動作の静かさを表す〈そっと〉の代わりにはならない。"}, {"text": "長い準備が大変終わった。", "explanation": "ここは〈やっと〉（苦労の末に、ようやく）の意味。〈大変〉は程度の強さなので、苦労して成し遂げた気持ちを表す〈やっと〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38172, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は大変な寒くて、外に出られませんでした。", "corrected_sentence": "昨日は大変寒くて、外に出られませんでした。", "error_description": "「大変」は副詞なので、形容詞の前に「な」を付けない。「大変な寒い」は誤りで、正しくは「大変寒い」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38172, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その日の山登りは大変だ暑かった。", "corrected_sentence": "その日の山登りは大変暑かった。", "error_description": "副詞「大変」の後に「だ」を付けない。「大変だ暑い」は誤りで、正しくは「大変暑い」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
