INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38173, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "程度がはなはだしいさま。非常に。", "primary_collocate": null, "pronunciation": "たいへん", "ipa": "taiheɴ", "syllable_count": 4, "sentences": [{"text": "本日は大変お忙しい中、ご出席いただきありがとうございます。", "target_word": "大変", "complexity_tier": "T3", "furigana": "本日[ほんじつ]は大変[たいへん]お忙[いそが]しい中[なか]、ご出席[しゅっせき]いただきありがとうございます。", "sentence_source": "generated"}, {"text": "先日は大変お世話になりました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "先日[せんじつ]は大変[たいへん]お世話[せわ]になりました。", "sentence_source": "generated"}, {"text": "彼の発表は大変すばらしく、会場から大きな拍手が起こりました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "彼[かれ]の発表[はっぴょう]は大変[たいへん]すばらしく、会場[かいじょう]から大[おお]きな拍手[はくしゅ]が起[お]こりました。", "sentence_source": "generated"}, {"text": "新しい工場の完成を、大変うれしく思います。", "target_word": "大変", "complexity_tier": "T3", "furigana": "新[あたら]しい工場[こうじょう]の完成[かんせい]を、大変[たいへん]うれしく思[おも]います。", "sentence_source": "generated"}, {"text": "台風の影響で、飛行機の到着が大変遅れています。", "target_word": "大変", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、飛行機[ひこうき]の到着[とうちゃく]が大変[たいへん]遅[おく]れています。", "sentence_source": "generated"}, {"text": "この地域は大変雨が多く、一年中緑が豊かです。", "target_word": "大変", "complexity_tier": "T3", "furigana": "この地域[ちいき]は大変[たいへん]雨[あめ]が多[おお]く、一年中[いちねんじゅう]緑[みどり]が豊[ゆた]かです。", "sentence_source": "generated"}, {"text": "今年の夏は大変暑く、熱中症で運ばれる人が増えました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は大変[たいへん]暑[あつ]く、熱中症[ねっちゅうしょう]で運[はこ]ばれる人[ひと]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "彼女は大変優秀な成績で大学を卒業しました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大変[たいへん]優秀[ゆうしゅう]な成績[せいせき]で大学[だいがく]を卒業[そつぎょう]しました。", "sentence_source": "generated"}, {"text": "社長は大変厳しい方ですが、社員のことをよく考えています。", "target_word": "大変", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は大変[たいへん]厳[きび]しい方[かた]ですが、社員[しゃいん]のことをよく考[かんが]えています。", "sentence_source": "generated"}, {"text": "長い間お待たせして、大変失礼いたしました。", "target_word": "大変", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]お待[ま]たせして、大変[たいへん]失礼[しつれい]いたしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大変", "label": "基本形"}], "register": "formal", "sense_fingerprint": "程度が非常に高いことを表す改まった副詞。挨拶や丁寧な文で形容詞・動詞を修飾する。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38173, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大変", "is_correct": true, "explanation": "「大変お忙しい」の「大変」は、「お忙しい」の程度を強める副詞で、挨拶の文に合う。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "眠りの深さを表す語。「ぐっすりお忙しい」は意味が通らない。"}, {"text": "ひとまず", "is_correct": false, "explanation": "当面はの意を表す語で、程度を強める働きはない。「ひとまずお忙しい」は不自然。"}, {"text": "ぴったり", "is_correct": false, "explanation": "ちょうど合う意を表す語で、程度を強める用法はない。「ぴったりお忙しい」は合わない。"}], "explanations": {"大変": "「大変お忙しい」の「大変」は、「お忙しい」の程度を強める副詞で、挨拶の文に合う。", "ぐっすり": "眠りの深さを表す語。「ぐっすりお忙しい」は意味が通らない。", "ひとまず": "当面はの意を表す語で、程度を強める働きはない。「ひとまずお忙しい」は不自然。", "ぴったり": "ちょうど合う意を表す語で、程度を強める用法はない。「ぴったりお忙しい」は合わない。"}, "sentence_index": 0, "correct_answer": "大変"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大変窓の外を見ると、雪が降っていた。", "explanation": "ここは〈ふと〉（思いがけず、なにげなく）の意味。〈大変〉は程度の強さを表すので、思いがけない一瞬の動作を表す〈ふと〉の代わりにはならない。"}, {"text": "夕方になって、みんな大変帰りました。", "explanation": "ここは〈もう〉（すでに）の意味。〈大変〉は程度の強さを表すので、動作がすでに済んだことを表す〈もう〉の代わりにはならない。"}, {"text": "その危険には大変気づきませんでした。", "explanation": "ここは〈全く〉（まったく〜ない）の意味。〈大変〉は程度の強調で、打ち消しと結んで「まったく〜ない」の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38173, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大変", "is_correct": true, "explanation": "「大変暑く」の「大変」は、暑さの程度を強める副詞。"}, {"text": "一度も", "is_correct": false, "explanation": "回数の否定を表す語で、暑さの程度には合わない。"}, {"text": "ちっとも", "is_correct": false, "explanation": "打ち消しと結ぶ語。肯定の「暑く」には続かない。"}, {"text": "まるで", "is_correct": false, "explanation": "たとえを表す語で、程度の副詞として「暑く」と続けると不自然。"}], "explanations": {"大変": "「大変暑く」の「大変」は、暑さの程度を強める副詞。", "一度も": "回数の否定を表す語で、暑さの程度には合わない。", "ちっとも": "打ち消しと結ぶ語。肯定の「暑く」には続かない。", "まるで": "たとえを表す語で、程度の副詞として「暑く」と続けると不自然。"}, "sentence_index": 6, "correct_answer": "大変"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その件については、大変存じ上げません。", "explanation": "ここは〈全然〉（まったく〜ない）の意味。〈大変〉は程度の強調で、打ち消しと結んで「まったく〜ない」の意味にはならない。"}, {"text": "予定どおり、電車が大変到着しました。", "explanation": "ここは〈まもなく〉（もうすぐ、じきに）の意味。〈大変〉は程度の強さを表すので、時間の近さを表す〈まもなく〉の代わりにはならない。"}, {"text": "ずっと探していた鍵が、大変見つかりました。", "explanation": "ここは〈やっと〉（苦労の末に、ようやく）の意味。〈大変〉は程度の強さで、苦労して得た結果を表す〈やっと〉の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38173, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい店の開店を、大変のうれしく思います。", "corrected_sentence": "新しい店の開店を、大変うれしく思います。", "error_description": "副詞「大変」に「の」を付けない。「大変のうれしく」は誤りで、正しくは「大変うれしく」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38173, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の宴会は大変を盛り上がりました。", "corrected_sentence": "昨日の宴会は大変盛り上がりました。", "error_description": "副詞「大変」に格助詞「を」は付かない。「大変を盛り上がりました」は誤りで、正しくは「大変盛り上がりました」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38174, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「幸せを感じる」の対象を示す「を」で、感じるの目的語として合う。"}, {"text": "か", "is_correct": false, "explanation": "疑問の「か」では感じるの目的語にならず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」では、感じるに続けても意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は感じるに続かず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「幸せを感じる」の対象を示す「を」で、感じるの目的語として合う。", "か": "疑問の「か」では感じるの目的語にならず、文が成り立たない。", "で": "手段や場所の「で」では、感じるに続けても意味が通らない。", "へ": "方向を示す「へ」は感じるに続かず、不自然。"}, "error_tags": {"か": "疑問", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "「幸せ」の対義語で、うれしい気持ちとは反対の状態を表す。"}, {"text": "悲しみ", "is_correct": false, "explanation": "感情を表すが、「幸せ」の対義語として辞書で扱われない。"}, {"text": "苦労", "is_correct": false, "explanation": "つらい思いを表すが、「幸せ」の対義語としては挙がらない。"}, {"text": "寂しさ", "is_correct": false, "explanation": "感情名詞だが、「幸せ」の対義語ではない。"}], "correct_answer": "不幸", "explanations": {"不幸": "「幸せ」の対義語で、うれしい気持ちとは反対の状態を表す。", "悲しみ": "感情を表すが、「幸せ」の対義語として辞書で扱われない。", "苦労": "つらい思いを表すが、「幸せ」の対義語としては挙がらない。", "寂しさ": "感情名詞だが、「幸せ」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38174, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語の「が」で、「広がる」の主語として合う。"}, {"text": "を", "is_correct": false, "explanation": "「広がる」は自動詞なので目的語の「を」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の「で」では、広がるの主語が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "引用や共同を表す「と」では、広がるの主語にならず不自然。"}], "correct_answer": "が", "explanations": {"が": "主語の「が」で、「広がる」の主語として合う。", "を": "「広がる」は自動詞なので目的語の「を」は取らない。", "で": "手段や場所の「で」では、広がるの主語が成立しない。", "と": "引用や共同を表す「と」では、広がるの主語にならず不自然。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "引用・共同"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "「幸せ」の対義語で、うれしい気持ちとは反対の状態を表す。"}, {"text": "憂い", "is_correct": false, "explanation": "物思いの意味で、「幸せ」の対義語ではない。"}, {"text": "苦悩", "is_correct": false, "explanation": "強い悩みを表すが、「幸せ」の対義語としては挙がらない。"}, {"text": "不安", "is_correct": false, "explanation": "心配の意味で、「幸せ」の対義語ではない。"}], "correct_answer": "不幸", "explanations": {"不幸": "「幸せ」の対義語で、うれしい気持ちとは反対の状態を表す。", "憂い": "物思いの意味で、「幸せ」の対義語ではない。", "苦悩": "強い悩みを表すが、「幸せ」の対義語としては挙がらない。", "不安": "心配の意味で、「幸せ」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38174, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "うれしい気もちになること。", "primary_collocate": null, "pronunciation": "しあわせ", "ipa": "ɕiawase", "syllable_count": 4, "sentences": [{"text": "友だちから手紙をもらって、とても幸せな気持ちになりました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "ともだちからてがみをもらって、とてもしあわせなきもちになりました。", "sentence_source": "generated"}, {"text": "温かいお風呂に入ると、幸せを感じます。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "あたたかいおふろにはいると、しあわせをかんじます。", "sentence_source": "generated"}, {"text": "子どもの笑顔を見るたびに、幸せな気分になります。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "こどものえがおをみるたびに、しあわせなきぶんになります。", "sentence_source": "generated"}, {"text": "好きな歌を歌っているとき、私は幸せです。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "すきなうたをうたっているとき、わたしはしあわせです。", "sentence_source": "generated"}, {"text": "おいしいケーキを食べた妹は、幸せな顔をしていました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "おいしいケーキをたべたいもうとは、しあわせなかおをしていました。", "sentence_source": "generated"}, {"text": "久しぶりに家族と食事ができて、幸せでした。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "ひさしぶりにかぞくとしょくじができて、しあわせでした。", "sentence_source": "generated"}, {"text": "雨上がりの空に虹を見つけて、ちょっと幸せになりました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "あめあがりのそらににじをみつけて、ちょっとしあわせになりました。", "sentence_source": "generated"}, {"text": "母のお弁当を開けた瞬間、幸せが胸いっぱいに広がりました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "ははのおべんとうをあけたしゅんかん、しあわせがむねいっぱいにひろがりました。", "sentence_source": "generated"}, {"text": "朝いちばんにコーヒーを飲む時間が、私には小さな幸せです。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "あさいちばんにコーヒーをのむじかんが、わたしにはちいさなしあわせです。", "sentence_source": "generated"}, {"text": "「ありがとう」と言われて、幸せな気持ちで一日を終えました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "「ありがとう」といわれて、しあわせなきもちでいちにちをおえました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸せ", "label": "基本形"}, {"form": "幸せな", "label": "連体形"}, {"form": "幸せに", "label": "連用形"}, {"form": "幸せです", "label": "丁寧形"}], "register": "丁寧", "sense_fingerprint": "出来事をきっかけに、その場でうれしい気持ちになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38174, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幸せ", "is_correct": true, "explanation": "「とても幸せな気持ち」の形で、名詞として「な」に続く。"}, {"text": "幸せに", "is_correct": false, "explanation": "連用形は「な」に続けると文が成り立たない。"}, {"text": "幸せで", "is_correct": false, "explanation": "で形は「な」に続かず、文として不自然。"}, {"text": "幸せだ", "is_correct": false, "explanation": "断定の「だ」は「な」に続けられず、「幸せだな気持ち」は誤り。"}], "explanations": {"幸せ": "「とても幸せな気持ち」の形で、名詞として「な」に続く。", "幸せに": "連用形は「な」に続けると文が成り立たない。", "幸せで": "で形は「な」に続かず、文として不自然。", "幸せだ": "断定の「だ」は「な」に続けられず、「幸せだな気持ち」は誤り。"}, "sentence_index": 0, "correct_answer": "幸せ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新しいペンは幸せです。", "explanation": "ここは〈気に入って満足している〉の意味。物に対しては「気に入っている」と言い、「幸せ」は人の心の状態に使うので合わない。"}, {"text": "明日の天気は、とても幸せだと思います。", "explanation": "ここは〈好天〉の意味。天気の良し悪しは「幸せ」ではなく「いい天気」などで表すので合わない。"}, {"text": "彼は会議で幸せな意見を出しました。", "explanation": "ここは〈有益〉の意味。意見の良し悪しには「有益」を使い、幸せは感情にしか使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38174, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幸せ", "is_correct": true, "explanation": "「ちょっと幸せになりました」で、「幸せ」に「に」が続いて自然。"}, {"text": "幸せな", "is_correct": false, "explanation": "な形は「になりました」に続けられず、不自然。"}, {"text": "幸せの", "is_correct": false, "explanation": "「の」を付けると「になりました」が続かず、成り立たない。"}, {"text": "幸せを", "is_correct": false, "explanation": "目的語の「を」は「になる」に続かず、文法的に誤り。"}], "explanations": {"幸せ": "「ちょっと幸せになりました」で、「幸せ」に「に」が続いて自然。", "幸せな": "な形は「になりました」に続けられず、不自然。", "幸せの": "「の」を付けると「になりました」が続かず、成り立たない。", "幸せを": "目的語の「を」は「になる」に続かず、文法的に誤り。"}, "sentence_index": 6, "correct_answer": "幸せ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "健康診断の結果が悪くて、幸せな気持ちになりました。", "explanation": "ここは〈幸い（不幸中の幸い）〉の意味。悪い結果には「幸せな気持ち」ではなく不安や落胆が合うので、この文脈では合わない。"}, {"text": "寝坊して、朝から幸せに遅刻しました。", "explanation": "ここは〈好都合〉の意味。遅刻は好都合な出来事ではないので、「幸せに」では合わない。"}, {"text": "大切な書類をなくして、幸せな気分になりました。", "explanation": "ここは〈安堵（ほっとする）〉の意味。なくし物をしたことにほっとする要素はなく、「幸せ」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38174, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お祭りの夜、子どもたちは幸せが感じていました。", "corrected_sentence": "お祭りの夜、子どもたちは幸せを感じていました。", "error_description": "「感じる」は対象を「を」で示す。「が」は誤りで、正しくは「幸せを感じていました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38174, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族と食卓を囲むと、幸せを感じるます。", "corrected_sentence": "家族と食卓を囲むと、幸せを感じます。", "error_description": "「感じる」に「ます」を続けるには「感じ」に変える。「感じるます」は「る」が余分で誤り。正しくは「感じます」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38175, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "「幸せ」の対義語。心が満たされない状態を表し、ここでの満足して幸せな人生と対になる。"}, {"text": "健康", "is_correct": false, "explanation": "身体が丈夫な状態を表す。心が満たされているかどうかの反対語ではない。"}, {"text": "平和", "is_correct": false, "explanation": "争いがない状態を表す。心の満たされ方の反対語とは言えない。"}, {"text": "財産", "is_correct": false, "explanation": "持っている資産を指す。心の満足の反対語にはならない。"}], "correct_answer": "不幸", "explanations": {"不幸": "「幸せ」の対義語。心が満たされない状態を表し、ここでの満足して幸せな人生と対になる。", "健康": "身体が丈夫な状態を表す。心が満たされているかどうかの反対語ではない。", "平和": "争いがない状態を表す。心の満たされ方の反対語とは言えない。", "財産": "持っている資産を指す。心の満足の反対語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38175, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "「幸せ」の対義語。満たされない状態を表し、ここでの満足して暮らす幸せと対になる。"}, {"text": "病気", "is_correct": false, "explanation": "体の不調を表す。心が満たされる状態の反対語とはならない。"}, {"text": "貧困", "is_correct": false, "explanation": "お金や物に乏しい状態を指す。ここで述べる心の満足の反対語とは言えない。"}, {"text": "悲劇", "is_correct": false, "explanation": "悲しい出来事を指す。幸せな状態そのものの反対語ではない。"}], "correct_answer": "不幸", "explanations": {"不幸": "「幸せ」の対義語。満たされない状態を表し、ここでの満足して暮らす幸せと対になる。", "病気": "体の不調を表す。心が満たされる状態の反対語とはならない。", "貧困": "お金や物に乏しい状態を指す。ここで述べる心の満足の反対語とは言えない。", "悲劇": "悲しい出来事を指す。幸せな状態そのものの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38175, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心が満たされて、満足している状態。", "primary_collocate": null, "pronunciation": "しあわせ", "ipa": "ɕiawase", "syllable_count": 4, "sentences": [{"text": "好きな仕事をして家族と暮らせる今の生活が、私の幸せです。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "すきなしごとをしてかぞくとくらせるいまのせいかつが、わたしのしあわせです。", "sentence_source": "generated"}, {"text": "お金がなくても、心が満たされていれば幸せに暮らせます。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "おかねがなくても、こころがみたされていればしあわせにくらせます。", "sentence_source": "generated"}, {"text": "祖母は「毎日元気に過ごせることが幸せです」と言っていました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "そぼは「まいにちげんきにすごせることがしあわせです」といっていました。", "sentence_source": "generated"}, {"text": "彼は多くを望まず、今の暮らしに満足して幸せな人生を送っています。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "かれはおおくをのぞまず、いまのくらしにまんぞくしてしあわせなじんせいをおくっています。", "sentence_source": "generated"}, {"text": "本当の幸せとは何かを、私は長い間考えてきました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "ほんとうのしあわせとはなにかを、わたしはながいあいだかんがえてきました。", "sentence_source": "generated"}, {"text": "家族が健康でいてくれることが、何よりの幸せです。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "かぞくがけんこうでいてくれることが、なによりのしあわせです。", "sentence_source": "generated"}, {"text": "結婚して二十年、夫婦で幸せに年を重ねてきました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "けっこんしてにじゅうねん、ふうふでしあわせにとしをかさねてきました。", "sentence_source": "generated"}, {"text": "幸せな毎日を送るために、無理をしすぎないようにしています。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "しあわせなまいにちをおくるために、むりをしすぎないようにしています。", "sentence_source": "generated"}, {"text": "田舎での静かな暮らしに、父は心から幸せを感じていました。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "いなかでのしずかなくらしに、ちちはこころからしあわせをかんじていました。", "sentence_source": "generated"}, {"text": "物をたくさん持つことより、満足して暮らすことが幸せだと思います。", "target_word": "幸せ", "complexity_tier": "T3", "furigana": "ものをたくさんもつことより、まんぞくしてくらすことがしあわせだとおもいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸せ", "label": "基本形"}, {"form": "幸せな", "label": "連体形"}, {"form": "幸せに", "label": "連用形"}, {"form": "幸せだ", "label": "断定形"}], "register": "丁寧", "sense_fingerprint": "暮らしや人生に心が満たされ、満足している続いた状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38175, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幸せ", "is_correct": true, "explanation": "「私の幸せです」で、今の生活が心の満たされた状態だと言い表す。"}, {"text": "迷惑", "is_correct": false, "explanation": "「迷惑」は人に手間や害をかけることで、好きな仕事と家族との暮らしの評価にはならない。"}, {"text": "騒音", "is_correct": false, "explanation": "「騒音」は耳障りな音を指す。暮らしを「私の騒音です」と言うと意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は空模様を指す。生活を「私の天気です」と言っても文の内容が成り立たない。"}], "explanations": {"幸せ": "「私の幸せです」で、今の生活が心の満たされた状態だと言い表す。", "迷惑": "「迷惑」は人に手間や害をかけることで、好きな仕事と家族との暮らしの評価にはならない。", "騒音": "「騒音」は耳障りな音を指す。暮らしを「私の騒音です」と言うと意味が通らない。", "天気": "「天気」は空模様を指す。生活を「私の天気です」と言っても文の内容が成り立たない。"}, "sentence_index": 0, "correct_answer": "幸せ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は味がよいが、幸せが高い。", "explanation": "ここは〈値段〉の意味。幸せは価格を表さないので、「高い」とは合わない。"}, {"text": "毎日走って、幸せを鍛えた。", "explanation": "ここは〈体力〉の意味。幸せは心の満足を指し、鍛えて強くするものではない。"}, {"text": "彼は幸せが豊富で、どんな質問にも答える。", "explanation": "ここは〈知識〉の意味。幸せは学識や情報を指さないので、「豊富で答える」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38175, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幸せ", "is_correct": true, "explanation": "「夫婦で幸せに年を重ねる」の幸せ。心が満たされた状態で年を重ねたことを表す。"}, {"text": "夢", "is_correct": false, "explanation": "将来の希望を指す。すでに年を重ねてきた事実を述べる文には合わない。"}, {"text": "義務", "is_correct": false, "explanation": "しなければならない務めを指す。夫婦が年を重ねた様子の説明にはならない。"}, {"text": "失敗", "is_correct": false, "explanation": "うまくいかなかったことを指す。ここで述べる満ちた暮らしと合わない。"}], "explanations": {"幸せ": "「夫婦で幸せに年を重ねる」の幸せ。心が満たされた状態で年を重ねたことを表す。", "夢": "将来の希望を指す。すでに年を重ねてきた事実を述べる文には合わない。", "義務": "しなければならない務めを指す。夫婦が年を重ねた様子の説明にはならない。", "失敗": "うまくいかなかったことを指す。ここで述べる満ちた暮らしと合わない。"}, "sentence_index": 6, "correct_answer": "幸せ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の幸せが二十人を超えた。", "explanation": "ここは〈人数〉の意味。幸せは人の数を表さないので、「二十人を超える」とは合わない。"}, {"text": "彼は年齢の割に幸せが若く見える。", "explanation": "ここは〈年齢〉の意味。幸せは年の数を表さないので、「若く見える」の主語にはならない。"}, {"text": "今日は幸せがとても高く、洗濯物が乾かない。", "explanation": "ここは〈湿度〉の意味。幸せは空気中の水分を表さないので、「高い」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38175, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日家族と過ごせて、私は幸せが感じる。", "corrected_sentence": "毎日家族と過ごせて、私は幸せを感じる。", "error_description": "「幸せを感じる」の「を」が「が」になっている。感じる対象の幸せは目的語なので「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38175, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちが元気に育ち、夫婦で幸せな暮らしている。", "corrected_sentence": "子どもたちが元気に育ち、夫婦で幸せに暮らしている。", "error_description": "動詞「暮らしている」を修飾する形は連用形「幸せに」。「幸せな」は連体形で、動詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38177, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「夢を、彼は忘れていない」の目的語。忘れる対象なので「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「夢に忘れていない」では、忘れる対象を示せず文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示す。「夢で忘れていない」では対象を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示す。夢は相手ではないので「夢と忘れていない」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「夢を、彼は忘れていない」の目的語。忘れる対象なので「を」が入る。", "に": "「夢に忘れていない」では、忘れる対象を示せず文が成り立たない。", "で": "「で」は場所や手段を示す。「夢で忘れていない」では対象を表せない。", "と": "「と」は相手や並列を示す。夢は相手ではないので「夢と忘れていない」は不自然。"}, "error_tags": {"に": "位置・対象", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38177, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「彼の夢は」の「は」。夢について述べる文の主題を示す。"}, {"text": "を", "is_correct": false, "explanation": "「夢を小さな店を開く」と目的語が二つ並び、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。夢は行き先ではないので「夢へ」は合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。夢は店を開く起点ではないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「彼の夢は」の「は」。夢について述べる文の主題を示す。", "を": "「夢を小さな店を開く」と目的語が二つ並び、文が成り立たない。", "へ": "「へ」は方向を示す。夢は行き先ではないので「夢へ」は合わない。", "から": "「から」は起点を示す。夢は店を開く起点ではないので合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38177, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "将来こうなりたい、こうしたいという、心の中で思い描く理想や願い。", "primary_collocate": null, "pronunciation": "ゆめ", "ipa": "jɯme", "syllable_count": 2, "sentences": [{"text": "私の夢は、将来医者になって多くの人を助けることだ。", "target_word": "夢", "complexity_tier": "T3", "furigana": "私[わたし]の夢[ゆめ]は、将来[しょうらい]医者[いしゃ]になって多[おお]くの人[ひと]を助[たす]けることだ。", "sentence_source": "generated"}, {"text": "子どものころの夢を、彼は今も忘れていない。", "target_word": "夢", "complexity_tier": "T3", "furigana": "子[こ]どものころの夢[ゆめ]を、彼[かれ]は今[いま]も忘[わす]れていない。", "sentence_source": "generated"}, {"text": "彼女は歌手になる夢をかなえるために、毎日練習している。", "target_word": "夢", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は歌手[かしゅ]になる夢[ゆめ]をかなえるために、毎日[まいにち]練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "夢を持つ人は、困難があってもあきらめにくい。", "target_word": "夢", "complexity_tier": "T3", "furigana": "夢[ゆめ]を持[も]つ人[ひと]は、困難[こんなん]があってもあきらめにくい。", "sentence_source": "generated"}, {"text": "兄は大きな夢を抱いて、外国へ留学した。", "target_word": "夢", "complexity_tier": "T3", "furigana": "兄[あに]は大[おお]きな夢[ゆめ]を抱[いだ]いて、外国[がいこく]へ留学[りゅうがく]した。", "sentence_source": "generated"}, {"text": "家が貧しかったので、大学に行く夢は一度あきらめた。", "target_word": "夢", "complexity_tier": "T3", "furigana": "家[いえ]が貧[まず]しかったので、大学[だいがく]に行[い]く夢[ゆめ]は一度[いちど]あきらめた。", "sentence_source": "generated"}, {"text": "先生に夢を聞かれて、私は宇宙飛行士だと答えた。", "target_word": "夢", "complexity_tier": "T3", "furigana": "先生[せんせい]に夢[ゆめ]を聞[き]かれて、私[わたし]は宇宙飛行士[うちゅうひこうし]だと答[こた]えた。", "sentence_source": "generated"}, {"text": "彼の夢は小さな店を開くことで、そのために貯金している。", "target_word": "夢", "complexity_tier": "T3", "furigana": "彼[かれ]の夢[ゆめ]は小[ちい]さな店[みせ]を開[ひら]くことで、そのために貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "夢がかなった日、母は涙を流して喜んでくれた。", "target_word": "夢", "complexity_tier": "T3", "furigana": "夢[ゆめ]がかなった日[ひ]、母[はは]は涙[なみだ]を流[なが]して喜[よろこ]んでくれた。", "sentence_source": "generated"}, {"text": "自分の夢を人に話すと、不思議とやる気が出てくる。", "target_word": "夢", "complexity_tier": "T3", "furigana": "自分[じぶん]の夢[ゆめ]を人[ひと]に話[はな]すと、不思議[ふしぎ]とやる気[き]が出[で]てくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "夢", "label": "基本形"}, {"form": "夢の", "label": "連体形（の）"}, {"form": "夢を", "label": "目的語形（を）"}], "register": "中立（普通体）", "sense_fingerprint": "将来の理想や願いとしての夢（睡眠中に見る夢ではない）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: 貧しかっ (Zipf 2.46)']::text[], '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38177, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夢", "is_correct": true, "explanation": "「私の夢」は将来医者になるという理想を指し、文の内容に合う。"}, {"text": "騒音", "is_correct": false, "explanation": "耳障りな音を指す。将来の進路の理想を述べる文には合わない。"}, {"text": "迷惑", "is_correct": false, "explanation": "人に手間をかけることを表す。将来の理想を述べる文には合わない。"}, {"text": "悲鳴", "is_correct": false, "explanation": "驚いたときに出す声を指す。将来の理想の説明にはならない。"}], "explanations": {"夢": "「私の夢」は将来医者になるという理想を指し、文の内容に合う。", "騒音": "耳障りな音を指す。将来の進路の理想を述べる文には合わない。", "迷惑": "人に手間をかけることを表す。将来の理想を述べる文には合わない。", "悲鳴": "驚いたときに出す声を指す。将来の理想の説明にはならない。"}, "sentence_index": 0, "correct_answer": "夢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テストの夢が二十点上がった。", "explanation": "ここは〈点数〉の意味。夢は点数を表さないので、「二十点上がった」とは合わない。"}, {"text": "熱があり、夢が高い。", "explanation": "ここは〈体温〉の意味。夢は体の温度を表さないので、「高い」とは合わない。"}, {"text": "テレビの夢を下げた。", "explanation": "ここは〈音量〉の意味。夢は数値として上げ下げできないので、「下げる」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38177, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夢", "is_correct": true, "explanation": "「先生に夢を聞かれて」の夢。将来なりたいものを指し、宇宙飛行士と答える文脈に合う。"}, {"text": "失敗", "is_correct": false, "explanation": "うまくいかなかったことを指す。「先生に失敗を聞かれて」は文脈に合わない。"}, {"text": "不安", "is_correct": false, "explanation": "心配な気持ちを指す。「先生に不安を聞かれて」は文として不自然。"}, {"text": "義務", "is_correct": false, "explanation": "しなければならない務めを指す。将来の職業を問われる場面とは合わない。"}], "explanations": {"夢": "「先生に夢を聞かれて」の夢。将来なりたいものを指し、宇宙飛行士と答える文脈に合う。", "失敗": "うまくいかなかったことを指す。「先生に失敗を聞かれて」は文脈に合わない。", "不安": "心配な気持ちを指す。「先生に不安を聞かれて」は文として不自然。", "義務": "しなければならない務めを指す。将来の職業を問われる場面とは合わない。"}, "sentence_index": 6, "correct_answer": "夢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の夢が二十人を超えた。", "explanation": "ここは〈人数〉の意味。夢は人の数を表さないので、「二十人を超える」とは合わない。"}, {"text": "除湿機で夢を下げた。", "explanation": "ここは〈湿度〉の意味。夢は空気中の水分を表さないので、「下げる」とは合わない。"}, {"text": "三キロ減って、夢が減った。", "explanation": "ここは〈体重〉の意味。夢は重さを表さないので、「減った」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38177, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自分の夢が大切にして、毎日少しずつ前に進む。", "corrected_sentence": "自分の夢を大切にして、毎日少しずつ前に進む。", "error_description": "「大切にする」の目的語は「を」。「夢が大切にする」は誤りで、「夢を大切にする」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38177, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夢をかなうまで、毎日練習を続けている。", "corrected_sentence": "夢がかなうまで、毎日練習を続けている。", "error_description": "「かなう」は自動詞なので主語の「夢が」が正しい。「夢をかなう」は誤りで、目的語の「を」は使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38178, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を示す「に」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「あります」は「を」を取らず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、存在する場所には使えない。"}, {"text": "で", "is_correct": false, "explanation": "「ある」の存在場所は「に」で、「で」は不自然。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を示す「に」が正しい。", "を": "「あります」は「を」を取らず、文が成立しない。", "へ": "「へ」は方向を表し、存在する場所には使えない。", "で": "「ある」の存在場所は「に」で、「で」は不自然。"}, "error_tags": {"を": "object_marker", "へ": "direction", "で": "action_location"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38178, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「緑地のにおい」と名詞を結ぶ「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「緑地をにおい」では名詞の修飾にならず文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「におい」を修飾できない。"}, {"text": "と", "is_correct": false, "explanation": "「緑地とにおいが強くなる」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「緑地のにおい」と名詞を結ぶ「の」が正しい。", "を": "「緑地をにおい」では名詞の修飾にならず文が成立しない。", "へ": "「へ」は方向を表し、「におい」を修飾できない。", "と": "「緑地とにおいが強くなる」では意味が通らない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38178, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面に草や木がたくさんある場所のことです。", "primary_collocate": null, "pronunciation": "りょくち", "ipa": "ɾʲokɯtɕi", "syllable_count": 3, "sentences": [{"text": "緑地に行く。", "target_word": "緑地", "complexity_tier": "T1", "furigana": "緑地[りょくち]に行[い]く。", "sentence_source": "generated"}, {"text": "ここは緑地です。", "target_word": "緑地", "complexity_tier": "T1", "furigana": "ここは緑地[りょくち]です。", "sentence_source": "generated"}, {"text": "緑地に大きい木があります。", "target_word": "緑地", "complexity_tier": "T2", "furigana": "緑地[りょくち]に大[おお]きい木[き]があります。", "sentence_source": "generated"}, {"text": "子どもたちは緑地で走っています。", "target_word": "緑地", "complexity_tier": "T2", "furigana": "子[こ]どもたちは緑地[りょくち]で走[はし]っています。", "sentence_source": "generated"}, {"text": "緑地の中を犬と歩いた。", "target_word": "緑地", "complexity_tier": "T2", "furigana": "緑地[りょくち]の中[なか]を犬[いぬ]と歩[ある]いた。", "sentence_source": "generated"}, {"text": "学校の後ろに小さな緑地ができた。", "target_word": "緑地", "complexity_tier": "T3", "furigana": "学校[がっこう]の後[うし]ろに小[ちい]さな緑地[りょくち]ができた。", "sentence_source": "generated"}, {"text": "緑地では花も草もたくさん見られる。", "target_word": "緑地", "complexity_tier": "T3", "furigana": "緑地[りょくち]では花[はな]も草[くさ]もたくさん見[み]られる。", "sentence_source": "generated"}, {"text": "雨の日は緑地のにおいが強くなる。", "target_word": "緑地", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は緑地[りょくち]のにおいが強[つよ]くなる。", "sentence_source": "generated"}, {"text": "緑地が多い町に引っ越したいと思っている。", "target_word": "緑地", "complexity_tier": "T4", "furigana": "緑地[りょくち]が多[おお]い町[まち]に引[ひ]っ越[こ]したいと思[おも]っている。", "sentence_source": "generated"}, {"text": "この緑地を守るために、みんなで毎週ごみを拾っている。", "target_word": "緑地", "complexity_tier": "T4", "furigana": "この緑地[りょくち]を守[まも]るために、みんなで毎週[まいしゅう]ごみを拾[ひろ]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緑地帯", "label": "派生"}, {"form": "緑地化",