INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38178, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "緑地", "is_correct": true, "explanation": "「りょくち」で、聞いた語と同じ。"}, {"text": "陸地", "is_correct": false, "explanation": "「りくち」で、「りょ」が「り」に変わっている。"}, {"text": "領地", "is_correct": false, "explanation": "「りょうち」で、「く」が「う」に変わっている。"}, {"text": "緑化", "is_correct": false, "explanation": "「りょくか」で、「ち」が「か」に変わっている。"}], "explanations": {"緑地": "「りょくち」で、聞いた語と同じ。", "陸地": "「りくち」で、「りょ」が「り」に変わっている。", "領地": "「りょうち」で、「く」が「う」に変わっている。", "緑化": "「りょくか」で、「ち」が「か」に変わっている。"}, "sentence_index": null, "correct_answer": "緑地"}, "level_3": {"options": [{"text": "緑地", "is_correct": true, "explanation": "行く先の場所として自然で意味が合う。"}, {"text": "名前", "is_correct": false, "explanation": "形は合うが、「行く」先にならず意味が合わない。"}, {"text": "理由", "is_correct": false, "explanation": "形は合うが、場所ではなく意味が合わない。"}, {"text": "気持ち", "is_correct": false, "explanation": "形は合うが、行く先の場所を表さず意味が合わない。"}], "explanations": {"緑地": "行く先の場所として自然で意味が合う。", "名前": "形は合うが、「行く」先にならず意味が合わない。", "理由": "形は合うが、場所ではなく意味が合わない。", "気持ち": "形は合うが、行く先の場所を表さず意味が合わない。"}, "sentence_index": 0, "correct_answer": "緑地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は朝ごはんに緑地を食べた。", "explanation": "緑地は草木のある場所で、食べ物ではない。"}, {"text": "寒い日は緑地を着ると暖かい。", "explanation": "緑地は場所で、服のように着るものではない。"}, {"text": "緑地を書いて先生に出した。", "explanation": "緑地は場所で、宿題のように書いて出すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
