INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38179, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「減る」の主語を示す「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「減る」は自動詞なので「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「緑地に減ると」では主語がなくなり文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「減る」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「減る」の主語を示す「が」が正しい。", "を": "「減る」は自動詞なので「を」は使えない。", "に": "「緑地に減ると」では主語がなくなり文が成立しない。", "へ": "「へ」は方向を表し、「減る」の主語にはならない。"}, "error_tags": {"を": "transitive_confusion", "に": "location_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38179, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "都市や地域の中で、自然の植物が生えている土地や公園などのこと。", "primary_collocate": null, "pronunciation": "りょくち", "ipa": "ɾʲokɯtɕi", "syllable_count": 3, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "緑地", "complexity_tier": "T6", "furigana": "特[とく]に、住民[じゅうみん]の主体的[しゅたいてき]な参加[さんか]により創出[そうしゅつ]されるガーデンは、生物[せいぶつ]多様性[たようせい]の回復[かいふく]のみならず、微気候[びきこう]の改善[かいぜん]といった側面[そくめん]においても近隣[きんりん]緑地[りょくち]に好影響[こうえいきょう]を及[およ]ぼしている。", "sentence_source": "mined"}, {"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "緑地", "complexity_tier": "T6", "furigana": "既存[きぞん]の緑地[りょくち]と有機的[ゆうきてき]にネットワークを形成[けいせい]することで生態系[せいたいけい]の回廊[かいろう]としての機能[きのう]を補完[ほかん]し、ひいては地域[ちいき]全体[ぜんたい]の環境[かんきょう]リテラシーを向上[こうじょう]させる原動力[げんどうりょく]となり得[え]るのである。", "sentence_source": "mined"}, {"text": "緑地で遊ぶ。", "target_word": "緑地", "complexity_tier": "T1", "furigana": "緑地[りょくち]で遊[あそ]ぶ。", "sentence_source": "generated"}, {"text": "駅の近くに広い緑地があります。", "target_word": "緑地", "complexity_tier": "T2", "furigana": "駅[えき]の近[ちか]くに広[ひろ]い緑地[りょくち]があります。", "sentence_source": "generated"}, {"text": "緑地は町の人が休む場所です。", "target_word": "緑地", "complexity_tier": "T2", "furigana": "緑地[りょくち]は町[まち]の人[ひと]が休[やす]む場所[ばしょ]です。", "sentence_source": "generated"}, {"text": "毎朝、緑地を歩いて会社へ行っている。", "target_word": "緑地", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、緑地[りょくち]を歩[ある]いて会社[かいしゃ]へ行[い]っている。", "sentence_source": "generated"}, {"text": "川のそばの緑地でお弁当を食べた。", "target_word": "緑地", "complexity_tier": "T3", "furigana": "川[かわ]のそばの緑地[りょくち]でお弁当[べんとう]を食[た]べた。", "sentence_source": "generated"}, {"text": "緑地が減ると、夏の町は暑くなってしまう。", "target_word": "緑地", "complexity_tier": "T4", "furigana": "緑地[りょくち]が減[へ]ると、夏[なつ]の町[まち]は暑[あつ]くなってしまう。", "sentence_source": "generated"}, {"text": "市は古い工場の跡を緑地に変える計画を発表した。", "target_word": "緑地", "complexity_tier": "T4", "furigana": "市[し]は古[ふる]い工場[こうじょう]の跡[あと]を緑地[りょくち]に変[か]える計画[けいかく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "住宅の間に緑地を残すことは、災害のときの避難場所にもなるため重要だ。", "target_word": "緑地", "complexity_tier": "T5", "furigana": "住宅[じゅうたく]の間[あいだ]に緑地[りょくち]を残[のこ]すことは、災害[さいがい]のときの避難場所[ひなんばしょ]にもなるため重要[じゅうよう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緑地帯", "label": "派生"}, {"form": "緑地化", "label": "派生"}, {"form": "都市緑地", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 都市にある草木の多い土地や公園", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01b9edc6-97f7-4887-afa1-fce3d82da614') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
