tion_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38179, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "緑地", "is_correct": true, "explanation": "「りょくち」で、聞いた語と同じ。"}, {"text": "緑茶", "is_correct": false, "explanation": "「りょくちゃ」で、「ち」が「ちゃ」に変わっている。"}, {"text": "局地", "is_correct": false, "explanation": "「きょくち」で、「りょ」が「きょ」に変わっている。"}, {"text": "領地", "is_correct": false, "explanation": "「りょうち」で、「く」が「う」に変わっている。"}], "explanations": {"緑地": "「りょくち」で、聞いた語と同じ。", "緑茶": "「りょくちゃ」で、「ち」が「ちゃ」に変わっている。", "局地": "「きょくち」で、「りょ」が「きょ」に変わっている。", "領地": "「りょうち」で、「く」が「う」に変わっている。"}, "sentence_index": null, "correct_answer": "緑地"}, "level_3": {"options": [{"text": "緑地", "is_correct": true, "explanation": "川のそばでお弁当を食べる場所として意味が合う。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、お弁当を食べる場所にならず意味が合わない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが、川のそばの場所を表さず意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「で」でお弁当を食べる場所にならず意味が合わない。"}], "explanations": {"緑地": "川のそばでお弁当を食べる場所として意味が合う。", "辞書": "形は合うが、お弁当を食べる場所にならず意味が合わない。", "時計": "形は合うが、川のそばの場所を表さず意味が合わない。", "季節": "形は合うが、「で」でお弁当を食べる場所にならず意味が合わない。"}, "sentence_index": 6, "correct_answer": "緑地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緑地を三台、駐車場に止めておいた。", "explanation": "緑地は土地で、車のように「台」で数えて止めるものではない。"}, {"text": "母は緑地を台所で切って、サラダに入れた。", "explanation": "緑地は土地で、野菜のように切って食べるものではない。"}, {"text": "緑地を弾いて、みんなで歌を歌った。", "explanation": "緑地は場所で、楽器のように弾くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38179, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎週日曜日、家族で緑地をお弁当を食べる。", "corrected_sentence": "毎週日曜日、家族で緑地でお弁当を食べる。", "error_description": "動作が行われる場所は「で」で示すので、「緑地を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38179, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春になると、緑地を花が咲いている。", "corrected_sentence": "春になると、緑地に花が咲いている。", "error_description": "「咲く」は場所を「に」で示すので、「緑地を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95e1ad5a-14c6-43a7-bb2e-85a6e8d64c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38180, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "水平", "is_correct": true, "explanation": "「垂直」の対義語。床や地面と平行な向きを表し、まっすぐ立つ向きと直角をなす。"}, {"text": "斜め", "is_correct": false, "explanation": "傾いている様子を表す。垂直と対になる関係ではない。"}, {"text": "平ら", "is_correct": false, "explanation": "表面に凸凹がない様子を表す。立つ向きの反対語とはならない。"}, {"text": "柔らか", "is_correct": false, "explanation": "かたさの反対を表す。垂直の対義語ではない。"}], "correct_answer": "水平", "explanations": {"水平": "「垂直」の対義語。床や地面と平行な向きを表し、まっすぐ立つ向きと直角をなす。", "斜め": "傾いている様子を表す。垂直と対になる関係ではない。", "平ら": "表面に凸凹がない様子を表す。立つ向きの反対語とはならない。", "柔らか": "かたさの反対を表す。垂直の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38180, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "水平", "is_correct": true, "explanation": "「垂直」の対義語。床や地面と平行な向きを表す。"}, {"text": "滑らか", "is_correct": false, "explanation": "表面に引っかかりがない様子を表す。立つ向きの反対語とはならない。"}, {"text": "静か", "is_correct": false, "explanation": "音や動きが少ない様子を表す。垂直の対義語ではない。"}, {"text": "大まか", "is_correct": false, "explanation": "細部にこだわらない様子を表す。垂直と反対の関係はない。"}], "correct_answer": "水平", "explanations": {"水平": "「垂直」の対義語。床や地面と平行な向きを表す。", "滑らか": "表面に引っかかりがない様子を表す。立つ向きの反対語とはならない。", "静か": "音や動きが少ない様子を表す。垂直の対義語ではない。", "大まか": "細部にこだわらない様子を表す。垂直と反対の関係はない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38180, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "まっすぐ立っていることや、上の方に向かっていること。", "primary_collocate": null, "pronunciation": "すいちょく", "ipa": "sɯitɕokɯ", "syllable_count": 4, "sentences": [{"text": "木の棒を地面に垂直に立てて、旗をつけた。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "木[き]の棒[ぼう]を地面[じめん]に垂直[すいちょく]に立[た]てて、旗[はた]をつけた。", "sentence_source": "generated"}, {"text": "背中を垂直に伸ばして座ると、疲れにくい。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "背中[せなか]を垂直[すいちょく]に伸[の]ばして座[すわ]ると、疲[つか]れにくい。", "sentence_source": "generated"}, {"text": "垂直な崖を登るには、特別な道具が必要だ。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "垂直[すいちょく]な崖[がけ]を登[のぼ]るには、特別[とくべつ]な道具[どうぐ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "ロケットは発射台からほぼ垂直に空へ上がっていった。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "ロケットは発射台[はっしゃだい]からほぼ垂直[すいちょく]に空[そら]へ上[あ]がっていった。", "sentence_source": "generated"}, {"text": "このビルの壁は、床に対して垂直に作られている。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "このビルの{壁|かべ}は、{床|ゆか}に{対|たい}して{垂直|すいちょく}に{作|つく}られている。", "sentence_source": "generated"}, {"text": "柱が垂直に立っているか、糸を使って確かめた。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "柱[はしら]が垂直[すいちょく]に立[た]っているか、糸[いと]を使[つか]って確[たし]かめた。", "sentence_source": "generated"}, {"text": "煙が垂直に昇っていたので、風はないと分かった。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "煙[けむり]が垂直[すいちょく]に昇[のぼ]っていたので、風[かぜ]はないと分[わ]かった。", "sentence_source": "generated"}, {"text": "壁は垂直なので、ここから登るのは難しい。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "壁[かべ]は垂直[すいちょく]なので、ここから登[のぼ]るのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "旗のさおを垂直にしないと、風で倒れやすい。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "旗[はた]のさおを垂直[すいちょく]にしないと、風[かぜ]で倒[たお]れやすい。", "sentence_source": "generated"}, {"text": "ヘリコプターは垂直に上がって、ビルの屋上から離れた。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "ヘリコプターは垂直[すいちょく]に上[あ]がって、ビルの屋上[おくじょう]から離[はな]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "垂直", "label": "基本形"}, {"form": "垂直に", "label": "連用形（に）"}, {"form": "垂直な", "label": "連体形（な）"}], "register": "中立（普通体）", "sense_fingerprint": "傾かずまっすぐ立つ、または真上に向かう様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38180, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垂直", "is_correct": true, "explanation": "「地面に垂直に立てる」の形。地面に対してまっすぐ立てる様子を表す。"}, {"text": "賑やか", "is_correct": false, "explanation": "人や物が多く活気のある様子を指す。棒を立てる向きの説明にならない。"}, {"text": "不思議", "is_correct": false, "explanation": "普通でなく妙な様子を指す。棒を立てる動作の説明には合わない。"}, {"text": "騒音", "is_correct": false, "explanation": "耳障りな音を指す。棒を立てる向きの説明にはならない。"}], "explanations": {"垂直": "「地面に垂直に立てる」の形。地面に対してまっすぐ立てる様子を表す。", "賑やか": "人や物が多く活気のある様子を指す。棒を立てる向きの説明にならない。", "不思議": "普通でなく妙な様子を指す。棒を立てる動作の説明には合わない。", "騒音": "耳障りな音を指す。棒を立てる向きの説明にはならない。"}, "sentence_index": 0, "correct_answer": "垂直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日は垂直が高くて、洗濯物が乾かない。", "explanation": "ここは〈湿度〉の意味。垂直は角度や向きを表し、空気中の水分を指さないので「高い」とは合わない。"}, {"text": "テレビの垂直を上げてください。", "explanation": "ここは〈音量〉の意味。垂直は角度の状態で、数値として上げ下げできない。"}, {"text": "ダイエットで垂直が三キロ減った。", "explanation": "ここは〈体重〉の意味。垂直は重さを表さないので、「三キロ減った」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38180, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垂直", "is_correct": true, "explanation": "「煙が垂直に昇る」の形。まっすぐ上に向かう様子で、風がないと分かる根拠になる。"}, {"text": "迷惑", "is_correct": false, "explanation": "人に手間や害をかけることを表す。煙の昇り方の説明にはならない。"}, {"text": "憂鬱", "is_correct": false, "explanation": "気分が沈んでいる状態を指す。煙の向きを表せない。"}, {"text": "騒音", "is_correct": false, "explanation": "耳障りな音を指す。煙の昇り方の説明にはならない。"}], "explanations": {"垂直": "「煙が垂直に昇る」の形。まっすぐ上に向かう様子で、風がないと分かる根拠になる。", "迷惑": "人に手間や害をかけることを表す。煙の昇り方の説明にはならない。", "憂鬱": "気分が沈んでいる状態を指す。煙の向きを表せない。", "騒音": "耳障りな音を指す。煙の昇り方の説明にはならない。"}, "sentence_index": 6, "correct_answer": "垂直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その歌手は垂直が高い。", "explanation": "ここは〈人気〉の意味。垂直は向きを表し、評判の高さには使えないので、「高い」とは合わない。"}, {"text": "今期は垂直が増えた。", "explanation": "ここは〈利益〉の意味。垂直は金額を表さないので、「増えた」とは合わない。"}, {"text": "部屋の垂直が広い。", "explanation": "ここは〈面積〉の意味。垂直は広さを表さないので、「広い」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38180, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この柱は床に対して垂直な立てられている。", "corrected_sentence": "この柱は床に対して垂直に立てられている。", "error_description": "動詞「立てられている」を修飾する形は連用形「垂直に」。「垂直な」は連体形で、動詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "垂直に", "is_correct": true, "explanation": "連用形。動詞「伸ばして」を修飾し、背中をまっすぐにする様子を表す。"}, {"text": "垂直な", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、「伸ばして」の前には入らない。"}, {"text": "垂直", "is_correct": false, "explanation": "語の基本形。「背中を〜伸ばして」の位置では連用形が必要で、この形は入らない。"}, {"text": "垂直で", "is_correct": false, "explanation": "「だ」の連用中止形。「伸ばして」を直接修飾できず、この位置には合わない。"}], "correct_form": "垂直に", "base_form": "垂直", "form_label": "連用形（に）", "sentence_index": 1, "explanations": {"垂直に": "連用形。動詞「伸ばして」を修飾し、背中をまっすぐにする様子を表す。", "垂直な": "連体形。名詞を修飾する形で、「伸ばして」の前には入らない。", "垂直": "語の基本形。「背中を〜伸ばして」の位置では連用形が必要で、この形は入らない。", "垂直で": "「だ」の連用中止形。「伸ばして」を直接修飾できず、この位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38180, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旗ざおは地面に対して垂直だ立っている。", "corrected_sentence": "旗ざおは地面に対して垂直に立っている。", "error_description": "動詞「立っている」を修飾する形は連用形「垂直に」。「垂直だ」は断定形で、続く動詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "垂直", "is_correct": true, "explanation": "文中の「壁は垂直なので」の形。状態を述べる基本形として使われている。"}, {"text": "垂直に", "is_correct": false, "explanation": "連用形。「壁は〜なので」の述語位置には「に」の形は入らない。"}, {"text": "垂直なら", "is_correct": false, "explanation": "仮定の形。「ので」と続かないため、理由を述べる文の述語には入らない。"}, {"text": "垂直だろう", "is_correct": false, "explanation": "推量の形。「ので」の前には続かず、確かな理由を述べる文には合わない。"}], "correct_form": "垂直", "base_form": "垂直", "form_label": "基本形", "sentence_index": 7, "explanations": {"垂直": "文中の「壁は垂直なので」の形。状態を述べる基本形として使われている。", "垂直に": "連用形。「壁は〜なので」の述語位置には「に」の形は入らない。", "垂直なら": "仮定の形。「ので」と続かないため、理由を述べる文の述語には入らない。", "垂直だろう": "推量の形。「ので」の前には続かず、確かな理由を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38181, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "水平", "is_correct": true, "explanation": "地面と平行な向きを表し、垂直の対義語。「横の揺れ」に対応する語。"}, {"text": "斜面", "is_correct": false, "explanation": "傾いた地面の面を指す名詞で、垂直の対義語ではない。"}, {"text": "対角線", "is_correct": false, "explanation": "図形の向かい合う頂点を結ぶ線を指し、垂直と対になる関係にはない。"}, {"text": "中心", "is_correct": false, "explanation": "ものの真ん中の点を指す名詞で、垂直と対義の関係にはない。"}], "correct_answer": "水平", "explanations": {"水平": "地面と平行な向きを表し、垂直の対義語。「横の揺れ」に対応する語。", "斜面": "傾いた地面の面を指す名詞で、垂直の対義語ではない。", "対角線": "図形の向かい合う頂点を結ぶ線を指し、垂直と対になる関係にはない。", "中心": "ものの真ん中の点を指す名詞で、垂直と対義の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38181, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "水平", "is_correct": true, "explanation": "地面と平行な向きを表し、垂直の対義語。「建物の壁」の向きと対になる語。"}, {"text": "曲線", "is_correct": false, "explanation": "曲がった線を表す名詞で、垂直の対義語ではない。"}, {"text": "球面", "is_correct": false, "explanation": "球の表面を指す名詞で、垂直と対になる関係にはない。"}, {"text": "放物線", "is_correct": false, "explanation": "投げたものの軌道などを表す曲線で、垂直の対義語ではない。"}], "correct_answer": "水平", "explanations": {"水平": "地面と平行な向きを表し、垂直の対義語。「建物の壁」の向きと対になる語。", "曲線": "曲がった線を表す名詞で、垂直の対義語ではない。", "球面": "球の表面を指す名詞で、垂直と対になる関係にはない。", "放物線": "投げたものの軌道などを表す曲線で、垂直の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38181, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "地面に対して垂直な方向。または、物事の状態がその方向にあること。", "primary_collocate": null, "pronunciation": "すいちょく", "ipa": "sɯitɕokɯ", "syllable_count": 4, "sentences": [{"text": "雨は風がなかったので、地面に垂直に落ちてきた。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "雨[あめ]は風[かぜ]がなかったので、地面[じめん]に垂直[すいちょく]に落[お]ちてきた。", "sentence_source": "generated"}, {"text": "この装置は、地面に垂直な向きの揺れを細かく測れる。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "この装置[そうち]は、地面[じめん]に垂直[すいちょく]な向[む]きの揺[ゆ]れを細[こま]かく測[はか]れる。", "sentence_source": "generated"}, {"text": "地面に垂直な線をチョークで引いて、高さを測った。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "地面[じめん]に垂直[すいちょく]な線[せん]をチョークで引[ひ]いて、高[たか]さを測[はか]った。", "sentence_source": "generated"}, {"text": "地震では、横の揺れだけでなく、垂直の揺れも起こることがある。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "地震[じしん]では、横[よこ]の揺[ゆ]れだけでなく、垂直[すいちょく]の揺[ゆ]れも起[お]こることがある。", "sentence_source": "generated"}, {"text": "板を床に対して垂直に置くと、棚の仕切りになる。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "板[いた]を床[ゆか]に対[たい]して垂直[すいちょく]に置[お]くと、棚[たな]の仕切[しき]りになる。", "sentence_source": "generated"}, {"text": "日の光が垂直に当たる夏の昼は、影がとても短い。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "日[ひ]の光[ひかり]が垂直[すいちょく]に当[あ]たる夏[なつ]の昼[ひる]は、影[かげ]がとても短[みじか]い。", "sentence_source": "generated"}, {"text": "工事では、穴を地面に垂直に掘ることが大切だ。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "工事[こうじ]では、穴[あな]を地面[じめん]に垂直[すいちょく]に掘[ほ]ることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "ボールは地面に垂直に弾んで、またてのひらに戻った。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "ボールは地面[じめん]に垂直[すいちょく]に弾[はず]んで、またてのひらに戻[もど]った。", "sentence_source": "generated"}, {"text": "このエレベーターは地面に垂直な方向にだけ動く。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "このエレベーターは地面[じめん]に垂直[すいちょく]な方向[ほうこう]にだけ動[うご]く。", "sentence_source": "generated"}, {"text": "建物の壁が地面に垂直かどうかを、水準器で調べた。", "target_word": "垂直", "complexity_tier": "T3", "furigana": "建物[たてもの]の壁[かべ]が地面[じめん]に垂直[すいちょく]かどうかを、水準器[すいじゅんき]で調[しら]べた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "垂直", "label": "基本形"}, {"form": "垂直に", "label": "連用形（に）"}, {"form": "垂直な", "label": "連体形（な）"}], "register": "中立（普通体）", "sense_fingerprint": "地面に対して直角をなす向き・その向きにある状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38181, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垂直", "is_correct": true, "explanation": "「地面に垂直に落ちる」は、風がなく雨が真下へ落ちるという文脈と合う。"}, {"text": "水平", "is_correct": false, "explanation": "水平は地面と平行な向き。風がなかった文脈では、雨が横へ落ちる理由がなく合わない。"}, {"text": "斜め", "is_correct": false, "explanation": "斜めは傾いた向き。雨が斜めに落ちるには風が必要で、「風がなかった」と矛盾する。"}, {"text": "平行", "is_correct": false, "explanation": "平行は地面と並ぶ向き。雨が地面と並んで落ちることはできないので合わない。"}], "explanations": {"垂直": "「地面に垂直に落ちる」は、風がなく雨が真下へ落ちるという文脈と合う。", "水平": "水平は地面と平行な向き。風がなかった文脈では、雨が横へ落ちる理由がなく合わない。", "斜め": "斜めは傾いた向き。雨が斜めに落ちるには風が必要で、「風がなかった」と矛盾する。", "平行": "平行は地面と並ぶ向き。雨が地面と並んで落ちることはできないので合わない。"}, "sentence_index": 0, "correct_answer": "垂直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は性格が垂直で、いつも正直だ。", "explanation": "真っ直ぐ（正直で飾らない性格）を言いたい文だが、垂直は方向や角度の語なので、性格には使わない。"}, {"text": "この歌は垂直で、聞いていて心地よい。", "explanation": "軽快（リズムが軽やかなこと）を言いたい文だが、垂直は方向の語で、音楽の雰囲気には使えない。"}, {"text": "二人の意見は垂直をたどった。", "explanation": "ここは〈平行線をたどる〉（話が進まない）の慣用句。垂直は方向の語で、この言い回しには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38181, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垂直", "is_correct": true, "explanation": "「穴を地面に垂直に掘る」は、地面に対して真下へ掘る向きを表し、文と合う。"}, {"text": "不規則", "is_correct": false, "explanation": "形がばらばらという意味で、精度が大切な工事の文脈と合わない。"}, {"text": "平面", "is_correct": false, "explanation": "平らな面を表す名詞で、穴を掘る向きを示せず不自然。"}, {"text": "直線", "is_correct": false, "explanation": "一直線を表すが、地面に対する向きを示す語ではなく、穴の掘り方として不自然。"}], "explanations": {"垂直": "「穴を地面に垂直に掘る」は、地面に対して真下へ掘る向きを表し、文と合う。", "不規則": "形がばらばらという意味で、精度が大切な工事の文脈と合わない。", "平面": "平らな面を表す名詞で、穴を掘る向きを示せず不自然。", "直線": "一直線を表すが、地面に対する向きを示す語ではなく、穴の掘り方として不自然。"}, "sentence_index": 6, "correct_answer": "垂直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は垂直で、約束をいつも守る。", "explanation": "誠実（真心があること）を言いたい文だが、垂直は方向や角度を表すので、人柄には使えない。"}, {"text": "作業は垂直で、とても退屈だった。", "explanation": "単調（変化がないこと）を言いたい文だが、垂直は角度の語で、作業の様子には合わない。"}, {"text": "父は垂直で、夜更かしを決して許さなかった。", "explanation": "厳格（ゆるみがないこと）を言いたい文だが、垂直は方向の語で、人の態度には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38181, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風のない日は、雨が地面に垂直な落ちる。", "corrected_sentence": "風のない日は、雨が地面に垂直に落ちる。", "error_description": "「垂直」が動詞「落ちる」を修飾するので、連用形「垂直に」が正しい。「垂直な」は連体形で名詞を修飾する形なので、動詞の前には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38181, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "壁は床に対して垂直で立っている。", "corrected_sentence": "壁は床に対して垂直に立っている。", "error_description": "動詞「立つ」を修飾するので、連用形「垂直に」が正しい。「垂直で」は誤りで、「に」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38182, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「農場で」は動作の場所を示し、「では」の文として自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すが、農場は乳をしぼられる対象ではない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「農場がは」と続かず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "所属の「の」。「農場のは」と続けられず、不自然。"}], "correct_answer": "で", "explanations": {"で": "「農場で」は動作の場所を示し、「では」の文として自然。", "を": "「を」は対象を示すが、農場は乳をしぼられる対象ではない。", "が": "主格の「が」。「農場がは」と続かず、文が成り立たない。", "の": "所属の「の」。「農場のは」と続けられず、不自然。"}, "error_tags": {"を": "対象", "が": "主格", "の": "所属"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38182, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「農場の広い敷地」と所属を示す「の」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、敷地を表す語の後には合わない。"}, {"text": "を", "is_correct": false, "explanation": "対象の「を」。「農場を広い敷地には」と続かず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「農場から広い敷地には」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「農場の広い敷地」と所属を示す「の」が正しい。", "へ": "方向を示すので、敷地を表す語の後には合わない。", "を": "対象の「を」。「農場を広い敷地には」と続かず、不自然。", "から": "起点を示すが、「農場から広い敷地には」は意味が通らない。"}, "error_tags": {"へ": "方向", "を": "対象", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38182, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物や動物を育てる大きな場所です。", "primary_collocate": null, "pronunciation": "のうじょう", "ipa": "noːdʑoː", "syllable_count": 4, "sentences": [{"text": "私の叔父は、北海道で大きな農場を経営している。", "target_word": "農場", "complexity_tier": "T3", "furigana": "私[わたし]の叔父[おじ]は、北海道[ほっかいどう]で大[おお]きな農場[のうじょう]を経営[けいえい]している。", "sentence_source": "generated"}, {"text": "農場では、朝五時に牛の乳をしぼる。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]では、朝[あさ]五時[ごじ]に牛[うし]の乳[ちち]をしぼる。", "sentence_source": "generated"}, {"text": "子どもたちは農場でいちご狩りをして、大喜びだった。", "target_word": "農場", "complexity_tier": "T3", "furigana": "子[こ]どもたちは農場[のうじょう]でいちご狩[が]りをして、大喜[おおよろこ]びだった。", "sentence_source": "generated"}, {"text": "農場の羊は、春になると毛を刈ってもらう。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]の羊[ひつじ]は、春[はる]になると毛[け]を刈[か]ってもらう。", "sentence_source": "generated"}, {"text": "台風が近づいてきたので、農場の人たちは急いで畑の野菜を収穫した。", "target_word": "農場", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づいてきたので、農場[のうじょう]の人[ひと]たちは急[いそ]いで畑[はたけ]の野菜[やさい]を収穫[しゅうかく]した。", "sentence_source": "generated"}, {"text": "この農場の卵は新鮮で、町の人にとても人気がある。", "target_word": "農場", "complexity_tier": "T3", "furigana": "この農場[のうじょう]の卵[たまご]は新鮮[しんせん]で、町[まち]の人[ひと]にとても人気[にんき]がある。", "sentence_source": "generated"}, {"text": "将来は自分の農場を持って、有機野菜を作りたい。", "target_word": "農場", "complexity_tier": "T3", "furigana": "将来[しょうらい]は自分[じぶん]の農場[のうじょう]を持[も]って、有機野菜[ゆうきやさい]を作[つく]りたい。", "sentence_source": "generated"}, {"text": "農場の広い敷地には、豚小屋や倉庫が並んでいる。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]の広[ひろ]い敷地[しきち]には、豚小屋[ぶたごや]や倉庫[そうこ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "学校の遠足で、農場にバターづくりを体験しに行った。", "target_word": "農場", "complexity_tier": "T3", "furigana": "学校[がっこう]の遠足[えんそく]で、農場[のうじょう]にバターづくりを体験[たいけん]しに行[い]った。", "sentence_source": "generated"}, {"text": "農場が山のふもとにあるので、冬は雪で道が通れなくなる。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]が山[やま]のふもとにあるので、冬[ふゆ]は雪[ゆき]で道[みち]が通[とお]れなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "作物や動物を育てる広い場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38182, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農場", "is_correct": true, "explanation": "北海道で大きな土地を経営する対象として自然に入る。"}, {"text": "農薬", "is_correct": false, "explanation": "薬剤なので、経営の対象にならない。"}, {"text": "農機", "is_correct": false, "explanation": "機械の名前で、経営する対象ではない。"}, {"text": "肥料", "is_correct": false, "explanation": "作物に与える物で、経営の対象にならない。"}], "explanations": {"農場": "北海道で大きな土地を経営する対象として自然に入る。", "農薬": "薬剤なので、経営の対象にならない。", "農機": "機械の名前で、経営する対象ではない。", "肥料": "作物に与える物で、経営の対象にならない。"}, "sentence_index": 0, "correct_answer": "農場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この農場では、毎日千個の部品を組み立てている。", "explanation": "ここは〈工場〉の意味。部品の組み立ては工場の仕事で、農場は作物や家畜を育てる土地。"}, {"text": "県は地元の農場を海外へ輸出する計画だ。", "explanation": "ここは〈農産物〉の意味。輸出されるのは作物などの品物で、農場という土地は輸出できない。"}, {"text": "祖父は代々の農場として、畑の世話を一人で続けてきた。", "explanation": "ここは〈農家〉の意味。人や家の立場を表す「として」には、土地の農場は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38182, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農場", "is_correct": true, "explanation": "自分の土地として持ち、有機野菜を作る場所として自然に入る。"}, {"text": "収穫", "is_correct": false, "explanation": "作業や収量を表し、持つ対象ではない。"}, {"text": "飼料", "is_correct": false, "explanation": "家畜のえさで、「持って作りたい」の対象にならない。"}, {"text": "種苗", "is_correct": false, "explanation": "植える苗や種で、自分の土地として持つ意味にはならない。"}], "explanations": {"農場": "自分の土地として持ち、有機野菜を作る場所として自然に入る。", "収穫": "作業や収量を表し、持つ対象ではない。", "飼料": "家畜のえさで、「持って作りたい」の対象にならない。", "種苗": "植える苗や種で、自分の土地として持つ意味にはならない。"}, "sentence_index": 6, "correct_answer": "農場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農場の専門を大学で三年間学んだ。", "explanation": "ここは〈農業〉の意味。大学で学ぶのは学問の農業で、土地の農場は専門分野にならない。"}, {"text": "農場を終えて、家へ帰った。", "explanation": "ここは〈農作業〉の意味。終えられるのは作業で、土地の農場は終えるものではない。"}, {"text": "農場を冷蔵庫に入れて、夏でも冷やしておく。", "explanation": "ここは〈食材〉の意味。冷蔵庫に入れて冷やすのは食材で、土地の農場は入らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38182, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋には、農場が採れた栗を売っている。", "corrected_sentence": "秋には、農場で採れた栗を売っている。", "error_description": "場所を表す「で」が「が」になっている。「農場で採れた」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38182, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方になると、農場を牛が小屋へ戻っていく。", "corrected_sentence": "夕方になると、農場の牛が小屋へ戻っていく。", "error_description": "「農場」に続く所属の「の」が「を」になっている。「農場の牛」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38183, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "農場は「育てている」動作の場所なので、場所を表す「で」が正しい。"}, {"text": "の", "is_correct": false, "explanation": "所属の「の」。「農場の、」と読点で切れ、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すので、ここで育てている場所を表すことはできない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、育てる場所を示す文脈には合わない。"}], "correct_answer": "で", "explanations": {"で": "農場は「育てている」動作の場所なので、場所を表す「で」が正しい。", "の": "所属の「の」。「農場の、」と読点で切れ、文が成り立たない。", "から": "起点を示すので、ここで育てている場所を表すことはできない。", "より": "比較の助詞で、育てる場所を示す文脈には合わない。"}, "error_tags": {"の": "所属", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38183, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「農場の近く」と名詞を続けて場所を示す「の」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、住んでいる位置の説明には合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列や共同を示すが、「近くに住む」の前では意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "対象の「を」。「農場を近くに住んでいる」と続かず、不自然。"}], "correct_answer": "の", "explanations": {"の": "「農場の近く」と名詞を続けて場所を示す「の」が正しい。", "へ": "方向を示すので、住んでいる位置の説明には合わない。", "と": "並列や共同を示すが、「近くに住む」の前では意味が通らない。", "を": "対象の「を」。「農場を近くに住んでいる」と続かず、不自然。"}, "error_tags": {"へ": "方向", "と": "並列", "を": "対象"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38183, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "野菜や果物、動物などを育てるための土地や建物のことを言います。", "primary_collocate": null, "pronunciation": "のうじょう", "ipa": "noːdʑoː", "syllable_count": 4, "sentences": [{"text": "夜が明け、太陽が農場を照らし始める朝、農家の男は鶏舎へと足を運ぶ。", "target_word": "農場", "complexity_tier": "T3", "furigana": "夜[よる]が明[あ]け、太陽[たいよう]が農場[のうじょう]を照[て]らし始[はじ]める朝[あさ]、農家[のうか]の男[おとこ]は鶏舎[けいしゃ]へと足[あし]を運[はこ]ぶ。", "sentence_source": "mined"}, {"text": "祖父は小さな農場で、トマトときゅうりを育てている。", "target_word": "農場", "complexity_tier": "T3", "furigana": "祖父[そふ]は小[ちい]さな農場[のうじょう]で、トマトときゅうりを育[そだ]てている。", "sentence_source": "generated"}, {"text": "夏休みに、家族で牛のいる農場へ見学に行った。", "target_word": "農場", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、家族[かぞく]で牛[うし]のいる農場[のうじょう]へ見学[けんがく]に行[い]った。", "sentence_source": "generated"}, {"text": "この農場では、朝早くから多くの人が収穫の仕事をしている。", "target_word": "農場", "complexity_tier": "T3", "furigana": "この農場[のうじょう]では、朝早[あさはや]くから多[おお]くの人[ひと]が収穫[しゅうかく]の仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "大雨で農場の畑が水に浸かり、野菜がだめになった。", "target_word": "農場", "complexity_tier": "T3", "furigana": "大雨[おおあめ]で農場[のうじょう]の畑[はたけ]が水[みず]に浸[つ]かり、野菜[やさい]がだめになった。", "sentence_source": "generated"}, {"text": "農場で働く友達から、とれたての果物をもらった。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]で働[はたら]く友達[ともだち]から、とれたての果物[くだもの]をもらった。", "sentence_source": "generated"}, {"text": "農場には広い草地があるので、馬を放して飼うことができる。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]には広[ひろ]い草地[くさち]があるので、馬[うま]を放[はな]して飼[か]うことができる。", "sentence_source": "generated"}, {"text": "農場の近くに住んでいるため、窓を開けると牛の声が聞こえる。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]の近[ちか]くに住[す]んでいるため、窓[まど]を開[あ]けると牛[うし]の声[こえ]が聞[き]こえる。", "sentence_source": "generated"}, {"text": "都会育ちの私は、農場で初めて本物のにわとりを見た。", "target_word": "農場", "complexity_tier": "T3", "furigana": "都会育[とかいそだ]ちの私[わたし]は、農場[のうじょう]で初[はじ]めて本物[ほんもの]のにわとりを見[み]た。", "sentence_source": "generated"}, {"text": "農場から市場まで、毎朝トラックで野菜を運ぶ。", "target_word": "農場", "complexity_tier": "T3", "furigana": "農場[のうじょう]から市場[いちば]まで、毎朝[まいあさ]トラックで野菜[やさい]を運[はこ]ぶ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "農場", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "野菜・果物・家畜などを育てる土地や建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38183, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "農場", "is_correct": true, "explanation": "農家の男が鶏舎へ向かう朝に、太陽が照らす場所として自然に入る。"}, {"text": "農業", "is_correct": false, "explanation": "仕事や産業の名前で、太陽が照らす場所にはならない。"}, {"text": "農政", "is_correct": false, "explanation": "農業政策の名前で、太陽が照らす対象にはならない。"}, {"text": "農機", "is_correct": false, "explanation": "農業用機械の名前で、照らされる場所ではない。"}], "explanations": {"農場": "農家の男が鶏舎へ向かう朝に、太陽が照らす場所として自然に入る。", "農業": "仕事や産業の名前で、太陽が照らす場所にはならない。", "農政": "農業政策の名前で、太陽が照らす対象にはならない。", "農機": "農業用機械の名前で、照らされる場所ではない。"}, "sentence_index": 0, "correct_answer": "農場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この農場では、朝早くから多くの人が製品を組み立てている。", "explanation": "ここは〈工場〉の意味。農場は作物や家畜を育てる土地なので、製品の組み立てには合わない。"}, {"text": "農場を学ぶために、大学の農学部へ進んだ。", "explanation": "ここは〈農業〉の意味。学ぶ対象は学問の農業で、土地の農場は学問の対象にならない。"}, {"text": "祖父は代々の農場として、朝早くから畑で働いている。", "explanation": "ここは〈農家〉の意味。人や家の立場を表す「として」には、土地の農場は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38183, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "農場", "is_correct": true, "explanation": "広い草地があり馬を放して飼える場所として自然に入る。"}, {"text": "肥料", "is_correct": false, "explanation": "作物に与える物で、草地のある場所を表さない。"}, {"text": "飼料", "is_correct": false, "explanation": "家畜のえさで、馬を放して飼える場所の説明にならない。"}, {"text": "種苗", "is_correct": false, "explanation": "植える苗や種のことで、馬を放せる場所ではない。"}], "explanations": {"農場": "広い草地があり馬を放して飼える場所として自然に入る。", "肥料": "作物に与える物で、草地のある場所を表さない。", "飼料": "家畜のえさで、馬を放して飼える場所の説明にならない。", "種苗": "植える苗や種のことで、馬を放せる場所ではない。"}, "sentence_index": 6, "correct_answer": "農場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "県は地元の農場を海外へ輸出する計画を立てた。", "explanation": "ここは〈農産物〉の意味。輸出されるのは作物などの品物で、土地の農場は輸出の対象にならない。"}, {"text": "農場を終えて、家へ帰った。", "explanation": "ここは〈農作業〉の意味。終えられるのは作業で、土地の農場は終えるものではない。"}, {"text": "農場の改札で、乗客が切符を見せている。", "explanation": "ここは〈駅〉の意味。改札や切符は駅の設備なので、作物や家畜を育てる土地の農場には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38183, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は友達と農場に乗馬を楽しんだ。", "corrected_sentence": "週末は友達と農場で乗馬を楽しんだ。", "error_description": "動作の場所を表す「で」が「に」になっている。「農場で乗馬を楽しむ」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38183, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "農場で奥に大きな倉庫がある。", "corrected_sentence": "農場の奥に大きな倉庫がある。", "error_description": "「奥」を修飾する所在の「の」が「で」になっている。「農場の奥」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38184, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「心から」で「心の底から」の意。ここで寛ぐ気持ちの起点を表す。"}, {"text": "を", "is_correct": false, "explanation": "寛ぐは目的語を取らないので、「心を寛ぐ」とは言わない。"}, {"text": "に", "is_correct": false, "explanation": "「心に寛ぐ」は対象や方向の形として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「心と寛ぐ」は共同の相手を表すことになり、文脈に合わない。"}], "correct_answer": "から", "explanations": {"から": "「心から」で「心の底から」の意。ここで寛ぐ気持ちの起点を表す。", "を": "寛ぐは目的語を取らないので、「心を寛ぐ」とは言わない。", "に": "「心に寛ぐ」は対象や方向の形として不自然。", "と": "「心と寛ぐ」は共同の相手を表すことになり、文脈に合わない。"}, "error_tags": {"から": "起点", "を": "対象", "に": "方向・帰着", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38184, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「入ってから」で、動作の後に続けることを表す。"}, {"text": "を", "is_correct": false, "explanation": "「入ってを寛ぎ」は目的語の形として不自然。"}, {"text": "が", "is_correct": false, "explanation": "「入ってが寛ぎたい」は主語の形になり、文が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「入ってに寛ぎ」は方向や帰着を表し、動作の後を表せない。"}], "correct_answer": "から", "explanations": {"から": "「入ってから」で、動作の後に続けることを表す。", "を": "「入ってを寛ぎ」は目的語の形として不自然。", "が": "「入ってが寛ぎたい」は主語の形になり、文が通らない。", "に": "「入ってに寛ぎ」は方向や帰着を表し、動作の後を表せない。"}, "error_tags": {"から": "起点・順序", "を": "対象", "が": "主語", "に": "方向・帰着"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38184, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "家などで気持ちを楽にして、ゆっくり休むこと。", "primary_collocate": null, "pronunciation": "くつろぐ", "ipa": "kɯtsɯɾoɡɯ", "syllable_count": 4, "sentences": [{"text": "休みの日は、家でゆっくり寛ぐのが好きです。", "target_word": "寛ぐ", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、家[いえ]でゆっくり寛[くつろ]ぐのが好[す]きです。", "sentence_source": "generated"}, {"text": "温泉に入って、心から寛ぐことができました。", "target_word": "寛ぐ", "complexity_tier": "T3", "furigana": "温泉[おんせん]に入[はい]って、心[こころ]から寛[くつろ]ぐことができました。", "sentence_source": "generated"}, {"text": "お客さんが来るまで、ソファで寛いでいてください。", "target_word": "寛いで", "complexity_tier": "T3", "furigana": "お客[きゃく]さんが来[く]るまで、ソファで寛[くつろ]いでいてください。", "sentence_source": "generated"}, {"text": "部屋が暖かいので、猫も床の上で寛いでいます。", "target_word": "寛いで", "complexity_tier": "T3", "furigana": "部屋[へや]が暖[あたた]かいので、猫[ねこ]も床[ゆか]の上[うえ]で寛[くつろ]いでいます。", "sentence_source": "generated"}, {"text": "旅行の初日は、ホテルのロビーで寛ぎました。", "target_word": "寛ぎ", "complexity_tier": "T3", "furigana": "旅行[りょこう]の初日[しょにち]は、ホテルのロビーで寛[くつろ]ぎました。", "sentence_source": "generated"}, {"text": "仕事が忙しくて、最近は家でも寛げません。", "target_word": "寛げ", "complexity_tier": "T3", "furigana": "仕事[しごと]が忙[いそが]しくて、最近[さいきん]は家[いえ]でも寛[くつろ]げません。", "sentence_source": "generated"}, {"text": "祖母の家に行くと、いつも気持ちが落ち着いて寛げます。", "target_word": "寛げ", "complexity_tier": "T3", "furigana": "祖母[そぼ]の家[いえ]に行[い]くと、いつも気持[きも]ちが落[お]ち着[つ]いて寛[くつろ]げます。", "sentence_source": "generated"}, {"text": "疲れたので、お風呂に入ってから寛ぎたいです。", "target_word": "寛ぎ", "complexity_tier": "T3", "furigana": "疲[つか]れたので、お風呂[ふろ]に入[はい]ってから寛[くつろ]ぎたいです。", "sentence_source": "generated"}, {"text": "この喫茶店は静かで、本を読みながら寛ぐ人が多いです。", "target_word": "寛ぐ", "complexity_tier": "T3", "furigana": "この喫茶店[きっさてん]は静[しず]かで、本[ほん]を読[よ]みながら寛[くつろ]ぐ人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "試験が終わったので、今日は友達と寛いだ時間を過ごしました。", "target_word": "寛いだ", "complexity_tier": "T3", "furigana": "試験[しけん]が終[お]わったので、今日[きょう]は友達[ともだち]と寛[くつろ]いだ時間[じかん]を過[す]ごしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寛ぐ", "label": "基本形"}, {"form": "寛ぎます", "label": "ます形"}, {"form": "寛いで", "label": "て形"}, {"form": "寛いだ", "label": "た形"}, {"form": "寛がない", "label": "ない形"}, {"form": "寛げる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "家や温泉などで体の力を抜き、ゆっくり休んで楽に過ごす。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38184, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寛ぐ", "is_correct": true, "explanation": "「寛ぐ」は気持ちを楽にして休む意味で、家でゆっくり過ごす行為に合う。"}, {"text": "叱る", "is_correct": false, "explanation": "人を注意する行為で、家でゆっくり過ごす文脈には合わない。"}, {"text": "嫌がる", "is_correct": false, "explanation": "いやだと感じる意味。「ゆっくり嫌がるのが好き」は不自然。"}, {"text": "暴れる", "is_correct": false, "explanation": "騒ぎ回る意味で、ゆっくり過ごすこととは矛盾する。"}], "explanations": {"寛ぐ": "「寛ぐ」は気持ちを楽にして休む意味で、家でゆっくり過ごす行為に合う。", "叱る": "人を注意する行為で、家でゆっくり過ごす文脈には合わない。", "嫌がる": "いやだと感じる意味。「ゆっくり嫌がるのが好き」は不自然。", "暴れる": "騒ぎ回る意味で、ゆっくり過ごすこととは矛盾する。"}, "sentence_index": 0, "correct_answer": "寛ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の言動を悔やんで寛ぎました。", "explanation": "ここは〈悔やむ〉の意味。寛ぐは気持ちを楽にする意味で、後悔の気持ちとは両立しないので、この文の意味には合わない。"}, {"text": "締め切りが迫って寛ぎました。", "explanation": "ここは〈焦る〉の意味。寛ぐは落ち着いてくつろぐ意味で、切羽詰まった気持ちは表せない。"}, {"text": "犬から寛ぎました。", "explanation": "ここは〈逃げる〉の意味。寛ぐは落ち着いてくつろぐ意味で、危険から離れる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38184, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寛げ", "is_correct": true, "explanation": "可能形の「寛げ」は、くつろげるの意。「気持ちが落ち着いて〜ます」に続く。"}, {"text": "黙り", "is_correct": false, "explanation": "話さないの意。気持ちが落ち着く文脈には合わない。"}, {"text": "怒り", "is_correct": false, "explanation": "怒る感情を表し、落ち着いた状態と矛盾する。"}, {"text": "泣き", "is_correct": false, "explanation": "悲しみを表す行為で、落ち着いた気分の文脈には合わない。"}], "explanations": {"寛げ": "可能形の「寛げ」は、くつろげるの意。「気持ちが落ち着いて〜ます」に続く。", "黙り": "話さないの意。気持ちが落ち着く文脈には合わない。", "怒り": "怒る感情を表し、落ち着いた状態と矛盾する。", "泣き": "悲しみを表す行為で、落ち着いた気分の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "寛げ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな声で寛ぎました。", "explanation": "ここは〈叫ぶ〉の意味。寛ぐは落ち着いてくつろぐ意味で、大声を出すことは表せない。"}, {"text": "電車に寛ぎました。", "explanation": "ここは〈遅れる〉の意味。寛ぐは気持ちを楽にする意味で、乗り物に遅れたことは表せない。"}, {"text": "大きな地震に寛ぎました。", "explanation": "ここは〈驚く〉の意味。寛ぐは心が落ち着く意味で、驚いた心の動きは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38184, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日は家で寛ぐたいです。", "corrected_sentence": "今日は家で寛ぎたいです。", "error_description": "「たい」に続くときは連用形の「寛ぎ」にする。「寛ぐたい」は誤りで、正しくは「寛ぎたい」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寛ぐ", "is_correct": true, "explanation": "「ことができました」の前は辞書形。ここで文法的に正しい形。"}, {"text": "寛いで", "is_correct": false, "explanation": "て形で、「ことができました」には直接続かない。"}, {"text": "寛いだ", "is_correct": false, "explanation": "た形で、「ことができる」の前には置けない。"}, {"text": "寛ぎ", "is_correct": false, "explanation": "連用形で、「ことができました」には直接続かない。"}], "correct_form": "寛ぐ", "base_form": "寛ぐ", "form_label": "基本形", "sentence_index": 1, "explanations": {"寛ぐ": "「ことができました」の前は辞書形。ここで文法的に正しい形。", "寛いで": "て形で、「ことができました」には直接続かない。", "寛いだ": "た形で、「ことができる」の前には置けない。", "寛ぎ": "連用形で、「ことができました」には直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38184, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末はソファで寛いたいです。", "corrected_sentence": "週末はソファで寛ぎたいです。", "error_description": "「たい」の前は連用形の「寛ぎ」にする。「寛いたい」は誤りで、正しくは「寛ぎたい」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寛ぎ", "is_correct": true, "explanation": "連用形で、「寛ぎたい」の前に来る形。"}, {"text": "寛ぎます", "is_correct": false, "explanation": "ます形で、「寛ぎますたいです」とは続かず誤り。"}, {"text": "寛がない", "is_correct": false, "explanation": "ない形で否定の意味になり、「寛がないたい」は続かない。"}, {"text": "寛がず", "is_correct": false, "explanation": "文語的な否定のず形で、「寛がずたい」は続かず不自然。"}], "correct_form": "寛ぎ", "base_form": "寛ぐ", "form_label": "連用形", "sentence_index": 7, "explanations": {"寛ぎ": "連用形で、「寛ぎたい」の前に来る形。", "寛ぎます": "ます形で、「寛ぎますたいです」とは続かず誤り。", "寛がない": "ない形で否定の意味になり、「寛がないたい」は続かない。", "寛がず": "文語的な否定のず形で、「寛がずたい」は続かず不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
