INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38185, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「休憩室で寛ぐ」の「で」は、くつろぐ場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "寛ぐは目的語を取らないので、「休憩室を寛ぐ」とは言わない。"}, {"text": "が", "is_correct": false, "explanation": "「休憩室が寛ぐ」は主語が寛ぐ人にならず、文が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「休憩室へ寛ぐ」は方向を表し、くつろぐ場所を示せない。"}], "correct_answer": "で", "explanations": {"で": "「休憩室で寛ぐ」の「で」は、くつろぐ場所を表す。", "を": "寛ぐは目的語を取らないので、「休憩室を寛ぐ」とは言わない。", "が": "「休憩室が寛ぐ」は主語が寛ぐ人にならず、文が通らない。", "へ": "「休憩室へ寛ぐ」は方向を表し、くつろぐ場所を示せない。"}, "error_tags": {"で": "場所", "を": "対象", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38185, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "心身をゆったりと休めて、気持ちを楽にすること。", "primary_collocate": null, "pronunciation": "くつろぐ", "ipa": "kɯtsɯɾoɡɯ", "syllable_count": 4, "sentences": [{"text": "日曜日は何もせず、一日中家で寛いでいました。", "target_word": "寛いで", "complexity_tier": "T3", "furigana": "日曜日[にちようび]は何[なに]もせず、一日中[いちにちじゅう]家[いえ]で寛[くつろ]いでいました。", "sentence_source": "generated"}, {"text": "友達の家は居心地がよくて、すっかり寛いでしまいました。", "target_word": "寛いで", "complexity_tier": "T3", "furigana": "友達[ともだち]の家[いえ]は居心地[いごこち]がよくて、すっかり寛[くつろ]いでしまいました。", "sentence_source": "generated"}, {"text": "旅館の畳の部屋で、浴衣を着て寛ぎました。", "target_word": "寛ぎ", "complexity_tier": "T3", "furigana": "旅館[りょかん]の畳[たたみ]の部屋[へや]で、浴衣[ゆかた]を着[き]て寛[くつろ]ぎました。", "sentence_source": "generated"}, {"text": "緊張していた彼も、お茶を飲むうちに寛ぎ始めました。", "target_word": "寛ぎ", "complexity_tier": "T3", "furigana": "緊張[きんちょう]していた彼[かれ]も、お茶[ちゃ]を飲[の]むうちに寛[くつろ]ぎ始[はじ]めました。", "sentence_source": "generated"}, {"text": "仕事から帰って、好きな音楽を聞きながら寛ぎます。", "target_word": "寛ぎ", "complexity_tier": "T3", "furigana": "仕事[しごと]から帰[かえ]って、好[す]きな音楽[おんがく]を聞[き]きながら寛[くつろ]ぎます。", "sentence_source": "generated"}, {"text": "狭いホテルの部屋では、なかなか寛げませんでした。", "target_word": "寛げ", "complexity_tier": "T3", "furigana": "狭[せま]いホテルの部屋[へや]では、なかなか寛[くつろ]げませんでした。", "sentence_source": "generated"}, {"text": "緊張しないで、どうぞ寛いでください。", "target_word": "寛いで", "complexity_tier": "T3", "furigana": "緊張[きんちょう]しないで、どうぞ寛[くつろ]いでください。", "sentence_source": "generated"}, {"text": "休憩室で寛ぐ時間が、午後の仕事の力になります。", "target_word": "寛ぐ", "complexity_tier": "T3", "furigana": "休憩室[きゅうけいしつ]で寛[くつろ]ぐ時間[じかん]が、午後[ごご]の仕事[しごと]の力[ちから]になります。", "sentence_source": "generated"}, {"text": "犬は飼い主のそばで、安心して寛いでいます。", "target_word": "寛いで", "complexity_tier": "T3", "furigana": "犬[いぬ]は飼[か]い主[ぬし]のそばで、安心[あんしん]して寛[くつろ]いでいます。", "sentence_source": "generated"}, {"text": "長い会議が終わり、みんなソファに座って寛いでいました。", "target_word": "寛いで", "complexity_tier": "T3", "furigana": "長[なが]い会議[かいぎ]が終[お]わり、みんなソファに座[すわ]って寛[くつろ]いでいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寛ぐ", "label": "基本形"}, {"form": "寛ぎます", "label": "ます形"}, {"form": "寛いで", "label": "て形"}, {"form": "寛いだ", "label": "た形"}, {"form": "寛がない", "label": "ない形"}, {"form": "寛げる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "緊張や疲れを解き、心も体も楽な状態で過ごす。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38185, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寛いで", "is_correct": true, "explanation": "「家で寛いでいました」の形で、一日中くつろいで過ごしたことを表す。"}, {"text": "負けて", "is_correct": false, "explanation": "勝負に敗れる意味で、家で過ごす文脈には合わない。"}, {"text": "出かけて", "is_correct": false, "explanation": "外へ行く意味で、「家で出かけていました」は矛盾する。"}, {"text": "登って", "is_correct": false, "explanation": "高い所へ上がる意味で、家で過ごす文脈には合わない。"}], "explanations": {"寛いで": "「家で寛いでいました」の形で、一日中くつろいで過ごしたことを表す。", "負けて": "勝負に敗れる意味で、家で過ごす文脈には合わない。", "出かけて": "外へ行く意味で、「家で出かけていました」は矛盾する。", "登って": "高い所へ上がる意味で、家で過ごす文脈には合わない。"}, "sentence_index": 0, "correct_answer": "寛いで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時間がないので寛ぎました。", "explanation": "ここは〈急ぐ〉の意味。寛ぐは落ち着いてくつろぐ意味で、時間が迫っている状況とは矛盾する。"}, {"text": "店員に寛ぎました。", "explanation": "ここは〈怒る〉の意味。寛ぐは気持ちを楽にする意味で、人に怒った気持ちは表せない。"}, {"text": "試験に寛ぎました。", "explanation": "ここは〈失敗する〉の意味。寛ぐは落ち着いて過ごす意味で、試験の結果が悪かったことは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38185, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寛いで", "is_correct": true, "explanation": "「どうぞ寛いでください」の形で、くつろいで過ごすよう勧める表現になる。"}, {"text": "汚して", "is_correct": false, "explanation": "汚す行為を勧める意味になり、くつろぐ勧めとして不自然。"}, {"text": "壊して", "is_correct": false, "explanation": "壊す行為を勧めることになり、文脈に合わない。"}, {"text": "殴って", "is_correct": false, "explanation": "暴力の意味になり、くつろぐ勧めとして成り立たない。"}], "explanations": {"寛いで": "「どうぞ寛いでください」の形で、くつろいで過ごすよう勧める表現になる。", "汚して": "汚す行為を勧める意味になり、くつろぐ勧めとして不自然。", "壊して": "壊す行為を勧めることになり、文脈に合わない。", "殴って": "暴力の意味になり、くつろぐ勧めとして成り立たない。"}, "sentence_index": 6, "correct_answer": "寛いで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "咳き込むほどの煙で寛いだ。", "explanation": "ここは〈咳き込む〉の意味。寛ぐは落ち着いてくつろぐ意味で、せき込むような苦しさは表せない。"}, {"text": "テストの結果に寛ぎました。", "explanation": "ここは〈落ち込む〉の意味。寛ぐは気持ちを楽にする意味で、気持ちが沈んだことは表せない。"}, {"text": "上司に寛ぎました。", "explanation": "ここは〈逆らう〉の意味。寛ぐは穏やかに過ごす意味で、相手に反抗する行為は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38185, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅館の部屋で寛いだ過ごしました。", "corrected_sentence": "旅館の部屋で寛いで過ごしました。", "error_description": "「寛いで過ごす」はて形で続ける。「寛いだ過ごし」は誤りで、正しくは「寛いで過ごし」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寛いで", "is_correct": true, "explanation": "て形で、「しまいました」に続けると、くつろいでしまったの意味になる。"}, {"text": "寛ぐ", "is_correct": false, "explanation": "辞書形で、「寛ぐしまいました」は接続が成り立たない。"}, {"text": "寛いだ", "is_correct": false, "explanation": "た形で、「寛いだしまいました」は接続が誤り。"}, {"text": "寛ぎ", "is_correct": false, "explanation": "連用形で、「しまいました」には直接続かない。"}], "correct_form": "寛いで", "base_form": "寛ぐ", "form_label": "て形", "sentence_index": 1, "explanations": {"寛いで": "て形で、「しまいました」に続けると、くつろいでしまったの意味になる。", "寛ぐ": "辞書形で、「寛ぐしまいました」は接続が成り立たない。", "寛いだ": "た形で、「寛いだしまいました」は接続が誤り。", "寛ぎ": "連用形で、「しまいました」には直接続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38185, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湯船でゆっくり寛ぐていました。", "corrected_sentence": "湯船でゆっくり寛いでいました。", "error_description": "「寛ぐ」をて形にすると「寛いで」になる。「寛ぐていた」は誤りで、正しくは「寛いでいた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寛ぐ", "is_correct": true, "explanation": "辞書形で、「寛ぐ時間」と名詞を修飾する形。"}, {"text": "寛いで", "is_correct": false, "explanation": "て形で、名詞を修飾する形にはならない。"}, {"text": "寛げ", "is_correct": false, "explanation": "可能形の語幹で、名詞を直接修飾できない。"}, {"text": "寛がない", "is_correct": false, "explanation": "ない形で、「寛がない時間」は寛がない時間を表し、意味が逆になる。"}], "correct_form": "寛ぐ", "base_form": "寛ぐ", "form_label": "基本形", "sentence_index": 7, "explanations": {"寛ぐ": "辞書形で、「寛ぐ時間」と名詞を修飾する形。", "寛いで": "て形で、名詞を修飾する形にはならない。", "寛げ": "可能形の語幹で、名詞を直接修飾できない。", "寛がない": "ない形で、「寛がない時間」は寛がない時間を表し、意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38186, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "〈見かけた〉の場所を示す〈で〉。家の近くという場所で見かけたことを表す。"}, {"text": "が", "is_correct": false, "explanation": "〈近くが〉が主語になると『近くが大きな犬を見かけた』となり、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "〈近くを〉を〈見かけた〉の対象にできず、〈を〉が二つ重なって不自然。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や相手を示すので、『近くと大きな犬を見かけた』は不自然。"}], "correct_answer": "で", "explanations": {"で": "〈見かけた〉の場所を示す〈で〉。家の近くという場所で見かけたことを表す。", "が": "〈近くが〉が主語になると『近くが大きな犬を見かけた』となり、意味が通らない。", "を": "〈近くを〉を〈見かけた〉の対象にできず、〈を〉が二つ重なって不自然。", "と": "〈と〉は並列や相手を示すので、『近くと大きな犬を見かけた』は不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38186, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈ある〉の存在場所を示す〈に〉。病院が近くにあるという意味になる。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すので、〈近くへあって〉では存在する場所を示せない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表すので、〈近くからあって〉では存在の場所にならず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞を続ける助詞で、〈近くのあって〉は〈ある〉に続かず誤り。"}], "correct_answer": "に", "explanations": {"に": "〈ある〉の存在場所を示す〈に〉。病院が近くにあるという意味になる。", "へ": "〈へ〉は方向を表すので、〈近くへあって〉では存在する場所を示せない。", "から": "〈から〉は起点を表すので、〈近くからあって〉では存在の場所にならず、不自然。", "の": "〈の〉は名詞を続ける助詞で、〈近くのあって〉は〈ある〉に続かず誤り。"}, "error_tags": {"へ": "方向", "から": "起点", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38186, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "近くの意味は、ある場所からあまり遠くないところです。", "primary_collocate": null, "pronunciation": "ちかく", "ipa": "tɕikakɯ", "syllable_count": 3, "sentences": [{"text": "駅の近くに、新しいパン屋ができました。", "target_word": "近く", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに、新[あたら]しいパン屋[や]ができました。", "sentence_source": "generated"}, {"text": "家の近くで、大きな犬を見かけました。", "target_word": "近く", "complexity_tier": "T3", "furigana": "家[いえ]の近[ちか]くで、大[おお]きな犬[いぬ]を見[み]かけました。", "sentence_source": "generated"}, {"text": "学校の近くには、小さな公園があります。", "target_word": "近く", "complexity_tier": "T3", "furigana": "学校[がっこう]の近[ちか]くには、小[ちい]さな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "すみません、この近くにトイレはありますか。", "target_word": "近く", "complexity_tier": "T3", "furigana": "すみません、この近[ちか]くにトイレはありますか。", "sentence_source": "generated"}, {"text": "私の家は海の近くなので、夏は涼しいです。", "target_word": "近く", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]は海[うみ]の近[ちか]くなので、夏[なつ]は涼[すず]しいです。", "sentence_source": "generated"}, {"text": "近くの店で牛乳を買ってきてください。", "target_word": "近く", "complexity_tier": "T3", "furigana": "近[ちか]くの店[みせ]で牛乳[ぎゅうにゅう]を買[か]ってきてください。", "sentence_source": "generated"}, {"text": "会社の近くに住んでいるので、歩いて通勤できます。", "target_word": "近く", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の近[ちか]くに住[す]んでいるので、歩[ある]いて通勤[つうきん]できます。", "sentence_source": "generated"}, {"text": "病院が近くにあって、とても安心です。", "target_word": "近く", "complexity_tier": "T3", "furigana": "病院[びょういん]が近[ちか]くにあって、とても安心[あんしん]です。", "sentence_source": "generated"}, {"text": "近くまで来たので、友達の家に寄りました。", "target_word": "近く", "complexity_tier": "T3", "furigana": "近[ちか]くまで来[き]たので、友達[ともだち]の家[いえ]に寄[よ]りました。", "sentence_source": "generated"}, {"text": "図書館の近くを通ったとき、先生に会いました。", "target_word": "近く", "complexity_tier": "T3", "furigana": "図書館[としょかん]の近[ちか]くを通[とお]ったとき、先生[せんせい]に会[あ]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "近く", "label": "基本形"}, {"form": "近くに", "label": "に格"}, {"form": "近くの", "label": "連体形"}, {"form": "近くで", "label": "で格"}], "register": "neutral", "sense_fingerprint": "ある場所からあまり離れていない所を表す場所名詞。「〜の近くに」の形で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38186, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "近く", "is_correct": true, "explanation": "「駅の近くに」: 場所を示す名詞で、店ができた位置を自然に表す。"}, {"text": "電車", "is_correct": false, "explanation": "「駅の電車に」: 電車は乗り物で、パン屋の所在地にはならない。"}, {"text": "切符", "is_correct": false, "explanation": "「駅の切符に」: 切符は場所ではなく、店ができる位置を表せない。"}, {"text": "時刻表", "is_correct": false, "explanation": "「駅の時刻表に」: 時刻表は掲示物で、店の所在を示さない。"}], "explanations": {"近く": "「駅の近くに」: 場所を示す名詞で、店ができた位置を自然に表す。", "電車": "「駅の電車に」: 電車は乗り物で、パン屋の所在地にはならない。", "切符": "「駅の切符に」: 切符は場所ではなく、店ができる位置を表せない。", "時刻表": "「駅の時刻表に」: 時刻表は掲示物で、店の所在を示さない。"}, "sentence_index": 0, "correct_answer": "近く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "近く、新しい部屋に引っ越しました。", "explanation": "〈最近〉（少し前）と取り違えた。〈近く〉は〈近いうち〉の意味なので、過去の出来事には使えない。"}, {"text": "近くの将来、この町は大きく変わるでしょう。", "explanation": "〈近い将来〉の〈近い〉と取り違えた。〈近く〉は名詞なので〈近くの将来〉とは言えず、時間の意味にもならない。"}, {"text": "彼女とは近くの仲なので、何でも相談できる。", "explanation": "〈近しい〉（親しい）と取り違えた。人間関係の親しさは〈近しい〉で表し、〈近く〉（場所）では意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38186, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近く", "is_correct": true, "explanation": "「会社の近くに住んでいる」: 住んでいる場所の周辺を表す。"}, {"text": "駅", "is_correct": false, "explanation": "「会社の駅に住んでいる」: 駅は会社と別の場所で、この関係は不自然。"}, {"text": "社内", "is_correct": false, "explanation": "「会社の社内に住んでいる」: 社内は会社の中で、住居の場所にならない。"}, {"text": "制服", "is_correct": false, "explanation": "「会社の制服に住んでいる」: 制服は衣類で、住む場所にならない。"}], "explanations": {"近く": "「会社の近くに住んでいる」: 住んでいる場所の周辺を表す。", "駅": "「会社の駅に住んでいる」: 駅は会社と別の場所で、この関係は不自然。", "社内": "「会社の社内に住んでいる」: 社内は会社の中で、住居の場所にならない。", "制服": "「会社の制服に住んでいる」: 制服は衣類で、住む場所にならない。"}, "sentence_index": 6, "correct_answer": "近く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの店の近くは五十メートルです。", "explanation": "〈距離〉の意味と取り違えた。〈近く〉は場所を指す名詞で、長さを示す語にはならない。"}, {"text": "大会を近くに控えて、練習に熱が入っている。", "explanation": "〈近く〉を時間の意味（近いうち）で使っている。この義項は場所の近さなので、時間の近さには当てはまらない。"}, {"text": "先生に近くを伝えた。", "explanation": "〈近況〉（最近の様子）と取り違えた。〈近くを伝える〉は内容を表せず、〈近況〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38186, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園の近くを、子どもが遊んでいます。", "corrected_sentence": "公園の近くで、子どもが遊んでいます。", "error_description": "場所を表す〈で〉が正しい。〈を〉を使うと〈近くを遊ぶ〉となり、場所の意味が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38186, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図書館の近くが、大きな公園があります。", "corrected_sentence": "図書館の近くに、大きな公園があります。", "error_description": "存在の場所を表す〈に〉が正しい。〈が〉だと〈近くが〉が主語になり、『近くが公園がある』となって不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38189, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『動産を分けた』で、分ける対象を示す目的語。"}, {"text": "の", "is_correct": false, "explanation": "『父の動産の、兄弟で分けた』では、文の対象が立たず成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『動産に分けた』では、分ける対象を示せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、『動産へ分けた』では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "『動産を分けた』で、分ける対象を示す目的語。", "の": "『父の動産の、兄弟で分けた』では、文の対象が立たず成り立たない。", "に": "『動産に分けた』では、分ける対象を示せず不自然。", "へ": "『へ』は方向を表すので、『動産へ分けた』では意味が通らない。"}, "error_tags": {"の": "連体修飾", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38189, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『動産は』で、ここでは動産の持ち運びやすさを話題として示す。"}, {"text": "と", "is_correct": false, "explanation": "『動産と簡単に』では並列・共同の相手を示すが、続く文に相手がなく成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "『動産から簡単に』では起点を示すことになり、話題を示す『は』の役割と合わず不自然。"}, {"text": "で", "is_correct": false, "explanation": "『動産で簡単に』では手段・場所を示すが、『移せる』の手段として続かず不自然。"}], "correct_answer": "は", "explanations": {"は": "『動産は』で、ここでは動産の持ち運びやすさを話題として示す。", "と": "『動産と簡単に』では並列・共同の相手を示すが、続く文に相手がなく成り立たない。", "から": "『動産から簡単に』では起点を示すことになり、話題を示す『は』の役割と合わず不自然。", "で": "『動産で簡単に』では手段・場所を示すが、『移せる』の手段として続かず不自然。"}, "error_tags": {"と": "並列・共同", "から": "起点", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38189, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "動産とは、土地や建物などの不動産に対して、家具や車など、持ち運びが可能な財産のことを指します。", "primary_collocate": null, "pronunciation": "どうさん", "ipa": "doːsaɴ", "syllable_count": 4, "sentences": [{"text": "車や家具は動産であり、土地や建物とは区別される。", "target_word": "動産", "complexity_tier": "T3", "furigana": "車[くるま]や家具[かぐ]は動産[どうさん]であり、土地[とち]や建物[たてもの]とは区別[くべつ]される。", "sentence_source": "generated"}, {"text": "彼は亡くなった父の動産を、兄弟で分けた。", "target_word": "動産", "complexity_tier": "T3", "furigana": "彼[かれ]は亡[な]くなった父[ちち]の動産[どうさん]を、兄弟[きょうだい]で分[わ]けた。", "sentence_source": "generated"}, {"text": "動産は持ち運べるため、盗まれやすい。", "target_word": "動産", "complexity_tier": "T3", "furigana": "動産[どうさん]は持[も]ち運[はこ]べるため、盗[ぬす]まれやすい。", "sentence_source": "generated"}, {"text": "銀行は、会社の動産を担保として受け取った。", "target_word": "動産", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]は、会社[かいしゃ]の動産[どうさん]を担保[たんぽ]として受[う]け取[と]った。", "sentence_source": "generated"}, {"text": "引っ越しの際、高価な動産には保険をかけておいた。", "target_word": "動産", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの際[さい]、高価[こうか]な動産[どうさん]には保険[ほけん]をかけておいた。", "sentence_source": "generated"}, {"text": "裁判所は、借金を返せない人の動産を差し押さえた。", "target_word": "動産", "complexity_tier": "T3", "furigana": "裁判所[さいばんしょ]は、借金[しゃっきん]を返[かえ]せない人[ひと]の動産[どうさん]を差[さ]し押[お]さえた。", "sentence_source": "generated"}, {"text": "宝石や絵画も、価値の高い動産に入る。", "target_word": "動産", "complexity_tier": "T3", "furigana": "宝石[ほうせき]や絵画[かいが]も、価値[かち]の高[たか]い動産[どうさん]に入[はい]る。", "sentence_source": "generated"}, {"text": "土地と違って、動産は簡単に別の場所へ移せる。", "target_word": "動産", "complexity_tier": "T3", "furigana": "土地[とち]と違[ちが]って、動産[どうさん]は簡単[かんたん]に別[べつ]の場所[ばしょ]へ移[うつ]せる。", "sentence_source": "generated"}, {"text": "動産の売買には、登記が必要ないことが多い。", "target_word": "動産", "complexity_tier": "T3", "furigana": "動産[どうさん]の売買[ばいばい]には、登記[とうき]が必要[ひつよう]ないことが多[おお]い。", "sentence_source": "generated"}, {"text": "火災で建物は残ったが、中の動産はすべて失われた。", "target_word": "動産", "complexity_tier": "T3", "furigana": "火災[かさい]で建物[たてもの]は残[のこ]ったが、中[なか]の動産[どうさん]はすべて失[うしな]われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動産", "label": "基本形"}], "register": "やや硬い書き言葉（常体）", "sense_fingerprint": "土地や建物に対して、家具や車など持ち運べる財産", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fe9a294-c720-4877-860c-14bdcabf3668') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38189, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動産", "is_correct": true, "explanation": "持ち運べる物を指し、車や家具がこれに当たるという文に合う。"}, {"text": "不動産", "is_correct": false, "explanation": "土地や建物を指すので、車や家具に当てはまらず、『区別される』という文とも矛盾する。"}, {"text": "債権", "is_correct": false, "explanation": "人に対して請求できる権利のことで、車や家具を指さない。"}, {"text": "登記", "is_correct": false, "explanation": "権利を公に記録することで、物の種類を表さない。"}], "explanations": {"動産": "持ち運べる物を指し、車や家具がこれに当たるという文に合う。", "不動産": "土地や建物を指すので、車や家具に当てはまらず、『区別される』という文とも矛盾する。", "債権": "人に対して請求できる権利のことで、車や家具を指さない。", "登記": "権利を公に記録することで、物の種類を表さない。"}, "sentence_index": 0, "correct_answer": "動産"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "銀行は、会社の動産である工場の建物を担保として受け取った。", "explanation": "ここは〈不動産〉の意味。建物は動かせないので、動産とは言わない。"}, {"text": "工場の土地は動産として帳簿に計上される。", "explanation": "ここは〈固定資産〉の意味。土地は動かせないので、動産の分類には入らない。"}, {"text": "銀行は、会社の特許権を動産として担保に受け取った。", "explanation": "ここは〈財産〉全体の意味と取り違えた用法。動産は形のある物に限るので、形のない特許権は動産の中には入らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38189, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動産", "is_correct": true, "explanation": "持ち運べる物を指し、宝石や絵画がその分類に入るという文に合う。"}, {"text": "利息", "is_correct": false, "explanation": "「利息」は借りた金に対して払う金銭のことで、宝石や絵画が入る分類ではない。"}, {"text": "税金", "is_correct": false, "explanation": "「税金」は国や自治体に納める金のことで、宝石や絵画の分類を表さない。"}, {"text": "借金", "is_correct": false, "explanation": "「借金」は返す義務のある借り入れのことで、宝石や絵画の分類を表さない。"}], "explanations": {"動産": "持ち運べる物を指し、宝石や絵画がその分類に入るという文に合う。", "利息": "「利息」は借りた金に対して払う金銭のことで、宝石や絵画が入る分類ではない。", "税金": "「税金」は国や自治体に納める金のことで、宝石や絵画の分類を表さない。", "借金": "「借金」は返す義務のある借り入れのことで、宝石や絵画の分類を表さない。"}, "sentence_index": 6, "correct_answer": "動産"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "『美しい』は動産だ。", "explanation": "ここは〈形容詞〉と取り違えた用法。動産は持ち運べる財産を指す名詞で、『美しい』という形容詞の分類を表す語ではない。"}, {"text": "彼は滑らかな動産で、ボールを打ち返した。", "explanation": "ここは〈動作〉の意味（体の動き）。動産は持ち運べる財産のことで、体の動きは表さない。"}, {"text": "この船の動産は風で、帆を張って進む。", "explanation": "ここは〈動力〉の意味（船を進める力）。動産は持ち運べる物のことで、進む力は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38189, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この機械は動産に扱われ、登記は必要ない。", "corrected_sentence": "この機械は動産として扱われ、登記は必要ない。", "error_description": "『〜として扱われる』と言うので、『として』を『に』に変えると不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38189, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "借金の返済が滞ったため、裁判所は動産が差し押さえた。", "corrected_sentence": "借金の返済が滞ったため、裁判所は動産を差し押さえた。", "error_description": "『差し押さえる』は動産を目的語に取るので『を』が必要。『が』では動産が主語になり、文が崩れる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88b1f8-5d45-4d88-bd3a-a38a9d3c3042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38190, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在する場所を示す「に」で、「このアパートには二十の部屋がある」の場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」だが、ある（存在）は目的語を取らないので「アパートを二十の部屋がある」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は存在する場所には使わず、「アパートへ二十の部屋がある」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞をつなぐもので、「アパートの、〜がある」と文を終わらせられない。"}], "correct_answer": "に", "explanations": {"に": "存在する場所を示す「に」で、「このアパートには二十の部屋がある」の場所を表す。", "を": "目的語の「を」だが、ある（存在）は目的語を取らないので「アパートを二十の部屋がある」は不自然。", "へ": "方向を示す「へ」は存在する場所には使わず、「アパートへ二十の部屋がある」は成り立たない。", "の": "連体修飾の「の」は名詞をつなぐもので、「アパートの、〜がある」と文を終わらせられない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "の": "連体修飾の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38190, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「アパートの前」を作る連体修飾の「の」で、前にある場所がアパートであることを示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」にすると「アパートが前に」となり、場所として前を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」にすると「アパートと前に」となり、場所の関係が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段の「で」にすると「アパートで前に」となり、前の位置を示せない。"}], "correct_answer": "の", "explanations": {"の": "「アパートの前」を作る連体修飾の「の」で、前にある場所がアパートであることを示す。", "が": "主語の「が」にすると「アパートが前に」となり、場所として前を示せない。", "と": "並列の「と」にすると「アパートと前に」となり、場所の関係が崩れる。", "で": "場所や手段の「で」にすると「アパートで前に」となり、前の位置を示せない。"}, "error_tags": {"が": "主語の誤り", "と": "並列の誤り", "で": "場所の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38190, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が住むための部屋がたくさんある大きな建物です。", "primary_collocate": null, "pronunciation": "あぱーと", "ipa": "apaːto", "syllable_count": 4, "sentences": [{"text": "駅の近くに、五階建ての大きなアパートが建った。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに、五階建[ごかいだ]ての大[おお]きなアパートが建[た]った。", "sentence_source": "generated"}, {"text": "このアパートには、二十の部屋がある。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "このアパートには、二十[にじゅう]の部屋[へや]がある。", "sentence_source": "generated"}, {"text": "兄は大学の近くのアパートに引っ越した。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]の近[ちか]くのアパートに引[ひ]っ越[こ]した。", "sentence_source": "generated"}, {"text": "古いアパートなので、家賃がとても安い。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "古[ふる]いアパートなので、家賃[やちん]がとても安[やす]い。", "sentence_source": "generated"}, {"text": "アパートの廊下で、隣の人に会って挨拶した。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "アパートの廊下[ろうか]で、隣[となり]の人[ひと]に会[あ]って挨拶[あいさつ]した。", "sentence_source": "generated"}, {"text": "新しいアパートを探して、不動産屋に行った。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "新[あたら]しいアパートを探[さが]して、不動産屋[ふどうさんや]に行[い]った。", "sentence_source": "generated"}, {"text": "川のそばのアパートは、夏でも風が通って涼しい。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "川[かわ]のそばのアパートは、夏[なつ]でも風[かぜ]が通[とお]って涼[すず]しい。", "sentence_source": "generated"}, {"text": "アパートの前に自転車が並んでいる。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "アパートの前[まえ]に自転車[じてんしゃ]が並[なら]んでいる。", "sentence_source": "generated"}, {"text": "大きなアパートの一階に、パン屋がある。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "大[おお]きなアパートの一階[いっかい]に、パン屋[や]がある。", "sentence_source": "generated"}, {"text": "台風のとき、アパートの住人は一階の集会室に集まった。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "台風[たいふう]のとき、アパートの住人[じゅうにん]は一階[いっかい]の集会室[しゅうかいしつ]に集[あつ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アパート", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人が住む部屋がいくつも入った建物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38190, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アパート", "is_correct": true, "explanation": "人が住む部屋が多く入った建物を指し、「五階建ての大きなアパートが建った」に合う。"}, {"text": "公園", "is_correct": false, "explanation": "人が遊ぶ屋外の場所で、五階建ての建物が建つという文には合わない。"}, {"text": "信号", "is_correct": false, "explanation": "交通を調整する設備で、五階建てで建つ建物ではないので文が成り立たない。"}, {"text": "地下鉄", "is_correct": false, "explanation": "地下を走る鉄道を指し、五階建ての建物が建つという文脈には合わない。"}], "explanations": {"アパート": "人が住む部屋が多く入った建物を指し、「五階建ての大きなアパートが建った」に合う。", "公園": "人が遊ぶ屋外の場所で、五階建ての建物が建つという文には合わない。", "信号": "交通を調整する設備で、五階建てで建つ建物ではないので文が成り立たない。", "地下鉄": "地下を走る鉄道を指し、五階建ての建物が建つという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "アパート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アパートで、警察官が容疑者を取り調べる。", "explanation": "取り調べを行う場所の話で、住まいであるアパートの意味には合わない。"}, {"text": "アパートで、先生が患者の手術をする。", "explanation": "ここは〈病院〉の意味。手術を行う医療施設の話で、住まいであるアパートには合わない。"}, {"text": "アパートで、先生が生徒に授業をする。", "explanation": "ここは〈学校〉の意味。授業を行う教育施設の話で、住まいであるアパートには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38190, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アパート", "is_correct": true, "explanation": "人が住む部屋が多く入った建物で、川のそばの建物が夏に涼しいという文脈に合う。"}, {"text": "扇風機", "is_correct": false, "explanation": "風を送る家電で、建物として風が通って涼しいという文の主語にはならない。"}, {"text": "電柱", "is_correct": false, "explanation": "電線を支える柱で、風が通って涼しいという文の主語にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、川のそばにあって涼しいという文の主語としては成り立たない。"}], "explanations": {"アパート": "人が住む部屋が多く入った建物で、川のそばの建物が夏に涼しいという文脈に合う。", "扇風機": "風を送る家電で、建物として風が通って涼しいという文の主語にはならない。", "電柱": "電線を支える柱で、風が通って涼しいという文の主語にはならない。", "冷蔵庫": "食品を冷やす家電で、川のそばにあって涼しいという文の主語としては成り立たない。"}, "sentence_index": 6, "correct_answer": "アパート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母はアパートで週三日、働いている。", "explanation": "ここは〈パート（短時間勤務）〉の意味。アパートは住まいの建物なので、働く場面には合わない。"}, {"text": "このアパートは、重い荷物を積む大きな倉庫だ。", "explanation": "ここは〈倉庫〉の意味。荷物を積んで保管する建物の話で、人が住むアパートには合わない。"}, {"text": "アパートでは、社員が毎朝朝礼をする。", "explanation": "ここは〈会社〉の意味。社員が集まる職場の話で、住人が暮らすアパートには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38190, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は、古いアパートを一階に住んでいる。", "corrected_sentence": "祖母は、古いアパートの一階に住んでいる。", "error_description": "「アパート」に続く助詞が「を」になっている。場所を表す「の」（アパートの一階）が正しい。「住む」は目的語を取らない動詞。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38190, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は、築五十年のアパートが二階に住んでいる。", "corrected_sentence": "兄は、築五十年のアパートの二階に住んでいる。", "error_description": "「アパート」に続く助詞が「が」になっている。場所を表す「の」が正しく、「が」だと主語になって文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38191, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、「アパートは、二階の角部屋だ」と話題を提示する。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」にすると「アパートを、二階の角部屋だ」となり、述語が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、名詞と「だ」の文の主題には使えない。"}, {"text": "に", "is_correct": false, "explanation": "位置を示す「に」にすると「アパートに、二階の角部屋だ」となり、文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、「アパートは、二階の角部屋だ」と話題を提示する。", "を": "目的語の「を」にすると「アパートを、二階の角部屋だ」となり、述語が合わない。", "へ": "方向を示す「へ」は、名詞と「だ」の文の主題には使えない。", "に": "位置を示す「に」にすると「アパートに、二階の角部屋だ」となり、文が成り立たない。"}, "error_tags": {"を": "目的語の誤り", "へ": "方向の誤り", "に": "位置の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38191, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「アパートの部屋」を作る連体修飾の「の」で、掃除する部屋がアパートのものであることを示す。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」にすると「アパートより部屋を」となり、掃除の対象を示せない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」が重なり「アパートを部屋を」となって非文。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」にすると「アパートと部屋を」となり、部屋がアパートに属するという関係が崩れる。"}], "correct_answer": "の", "explanations": {"の": "「アパートの部屋」を作る連体修飾の「の」で、掃除する部屋がアパートのものであることを示す。", "より": "比較の「より」にすると「アパートより部屋を」となり、掃除の対象を示せない。", "を": "目的語の「を」が重なり「アパートを部屋を」となって非文。", "と": "並列の「と」にすると「アパートと部屋を」となり、部屋がアパートに属するという関係が崩れる。"}, "error_tags": {"より": "比較の誤り", "から": "起点の誤り", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38191, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人々が暮らすための集合住宅で、各部屋が独立した居住スペースになっている建物のこと。", "primary_collocate": null, "pronunciation": "あぱーと", "ipa": "apaːto", "syllable_count": 4, "sentences": [{"text": "このアパートは、各部屋に台所とお風呂がついている。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "このアパートは、各部屋[かくへや]に台所[だいどころ]とお風呂[ふろ]がついている。", "sentence_source": "generated"}, {"text": "私が住むアパートは、二階の角部屋だ。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "私[わたし]が住[す]むアパートは、二階[にかい]の角部屋[かどべや]だ。", "sentence_source": "generated"}, {"text": "アパートの上の階の音が、夜になるとよく聞こえる。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "アパートの上[うえ]の階[かい]の音[おと]が、夜[よる]になるとよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "友達とアパートを借りて、二人で暮らしている。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "友達[ともだち]とアパートを借[か]りて、二人[ふたり]で暮[く]らしている。", "sentence_source": "generated"}, {"text": "父は定年のあと、持っていたアパートを人に貸している。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "父[ちち]は定年[ていねん]のあと、持[も]っていたアパートを人[ひと]に貸[か]している。", "sentence_source": "generated"}, {"text": "学生向けのアパートが、大学の周りに多い。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "学生向[がくせいむ]けのアパートが、大学[だいがく]の周[まわ]りに多[おお]い。", "sentence_source": "generated"}, {"text": "アパートの郵便受けに、新聞がたまっていた。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "アパートの郵便受[ゆうびんう]けに、新聞[しんぶん]がたまっていた。", "sentence_source": "generated"}, {"text": "引っ越し前に、アパートの部屋をきれいに掃除した。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]し前[まえ]に、アパートの部屋[へや]をきれいに掃除[そうじ]した。", "sentence_source": "generated"}, {"text": "ペットを飼えないアパートが多くて、部屋探しが大変だった。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "ペットを飼[か]えないアパートが多[おお]くて、部屋探[へやさが]しが大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "家賃が上がったので、別のアパートに移ることにした。", "target_word": "アパート", "complexity_tier": "T3", "furigana": "家賃[やちん]が上[あ]がったので、別[べつ]のアパートに移[うつ]ることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アパート", "label": "基本形"}], "register": "中立", "sense_fingerprint": "各部屋が独立した住まいになっている集合住宅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6723961-33ca-4712-8f1a-8170a5f30020') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38191, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アパート", "is_correct": true, "explanation": "各部屋に独立した住まいがある集合住宅で、台所や風呂が各部屋についているという文脈に合う。"}, {"text": "公園", "is_correct": false, "explanation": "屋外の遊び場で、各部屋に台所や風呂がついているという説明が成り立たない。"}, {"text": "駅", "is_correct": false, "explanation": "鉄道の乗降場所で、部屋に台所がついているという文の主語にはならない。"}, {"text": "花火", "is_correct": false, "explanation": "夜空に打ち上げるもので、部屋に台所や風呂がついているという説明には合わない。"}], "explanations": {"アパート": "各部屋に独立した住まいがある集合住宅で、台所や風呂が各部屋についているという文脈に合う。", "公園": "屋外の遊び場で、各部屋に台所や風呂がついているという説明が成り立たない。", "駅": "鉄道の乗降場所で、部屋に台所がついているという文の主語にはならない。", "花火": "夜空に打ち上げるもので、部屋に台所や風呂がついているという説明には合わない。"}, "sentence_index": 0, "correct_answer": "アパート"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アパートでは、お坊さんが毎朝お経をあげる。", "explanation": "ここは〈寺〉の意味。お経をあげる寺院の話で、各部屋が独立した住まいのアパートには合わない。"}, {"text": "アパートは、子どもが一日中遊べる広い公園だ。", "explanation": "ここは〈公園〉の意味。遊び場として使う場所の話で、人が住む集合住宅のアパートには合わない。"}, {"text": "母はアパートで週三日、働いている。", "explanation": "ここは〈パート〉の意味。アパートは住まいの建物なので、働く場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38191, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アパート", "is_correct": true, "explanation": "各部屋が独立した集合住宅で、郵便受けを持つ建物として「〜の郵便受け」に自然に入る。"}, {"text": "本棚", "is_correct": false, "explanation": "本を置く家具で、郵便受けの持ち主として文が成り立たない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電で、郵便受けがあるという文脈には合わない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花を生ける器で、郵便受けの持ち主として文が成り立たない。"}], "explanations": {"アパート": "各部屋が独立した集合住宅で、郵便受けを持つ建物として「〜の郵便受け」に自然に入る。", "本棚": "本を置く家具で、郵便受けの持ち主として文が成り立たない。", "冷蔵庫": "食品を冷やす家電で、郵便受けがあるという文脈には合わない。", "花瓶": "花を生ける器で、郵便受けの持ち主として文が成り立たない。"}, "sentence_index": 6, "correct_answer": "アパート"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "アパートで、警察官が容疑者を取り調べる。", "explanation": "取り調べを行う場所の話で、住まいであるアパートの意味には合わない。"}, {"text": "アパートでは、学生が大部屋で一緒に寝る。", "explanation": "ここは〈合宿所〉の意味。大部屋で共同生活をする施設の話で、各部屋が独立したアパートには合わない。"}, {"text": "アパートでは、お客さんが浴衣で泊まる。", "explanation": "ここは〈旅館〉の意味。浴衣で泊まる宿の話で、住人が暮らすアパートには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38191, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は、各部屋に鍵がついたアパートを住んでいる。", "corrected_sentence": "私は、各部屋に鍵がついたアパートに住んでいる。", "error_description": "「住む」に付く助詞が「を」になっている。住む場所を表す「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38191, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引っ越しで、新しいアパートが部屋を借りた。", "corrected_sentence": "引っ越しで、新しいアパートの部屋を借りた。", "error_description": "「アパート」に続く助詞が「が」になっている。部屋の所在を表す「の」が正しく、「が」だと主語になって「アパートが部屋を借りた」となり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1c725cd-60e6-48da-9c21-cb8af8e2abbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38192, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「人気を集める」の形で、「集める」の目的語を示すので「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「集める」は目的語に「を」をとる他動詞なので、「が」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は目的語を示さないので、「人気に集めている」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表し、目的語は示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「人気を集める」の形で、「集める」の目的語を示すので「を」が正しい。", "が": "「集める」は目的語に「を」をとる他動詞なので、「が」では文が成り立たない。", "に": "「に」は目的語を示さないので、「人気に集めている」は成り立たない。", "と": "「と」は並列や引用を表し、目的語は示せないので合わない。"}, "error_tags": {"が": "subject_marker", "に": "target_or_goal", "と": "coordinate_or_quote"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不人気", "is_correct": true, "explanation": "好かれていないことを表し、人気の対義語。「人気が高い」と対になる語。"}, {"text": "倉庫", "is_correct": false, "explanation": "物をしまう建物で、人気と反対の関係にはない。"}, {"text": "冷房", "is_correct": false, "explanation": "室内を冷やす設備で、人気の対義語ではない。"}, {"text": "機材", "is_correct": false, "explanation": "撮影や作業に使う道具で、人気と反対の関係にはない。"}], "correct_answer": "不人気", "explanations": {"不人気": "好かれていないことを表し、人気の対義語。「人気が高い」と対になる語。", "倉庫": "物をしまう建物で、人気と反対の関係にはない。", "冷房": "室内を冷やす設備で、人気の対義語ではない。", "機材": "撮影や作業に使う道具で、人気と反対の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38192, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人気がある」で、「ある」の主語を示すので「が」が正しい。"}, {"text": "から", "is_correct": false, "explanation": "「から」は出どころを示すので、「人気からある」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の相手が必要で、「人気よりある」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「人気へある」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「人気がある」で、「ある」の主語を示すので「が」が正しい。", "から": "「から」は出どころを示すので、「人気からある」は成り立たない。", "より": "「より」は比較の相手が必要で、「人気よりある」は文が成り立たない。", "へ": "「へ」は方向を示すので、「人気へある」は意味が通らない。"}, "error_tags": {"から": "source", "より": "comparison", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不人気", "is_correct": true, "explanation": "好かれていないことを表し、人気の対義語。「大きな人気を得る」と対になる語。"}, {"text": "水源", "is_correct": false, "explanation": "川の水の源を指す名詞で、人気と反対の関係にはない。"}, {"text": "造船", "is_correct": false, "explanation": "船を造ることを指し、人気の対義語ではない。"}, {"text": "製鉄", "is_correct": false, "explanation": "鉄を作ることを指し、人気と反対の関係にはない。"}], "correct_answer": "不人気", "explanations": {"不人気": "好かれていないことを表し、人気の対義語。「大きな人気を得る」と対になる語。", "水源": "川の水の源を指す名詞で、人気と反対の関係にはない。", "造船": "船を造ることを指し、人気の対義語ではない。", "製鉄": "鉄を作ることを指し、人気と反対の関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38192, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人が好きになること。", "primary_collocate": null, "pronunciation": "にんき", "ipa": "ɲiŋki", "syllable_count": 3, "sentences": [{"text": "この店のパンは味がよくて、町でとても人気がある。", "target_word": "人気", "complexity_tier": "T3", "furigana": "この店[みせ]のパンは味[あじ]がよくて、町[まち]でとても人気[にんき]がある。", "sentence_source": "generated"}, {"text": "新しい歌手が、若い人たちの間で人気を集めている。", "target_word": "人気", "complexity_tier": "T3", "furigana": "新[あたら]しい歌手[かしゅ]が、若[わか]い人[ひと]たちの間[あいだ]で人気[にんき]を集[あつ]めている。", "sentence_source": "generated"}, {"text": "人気が出たのは、彼女の明るい性格のおかげだ。", "target_word": "人気", "complexity_tier": "T3", "furigana": "人気[にんき]が出[で]たのは、彼女[かのじょ]の明[あか]るい性格[せいかく]のおかげだ。", "sentence_source": "generated"}, {"text": "その漫画は人気が高く、本屋ではいつも売り切れている。", "target_word": "人気", "complexity_tier": "T3", "furigana": "その漫画[まんが]は人気[にんき]が高[たか]く、本屋[ほんや]ではいつも売[う]り切[き]れている。", "sentence_source": "generated"}, {"text": "値段が安いので、この色のかばんは人気だ。", "target_word": "人気", "complexity_tier": "T3", "furigana": "値段[ねだん]が安[やす]いので、この色[いろ]のかばんは人気[にんき]だ。", "sentence_source": "generated"}, {"text": "去年は人気があった服も、今年はあまり売れない。", "target_word": "人気", "complexity_tier": "T3", "furigana": "去年[きょねん]は人気[にんき]があった服[ふく]も、今年[ことし]はあまり売[う]れない。", "sentence_source": "generated"}, {"text": "動物園ではパンダの人気が圧倒的で、いつも行列ができる。", "target_word": "人気", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]ではパンダの人気[にんき]が圧倒的[あっとうてき]で、いつも行列[ぎょうれつ]ができる。", "sentence_source": "generated"}, {"text": "優しい先生は、生徒たちに人気がある。", "target_word": "人気", "complexity_tier": "T3", "furigana": "優[やさ]しい先生[せんせい]は、生徒[せいと]たちに人気[にんき]がある。", "sentence_source": "generated"}, {"text": "人気が落ちてきたので、店は新しい料理を考えた。", "target_word": "人気", "complexity_tier": "T3", "furigana": "人気[にんき]が落[お]ちてきたので、店[みせ]は新[あたら]しい料理[りょうり]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "彼のチームは強くて、小さな町でも大きな人気を得ている。", "target_word": "人気", "complexity_tier": "T3", "furigana": "彼[かれ]のチームは強[つよ]くて、小[ちい]さな町[まち]でも大[おお]きな人気[にんき]を得[え]ている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人気", "label": "基本形"}, {"form": "人気の", "label": "連体形（の）"}, {"form": "人気が", "label": "主語形（が）"}], "register": "中立（普通体）", "sense_fingerprint": "多くの人に好かれている状態（店・人・物への好意）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38192, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人気", "is_correct": true, "explanation": "「町でとても人気がある」は、店のパンが多くの人に好かれている文脈と合う。"}, {"text": "寿命", "is_correct": false, "explanation": "生きている期間を表す名詞で、町での評判を述べる文には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "空の状態を表す語で、町の人々の好みを述べる文には合わない。"}, {"text": "湿気", "is_correct": false, "explanation": "空気中の水分を表す語で、評判を述べる文脈には合わない。"}], "explanations": {"人気": "「町でとても人気がある」は、店のパンが多くの人に好かれている文脈と合う。", "寿命": "生きている期間を表す名詞で、町での評判を述べる文には合わない。", "天気": "空の状態を表す語で、町の人々の好みを述べる文には合わない。", "湿気": "空気中の水分を表す語で、評判を述べる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "人気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の人気を入れ替えるため、窓を開けた。", "explanation": "空気（部屋の中の空気）を言いたい文だが、人気は人々に好かれている度合いの語で、空気の代わりにはならない。"}, {"text": "彼は人気が厚く、クラスのみんなに頼りにされている。", "explanation": "人望（信頼されて慕われること）を言いたい文だが、人気は「厚い」と結びつかず、人望の代わりにはならない。"}, {"text": "祭りの日は人気が多くて、前に進めなかった。", "explanation": "人混み（人の多さ）を言いたい文だが、人気は人の数ではなく好かれている度合いなので、混雑の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38192, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人気", "is_correct": true, "explanation": "「パンダの人気が圧倒的で、行列ができる」は、多くの人に好かれている文脈と合う。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表す語で、行列ができる理由としては文が成り立たない。"}, {"text": "寝床", "is_correct": false, "explanation": "寝るための場所を表す語で、行列の文脈と合わない。"}, {"text": "毛並み", "is_correct": false, "explanation": "体の毛の状態を表す語で、行列の文脈には合わない。"}], "explanations": {"人気": "「パンダの人気が圧倒的で、行列ができる」は、多くの人に好かれている文脈と合う。", "体重": "体の重さを表す語で、行列ができる理由としては文が成り立たない。", "寝床": "寝るための場所を表す語で、行列の文脈と合わない。", "毛並み": "体の毛の状態を表す語で、行列の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "人気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は人気が多く、子どもの数も増えている。", "explanation": "人数（人の多さ）を言いたい文だが、人気は好かれている度合いの語で、人の数は表せないので合わない。"}, {"text": "彼女の笑顔には人気が持てて、思わず見入った。", "explanation": "好感（好ましく感じること）を言いたい文だが、「好感が持てる」と言い、人気は持てないので合わない。"}, {"text": "あの店には、いつも人気が通ってくる。", "explanation": "常連（いつも決まって来る客）を言いたい文だが、人気は好かれている度合いの語で、店に通ってくることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38192, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この映画は若い人たちの間で人気に高い。", "corrected_sentence": "この映画は若い人たちの間で人気が高い。", "error_description": "「人気が高い」は、主語「人気」に「が」を付ける形。「人気に高い」は助詞の誤りで、「に」は不要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38192, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は若い人たちに人気ある。", "corrected_sentence": "この店は若い人たちに人気がある。", "error_description": "述語として「人気がある」と言うには「が」が必要。「人気ある」は不自然で、「が」を補うか「人気のある」（連体修飾）にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38193, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「人気のある俳優」の形で、「人気」と「ある」をつなげて連体修飾を作るので「の」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「人気をある俳優」は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、「人気にある俳優」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すので、「人気とある俳優」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「人気のある俳優」の形で、「人気」と「ある」をつなげて連体修飾を作るので「の」が正しい。", "を": "「を」は目的語を示すので、「人気をある俳優」は文が成り立たない。", "に": "「に」は場所や相手を示すので、「人気にある俳優」は意味が通らない。", "と": "「と」は並列や引用を示すので、「人気とある俳優」は成り立たない。"}, "error_tags": {"を": "object", "に": "target", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不人気", "is_correct": true, "explanation": "注目や好意を集めていないことを表し、人気の対義語。"}, {"text": "海底", "is_correct": false, "explanation": "海の底を指す名詞で、人気と反対の関係にはない。"}, {"text": "手紙", "is_correct": false, "explanation": "文字で伝える書き物で、人気の対義語ではない。"}, {"text": "乾燥", "is_correct": false, "explanation": "水分がなくなった状態を指し、人気と反対の関係にはない。"}], "correct_answer": "不人気", "explanations": {"不人気": "注目や好意を集めていないことを表し、人気の対義語。", "海底": "海の底を指す名詞で、人気と反対の関係にはない。", "手紙": "文字で伝える書き物で、人気の対義語ではない。", "乾燥": "水分がなくなった状態を指し、人気と反対の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38193, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「人気は予想以上で」の形で、話題の主題を示すので「は」が正しい。"}, {"text": "から", "is_correct": false, "explanation": "「から」は出どころを示すので、「人気から予想以上で」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の相手が必要で、「人気より予想以上で」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「人気へ予想以上で」は主題にならない。"}], "correct_answer": "は", "explanations": {"は": "「人気は予想以上で」の形で、話題の主題を示すので「は」が正しい。", "から": "「から」は出どころを示すので、「人気から予想以上で」は文が成り立たない。", "より": "「より」は比較の相手が必要で、「人気より予想以上で」は意味が通らない。", "へ": "「へ」は方向を示すので、「人気へ予想以上で」は主題にならない。"}, "error_tags": {"から": "source", "より": "comparison", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不人気", "is_correct": true, "explanation": "関心を集めていないことを表し、人気の対義語。「話題になる」の反対の状態に当たる語。"}, {"text": "製鉄", "is_correct": false, "explanation": "鉄を作ることを指し、人気と反対の関係にはない。"}, {"text": "造船", "is_correct": false, "explanation": "船を造ることを指し、人気の対義語ではない。"}, {"text": "漁港", "is_correct": false, "explanation": "漁船が出入りする港を指し、人気と反対の関係にはない。"}], "correct_answer": "不人気", "explanations": {"不人気": "関心を集めていないことを表し、人気の対義語。「話題になる」の反対の状態に当たる語。", "製鉄": "鉄を作ることを指し、人気と反対の関係にはない。", "造船": "船を造ることを指し、人気の対義語ではない。", "漁港": "漁船が出入りする港を指し、人気と反対の関係にはない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38193, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "多くの人に好まれたり、関心を持たれたりすること。", "primary_collocate": null, "pronunciation": "にんき", "ipa": "ɲiŋki", "syllable_count": 3, "sentences": [{"text": "そのドラマは放送のたびに人気が上がり、話題になった。", "target_word": "人気", "complexity_tier": "T3", "furigana": "そのドラマは放送[ほうそう]のたびに人気[にんき]が上[あ]がり、話題[わだい]になった。", "sentence_source": "generated"}, {"text": "人気のある俳優ほど、仕事の選び方に気をつけている。", "target_word": "人気", "complexity_tier": "T3", "furigana": "人気[にんき]のある俳優[はいゆう]ほど、仕事[しごと]の選[えら]び方[かた]に気[き]をつけている。", "sentence_source": "generated"}, {"text": "ネットでの人気が、売り上げに大きく関わるようになった。", "target_word": "人気", "complexity_tier": "T3", "furigana": "ネットでの人気[にんき]が、売[う]り上[あ]げに大[おお]きく関[かか]わるようになった。", "sentence_source": "generated"}, {"text": "彼の動画は人気を呼んで、一か月で百万回も見られた。", "target_word": "人気", "complexity_tier": "T3", "furigana": "彼[かれ]の動画[どうが]は人気[にんき]を呼[よ]んで、一[いっ]か月[げつ]で百万回[ひゃくまんかい]も見[み]られた。", "sentence_source": "generated"}, {"text": "人気が長く続く商品には、必ず理由がある。", "target_word": "人気", "complexity_tier": "T3", "furigana": "人気[にんき]が長[なが]く続[つづ]く商品[しょうひん]には、必[かなら]ず理由[りゆう]がある。", "sentence_source": "generated"}, {"text": "そのキャラクターは人気が急に上がって、広告にも使われるようになった。", "target_word": "人気", "complexity_tier": "T3", "furigana": "そのキャラクターは人気[にんき]が急[きゅう]に上[あ]がって、広告[こうこく]にも使[つか]われるようになった。", "sentence_source": "generated"}, {"text": "この観光地は、外国の旅行者にも人気がある。", "target_word": "人気", "complexity_tier": "T3", "furigana": "この観光地[かんこうち]は、外国[がいこく]の旅行者[りょこうしゃ]にも人気[にんき]がある。", "sentence_source": "generated"}, {"text": "新しい映画の人気は予想以上で、劇場は毎日満席だ。", "target_word": "人気", "complexity_tier": "T3", "furigana": "新[あたら]しい映画[えいが]の人気[にんき]は予想以上[よそういじょう]で、劇場[げきじょう]は毎日[まいにち]満席[まんせき]だ。", "sentence_source": "generated"}, {"text": "人気だけで選ぶと、本当に良いものを見のがすかもしれない。", "target_word": "人気", "complexity_tier": "T3", "furigana": "人気[にんき]だけで選[えら]ぶと、本当[ほんとう]に良[よ]いものを見[み]のがすかもしれない。", "sentence_source": "generated"}, {"text": "流行が変わると、昨日までの人気も、すぐに消えてしまう。", "target_word": "人気", "complexity_tier": "T3", "furigana": "流行[りゅうこう]が変[か]わると、昨日[きのう]までの人気[にんき]も、すぐに消[き]えてしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人気", "label": "基本形"}, {"form": "人気の", "label": "連体形（の）"}, {"form": "人気が", "label": "主語形（が）"}], "register": "中立（普通体）", "sense_fingerprint": "世間の好意と関心を集める度合い（話題性・評判）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95396f4a-2320-429b-aa71-33a2a092556f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38193, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人気", "is_correct": true, "explanation": "「放送のたびに人気が上がり、話題になった」は、ドラマの注目度が上がる文脈と合う。"}, {"text": "寛容", "is_correct": false, "explanation": "心が広く許すことを表し、番組の注目度が上がる文脈とは結びつかない。"}, {"text": "誠実", "is_correct": false, "explanation": "真心があることを表し、注目度の上昇を述べる主語にはならない。"}, {"text": "遠慮", "is_correct": false, "explanation": "控えめにすることを表し、ドラマの注目度が上がる文脈には合わない。"}], "explanations": {"人気": "「放送のたびに人気が上がり、話題になった」は、ドラマの注目度が上がる文脈と合う。", "寛容": "心が広く許すことを表し、番組の注目度が上がる文脈とは結びつかない。", "誠実": "真心があることを表し、注目度の上昇を述べる主語にはならない。", "遠慮": "控えめにすることを表し、ドラマの注目度が上がる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "人気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室の人気を入れ替えるため、窓を開けた。", "explanation": "空気（部屋の中の空気）を言いたい文だが、人気は人々の関心の度合いを表す語で、空気の代わりにはならない。"}, {"text": "その番組は人気が厚く、若い人の信頼を集めている。", "explanation": "人望（信頼されて慕われること）を言いたい文だが、人気は「厚い」とは結びつかず、人望の代わりにはならない。"}, {"text": "祭りの会場は人気が多く、身動きがとれない。", "explanation": "人混み（人の多さ）を言いたい文だが、人気は人の数ではなく注目の度合いなので、混雑の意味では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38193, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人気", "is_correct": true, "explanation": "「外国の旅行者にも人気がある」は、観光地が多くの人に関心を持たれている文脈と合う。"}, {"text": "寿命", "is_correct": false, "explanation": "生き物や物の寿命を指す語で、観光地の注目を述べる文には合わない。"}, {"text": "空腹", "is_correct": false, "explanation": "お腹がすいた状態を表し、観光地の文脈と合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "眠りが足りないことを表し、観光地と旅行者の文脈には合わない。"}], "explanations": {"人気": "「外国の旅行者にも人気がある」は、観光地が多くの人に関心を持たれている文脈と合う。", "寿命": "生き物や物の寿命を指す語で、観光地の注目を述べる文には合わない。", "空腹": "お腹がすいた状態を表し、観光地の文脈と合わない。", "寝不足": "眠りが足りないことを表し、観光地と旅行者の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "人気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の笑顔には人気が持てて、思わず見入った。", "explanation": "好感（好ましく感じること）を言いたい文だが、「好感が持てる」と言い、人気は持てないので合わない。"}, {"text": "店の前には、長い人気ができていた。", "explanation": "行列（人が並んで待つこと）を言いたい文だが、人気は並ぶものではないので、「長い人気」とは言えない。"}, {"text": "毎朝、決まった人気がこの店に来る。", "explanation": "常連（いつも決まって来る客）を言いたい文だが、人気は注目の意味なので、店に来ることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38193, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "人気の高く店は、いつも混んでいる。", "corrected_sentence": "人気の高い店は、いつも混んでいる。", "error_description": "名詞「店」を修飾する形は連体形「高い」。「高く」は連用形で、「店」に直接つながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38193, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人気が落とすと、客足も遠のく。", "corrected_sentence": "人気が落ちると、客足も遠のく。", "error_description": "「人気が落ちる」は自動詞で主語は「人気」。「落とす」は他動詞で、主語「人気」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10aebab-b879-4f15-b369-9cdfd96671b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38194, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」は対象を「を」で示すので、「値段を見る」は自然。"}, {"text": "が", "is_correct": false, "explanation": "「値段が見てから」では見る主体が値段になってしまい、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「見る」の対象は「を」で示すので、「に」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「値段で見てから」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「見る」は対象を「を」で示すので、「値段を見る」は自然。", "が": "「値段が見てから」では見る主体が値段になってしまい、不自然。", "に": "「見る」の対象は「を」で示すので、「に」は合わない。", "で": "「で」は手段や場所を示すので、「値段で見てから」は成り立たない。"}, "error_tags": {"が": "主語と誤解", "に": "対象・相手と誤解", "で": "手段・場所と誤解"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38194, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「聞く」は内容を目的語に取り、「値段を聞く」と言う。"}, {"text": "から", "is_correct": false, "explanation": "「から」は情報の出どころを示すので、「値段から聞いたら」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「値段より聞いたら」とは言えない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐもので、「聞く」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「聞く」は内容を目的語に取り、「値段を聞く」と言う。", "から": "「から」は情報の出どころを示すので、「値段から聞いたら」は不自然。", "より": "「より」は比較を示すので、「値段より聞いたら」とは言えない。", "の": "「の」は名詞をつなぐもので、「聞く」の目的語にはならない。"}, "error_tags": {"から": "起点と誤解", "より": "比較と誤解", "の": "名詞つなぎと誤解"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38194, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物を買うときに払うお金のこと。", "primary_collocate": null, "pronunciation": "ねだん", "ipa": "nedaɴ", "syllable_count": 3, "sentences": [{"text": "この店のりんごは値段が安いので、毎週買いに来る。", "target_word": "値段", "complexity_tier": "T3", "furigana": "この店(みせ)のりんごは値段(ねだん)が安(やす)いので、毎週(まいしゅう)買(か)いに来(く)る。", "sentence_source": "generated"}, {"text": "値段を見てから、買うかどうかを決めた。", "target_word": "値段", "complexity_tier": "T3", "furigana": "値段(ねだん)を見(み)てから、買(か)うかどうかを決(き)めた。", "sentence_source": "generated"}, {"text": "同じ靴でも、店によって値段がちがう。", "target_word": "値段", "complexity_tier": "T3", "furigana": "同(おな)じ靴(くつ)でも、店(みせ)によって値段(ねだん)がちがう。", "sentence_source": "generated"}, {"text": "値段が高すぎて、その時計は買えなかった。", "target_word": "値段", "complexity_tier": "T3", "furigana": "値段(ねだん)が高(たか)すぎて、その時計(とけい)は買(か)えなかった。", "sentence_source": "generated"}, {"text": "母は値段より味を大切にして、パンを選ぶ。", "target_word": "値段", "complexity_tier": "T3", "furigana": "母(はは)は値段(ねだん)より味(あじ)を大切(たいせつ)にして、パンを選(えら)ぶ。", "sentence_source": "generated"}, {"text": "箱に値段が書いてあるので、すぐにわかる。", "target_word": "値段", "complexity_tier": "T3", "furigana": "箱(はこ)に値段(ねだん)が書(か)いてあるので、すぐにわかる。", "sentence_source": "generated"}, {"text": "天気が悪い日が続いて、野菜の値段が上がった。", "target_word": "値段", "complexity_tier": "T3", "furigana": "天気(てんき)が悪(わる)い日(ひ)が続(つづ)いて、野菜(やさい)の値段(ねだん)が上(あ)がった。", "sentence_source": "generated"}, {"text": "値段を聞いたら、思ったより安くてうれしかった。", "target_word": "値段", "complexity_tier": "T3", "furigana": "値段(ねだん)を聞(き)いたら、思(おも)ったより安(やす)くてうれしかった。", "sentence_source": "generated"}, {"text": "兄は新しいかばんの値段を店の人にたずねた。", "target_word": "値段", "complexity_tier": "T3", "furigana": "兄(あに)は新(あたら)しいかばんの値段(ねだん)を店(みせ)の人(ひと)にたずねた。", "sentence_source": "generated"}, {"text": "値段が同じなら、大きいほうを買いたい。", "target_word": "値段", "complexity_tier": "T3", "furigana": "値段(ねだん)が同(おな)じなら、大(おお)きいほうを買(か)いたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "値段", "label": "基本形"}], "register": "中立（日常会話・普通体）", "sense_fingerprint": "日常の買い物で、物を買うときに払うお金の額", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38194, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "値段", "is_correct": true, "explanation": "「値段が安い」は、買う理由になる価格を表し、文の意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目を表すので、「この店のりんごは色が安い」とは言えない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは量を表すので、「りんごは重さが安い」は意味が通らない。"}, {"text": "大きさ", "is_correct": false, "explanation": "大きさは寸法を表すので、「りんごは大きさが安い」とは言えない。"}], "explanations": {"値段": "「値段が安い」は、買う理由になる価格を表し、文の意味に合う。", "色": "色は見た目を表すので、「この店のりんごは色が安い」とは言えない。", "重さ": "重さは量を表すので、「りんごは重さが安い」は意味が通らない。", "大きさ": "大きさは寸法を表すので、「りんごは大きさが安い」とは言えない。"}, "sentence_index": 0, "correct_answer": "値段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "健康診断で、血液の値段が基準より低かった。", "explanation": "ここは〈数値〉の意味。値段は支払うお金の額で、血液の検査結果には使わない。"}, {"text": "この本は、読む人の心を支えるほどの値段がある。", "explanation": "ここは〈価値〉の意味。値段は売買で決まる金額で、心の支えになる効果の大きさには使わない。"}, {"text": "テストの値段が八十点で、先生にほめられた。", "explanation": "ここは〈点数〉の意味。値段は金額で、テストの得点には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38194, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "値段", "is_correct": true, "explanation": "「野菜の値段が上がった」は、価格が上昇したという意味で、文に合う。"}, {"text": "形", "is_correct": false, "explanation": "形は見た目の特徴で、「野菜の形が上がった」とは言えない。"}, {"text": "産地", "is_correct": false, "explanation": "産地は生産された場所を表すので、「野菜の産地が上がった」は意味が通らない。"}, {"text": "包装", "is_correct": false, "explanation": "包装は包み方を表すので、「野菜の包装が上がった」は不自然。"}], "explanations": {"値段": "「野菜の値段が上がった」は、価格が上昇したという意味で、文に合う。", "形": "形は見た目の特徴で、「野菜の形が上がった」とは言えない。", "産地": "産地は生産された場所を表すので、「野菜の産地が上がった」は意味が通らない。", "包装": "包装は包み方を表すので、「野菜の包装が上がった」は不自然。"}, "sentence_index": 6, "correct_answer": "値段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちとの思い出には、お金に代えられない値段がある。", "explanation": "ここは〈値打ち〉の意味。値段は売買の金額で、お金に代えられない大切さは表さない。"}, {"text": "この電池は値段が長くて、一年以上もつ。", "explanation": "ここは〈寿命〉の意味。値段は金額なので、期間の長さは表さない。"}, {"text": "この部屋は値段が広く、家族四人で住める。", "explanation": "ここは〈面積〉の意味。値段は金額で、部屋の広さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38194, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その服は値段をちょっと高いけれど、質がいいので買うことにした。", "corrected_sentence": "その服は値段がちょっと高いけれど、質がいいので買うことにした。", "error_description": "誤った形は「値段を」、正しくは「値段が」。「高い」の主語は「が」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38194, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このホテルは値段が手ごろくて、部屋が広い。", "corrected_sentence": "このホテルは値段が手ごろで、部屋が広い。", "error_description": "誤った形は「手ごろくて」、正しくは「手ごろで」。「手ごろ」は形容動詞なので「で」で続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38195, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「手ごろだ」の主語は「が」で示すので、「値段が手ごろだ」と言う。"}, {"text": "を", "is_correct": false, "explanation": "「手ごろだ」は目的語を取らないので、「値段を手ごろだ」とは言えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や目標を示すので、「値段に手ごろだ」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐもので、述語の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「手ごろだ」の主語は「が」で示すので、「値段が手ごろだ」と言う。", "を": "「手ごろだ」は目的語を取らないので、「値段を手ごろだ」とは言えない。", "に": "「に」は相手や目標を示すので、「値段に手ごろだ」は成り立たない。", "の": "「の」は名詞をつなぐもので、述語の主語にはならない。"}, "error_tags": {"を": "目的語と誤解", "に": "相手・目標と誤解", "の": "名詞つなぎと誤解"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38195, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「二千円からだ」の主語となる値段を示すので、「値段が二千円からだ」と言う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「値段で二千円からだ」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「値段へ二千円からだ」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「値段より二千円からだ」とは言えない。"}], "correct_answer": "が", "explanations": {"が": "「二千円からだ」の主語となる値段を示すので、「値段が二千円からだ」と言う。", "で": "「で」は手段や場所を示すので、「値段で二千円からだ」は成り立たない。", "へ": "「へ」は方向を示すので、「値段へ二千円からだ」は不自然。", "より": "「より」は比較を示すので、「値段より二千円からだ」とは言えない。"}, "error_tags": {"で": "手段・場所と誤解", "へ": "方向と誤解", "より": "比較と誤解"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38195, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "品物やサービスに対して支払われるお金の額。", "primary_collocate": null, "pronunciation": "ねだん", "ipa": "nedaɴ", "syllable_count": 3, "sentences": [{"text": "ホテルの値段は、季節によって大きく変わる。", "target_word": "値段", "complexity_tier": "T3", "furigana": "ホテルの値段(ねだん)は、季節(きせつ)によって大(おお)きく変(か)わる。", "sentence_source": "generated"}, {"text": "この美容院はサービスの内容のわりに値段が手ごろだ。", "target_word": "値段", "complexity_tier": "T3", "furigana": "この美容院(びよういん)はサービスの内容(ないよう)のわりに値段(ねだん)が手(て)ごろだ。", "sentence_source": "generated"}, {"text": "材料が高くなったため、店は商品の値段を上げることにした。", "target_word": "値段", "complexity_tier": "T3", "furigana": "材料(ざいりょう)が高(たか)くなったため、店(みせ)は商品(しょうひん)の値段(ねだん)を上(あ)げることにした。", "sentence_source": "generated"}, {"text": "引っ越しの値段は、荷物の量で決まる。", "target_word": "値段", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの値段(ねだん)は、荷物(にもつ)の量(りょう)で決(き)まる。", "sentence_source": "generated"}, {"text": "値段を比べてから、安いほうのプランを選んだ。", "target_word": "値段", "complexity_tier": "T3", "furigana": "値段(ねだん)を比(くら)べてから、安(やす)いほうのプランを選(えら)んだ。", "sentence_source": "generated"}, {"text": "工事の値段が高かったので、別の会社にも見積もりを頼んだ。", "target_word": "値段", "complexity_tier": "T3", "furigana": "工事(こうじ)の値段(ねだん)が高(たか)かったので、別(べつ)の会社(かいしゃ)にも見積(みつも)もりを頼(たの)んだ。", "sentence_source": "generated"}, {"text": "値段に見合う品質かどうか、口コミを読んで確かめた。", "target_word": "値段", "complexity_tier": "T3", "furigana": "値段(ねだん)に見合(みあ)う品質(ひんしつ)かどうか、口(くち)コミを読(よ)んで確(たし)かめた。", "sentence_source": "generated"}, {"text": "このレストランのコースは、値段が二千円からだ。", "target_word": "値段", "complexity_tier": "T3", "furigana": "このレストランのコースは、値段(ねだん)が二千円(にせんえん)からだ。", "sentence_source": "generated"}, {"text": "修理の値段を聞いてから、新しいものを買うことにした。", "target_word": "値段", "complexity_tier": "T3", "furigana": "修理(しゅうり)の値段(ねだん)を聞(き)いてから、新(あたら)しいものを買(か)うことにした。", "sentence_source": "generated"}, {"text": "同じ品物でも、ネットのほうが値段は低いことが多い。", "target_word": "値段", "complexity_tier": "T3", "furigana": "同(おな)じ品物(しなもの)でも、ネットのほうが値段(ねだん)は低(ひく)いことが多(おお)い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "値段", "label": "基本形"}], "register": "中立（やや説明的・普通体）", "sense_fingerprint": "品物だけでなくサービスの代金も含む、支払われる金額", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38195, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "値段", "is_correct": true, "explanation": "「ホテルの値段は季節によって変わる」は、支払う金額が変わるという意味で自然。"}, {"text": "名前", "is_correct": false, "explanation": "名前は季節によって変わらないので、「ホテルの名前は季節によって変わる」は合わない。"}, {"text": "開業年", "is_correct": false, "explanation": "開業年は過去の一点で、季節によって変わるものではない。"}, {"text": "階数", "is_correct": false, "explanation": "階数は建物の構造で、季節によって変わるものではない。"}], "explanations": {"値段": "「ホテルの値段は季節によって変わる」は、支払う金額が変わるという意味で自然。", "名前": "名前は季節によって変わらないので、「ホテルの名前は季節によって変わる」は合わない。", "開業年": "開業年は過去の一点で、季節によって変わるものではない。", "階数": "階数は建物の構造で、季節によって変わるものではない。"}, "sentence_index": 0, "correct_answer": "値段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "検査の結果、血圧の値段が正常な範囲だった。", "explanation": "ここは〈数値〉の意味。値段は支払う金額で、血圧の測定値には使わない。"}, {"text": "駅までの値段が近いので、毎日歩いて通っている。", "explanation": "ここは〈距離〉の意味。値段は金額で、場所の遠近には使わない。"}, {"text": "この講座は、受講者にとって十分な値段がある。", "explanation": "ここは〈値打ち〉の意味。値段は支払う金額で、受けた価値の大きさを表すのには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38195, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "値段", "is_correct": true, "explanation": "「値段に見合う品質」は、支払う金額に釣り合う品質という意味で、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表すので、「天気に見合う品質」は意味が通らない。"}, {"text": "包装", "is_correct": false, "explanation": "包装は包み方を表すので、「包装に見合う品質」とは言えない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目を表すので、「色に見合う品質」は意味が通らない。"}], "explanations": {"値段": "「値段に見合う品質」は、支払う金額に釣り合う品質という意味で、文に合う。", "天気": "天気は空模様を表すので、「天気に見合う品質」は意味が通らない。", "包装": "包装は包み方を表すので、「包装に見合う品質」とは言えない。", "色": "色は見た目を表すので、「色に見合う品質」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "値段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この旅館は、一度に泊まれる値段が三十人分ある。", "explanation": "ここは〈人数〉の意味。値段は金額で、泊まれる人の数は表さない。"}, {"text": "この腕時計は、値段が長く、十年以上もつ。", "explanation": "ここは〈寿命〉の意味。値段は金額なので、期間の長さには使わない。"}, {"text": "今日の値段は一万歩を超えた。", "explanation": "ここは〈歩数〉の意味。値段は支払う金額で、歩いた回数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38195, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その宿は値段を安くて、設備がよかった。", "corrected_sentence": "その宿は値段が安くて、設備がよかった。", "error_description": "誤った形は「値段を」、正しくは「値段が」。「安い」の主語は「が」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38195, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このホテルは値段が手ごろくて、部屋が広い。", "corrected_sentence": "このホテルは値段が手ごろで、部屋が広い。", "error_description": "誤った形は「手ごろくて」、正しくは「手ごろで」。「手ごろ」は形容動詞なので「で」で続ける。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
