INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38196, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを買ったり売ったりすること。", "primary_collocate": null, "pronunciation": "ばいばい", "ipa": "baibai", "syllable_count": 4, "sentences": [{"text": "市場では、毎朝、野菜や魚の売買が行われる。", "target_word": "売買", "complexity_tier": "T3", "furigana": "市場(いちば)では、毎朝(まいあさ)、野菜(やさい)や魚(さかな)の売買(ばいばい)が行(おこな)われる。", "sentence_source": "generated"}, {"text": "子どもどうしのカードの売買は、親が禁止している。", "target_word": "売買", "complexity_tier": "T3", "furigana": "子(こ)どもどうしのカードの売買(ばいばい)は、親(おや)が禁止(きんし)している。", "sentence_source": "generated"}, {"text": "古い本の売買で、父は少しお金をもうけた。", "target_word": "売買", "complexity_tier": "T3", "furigana": "古(ふる)い本(ほん)の売買(ばいばい)で、父(ちち)は少(すこ)しお金(かね)をもうけた。", "sentence_source": "generated"}, {"text": "ネットでの売買が増えて、小さな店が困っている。", "target_word": "売買", "complexity_tier": "T3", "furigana": "ネットでの売買(ばいばい)が増(ふ)えて、小(ちい)さな店(みせ)が困(こま)っている。", "sentence_source": "generated"}, {"text": "古い家具の売買は、リサイクルショップが専門だ。", "target_word": "売買", "complexity_tier": "T3", "furigana": "古(ふる)い家具(かぐ)の売買(ばいばい)は、リサイクルショップが専門(せんもん)だ。", "sentence_source": "generated"}, {"text": "売買の話がまとまり、二人は握手をした。", "target_word": "売買", "complexity_tier": "T3", "furigana": "売買(ばいばい)の話(はなし)がまとまり、二人(ふたり)は握手(あくしゅ)をした。", "sentence_source": "generated"}, {"text": "友だちとの売買でも、お金のやりとりは記録しておく。", "target_word": "売買", "complexity_tier": "T3", "furigana": "友(とも)だちとの売買(ばいばい)でも、お金(かね)のやりとりは記録(きろく)しておく。", "sentence_source": "generated"}, {"text": "兄は中古車を売買する店で働いている。", "target_word": "売買", "complexity_tier": "T3", "furigana": "兄(あに)は中古車(ちゅうこしゃ)を売買(ばいばい)する店(みせ)で働(はたら)いている。", "sentence_source": "generated"}, {"text": "この市場では、牛の売買が昔から盛んだ。", "target_word": "売買", "complexity_tier": "T3", "furigana": "この市場(いちば)では、牛(うし)の売買(ばいばい)が昔(むかし)から盛(さか)んだ。", "sentence_source": "generated"}, {"text": "売買が成立したので、品物を相手に渡した。", "target_word": "売買", "complexity_tier": "T3", "furigana": "売買(ばいばい)が成立(せいりつ)したので、品物(しなもの)を相手(あいて)に渡(わた)した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売買", "label": "基本形"}, {"form": "売買する", "label": "する動詞"}], "register": "中立（日常的・普通体）", "sense_fingerprint": "身近な物を売ったり買ったりするやりとりそのもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38196, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "売買", "is_correct": true, "explanation": "「売買が行われる」は、物の売り買いという出来事を表し、文に合う。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目を表すので、「野菜や魚の色が行われる」とは言えない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は道具の名前で、「包丁が行われる」は意味が通らない。"}, {"text": "鮮度", "is_correct": false, "explanation": "鮮度は食べ物の新しさを表すので、「鮮度が行われる」とは言えない。"}], "explanations": {"売買": "「売買が行われる」は、物の売り買いという出来事を表し、文に合う。", "色": "色は見た目を表すので、「野菜や魚の色が行われる」とは言えない。", "包丁": "包丁は道具の名前で、「包丁が行われる」は意味が通らない。", "鮮度": "鮮度は食べ物の新しさを表すので、「鮮度が行われる」とは言えない。"}, "sentence_index": 0, "correct_answer": "売買"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "図書館の本は、一週間だけ売買できる。", "explanation": "ここは〈貸し借り〉の意味。売買は所有を相手に渡す取引で、期限付きで返す貸し借りには使わない。"}, {"text": "お金は払わず、お互いの切手を売買した。", "explanation": "ここは〈交換〉の意味。売買はお金で物を渡す取引なので、お金を払わない物のやりとりには使わない。"}, {"text": "代金は来月まとめて売買することになっている。", "explanation": "ここは〈支払い〉の意味。売買は物の取引そのもので、代金を払う行為は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38196, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "売買", "is_correct": true, "explanation": "「友だちとの売買」は、物のやりとりを指し、文の「お金のやりとり」と合う。"}, {"text": "外見", "is_correct": false, "explanation": "外見は見た目なので、「友だちとの外見でも、お金のやりとりは記録しておく」は意味が通らない。"}, {"text": "身長", "is_correct": false, "explanation": "身長は体の高さなので、お金のやりとりの話には合わない。"}, {"text": "性格", "is_correct": false, "explanation": "性格は人柄を表すので、「友だちとの性格」はお金の記録の話題に合わない。"}], "explanations": {"売買": "「友だちとの売買」は、物のやりとりを指し、文の「お金のやりとり」と合う。", "外見": "外見は見た目なので、「友だちとの外見でも、お金のやりとりは記録しておく」は意味が通らない。", "身長": "身長は体の高さなので、お金のやりとりの話には合わない。", "性格": "性格は人柄を表すので、「友だちとの性格」はお金の記録の話題に合わない。"}, "sentence_index": 6, "correct_answer": "売買"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このマンションは、毎月の家賃で売買している。", "explanation": "ここは〈賃貸〉の意味。売買は所有権を移す取引で、家賃を払って借りる契約には使わない。"}, {"text": "父は、読み終えた本を無料で売買した。", "explanation": "ここは〈譲渡〉の意味。売買は代金を払う取引なので、無料で渡す行為には使わない。"}, {"text": "祖父が亡くなり、家族は遺された家を代金を払わずに売買して受け継いだ。", "explanation": "ここは〈相続〉の意味。売買は代金を払う取引で、死後に財産を受け継ぐ場合には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38196, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中古車の売買を、名義変更の手続きが必要だ。", "corrected_sentence": "中古車の売買には、名義変更の手続きが必要だ。", "error_description": "誤った形は「売買を」、正しくは「売買には」。「必要だ」が求める対象は「には」で示すので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38196, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その売買が成長したので、代金を受け取った。", "corrected_sentence": "その売買が成立したので、代金を受け取った。", "error_description": "誤った形は「成長した」、正しくは「成立した」。売買は「成立する」ものなので、「成長」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38197, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38197, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「終わる」は自動詞なので、「売買が終わる」と主語に「が」を用いる。"}, {"text": "を", "is_correct": false, "explanation": "「終わる」は目的語を取らないので、「売買を終わる」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「売買へ終わる」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「売買より終わる」とは言えない。"}], "correct_answer": "が", "explanations": {"が": "「終わる」は自動詞なので、「売買が終わる」と主語に「が」を用いる。", "を": "「終わる」は目的語を取らないので、「売買を終わる」は不自然。", "へ": "「へ」は方向を示すので、「売買へ終わる」は成り立たない。", "より": "「より」は比較を示すので、「売買より終わる」とは言えない。"}, "error_tags": {"を": "目的語と誤解", "へ": "方向と誤解", "より": "比較と誤解"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38197, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "商品や財産などを、お金と交換して手に入れたり、他人に渡したりすること。", "primary_collocate": null, "pronunciation": "ばいばい", "ipa": "baibai", "syllable_count": 4, "sentences": [{"text": "不動産の売買では、契約書の内容をよく確認しなければならない。", "target_word": "売買", "complexity_tier": "T4", "furigana": "不動産(ふどうさん)の売買(ばいばい)では、契約書(けいやくしょ)の内容(ないよう)をよく確認(かくにん)しなければならない。", "sentence_source": "generated"}, {"text": "株式の売買は、証券会社を通じて行われる。", "target_word": "売買", "complexity_tier": "T4", "furigana": "株式(かぶしき)の売買(ばいばい)は、証券会社(しょうけんがいしゃ)を通(つう)じて行(おこな)われる。", "sentence_source": "generated"}, {"text": "美術品の売買には、専門家の鑑定が必要となる。", "target_word": "売買", "complexity_tier": "T4", "furigana": "美術品(びじゅつひん)の売買(ばいばい)には、専門家(せんもんか)の鑑定(かんてい)が必要(ひつよう)となる。", "sentence_source": "generated"}, {"text": "法律により、盗品の売買は固く禁じられている。", "target_word": "売買", "complexity_tier": "T4", "furigana": "法律(ほうりつ)により、盗品(とうひん)の売買(ばいばい)は固(かた)く禁(きん)じられている。", "sentence_source": "generated"}, {"text": "企業間の売買契約が成立し、商品が納入された。", "target_word": "売買", "complexity_tier": "T4", "furigana": "企業間(きぎょうかん)の売買(ばいばい)契約(けいやく)が成立(せいりつ)し、商品(しょうひん)が納入(のうにゅう)された。", "sentence_source": "generated"}, {"text": "売買の代金は、引き渡しの日までに支払うことになっている。", "target_word": "売買", "complexity_tier": "T4", "furigana": "売買(ばいばい)の代金(だいきん)は、引(ひ)き渡(わた)しの日(ひ)までに支払(しはら)うことになっている。", "sentence_source": "generated"}, {"text": "絶滅のおそれがある動物の売買は、国際条約で規制されている。", "target_word": "売買", "complexity_tier": "T4", "furigana": "絶滅(ぜつめつ)のおそれがある動物(どうぶつ)の売買(ばいばい)は、国際条約(こくさいじょうやく)で規制(きせい)されている。", "sentence_source": "generated"}, {"text": "土地の売買が終わると、所有者の名前が登記簿に書き換えられる。", "target_word": "売買", "complexity_tier": "T4", "furigana": "土地(とち)の売買(ばいばい)が終(お)わると、所有者(しょゆうしゃ)の名前(なまえ)が登記簿(とうきぼ)に書(か)き換(か)えられる。", "sentence_source": "generated"}, {"text": "個人間の売買でも、トラブルを防ぐために領収書を残すべきだ。", "target_word": "売買", "complexity_tier": "T4", "furigana": "個人間(こじんかん)の売買(ばいばい)でも、トラブルを防(ふせ)ぐために領収書(りょうしゅうしょ)を残(のこ)すべきだ。", "sentence_source": "generated"}, {"text": "売買によって得た利益には、税金がかかる。", "target_word": "売買", "complexity_tier": "T4", "furigana": "売買(ばいばい)によって得(え)た利益(りえき)には、税金(ぜいきん)がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売買", "label": "基本形"}, {"form": "売買する", "label": "する動詞"}], "register": "文章語（硬め・法律や経済の文脈）", "sense_fingerprint": "不動産・株式・契約など、財産や商品を対価と引き換えに移転する取引", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38197, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "売買", "is_correct": true, "explanation": "「不動産の売買では」は、財産の取引という場面を示し、契約書の確認と合う。"}, {"text": "郵便番号", "is_correct": false, "explanation": "郵便番号は住所を区分する番号で、「不動産の郵便番号では」は契約書の確認の話として意味が通らない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は空模様を表すので、契約書の確認の場面には合わない。"}, {"text": "築年数", "is_correct": false, "explanation": "築年数は建物の古さを表すので、「築年数では、契約書の内容を確認する」は意味が通らない。"}], "explanations": {"売買": "「不動産の売買では」は、財産の取引という場面を示し、契約書の確認と合う。", "郵便番号": "郵便番号は住所を区分する番号で、「不動産の郵便番号では」は契約書の確認の話として意味が通らない。", "天候": "天候は空模様を表すので、契約書の確認の場面には合わない。", "築年数": "築年数は建物の古さを表すので、「築年数では、契約書の内容を確認する」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "売買"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借金の売買として、所有する土地を差し出した。", "explanation": "ここは〈担保〉の意味。売買は代金と引き換えに所有を移す取引で、借金の保証には使わない。"}, {"text": "売買は契約期間ごとに見直される。", "explanation": "ここは〈賃料〉の意味。売買は一度きりの取引で、期間ごとに見直す仕組みはない。"}, {"text": "被災地へ売買すれば、税金の控除を受けられる。", "explanation": "ここは〈寄付〉の意味。売買は代金を払う取引で、無償で渡す寄付の控除対象とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38197, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "売買", "is_correct": true, "explanation": "「動物の売買」は物として動物を取引することを指し、規制の対象として文に合う。"}, {"text": "鳴き声", "is_correct": false, "explanation": "鳴き声は動物の声なので、「動物の鳴き声は国際条約で規制されている」は意味が通らない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は生きる期間を表すので、「動物の寿命は国際条約で規制されている」とは言えない。"}, {"text": "体毛", "is_correct": false, "explanation": "体毛は動物の体の毛で、国際条約による規制の対象にはならない。"}], "explanations": {"売買": "「動物の売買」は物として動物を取引することを指し、規制の対象として文に合う。", "鳴き声": "鳴き声は動物の声なので、「動物の鳴き声は国際条約で規制されている」は意味が通らない。", "寿命": "寿命は生きる期間を表すので、「動物の寿命は国際条約で規制されている」とは言えない。", "体毛": "体毛は動物の体の毛で、国際条約による規制の対象にはならない。"}, "sentence_index": 6, "correct_answer": "売買"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "銀行は、新しく店を開く人に売買した。", "explanation": "ここは〈融資〉の意味。売買は物を対価と引き換えに渡す取引で、お金を貸す行為には使わない。"}, {"text": "火災に備えて、建物に売買をかけた。", "explanation": "ここは〈保険〉の意味。売買は物の取引で、火災への備えとしてかける仕組みではない。"}, {"text": "会社は、働いた時間に応じて売買を払う。", "explanation": "ここは〈賃金〉の意味。売買は物の取引で、働いた対価として払うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38197, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "株式の売買へ、証券口座の開設が必要だ。", "corrected_sentence": "株式の売買には、証券口座の開設が必要だ。", "error_description": "誤った形は「売買へ」、正しくは「売買には」。「必要だ」が求める対象は「には」で示すので、「へ」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38197, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "土地の売買に成立すると、所有権が買い手に移る。", "corrected_sentence": "土地の売買が成立すると、所有権が買い手に移る。", "error_description": "誤った形は「売買に」、正しくは「売買が」。「成立する」の主語は「が」で示すので、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38198, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「魅力がある人」で、存在するものを示す「が」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「魅力をある人」では「ある」と結びつかず誤りです。"}, {"text": "へ", "is_correct": false, "explanation": "「魅力へある人」は方向の助詞が合わず誤りです。"}, {"text": "と", "is_correct": false, "explanation": "「魅力とある人」では「ある」に続けられず誤りです。"}], "correct_answer": "が", "explanations": {"が": "「魅力がある人」で、存在するものを示す「が」が入ります。", "を": "「魅力をある人」では「ある」と結びつかず誤りです。", "へ": "「魅力へある人」は方向の助詞が合わず誤りです。", "と": "「魅力とある人」では「ある」に続けられず誤りです。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "quotative_or_with"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38198, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「魅力を伝える」で、伝える対象を示す「を」が入ります。"}, {"text": "に", "is_correct": false, "explanation": "「魅力に伝える」では伝える対象を表せず誤りです。"}, {"text": "へ", "is_correct": false, "explanation": "「魅力へ伝える」は方向の助詞が合わず、対象を示せません。"}, {"text": "と", "is_correct": false, "explanation": "「魅力と伝える」では対象を示せず誤りです。"}], "correct_answer": "を", "explanations": {"を": "「魅力を伝える」で、伝える対象を示す「を」が入ります。", "に": "「魅力に伝える」では伝える対象を表せず誤りです。", "へ": "「魅力へ伝える」は方向の助詞が合わず、対象を示せません。", "と": "「魅力と伝える」では対象を示せず誤りです。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "quotative_or_with"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38198, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の心を引きつける力のことです。", "primary_collocate": null, "pronunciation": "みりょく", "ipa": "miɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "魅力がある。", "target_word": "魅力", "complexity_tier": "T1", "furigana": "魅力[みりょく]がある。", "sentence_source": "generated"}, {"text": "彼は魅力がある人です。", "target_word": "魅力", "complexity_tier": "T2", "furigana": "彼[かれ]は魅力[みりょく]がある人[ひと]です。", "sentence_source": "generated"}, {"text": "その歌手の魅力は声だ。", "target_word": "魅力", "complexity_tier": "T2", "furigana": "その歌手[かしゅ]の魅力[みりょく]は声[こえ]だ。", "sentence_source": "generated"}, {"text": "魅力を感じる人に会った。", "target_word": "魅力", "complexity_tier": "T2", "furigana": "魅力[みりょく]を感[かん]じる人[ひと]に会[あ]った。", "sentence_source": "generated"}, {"text": "年を取ると、新しい魅力が出てくる。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "年[とし]を取[と]ると、新[あたら]しい魅力[みりょく]が出[で]てくる。", "sentence_source": "generated"}, {"text": "この絵には、人を引きつける魅力があります。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "この絵[え]には、人[ひと]を引[ひ]きつける魅力[みりょく]があります。", "sentence_source": "generated"}, {"text": "魅力に負けて、つい買ってしまった。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "魅力[みりょく]に負[ま]けて、つい買[か]ってしまった。", "sentence_source": "generated"}, {"text": "魅力を伝えるには、まず自分が好きになることだ。", "target_word": "魅力", "complexity_tier": "T4", "furigana": "魅力[みりょく]を伝[つた]えるには、まず自分[じぶん]が好[す]きになることだ。", "sentence_source": "generated"}, {"text": "彼女の魅力に気づいたのは、一緒に働き始めてからだった。", "target_word": "魅力", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の魅力[みりょく]に気[き]づいたのは、一緒[いっしょ]に働[はたら]き始[はじ]めてからだった。", "sentence_source": "generated"}, {"text": "派手さはないが、この小さな店には人の心をつかんで離さない魅力がある。", "target_word": "魅力", "complexity_tier": "T5", "furigana": "派手[はで]さはないが、この小[ちい]さな店[みせ]には人[ひと]の心[こころ]をつかんで離[はな]さない魅力[みりょく]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "魅力的", "label": "派生"}, {"form": "魅力的な", "label": "活用"}, {"form": "魅力的に", "label": "活用"}, {"form": "魅力的だ", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 人の心を引きつける力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38198, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "魅力", "is_correct": true, "explanation": "見出し語の「みりょく」そのものです。"}, {"text": "気力", "is_correct": false, "explanation": "「きりょく」で、最初の一音だけが違う別の語です。"}, {"text": "視力", "is_correct": false, "explanation": "「しりょく」で、最初の一音だけが違う別の語です。"}, {"text": "微力", "is_correct": false, "explanation": "「びりょく」で、最初の一音（み→び）だけが違う別の語です。"}, {"text": "魅了", "is_correct": false, "explanation": "「みりょう」で、最後の一音だけが違う別の語です。"}], "explanations": {"魅力": "見出し語の「みりょく」そのものです。", "気力": "「きりょく」で、最初の一音だけが違う別の語です。", "視力": "「しりょく」で、最初の一音だけが違う別の語です。", "微力": "「びりょく」で、最初の一音（み→び）だけが違う別の語です。", "魅了": "「みりょう」で、最後の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "魅力"}, "level_3": {"options": [{"text": "魅力", "is_correct": true, "explanation": "「魅力がある」で、人を引きつける力があるという意味になります。"}, {"text": "昨日", "is_correct": false, "explanation": "形は合うが意味が合わない。「昨日がある」は不自然です。"}, {"text": "午後", "is_correct": false, "explanation": "形は合うが意味が合わない。「午後がある」だけでは文意が通りません。"}, {"text": "以前", "is_correct": false, "explanation": "形は合うが意味が合わない。「以前がある」は不自然です。"}], "explanations": {"魅力": "「魅力がある」で、人を引きつける力があるという意味になります。", "昨日": "形は合うが意味が合わない。「昨日がある」は不自然です。", "午後": "形は合うが意味が合わない。「午後がある」だけでは文意が通りません。", "以前": "形は合うが意味が合わない。「以前がある」は不自然です。"}, "sentence_index": 0, "correct_answer": "魅力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "魅力を切るために、はさみを使った。", "explanation": "「魅力」は性質で、はさみで切れる物ではありません。"}, {"text": "魅力は電車に乗って、東京へ行きました。", "explanation": "「魅力」は人のように電車に乗って移動するものではありません。"}, {"text": "魅力を食べて、とても甘かった。", "explanation": "「魅力」は食べ物ではなく、味もありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38198, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "魅力", "is_correct": true, "explanation": "見出し語の「みりょく」そのものです。"}, {"text": "火力", "is_correct": false, "explanation": "「かりょく」で、最初の一音だけが違う別の語です。"}, {"text": "魔力", "is_correct": false, "explanation": "「まりょく」で、最初の一音だけが違う別の語です。"}, {"text": "威力", "is_correct": false, "explanation": "「いりょく」で、最初の一音だけが違う別の語です。"}, {"text": "地力", "is_correct": false, "explanation": "「ちりょく」で、最初の一音だけが違う別の語です。"}], "explanations": {"魅力": "見出し語の「みりょく」そのものです。", "火力": "「かりょく」で、最初の一音だけが違う別の語です。", "魔力": "「まりょく」で、最初の一音だけが違う別の語です。", "威力": "「いりょく」で、最初の一音だけが違う別の語です。", "地力": "「ちりょく」で、最初の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "魅力"}, "level_3": {"options": [{"text": "魅力", "is_correct": true, "explanation": "「魅力に負けて買う」で、引きつける力に負けるという意味になります。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気に負けて物を買うのは不自然です。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。「野菜に負ける」は意味が通りません。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。「机に負ける」は意味が通りません。"}], "explanations": {"魅力": "「魅力に負けて買う」で、引きつける力に負けるという意味になります。", "天気": "形は合うが意味が合わない。天気に負けて物を買うのは不自然です。", "野菜": "形は合うが意味が合わない。「野菜に負ける」は意味が通りません。", "机": "形は合うが意味が合わない。「机に負ける」は意味が通りません。"}, "sentence_index": 6, "correct_answer": "魅力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "魅力を着て、寒い外へ出かけた。", "explanation": "「魅力」は服ではないので、「着る」の対象になりません。"}, {"text": "魅力が走って、犬を追いかけた。", "explanation": "「魅力」は性質で、走る主体にはなれません。"}, {"text": "魅力の重さは三キロで、箱に入れて送った。", "explanation": "「魅力」は重さを量って箱に入れられる物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
