INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38198, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "魅力を気づいたのは、最近だ。", "corrected_sentence": "魅力に気づいたのは、最近だ。", "error_description": "「気づく」の対象は「を」ではなく「に」で表します。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38199, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「魅力があります」で、存在するものを示す「が」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「魅力をあります」では「ある」と結びつかず誤りです。"}, {"text": "へ", "is_correct": false, "explanation": "「魅力へあります」は方向を表す助詞が合わず、文になりません。"}, {"text": "から", "is_correct": false, "explanation": "「魅力からあります」は起点の意味が合わず不自然です。"}], "correct_answer": "が", "explanations": {"が": "「魅力があります」で、存在するものを示す「が」が入ります。", "を": "「魅力をあります」では「ある」と結びつかず誤りです。", "へ": "「魅力へあります」は方向を表す助詞が合わず、文になりません。", "から": "「魅力からあります」は起点の意味が合わず不自然です。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38199, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「魅力のない商品」で、名詞を修飾する「の」が入ります。"}, {"text": "を", "is_correct": false, "explanation": "「魅力をない」では「ない」に続けられません。"}, {"text": "に", "is_correct": false, "explanation": "「魅力にない商品」は修飾として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「魅力へない」は方向の助詞が合わず誤りです。"}], "correct_answer": "の", "explanations": {"の": "「魅力のない商品」で、名詞を修飾する「の」が入ります。", "を": "「魅力をない」では「ない」に続けられません。", "に": "「魅力にない商品」は修飾として成り立ちません。", "へ": "「魅力へない」は方向の助詞が合わず誤りです。"}, "error_tags": {"を": "object_marker", "に": "target_marker", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38199, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人や物事に強く惹かれる性質や、価値があると感じさせる要素。", "primary_collocate": null, "pronunciation": "みりょく", "ipa": "miɾʲokɯ", "syllable_count": 3, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "魅力", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "この町には魅力があります。", "target_word": "魅力", "complexity_tier": "T2", "furigana": "この町[まち]には魅力[みりょく]があります。", "sentence_source": "generated"}, {"text": "彼女の魅力は、明るい笑顔だ。", "target_word": "魅力", "complexity_tier": "T2", "furigana": "彼女[かのじょ]の魅力[みりょく]は、明[あか]るい笑顔[えがお]だ。", "sentence_source": "generated"}, {"text": "魅力を感じて、この店に通っている。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "魅力[みりょく]を感[かん]じて、この店[みせ]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "本の魅力を友達に伝えたい。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "本[ほん]の魅力[みりょく]を友達[ともだち]に伝[つた]えたい。", "sentence_source": "generated"}, {"text": "彼にはたくさんの魅力がある。", "target_word": "魅力", "complexity_tier": "T2", "furigana": "彼[かれ]にはたくさんの魅力[みりょく]がある。", "sentence_source": "generated"}, {"text": "この仕事の魅力は、人の役に立てることだ。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "この仕事[しごと]の魅力[みりょく]は、人[ひと]の役[やく]に立[た]てることだ。", "sentence_source": "generated"}, {"text": "魅力のない商品は、すぐに売れなくなる。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "魅力[みりょく]のない商品[しょうひん]は、すぐに売[う]れなくなる。", "sentence_source": "generated"}, {"text": "魅力を引き出すために、新しい服を着てみた。", "target_word": "魅力", "complexity_tier": "T3", "furigana": "魅力[みりょく]を引[ひ]き出[だ]すために、新[あたら]しい服[ふく]を着[き]てみた。", "sentence_source": "generated"}, {"text": "京都の魅力は、古い街並みと四季の美しさにあると言われている。", "target_word": "魅力", "complexity_tier": "T5", "furigana": "京都[きょうと]の魅力[みりょく]は、古[ふる]い街並[まちな]みと四季[しき]の美[うつく]しさにあると言[い]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "魅力的", "label": "派生"}, {"form": "魅力的な", "label": "活用"}, {"form": "魅力的に", "label": "活用"}, {"form": "魅力的だ", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 強く惹かれる性質や価値ある要素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db2de57a-18ef-4f7c-9bcb-060880e83e4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38199, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "魅力", "is_correct": true, "explanation": "見出し語の「みりょく」そのものです。"}, {"text": "気力", "is_correct": false, "explanation": "「きりょく」で、最初の一音だけが違う別の語です。"}, {"text": "視力", "is_correct": false, "explanation": "「しりょく」で、最初の一音だけが違う別の語です。"}, {"text": "微力", "is_correct": false, "explanation": "「びりょく」で、最初の一音（み→び）だけが違う別の語です。"}, {"text": "魅了", "is_correct": false, "explanation": "「みりょう」で、最後の一音だけが違う別の語です。"}], "explanations": {"魅力": "見出し語の「みりょく」そのものです。", "気力": "「きりょく」で、最初の一音だけが違う別の語です。", "視力": "「しりょく」で、最初の一音だけが違う別の語です。", "微力": "「びりょく」で、最初の一音（み→び）だけが違う別の語です。", "魅了": "「みりょう」で、最後の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "魅力"}, "level_3": {"options": [{"text": "魅力", "is_correct": true, "explanation": "「商品の魅力を伝える」で、商品の惹かれる点を表し、文意に合います。"}, {"text": "悲しみ", "is_correct": false, "explanation": "形は合うが意味が合わない。商品を宣伝する文脈に合いません。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが意味が合わない。写真で商品の眠気を伝えることはできません。"}, {"text": "寒さ", "is_correct": false, "explanation": "形は合うが意味が合わない。商品を売る文脈に合いません。"}], "explanations": {"魅力": "「商品の魅力を伝える」で、商品の惹かれる点を表し、文意に合います。", "悲しみ": "形は合うが意味が合わない。商品を宣伝する文脈に合いません。", "眠気": "形は合うが意味が合わない。写真で商品の眠気を伝えることはできません。", "寒さ": "形は合うが意味が合わない。商品を売る文脈に合いません。"}, "sentence_index": 0, "correct_answer": "魅力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "魅力を食べて、お腹がいっぱいになった。", "explanation": "「魅力」は性質を表す語で、食べるものではありません。"}, {"text": "この町の魅力は三メートルの高さで、とても重い。", "explanation": "「魅力」は抽象的な性質で、高さや重さを持つ物ではありません。"}, {"text": "この魅力はとても冷たくて、雪の上に落ちた。", "explanation": "「魅力」は物のように落ちたり冷たかったりしません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38199, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "魅力", "is_correct": true, "explanation": "見出し語の「みりょく」そのものです。"}, {"text": "火力", "is_correct": false, "explanation": "「かりょく」で、最初の一音だけが違う別の語です。"}, {"text": "魔力", "is_correct": false, "explanation": "「まりょく」で、最初の一音だけが違う別の語です。"}, {"text": "威力", "is_correct": false, "explanation": "「いりょく」で、最初の一音だけが違う別の語です。"}, {"text": "地力", "is_correct": false, "explanation": "「ちりょく」で、最初の一音だけが違う別の語です。"}], "explanations": {"魅力": "見出し語の「みりょく」そのものです。", "火力": "「かりょく」で、最初の一音だけが違う別の語です。", "魔力": "「まりょく」で、最初の一音だけが違う別の語です。", "威力": "「いりょく」で、最初の一音だけが違う別の語です。", "地力": "「ちりょく」で、最初の一音だけが違う別の語です。"}, "sentence_index": null, "correct_answer": "魅力"}, "level_3": {"options": [{"text": "魅力", "is_correct": true, "explanation": "「仕事の魅力は…ことだ」で、仕事の惹かれる点を表します。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが意味が合わない。「役に立てること」が重さだとは言えません。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。仕事と天気は結びつきません。"}, {"text": "給料", "is_correct": false, "explanation": "形は合うが意味が合わない。給料が「人の役に立てること」だとは言えません。"}], "explanations": {"魅力": "「仕事の魅力は…ことだ」で、仕事の惹かれる点を表します。", "重さ": "形は合うが意味が合わない。「役に立てること」が重さだとは言えません。", "天気": "形は合うが意味が合わない。仕事と天気は結びつきません。", "給料": "形は合うが意味が合わない。給料が「人の役に立てること」だとは言えません。"}, "sentence_index": 6, "correct_answer": "魅力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "魅力を洗って、庭に干しておいた。", "explanation": "「魅力」は性質で、洗って干せる物ではありません。"}, {"text": "魅力を買うために、スーパーまで二十分歩いた。", "explanation": "「魅力」は店で買える物ではないので、「買う」の対象になりません。"}, {"text": "魅力が降って、道が濡れてしまった。", "explanation": "「魅力」は雨のように降るものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38199, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店には魅力をあります。", "corrected_sentence": "この店には魅力があります。", "error_description": "「ある」は存在するものを「が」で表します。「を」は使えません。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38199, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町の魅力に、人の優しさにある。", "corrected_sentence": "この町の魅力は、人の優しさにある。", "error_description": "「魅力」の後は主題を示す「は」が正しく、「に」では文が成り立ちません。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98925828-1aa0-4148-bf34-7629adb402bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
