INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38202, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "地面や、ものが育つ場所。", "primary_collocate": null, "pronunciation": "とち", "ipa": "totɕi", "syllable_count": 2, "sentences": [{"text": "この土地は栄養が豊かなので、どんな作物もよく育つ。", "target_word": "土地", "complexity_tier": "T3", "furigana": "この土地(とち)は栄養(えいよう)が豊(ゆた)かなので、どんな作物(さくもつ)もよく育(そだ)つ。", "sentence_source": "generated"}, {"text": "砂ばかりの土地では、木はなかなか根を張れない。", "target_word": "土地", "complexity_tier": "T3", "furigana": "砂(すな)ばかりの土地(とち)では、木(き)はなかなか根(ね)を張(は)れない。", "sentence_source": "generated"}, {"text": "寒い土地でも育つ麦を、研究者たちが開発した。", "target_word": "土地", "complexity_tier": "T4", "furigana": "寒(さむ)い土地(とち)でも育(そだ)つ麦(むぎ)を、研究者(けんきゅうしゃ)たちが開発(かいはつ)した。", "sentence_source": "generated"}, {"text": "雨が続いたせいで、土地がぬかるんで歩きにくい。", "target_word": "土地", "complexity_tier": "T3", "furigana": "雨(あめ)が続(つづ)いたせいで、土地(とち)がぬかるんで歩(ある)きにくい。", "sentence_source": "generated"}, {"text": "肥料をまいて、やせた土地を元気にする。", "target_word": "土地", "complexity_tier": "T3", "furigana": "肥料(ひりょう)をまいて、やせた土地(とち)を元気(げんき)にする。", "sentence_source": "generated"}, {"text": "みかんは、暖かくて日当たりのよい土地でよく実る。", "target_word": "土地", "complexity_tier": "T3", "furigana": "みかんは、暖(あたた)かくて日当(ひあ)たりのよい土地(とち)でよく実(みの)る。", "sentence_source": "generated"}, {"text": "火山のふもとの土地には、黒くて柔らかい土が広がっている。", "target_word": "土地", "complexity_tier": "T4", "furigana": "火山(かざん)のふもとの土地(とち)には、黒(くろ)くて柔(やわ)らかい土(つち)が広(ひろ)がっている。", "sentence_source": "generated"}, {"text": "塩分の多い土地では、ふつうの野菜は育たない。", "target_word": "土地", "complexity_tier": "T4", "furigana": "塩分(えんぶん)の多(おお)い土地(とち)では、ふつうの野菜(やさい)は育(そだ)たない。", "sentence_source": "generated"}, {"text": "その土地に合った花を選ぶと、手入れが楽になる。", "target_word": "土地", "complexity_tier": "T3", "furigana": "その土地(とち)に合(あ)った花(はな)を選(えら)ぶと、手入(ていれ)れが楽(らく)になる。", "sentence_source": "generated"}, {"text": "水はけのよい土地を選んで、ぶどうの木を植えた。", "target_word": "土地", "complexity_tier": "T3", "furigana": "水(みず)はけのよい土地(とち)を選(えら)んで、ぶどうの木(き)を植(う)えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "土地柄", "label": "複合名詞"}, {"form": "土地勘", "label": "複合名詞"}, {"form": "土地的", "label": "形容動詞的な派生形"}], "register": "neutral", "sense_fingerprint": "植物が育つ地面・土のある場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ぬかるん (Zipf 2.26)','sentence 9 above tier T2: contains vocabulary far above tier T2: 水はけ (Zipf 2.43)']::text[], '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38202, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "作物がよく育つ地面を指す語で、栄養が豊かという文に合う。"}, {"text": "空気", "is_correct": false, "explanation": "空気に栄養が豊かという言い方は合わず、作物の育つ地面の話と合わない。"}, {"text": "花", "is_correct": false, "explanation": "花は作物が育つ地面を指さず、「栄養が豊か」の主語として不自然。"}, {"text": "石", "is_correct": false, "explanation": "石に栄養が豊かという言い方は成り立たず、文脈と合わない。"}], "explanations": {"土地": "作物がよく育つ地面を指す語で、栄養が豊かという文に合う。", "空気": "空気に栄養が豊かという言い方は合わず、作物の育つ地面の話と合わない。", "花": "花は作物が育つ地面を指さず、「栄養が豊か」の主語として不自然。", "石": "石に栄養が豊かという言い方は成り立たず、文脈と合わない。"}, "sentence_index": 0, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この車は土地が速く、燃費もよい。", "explanation": "ここは〈速さ〉の意味。土地は地面を指すので、車の速度を表す語としては使わない。"}, {"text": "この部屋の土地は暖かく、ソファが置いてある。", "explanation": "ここは〈部屋〉の意味。土地は地面を指すので、室内の状態には使わない。"}, {"text": "この薬は土地が強く、子どもにも使える。", "explanation": "ここは〈効き目〉の意味。土地は地面を指すので、薬の作用の強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38202, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "黒くて柔らかい土が広がる地面を指し、火山のふもとの文に合う。"}, {"text": "机", "is_correct": false, "explanation": "机に土が広がるという文は成り立たず、ふもとの地面の話と合わない。"}, {"text": "川", "is_correct": false, "explanation": "川に土が広がるという言い方は合わず、ふもとの地面の話と合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲に土が広がるという文は意味が通らない。"}], "explanations": {"土地": "黒くて柔らかい土が広がる地面を指し、火山のふもとの文に合う。", "机": "机に土が広がるという文は成り立たず、ふもとの地面の話と合わない。", "川": "川に土が広がるという言い方は合わず、ふもとの地面の話と合わない。", "雲": "雲に土が広がるという文は意味が通らない。"}, "sentence_index": 6, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この野菜は土地が多く、みずみずしい。", "explanation": "ここは〈水分〉の意味。土地は地面の区画で、野菜の含む水の量は表さない。"}, {"text": "会議で土地が盛り上がった。", "explanation": "ここは〈話題〉の意味。土地は地面や場所を指すので、話し合いの内容には使わない。"}, {"text": "この花は土地が鮮やかだ。", "explanation": "ここは〈色〉の意味。土地は地面を指すので、花の色の鮮やかさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38202, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乾いた土地が育つ豆を、研究者たちが開発した。", "corrected_sentence": "乾いた土地でも育つ豆を、研究者たちが開発した。", "error_description": "誤りは「土地が」。育つのは豆なので、場所は「でも」で示す。「が」では土地が育つ主体になり、意味が合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38202, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この草は、湿った土地を生える。", "corrected_sentence": "この草は、湿った土地に生える。", "error_description": "誤りは「土地を」。「生える」は場所を「に」で示す自動詞なので、「を」では成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38203, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「買う」は対象に「を」をとる。「土地を買って」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」では買う対象にならず、「土地に買って」は文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、買う対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、買う対象としては使えない。"}], "correct_answer": "を", "explanations": {"を": "「買う」は対象に「を」をとる。「土地を買って」が正しい。", "に": "「に」では買う対象にならず、「土地に買って」は文が成り立たない。", "が": "「が」は主語を示すので、買う対象にはならない。", "へ": "「へ」は方向を示すので、買う対象としては使えない。"}, "error_tags": {"に": "indirect_target", "が": "subject_marker", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38203, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「耕す」は対象に「を」をとる。「土地を何日もかけて耕した」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、耕す対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、耕す対象としては使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、耕す対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「耕す」は対象に「を」をとる。「土地を何日もかけて耕した」が正しい。", "が": "「が」は主語を示すので、耕す対象にはならない。", "へ": "「へ」は方向を示すので、耕す対象としては使えない。", "と": "「と」は並列や相手を示し、耕す対象にはならない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "と": "coordinate"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38203, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間が活動したり、建物を建てたり、作物を育てたりするのに使われる、地表の部分。", "primary_collocate": null, "pronunciation": "とち", "ipa": "totɕi", "syllable_count": 2, "sentences": [{"text": "工場を建てるため、広い土地を探している。", "target_word": "土地", "complexity_tier": "T3", "furigana": "工場(こうじょう)を建(た)てるため、広(ひろ)い土地(とち)を探(さが)している。", "sentence_source": "generated"}, {"text": "父は郊外に土地を買って、小さな家を建てるつもりだ。", "target_word": "土地", "complexity_tier": "T3", "furigana": "父(ちち)は郊外(こうがい)に土地(とち)を買(か)って、小(ちい)さな家(いえ)を建(た)てるつもりだ。", "sentence_source": "generated"}, {"text": "この土地は雨が少なく、野菜を育てるのには向いていない。", "target_word": "土地", "complexity_tier": "T3", "furigana": "この土地(とち)は雨(あめ)が少(すく)なく、野菜(やさい)を育(そだ)てるのには向(む)いていない。", "sentence_source": "generated"}, {"text": "祖父は広い土地を持っていて、毎年米を作っている。", "target_word": "土地", "complexity_tier": "T3", "furigana": "祖父(そふ)は広(ひろ)い土地(とち)を持(も)っていて、毎年(まいとし)米(こめ)を作(つく)っている。", "sentence_source": "generated"}, {"text": "駅に近い土地は値段が高いので、なかなか買えない。", "target_word": "土地", "complexity_tier": "T3", "furigana": "駅(えき)に近(ちか)い土地(とち)は値段(ねだん)が高(たか)いので、なかなか買(か)えない。", "sentence_source": "generated"}, {"text": "川の近くの土地は、大雨のときに水が来る心配がある。", "target_word": "土地", "complexity_tier": "T4", "furigana": "川(かわ)の近(ちか)くの土地(とち)は、大雨(おおあめ)のときに水(みず)が来(く)る心配(しんぱい)がある。", "sentence_source": "generated"}, {"text": "市は使われていない土地を公園にすることを決めた。", "target_word": "土地", "complexity_tier": "T3", "furigana": "市(し)は使(つか)われていない土地(とち)を公園(こうえん)にすることを決(き)めた。", "sentence_source": "generated"}, {"text": "畑にするために、固い土地を何日もかけて耕した。", "target_word": "土地", "complexity_tier": "T4", "furigana": "畑(はたけ)にするために、固(かた)い土地(とち)を何日(なんにち)もかけて耕(たがや)した。", "sentence_source": "generated"}, {"text": "土地の広さに合わせて、建てられる家の大きさが決まる。", "target_word": "土地", "complexity_tier": "T4", "furigana": "土地(とち)の広(ひろ)さに合(あ)わせて、建(た)てられる家(いえ)の大(おお)きさが決(き)まる。", "sentence_source": "generated"}, {"text": "彼は土地を貸して、毎月お金をもらっている。", "target_word": "土地", "complexity_tier": "T3", "furigana": "彼(かれ)は土地(とち)を貸(か)して、毎月(まいつき)お金(かね)をもらっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "土地柄", "label": "複合名詞"}, {"form": "土地勘", "label": "複合名詞"}, {"form": "土地的", "label": "形容動詞的な派生形"}], "register": "neutral", "sense_fingerprint": "建築・耕作など人が利用する地面の区画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38203, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "建物を建てるための地表の区画を指し、広い土地を探す文に合う。"}, {"text": "機械", "is_correct": false, "explanation": "機械は建てる場所ではなく、探す対象として文脈に合わない。"}, {"text": "楽器", "is_correct": false, "explanation": "工場を建てる文脈で楽器を探すのは合わない。"}, {"text": "書類", "is_correct": false, "explanation": "工場を建てる文脈で書類を探すのは合わない。"}], "explanations": {"土地": "建物を建てるための地表の区画を指し、広い土地を探す文に合う。", "機械": "機械は建てる場所ではなく、探す対象として文脈に合わない。", "楽器": "工場を建てる文脈で楽器を探すのは合わない。", "書類": "工場を建てる文脈で書類を探すのは合わない。"}, "sentence_index": 0, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は土地が濃く、舌がしびれるほどだ。", "explanation": "ここは〈味〉の意味。土地は地面や区画を指すので、料理の味の濃さには使わない。"}, {"text": "今日は土地が上がって、とても暑い。", "explanation": "ここは〈気温〉の意味。土地は地面を指すので、気温の上昇には使わない。"}, {"text": "この授業は土地が長く、疲れた。", "explanation": "ここは〈長さ〉の意味。土地は地表の区画を指すので、時間の長さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38203, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "使われていない区画を公園にする文脈に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙を公園にするという文は成り立たず、文脈に合わない。"}, {"text": "電話", "is_correct": false, "explanation": "電話を公園にするという文は意味が通らない。"}, {"text": "料理", "is_correct": false, "explanation": "料理を公園にするという文は成り立たず、文脈と合わない。"}], "explanations": {"土地": "使われていない区画を公園にする文脈に合う。", "手紙": "手紙を公園にするという文は成り立たず、文脈に合わない。", "電話": "電話を公園にするという文は意味が通らない。", "料理": "料理を公園にするという文は成り立たず、文脈と合わない。"}, "sentence_index": 6, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋の土地が広く、家具がよく入る。", "explanation": "ここは〈部屋〉の意味。土地は建物を建てる地面の区画で、室内の広さには使わない。"}, {"text": "私はこのお店で土地を注文した。", "explanation": "ここは〈料理〉の意味。土地は地面や区画を指すので、注文できる品には使わない。"}, {"text": "彼は性格の土地が優しい。", "explanation": "ここは〈性格〉の意味。土地は場所の区画で、人の気質を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38203, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、広い土地を米を作っている。", "corrected_sentence": "祖父は、広い土地で米を作っている。", "error_description": "誤りは「土地を」。「作る」の場所は「で」で示す。「を」にすると「米を」と目的語が二つになり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38203, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この土地が家を建てた。", "corrected_sentence": "この土地に家を建てた。", "error_description": "誤りは「土地が」。「建てる」の場所は「に」で示す。「が」では土地が建てる主体になり、意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
