INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38205, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とれたてで、品質が良く、腐っていないこと", "primary_collocate": null, "pronunciation": "しんせん", "ipa": "ɕinseɴ", "syllable_count": 4, "sentences": [{"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "新鮮", "complexity_tier": "T4", "furigana": "この時間帯[じかんたい]に与[あた]える食[た]べ物[もの]は、地元[じもと]で採[と]れた新鮮[しんせん]な穀物[こくもつ]と野菜[やさい]を混[ま]ぜ合[あ]わせたものだ。", "sentence_source": "mined"}, {"text": "朝市で買った魚は新鮮で、刺身にしておいしく食べた。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "朝市[あさいち]で買[か]った魚[さかな]は新鮮[しんせん]で、刺身[さしみ]にしておいしく食[た]べた。", "sentence_source": "generated"}, {"text": "この野菜は畑から届いたばかりで、とても新鮮だ。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "この野菜[やさい]は畑[はたけ]から届[とど]いたばかりで、とても新鮮[しんせん]だ。", "sentence_source": "generated"}, {"text": "新鮮な果物は、皮にはりがあって香りも強い。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "新鮮[しんせん]な果物[くだもの]は、皮[かわ]にはりがあって香[かお]りも強[つよ]い。", "sentence_source": "generated"}, {"text": "肉が新鮮かどうかは、色とにおいを見ればわかる。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "肉[にく]が新鮮[しんせん]かどうかは、色[いろ]とにおいを見[み]ればわかる。", "sentence_source": "generated"}, {"text": "冷蔵庫に入れなかったので、牛乳はもう新鮮ではなかった。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]に入[い]れなかったので、牛乳[ぎゅうにゅう]はもう新鮮[しんせん]ではなかった。", "sentence_source": "generated"}, {"text": "港の近くの店は、新鮮な貝を安く出してくれる。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "港[みなと]の近[ちか]くの店[みせ]は、新鮮[しんせん]な貝[かい]を安[やす]く出[だ]してくれる。", "sentence_source": "generated"}, {"text": "魚は新鮮なうちに食べたいので、買ってすぐ家に帰った。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "魚[さかな]は新鮮[しんせん]なうちに食[た]べたいので、買[か]ってすぐ家[いえ]に帰[かえ]った。", "sentence_source": "generated"}, {"text": "海から遠い町なので、新鮮な魚はなかなか手に入らない。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "海[うみ]から遠[とお]い町[まち]なので、新鮮[しんせん]な魚[さかな]はなかなか手[て]に入[はい]らない。", "sentence_source": "generated"}, {"text": "新鮮な牛乳は、そのまま飲んでも甘くておいしい。", "target_word": "新鮮", "complexity_tier": "T3", "furigana": "新鮮[しんせん]な牛乳[ぎゅうにゅう]は、そのまま飲[の]んでも甘[あま]くておいしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "新鮮だ", "label": "終止形"}, {"form": "新鮮な", "label": "連体形"}, {"form": "新鮮で", "label": "連用形"}, {"form": "新鮮だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "魚・野菜・卵などの食品が、とれたてで傷んでいない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38205, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新鮮", "is_correct": true, "explanation": "採れたてで質の良い穀物の状態を表し、この文の意味に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "人の性格を表す語で、穀物の状態には使わない。"}, {"text": "静か", "is_correct": false, "explanation": "穏やかな様子を表すので、穀物の状態の説明にならない。"}, {"text": "冷静", "is_correct": false, "explanation": "人の判断や態度を表すので、穀物には使わない。"}], "explanations": {"新鮮": "採れたてで質の良い穀物の状態を表し、この文の意味に合う。", "陽気": "人の性格を表す語で、穀物の状態には使わない。", "静か": "穏やかな様子を表すので、穀物の状態の説明にならない。", "冷静": "人の判断や態度を表すので、穀物には使わない。"}, "sentence_index": 0, "correct_answer": "新鮮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新鮮なお湯で、足をゆっくり温めた。", "explanation": "ここは〈温かい〉の意味。新鮮はとれたての食べ物の状態を表すので、お湯の温かさには使わない。"}, {"text": "新鮮なスマホを買ってから、毎日ずっと使っている。", "explanation": "ここは〈新品〉の意味。新鮮は食べ物の状態を表すので、機械には使わない。"}, {"text": "新鮮な体を保つために、毎日よく眠る。", "explanation": "ここは〈健康〉の意味。新鮮は食べ物の状態を表すので、体の状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38205, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新鮮", "is_correct": true, "explanation": "とれたてで質の良い貝の状態を表し、この文の意味に合う。"}, {"text": "大胆", "is_correct": false, "explanation": "人の行動や性格を表す語で、貝の説明にならない。"}, {"text": "穏やか", "is_correct": false, "explanation": "人や様子を表す語で、貝の状態には使わない。"}, {"text": "不器用", "is_correct": false, "explanation": "人の動作を表す語で、貝には使わない。"}], "explanations": {"新鮮": "とれたてで質の良い貝の状態を表し、この文の意味に合う。", "大胆": "人の行動や性格を表す語で、貝の説明にならない。", "穏やか": "人や様子を表す語で、貝の状態には使わない。", "不器用": "人の動作を表す語で、貝には使わない。"}, "sentence_index": 6, "correct_answer": "新鮮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新鮮なタオルで、手をよく拭いた。", "explanation": "ここは〈汚れがない〉の意味。新鮮はとれたての食べ物の状態を表すので、タオルの清潔さには使わない。"}, {"text": "新鮮な宝石を買って、母にプレゼントした。", "explanation": "ここは〈高価な〉の意味。新鮮は食べ物の状態を表すので、宝石の値打ちには使わない。"}, {"text": "新鮮な靴で、山道を三時間歩いた。", "explanation": "ここは〈丈夫な〉の意味。新鮮は食べ物の状態を表すので、靴の丈夫さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38205, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市場で新鮮の魚を買い、その日のうちに料理した。", "corrected_sentence": "市場で新鮮な魚を買い、その日のうちに料理した。", "error_description": "形状詞を名詞につなぐ「な」が「の」になっている。「新鮮な魚」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "新鮮で", "is_correct": true, "explanation": "連用形で、後ろに「刺身にして」「おいしく」と続けられる。"}, {"text": "新鮮だ", "is_correct": false, "explanation": "終止形は文を言い切るので、「〜で、」と続けられない。"}, {"text": "新鮮な", "is_correct": false, "explanation": "連体形は名詞につくので、「魚は」の述語にはならない。"}, {"text": "新鮮だった", "is_correct": false, "explanation": "過去形は文末に使うので、「で、」と続く形にはならない。"}], "correct_form": "新鮮で", "base_form": "新鮮だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"新鮮で": "連用形で、後ろに「刺身にして」「おいしく」と続けられる。", "新鮮だ": "終止形は文を言い切るので、「〜で、」と続けられない。", "新鮮な": "連体形は名詞につくので、「魚は」の述語にはならない。", "新鮮だった": "過去形は文末に使うので、「で、」と続く形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38205, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市場で買った野菜は、とても新鮮ではった。", "corrected_sentence": "市場で買った野菜は、とても新鮮だった。", "error_description": "「新鮮」に続く「だった」が「ではった」になっていて活用が誤り。「新鮮だった」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "新鮮な", "is_correct": true, "explanation": "連体形で、「うち」という名詞を修飾する形。"}, {"text": "新鮮に", "is_correct": false, "explanation": "連用形で、名詞の「うち」を修飾できない。"}, {"text": "新鮮だ", "is_correct": false, "explanation": "終止形で、名詞「うち」を修飾できず、「新鮮だうちに」は成り立たない。"}, {"text": "新鮮で", "is_correct": false, "explanation": "連用形で、名詞「うち」を修飾できず、文が成り立たない。"}], "correct_form": "新鮮な", "base_form": "新鮮だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"新鮮な": "連体形で、「うち」という名詞を修飾する形。", "新鮮に": "連用形で、名詞の「うち」を修飾できない。", "新鮮だ": "終止形で、名詞「うち」を修飾できず、「新鮮だうちに」は成り立たない。", "新鮮で": "連用形で、名詞「うち」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38206, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、食料は買う側ではなく買いためる対象なので、ここには入らない。"}, {"text": "を", "is_correct": true, "explanation": "「買いためる」は目的語を「を」で示すので、ここに入る。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示し、買いためる対象にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、買いためる対象にはならない。"}], "correct_answer": "を", "explanations": {"が": "「が」は主語を示すが、食料は買う側ではなく買いためる対象なので、ここには入らない。", "を": "「買いためる」は目的語を「を」で示すので、ここに入る。", "に": "「に」は相手や場所を示し、買いためる対象にはならない。", "で": "「で」は手段や場所を示し、買いためる対象にはならない。"}, "error_tags": {"が": "主語", "に": "相手・場所", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38206, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38206, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が生きていくのに必要な、食べるものです。", "primary_collocate": null, "pronunciation": "しょくりょう", "ipa": "ɕokɯɾʲoː", "syllable_count": 4, "sentences": [{"text": "山で道に迷ったので、少ない食料を大事に食べた。", "target_word": "食料", "complexity_tier": "T3", "furigana": "山[やま]で道[みち]に迷[まよ]ったので、少[すく]ない食料[しょくりょう]を大事[だいじ]に食[た]べた。", "sentence_source": "generated"}, {"text": "冬が来る前に、家族が暮らせるだけの食料を買いためた。", "target_word": "食料", "complexity_tier": "T3", "furigana": "冬が来る前に、家族が暮らせるだけの{食料|しょくりょう}を買いためた。", "sentence_source": "generated"}, {"text": "食料がなくなったので、近くのスーパーへ買いに行った。", "target_word": "食料", "complexity_tier": "T3", "furigana": "食料[しょくりょう]がなくなったので、近[ちか]くのスーパーへ買[か]いに行[い]った。", "sentence_source": "generated"}, {"text": "船には一週間分の食料が積まれていた。", "target_word": "食料", "complexity_tier": "T3", "furigana": "船[ふね]には一週間分[いっしゅうかんぶん]の食料[しょくりょう]が積[つ]まれていた。", "sentence_source": "generated"}, {"text": "人は水と食料がなければ、生きていけない。", "target_word": "食料", "complexity_tier": "T3", "furigana": "人[ひと]は水[みず]と食料[しょくりょう]がなければ、生[い]きていけない。", "sentence_source": "generated"}, {"text": "キャンプに行く前に、みんなで食料を分けて持った。", "target_word": "食料", "complexity_tier": "T3", "furigana": "キャンプに行[い]く前[まえ]に、みんなで食料[しょくりょう]を分[わ]けて持[も]った。", "sentence_source": "generated"}, {"text": "食料を買いすぎないように、冷蔵庫の中を確かめる。", "target_word": "食料", "complexity_tier": "T3", "furigana": "食料[しょくりょう]を買[か]いすぎないように、冷蔵庫[れいぞうこ]の中[なか]を確[たし]かめる。", "sentence_source": "generated"}, {"text": "大雪で道がふさがり、村に食料が届かなくなった。", "target_word": "食料", "complexity_tier": "T3", "furigana": "大雪[おおゆき]で道[みち]がふさがり、村[むら]に食料[しょくりょう]が届[とど]かなくなった。", "sentence_source": "generated"}, {"text": "子どもたちは、お年寄りに食料を配るボランティアをした。", "target_word": "食料", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、お年寄[としよ]りに食料[しょくりょう]を配[くば]るボランティアをした。", "sentence_source": "generated"}, {"text": "大雪に備えて、村の人たちは冬の食料を蔵にたくわえた。", "target_word": "食料", "complexity_tier": "T3", "furigana": "大雪に備えて、村の人たちは冬の{食料|しょくりょう}を蔵にたくわえた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "食料", "label": "基本形"}], "register": "中立", "sense_fingerprint": "生きていくために必要な食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38206, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水", "is_correct": false, "explanation": "水は飲むもので、食べる対象ではないので「食べた」と合わない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は吸うもので、食べ物ではないので「食べた」と合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は食べ物ではないので、食べたとは言えない。"}, {"text": "食料", "is_correct": true, "explanation": "少ない食べ物を大事に食べたという文脈で〈食料〉が入る。"}], "explanations": {"水": "水は飲むもので、食べる対象ではないので「食べた」と合わない。", "空気": "空気は吸うもので、食べ物ではないので「食べた」と合わない。", "紙": "紙は食べ物ではないので、食べたとは言えない。", "食料": "少ない食べ物を大事に食べたという文脈で〈食料〉が入る。"}, "sentence_index": 0, "correct_answer": "食料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は食料を防ぐため、台所を清潔にしている。", "explanation": "ここは〈食中毒〉の意味。病気の予防には〈食中毒〉を使い、〈食料〉は防ぐ対象ではないので合わない。"}, {"text": "使い終えた食料を、台所で洗って乾かした。", "explanation": "ここは〈食器〉の意味。洗うのは器具で、食べ物の〈食料〉は洗う対象ではない。"}, {"text": "食料の鋭い人は、わずかな違いも見分けられる。", "explanation": "ここは〈味覚〉の意味。味を感じる力には〈味覚〉を使い、〈食料〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38206, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思い出", "is_correct": false, "explanation": "思い出は心に残る記憶で、買うものではないので合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は気持ちで、買うものではないので合わない。"}, {"text": "食料", "is_correct": true, "explanation": "買いすぎないようにする対象で、買い物の文脈なので〈食料〉が入る。"}, {"text": "空", "is_correct": false, "explanation": "空は上に広がるもので、買うものではないので合わない。"}], "explanations": {"思い出": "思い出は心に残る記憶で、買うものではないので合わない。", "感謝": "感謝は気持ちで、買うものではないので合わない。", "食料": "買いすぎないようにする対象で、買い物の文脈なので〈食料〉が入る。", "空": "空は上に広がるもので、買うものではないので合わない。"}, "sentence_index": 6, "correct_answer": "食料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父に箸の食料を教わり、やっと上手に持てるようになった。", "explanation": "ここは〈食べ方〉の意味。やり方や作法には〈食べ方〉を使い、〈食料〉は食べ物そのものなので合わない。"}, {"text": "食料に手を洗うことを忘れないでください。", "explanation": "ここは〈食前〉（食べる前）の意味。時を表す語なので、〈食料〉では手を洗う時を示せない。"}, {"text": "強い胃の痛みが続くので、食料を検査してもらった。", "explanation": "ここは〈食道〉（のどから胃につながる管）の意味。体の部位には〈食道〉を使い、〈食料〉は検査の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38206, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "非常時には、食料に備蓄を確認しておく。", "corrected_sentence": "非常時には、食料の備蓄を確認しておく。", "error_description": "「食料の備蓄」の「の」が「に」になっている。「食料」は「備蓄」を修飾するので、正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38206, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "買いだめした食料が、冬の間に食べきった。", "corrected_sentence": "買いだめした食料を、冬の間に食べきった。", "error_description": "「食料」の後の助詞が「が」になっている。「食べきる」は目的語に「を」を取るので、正しくは「食料を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38208, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「万が一の〜こと」と連体修飾する正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「万が一が〜こと」では名詞を修飾できず不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、名詞「こと」を修飾する位置では使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、万が一に直接続く位置では不自然。"}], "correct_answer": "の", "explanations": {"の": "「万が一の〜こと」と連体修飾する正しい助詞。", "が": "主語を示す助詞で、「万が一が〜こと」では名詞を修飾できず不自然。", "を": "目的語を示す助詞で、名詞「こと」を修飾する位置では使えない。", "で": "手段や場所を示す助詞で、万が一に直接続く位置では不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
