INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38208, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "もしものこと。", "primary_collocate": null, "pronunciation": "まんがいち", "ipa": "maŋɡaitɕi", "syllable_count": 5, "sentences": [{"text": "万が一のために、非常食を用意しています。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]のために、非常食[ひじょうしょく]を用意[ようい]しています。", "sentence_source": "generated"}, {"text": "万が一のことがあったら、すぐに私に電話してください。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]のことがあったら、すぐに私[わたし]に電話[でんわ]してください。", "sentence_source": "generated"}, {"text": "山に登るときは、万が一に備えて地図を持って行きます。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "山[やま]に登[のぼ]るときは、万[まん]が一[いち]に備[そな]えて地図[ちず]を持[も]って行[い]きます。", "sentence_source": "generated"}, {"text": "万が一、電車が止まった場合は、タクシーで行きます。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]、電車[でんしゃ]が止[と]まった場合[ばあい]は、タクシーで行[い]きます。", "sentence_source": "generated"}, {"text": "父は万が一のときのために、貯金をしています。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "父[ちち]は万[まん]が一[いち]のときのために、貯金[ちょきん]をしています。", "sentence_source": "generated"}, {"text": "万が一の場合は、この番号に連絡してください。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]の場合[ばあい]は、この番号[ばんごう]に連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "万が一雨が降ったら、試合は体育館で行います。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]雨[あめ]が降[ふ]ったら、試合[しあい]は体育館[たいいくかん]で行[おこな]います。", "sentence_source": "generated"}, {"text": "旅行の前に、万が一の事故を考えて保険に入りました。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に、万[まん]が一[いち]の事故[じこ]を考[かんが]えて保険[ほけん]に入[はい]りました。", "sentence_source": "generated"}, {"text": "万が一に備えて、懐中電灯を玄関に置いています。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]に備[そな]えて、懐中電灯[かいちゅうでんとう]を玄関[げんかん]に置[お]いています。", "sentence_source": "generated"}, {"text": "万が一忘れたときのために、メモを残しておきます。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]忘[わす]れたときのために、メモを残[のこ]しておきます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "万が一の", "label": "連体（の）"}, {"form": "万が一に", "label": "に格"}, {"form": "万が一、", "label": "文頭の副詞的用法"}], "register": "中立（丁寧体）", "sense_fingerprint": "もしものこと、予想していないことが起きる場合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38208, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万が一", "is_correct": true, "explanation": "もしもの事態への備えという文脈に合う名詞。"}, {"text": "平日", "is_correct": false, "explanation": "曜日の区分で、もしもの事態への備えとは合わない。"}, {"text": "季節", "is_correct": false, "explanation": "時期の意味で、非常食の備えという文脈と噛み合わない。"}, {"text": "風邪", "is_correct": false, "explanation": "病気の名で、非常食の備えとは結びつかない。"}], "explanations": {"万が一": "もしもの事態への備えという文脈に合う名詞。", "平日": "曜日の区分で、もしもの事態への備えとは合わない。", "季節": "時期の意味で、非常食の備えという文脈と噛み合わない。", "風邪": "病気の名で、非常食の備えとは結びつかない。"}, "sentence_index": 0, "correct_answer": "万が一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その列車は、万が一予定どおりに到着した。", "explanation": "ここは〈計画どおり・確実に〉の意味との混同。万が一は起きにくい想定に使うので、計画どおりに進んだ出来事には使わないので誤り。"}, {"text": "昨日、駅で万が一、先生に会いました。", "explanation": "ここは〈偶然〉の意味との混同。万が一は『もしそうなったら』の意味で、実際に起きた出来事には使わないので誤り。"}, {"text": "彼は万が一、毎朝遅刻します。", "explanation": "ここは〈いつも〉の意味との混同。万が一は起きにくい想定に使うので、習慣的な出来事には使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38208, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万が一", "is_correct": true, "explanation": "もしも雨が降った場合を表すので、試合を体育館で行うという文脈に合う。"}, {"text": "昨日", "is_correct": false, "explanation": "過去の一日を指すので、これから起きる場合の想定と合わない。"}, {"text": "予約", "is_correct": false, "explanation": "申し込みの意味で、雨が降った場合の想定とは噛み合わない。"}, {"text": "先月", "is_correct": false, "explanation": "過去の時期を表すので、試合の会場を決める文脈とずれる。"}], "explanations": {"万が一": "もしも雨が降った場合を表すので、試合を体育館で行うという文脈に合う。", "昨日": "過去の一日を指すので、これから起きる場合の想定と合わない。", "予約": "申し込みの意味で、雨が降った場合の想定とは噛み合わない。", "先月": "過去の時期を表すので、試合の会場を決める文脈とずれる。"}, "sentence_index": 6, "correct_answer": "万が一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は必ず忘れるので、万が一メモを残しておきます。", "explanation": "ここは〈確実に起こる〉の意味。万が一は起きにくい想定に使うので、確実に起こることには合わないので誤り。"}, {"text": "毎回忘れてしまうので、万が一、メモを残しておきます。", "explanation": "ここは〈繰り返し起きる・習慣的に〉の意味。万が一は例外的な想定を表すので、くり返し起きることには使わないので誤り。"}, {"text": "この問題は万が一よく起こるので、対策を考えています。", "explanation": "ここは〈頻繁に〉の意味。万が一は起きにくい事態を表すので、頻繁に起こる事柄には使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38208, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "万が一を事態に備えて、保険に入っておきます。", "corrected_sentence": "万が一の事態に備えて、保険に入っておきます。", "error_description": "名詞「事態」を修飾するには連体修飾の「の」が必要。「万が一を」の「を」は目的語の助詞で、名詞を修飾できない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38208, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "万が一に際に備えて、連絡先を書いておきます。", "corrected_sentence": "万が一の際に備えて、連絡先を書いておきます。", "error_description": "「際」の前には連体修飾の「の」が必要。「万が一に際に」は「に」が重なって不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
