INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38209, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「万が一の大雨」と連体修飾する正しい助詞。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「万が一が大雨」では名詞を修飾できず不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、名詞を修飾する位置では不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「万が一へ大雨」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「万が一の大雨」と連体修飾する正しい助詞。", "が": "主語を示す助詞で、「万が一が大雨」では名詞を修飾できず不自然。", "で": "手段や場所を示す助詞で、名詞を修飾する位置では不自然。", "へ": "方向を示す助詞で、「万が一へ大雨」では意味が通らない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38209, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "可能性は低いが、もしもそうなったら大変なことになるような事態や状況。", "primary_collocate": null, "pronunciation": "まんがいち", "ipa": "maŋɡaitɕi", "syllable_count": 5, "sentences": [{"text": "万が一、火事になったら大変なので、消火器を置いています。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]、火事[かじ]になったら大変[たいへん]なので、消火器[しょうかき]を置[お]いています。", "sentence_source": "generated"}, {"text": "万が一、機械が壊れて人がけがをしたら大変です。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]、機械[きかい]が壊[こわ]れて人[ひと]がけがをしたら大変[たいへん]です。", "sentence_source": "generated"}, {"text": "可能性は低いですが、万が一の地震に備えて水を買いました。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "可能性[かのうせい]は低[ひく]いですが、万[まん]が一[いち]の地震[じしん]に備[そな]えて水[みず]を買[か]いました。", "sentence_source": "generated"}, {"text": "万が一、子どもが迷子になったら、すぐ警察に連絡します。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]、子[こ]どもが迷子[まいご]になったら、すぐ警察[けいさつ]に連絡[れんらく]します。", "sentence_source": "generated"}, {"text": "万が一の事故を防ぐために、工事の前に何度も確認します。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]の事故[じこ]を防[ふせ]ぐために、工事[こうじ]の前[まえ]に何度[なんど]も確認[かくにん]します。", "sentence_source": "generated"}, {"text": "万が一失敗すれば、会社が大きな損をします。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]失敗[しっぱい]すれば、会社[かいしゃ]が大[おお]きな損[そん]をします。", "sentence_source": "generated"}, {"text": "飛行機は安全ですが、万が一の場合の出口を確認しておきます。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "飛行機[ひこうき]は安全[あんぜん]ですが、万[まん]が一[いち]の場合[ばあい]の出口[でぐち]を確認[かくにん]しておきます。", "sentence_source": "generated"}, {"text": "万が一の大雨に備え、川の近くの家は早めに避難しました。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]の大雨[おおあめ]に備[そな]え、川[かわ]の近[ちか]くの家[いえ]は早[はや]めに避難[ひなん]しました。", "sentence_source": "generated"}, {"text": "万が一の大事故に備えて、ブレーキ部品を毎年点検しています。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万が一[まんがいち]の大事故[だいじこ]に備[そな]えて、ブレーキ部品[ぶひん]を毎年[まいとし]点検[てんけん]しています。", "sentence_source": "generated"}, {"text": "万が一のけがに備えて、旅行には薬を持って行きます。", "target_word": "万が一", "complexity_tier": "T3", "furigana": "万[まん]が一[いち]のけがに備[そな]えて、旅行[りょこう]には薬[くすり]を持[も]って行[い]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "万が一の", "label": "連体（の）"}, {"form": "万が一に", "label": "に格"}, {"form": "万が一にも", "label": "にも（強調）"}, {"form": "万が一、", "label": "文頭の副詞的用法"}], "register": "中立（丁寧体）", "sense_fingerprint": "可能性は低いが、起これば大変になる事態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38209, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万が一", "is_correct": true, "explanation": "可能性は低いが、起これば大変な火事という想定に合う。"}, {"text": "毎日", "is_correct": false, "explanation": "繰り返し起きる期間を表すので、可能性が低い事態の想定と合わない。"}, {"text": "去年", "is_correct": false, "explanation": "過去の年を表すので、これから起こりうる火事の想定とずれる。"}, {"text": "財布", "is_correct": false, "explanation": "持ち物の名で、火事という事態の想定とは合わない。"}], "explanations": {"万が一": "可能性は低いが、起これば大変な火事という想定に合う。", "毎日": "繰り返し起きる期間を表すので、可能性が低い事態の想定と合わない。", "去年": "過去の年を表すので、これから起こりうる火事の想定とずれる。", "財布": "持ち物の名で、火事という事態の想定とは合わない。"}, "sentence_index": 0, "correct_answer": "万が一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うちの子は必ず迷子になるので、万が一に備えて連絡先を書いています。", "explanation": "ここは〈確実に起こる〉の意味。万が一は可能性が低い事態に使うので、確実に起こることには合わないので誤り。"}, {"text": "子どもが迷子になったので、万が一すぐ警察に連絡しました。", "explanation": "ここは〈即座に〉の意味との混同。万が一は『もしもの場合』を表し、実際に起きた場面で素早く行う意味では使わないので誤り。"}, {"text": "子どもは日常的に迷子になるので、万が一、すぐ警察に連絡します。", "explanation": "ここは〈いつも・繰り返し〉の意味。万が一は例外的な事態を表すので、くり返し起きることには使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38209, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万が一", "is_correct": true, "explanation": "起きる可能性は低いが、起きたら困る場合を表し、出口の確認という文脈に合う。"}, {"text": "毎年", "is_correct": false, "explanation": "繰り返し起きる期間を表すので、可能性の低い場合の想定とは合わない。"}, {"text": "以前", "is_correct": false, "explanation": "過去を表すので、これから起こりうる場合の想定と噛み合わない。"}, {"text": "次回", "is_correct": false, "explanation": "次の機会を表すので、緊急時の場合を指す文脈とずれる。"}], "explanations": {"万が一": "起きる可能性は低いが、起きたら困る場合を表し、出口の確認という文脈に合う。", "毎年": "繰り返し起きる期間を表すので、可能性の低い場合の想定とは合わない。", "以前": "過去を表すので、これから起こりうる場合の想定と噛み合わない。", "次回": "次の機会を表すので、緊急時の場合を指す文脈とずれる。"}, "sentence_index": 6, "correct_answer": "万が一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私はよくけがをするので、万が一のけがに備えて、旅行には薬を持って行きます。", "explanation": "ここは〈しばしば〉の意味。万が一は可能性の低い事態に使うので、頻繁に起こる状況には合わないので誤り。"}, {"text": "旅行では確実にけがをするので、万が一に備えて薬を持って行きます。", "explanation": "ここは〈ほぼ間違いなく起こる〉の意味。万が一は起きる可能性が低い事態を表すので、必ず起こることには使わないので誤り。"}, {"text": "旅行のたびに毎回けがをするので、万が一のけがに備えて薬を持って行きます。", "explanation": "ここは〈回数ごとに・例外なく〉の意味。万が一は例外的な事態を表すので、毎度起きることには使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38209, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "万が一で火事に備えて、消火器を玄関に置いています。", "corrected_sentence": "万が一の火事に備えて、消火器を玄関に置いています。", "error_description": "名詞「火事」を修飾するには連体修飾の「の」が必要。「万が一で」の「で」は名詞を修飾できず、ここでは不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38209, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飛行機は安全ですが、万が一を場合に備えて出口を確認しておきます。", "corrected_sentence": "飛行機は安全ですが、万が一の場合に備えて出口を確認しておきます。", "error_description": "名詞「場合」を修飾するには連体修飾の「の」が必要。「万が一を」の「を」は目的語の助詞で、名詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38210, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈保障する〉の対象を示す〈を〉。『暮らしを保障する』と自然につながる。"}, {"text": "が", "is_correct": false, "explanation": "〈暮らしが〉は主語になり、〈保障する〉の目的語として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "〈保障する〉は〈を〉で対象を取るので、〈に〉は不自然。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を表すので、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "〈保障する〉の対象を示す〈を〉。『暮らしを保障する』と自然につながる。", "が": "〈暮らしが〉は主語になり、〈保障する〉の目的語として成り立たない。", "に": "〈保障する〉は〈を〉で対象を取るので、〈に〉は不自然。", "で": "〈で〉は手段や場所を表すので、対象を示せない。"}, "error_tags": {"が": "主語", "に": "相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38210, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈保障する〉の対象〈健康〉を示す〈を〉。健康を保障するという関係になる。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並べる相手を示すので、〈健康と保障する〉では対象を表せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、〈健康へ保障する〉では保障の対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示すので、〈健康より保障する〉では対象を表せず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "〈保障する〉の対象〈健康〉を示す〈を〉。健康を保障するという関係になる。", "と": "〈と〉は並べる相手を示すので、〈健康と保障する〉では対象を表せず不自然。", "へ": "〈へ〉は方向を示すので、〈健康へ保障する〉では保障の対象を示せない。", "より": "〈より〉は比較を示すので、〈健康より保障する〉では対象を表せず文が成り立たない。"}, "error_tags": {"と": "並列", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38210, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "権利・生活・安全などが損なわれないよう、守ること。", "primary_collocate": null, "pronunciation": "ほしょう", "ipa": "hoɕoː", "syllable_count": 3, "sentences": [{"text": "憲法は、すべての国民の自由を保障している。", "target_word": "保障", "complexity_tier": "T3", "furigana": "憲法[けんぽう]は、すべての国民[こくみん]の自由[じゆう]を保障[ほしょう]している。", "sentence_source": "generated"}, {"text": "病気になっても生活が守られるように、国は最低限の暮らしを保障する。", "target_word": "保障", "complexity_tier": "T3", "furigana": "病気[びょうき]になっても生活[せいかつ]が守[まも]られるように、国[くに]は最低限[さいていげん]の暮[く]らしを保障[ほしょう]する。", "sentence_source": "generated"}, {"text": "この制度は、病気や事故のときの保障が手薄だ。", "target_word": "保障", "complexity_tier": "T3", "furigana": "この制度[せいど]は、病気[びょうき]や事故[じこ]のときの保障[ほしょう]が手薄[てうす]だ。", "sentence_source": "generated"}, {"text": "働く人の安全を保障するため、工場に新しい機械を入れた。", "target_word": "保障", "complexity_tier": "T3", "furigana": "働[はたら]く人[ひと]の安全[あんぜん]を保障[ほしょう]するため、工場[こうじょう]に新[あたら]しい機械[きかい]を入[い]れた。", "sentence_source": "generated"}, {"text": "老後の保障が不安で、毎月少しずつ貯金している。", "target_word": "保障", "complexity_tier": "T3", "furigana": "老後[ろうご]の保障[ほしょう]が不安[ふあん]で、毎月[まいつき]少[すこ]しずつ貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "この国では、子どもが学校に通う権利が保障されている。", "target_word": "保障", "complexity_tier": "T3", "furigana": "この国[くに]では、子[こ]どもが学校[がっこう]に通[かよ]う権利[けんり]が保障[ほしょう]されている。", "sentence_source": "generated"}, {"text": "保障がなければ、安心して新しい仕事を始められない。", "target_word": "保障", "complexity_tier": "T3", "furigana": "保障[ほしょう]がなければ、安心[あんしん]して新[あたら]しい仕事[しごと]を始[はじ]められない。", "sentence_source": "generated"}, {"text": "会社は社員の健康を保障するために、毎年検査を行う。", "target_word": "保障", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]の健康[けんこう]を保障[ほしょう]するために、毎年[まいとし]検査[けんさ]を行[おこな]う。", "sentence_source": "generated"}, {"text": "言論の自由が保障されない国では、人々は自由に意見を言えない。", "target_word": "保障", "complexity_tier": "T3", "furigana": "言論[げんろん]の自由[じゆう]が保障[ほしょう]されない国[くに]では、人々[ひとびと]は自由[じゆう]に意見[いけん]を言[い]えない。", "sentence_source": "generated"}, {"text": "育児休暇中も収入が保障されるので、安心して休める。", "target_word": "保障", "complexity_tier": "T3", "furigana": "育児[いくじ]休暇[きゅうか]中[ちゅう]も収入[しゅうにゅう]が保障[ほしょう]されるので、安心[あんしん]して休[やす]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保障する", "label": "辞書形(する動詞)"}, {"form": "保障した", "label": "過去形"}, {"form": "保障される", "label": "受身形"}, {"form": "保障しない", "label": "否定形"}], "register": "中立(普通体)", "sense_fingerprint": "権利・生活・安全などが損なわれないよう守ること(保証・補償とは別)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38210, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "「自由を保障している」: 権利が損なわれないよう守る意味で、文の内容に合う。"}, {"text": "発見", "is_correct": false, "explanation": "「自由を発見している」: 発見は見つける行為で、権利を守る意味にならない。"}, {"text": "返却", "is_correct": false, "explanation": "「自由を返却している」: 返却は物を戻す行為で、自由には使えない。"}, {"text": "目的", "is_correct": false, "explanation": "「自由を目的している」: 目的は狙いを表し、守る行為を表せない。"}], "explanations": {"保障": "「自由を保障している」: 権利が損なわれないよう守る意味で、文の内容に合う。", "発見": "「自由を発見している」: 発見は見つける行為で、権利を守る意味にならない。", "返却": "「自由を返却している」: 返却は物を戻す行為で、自由には使えない。", "目的": "「自由を目的している」: 目的は狙いを表し、守る行為を表せない。"}, "sentence_index": 0, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国立公園で動物を保障している。", "explanation": "〈保護〉（危険から守る）と取り違えた。生き物を外敵から守るのは〈保護〉で、〈保障〉は約束や権利の意味で使う。"}, {"text": "この園では、赤ちゃんを保障して育てている。", "explanation": "〈保育〉（子どもを預かり世話をする）と取り違えた。子どもの世話は〈保育〉で表し、〈保障〉とは言わない。"}, {"text": "建物の保障工事を来月行う。", "explanation": "〈保全〉（維持して傷みを防ぐ）と取り違えた。建物や設備の維持は〈保全〉で表し、〈保障〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38210, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "「保障がなければ」: 安全や生活を守る条件として、新しい仕事を始める安心の意味に合う。"}, {"text": "冷房", "is_correct": false, "explanation": "「冷房がなければ」: 冷房は室内の温度を整える設備で、仕事の安心とは結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気がなければ」: 天気は状態であり、仕事を始める安心の条件にならない。"}, {"text": "花束", "is_correct": false, "explanation": "「花束がなければ」: 花束は贈り物で、仕事を始める条件を表さない。"}], "explanations": {"保障": "「保障がなければ」: 安全や生活を守る条件として、新しい仕事を始める安心の意味に合う。", "冷房": "「冷房がなければ」: 冷房は室内の温度を整える設備で、仕事の安心とは結びつかない。", "天気": "「天気がなければ」: 天気は状態であり、仕事を始める安心の条件にならない。", "花束": "「花束がなければ」: 花束は贈り物で、仕事を始める条件を表さない。"}, "sentence_index": 6, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土地を保障にお金を借りた。", "explanation": "〈担保〉（借金の保証として差し出す物）と取り違えた。借金の担保は〈担保〉で表す。"}, {"text": "この水筒は中身を保障できる。", "explanation": "〈保温〉（温度を保つ）と取り違えた。温度を保つ意味には〈保障〉を使わない。"}, {"text": "大事な書類を保障しておく。", "explanation": "〈保管〉（大切に預かる）と取り違えた。物を預かって守るのは〈保管〉で、〈保障〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38210, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国では、誰もが学ぶ権利が保障られている。", "corrected_sentence": "この国では、誰もが学ぶ権利が保障されている。", "error_description": "受身の〈保障される〉が正しい。〈保障られる〉は受身の活用として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38210, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "育児休暇中も給料が保障するので、安心して休める。", "corrected_sentence": "育児休暇中も給料が保障されるので、安心して休める。", "error_description": "〈給料が〉が主語の受身なので〈保障される〉が必要。能動の〈保障する〉では主語が保障する側になり、不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
