INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38211, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が確実に実現するように、また安全であるように、責任を持って守ること。", "primary_collocate": null, "pronunciation": "ほしょう", "ipa": "hoɕoː", "syllable_count": 3, "sentences": [{"text": "政府は、災害のときも水の供給を保障すると発表した。", "target_word": "保障", "complexity_tier": "T3", "furigana": "政府[せいふ]は、災害[さいがい]のときも水[みず]の供給[きょうきゅう]を保障[ほしょう]すると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "この制度は、働く人が仕事を失っても収入を保障する。", "target_word": "保障", "complexity_tier": "T3", "furigana": "この制度[せいど]は、働[はたら]く人[ひと]が仕事[しごと]を失[うしな]っても収入[しゅうにゅう]を保障[ほしょう]する。", "sentence_source": "generated"}, {"text": "平和を保障するには、国どうしの信頼が欠かせない。", "target_word": "保障", "complexity_tier": "T3", "furigana": "平和[へいわ]を保障[ほしょう]するには、国[くに]どうしの信頼[しんらい]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "学校は、通学路の安全を保障する責任がある。", "target_word": "保障", "complexity_tier": "T3", "furigana": "学校[がっこう]は、通学路[つうがくろ]の安全[あんぜん]を保障[ほしょう]する責任[せきにん]がある。", "sentence_source": "generated"}, {"text": "契約では、最低限の給料が保障されている。", "target_word": "保障", "complexity_tier": "T3", "furigana": "契約[けいやく]では、最低限[さいていげん]の給料[きゅうりょう]が保障[ほしょう]されている。", "sentence_source": "generated"}, {"text": "国が保障しなければ、貧しい家の子は学校に行けなくなる。", "target_word": "保障", "complexity_tier": "T3", "furigana": "国[くに]が保障[ほしょう]しなければ、貧[まず]しい家[いえ]の子[こ]は学校[がっこう]に行[い]けなくなる。", "sentence_source": "generated"}, {"text": "医療を受ける権利は、誰にでも保障されるべきだ。", "target_word": "保障", "complexity_tier": "T3", "furigana": "医療[いりょう]を受[う]ける権利[けんり]は、誰[だれ]にでも保障[ほしょう]されるべきだ。", "sentence_source": "generated"}, {"text": "彼は会社に、家族の生活の保障を求めた。", "target_word": "保障", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]に、家族[かぞく]の生活[せいかつ]の保障[ほしょう]を求[もと]めた。", "sentence_source": "generated"}, {"text": "将来の保障がないまま、店を始めるのは危ない。", "target_word": "保障", "complexity_tier": "T3", "furigana": "将来[しょうらい]の保障[ほしょう]がないまま、店[みせ]を始[はじ]めるのは危[あぶ]ない。", "sentence_source": "generated"}, {"text": "安全が保障されていないので、その山には登らないことにした。", "target_word": "保障", "complexity_tier": "T3", "furigana": "安全[あんぜん]が保障[ほしょう]されていないので、その山[やま]には登[のぼ]らないことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保障する", "label": "辞書形(する動詞)"}, {"form": "保障した", "label": "過去形"}, {"form": "保障される", "label": "受身形"}, {"form": "保障しない", "label": "否定形"}], "register": "中立(普通体)", "sense_fingerprint": "国・組織などが責任を持って、収入・安全・権利が確実に守られるようにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38211, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "「水の供給を保障すると」: 供給が確実に続くよう責任を持って守る意味で、文に合う。"}, {"text": "翻訳", "is_correct": false, "explanation": "「水の供給を翻訳すると」: 翻訳は言語を訳す行為で、供給には使えない。"}, {"text": "撮影", "is_correct": false, "explanation": "「水の供給を撮影すると」: 撮影は映像を記録する行為で、供給の対象にならない。"}, {"text": "作曲", "is_correct": false, "explanation": "「水の供給を作曲すると」: 作曲は曲を作る行為で、供給とは結びつかない。"}], "explanations": {"保障": "「水の供給を保障すると」: 供給が確実に続くよう責任を持って守る意味で、文に合う。", "翻訳": "「水の供給を翻訳すると」: 翻訳は言語を訳す行為で、供給には使えない。", "撮影": "「水の供給を撮影すると」: 撮影は映像を記録する行為で、供給の対象にならない。", "作曲": "「水の供給を作曲すると」: 作曲は曲を作る行為で、供給とは結びつかない。"}, "sentence_index": 0, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この園では、夜の間も子どもを保障している。", "explanation": "〈保育〉（子どもを預かり世話をする）と取り違えた。子どもを預かって世話するのは〈保育〉で表し、〈保障〉とは言わない。"}, {"text": "大事な書類を保障しておく。", "explanation": "〈保管〉（大切に預かる）と取り違えた。物を預かって守るのは〈保管〉で、〈保障〉とは言わない。"}, {"text": "町は野生の鳥を保障している。", "explanation": "〈保護〉（危険から守る）と取り違えた。生き物を外敵から守るのは〈保護〉で、〈保障〉は約束や権利の意味で使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38211, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保障", "is_correct": true, "explanation": "「誰にでも保障されるべきだ」: 権利が誰にでも守られるべきだという意味で、文に合う。"}, {"text": "栄養", "is_correct": false, "explanation": "「誰にでも栄養されるべきだ」: 栄養は体に必要な物を与える意味で、権利には使えない。"}, {"text": "点滅", "is_correct": false, "explanation": "「誰にでも点滅されるべきだ」: 点滅は光が明暗を繰り返す意味で、権利に当てはまらない。"}, {"text": "呼吸", "is_correct": false, "explanation": "「誰にでも呼吸されるべきだ」: 呼吸は体の働きで、権利の文脈では意味が通らない。"}], "explanations": {"保障": "「誰にでも保障されるべきだ」: 権利が誰にでも守られるべきだという意味で、文に合う。", "栄養": "「誰にでも栄養されるべきだ」: 栄養は体に必要な物を与える意味で、権利には使えない。", "点滅": "「誰にでも点滅されるべきだ」: 点滅は光が明暗を繰り返す意味で、権利に当てはまらない。", "呼吸": "「誰にでも呼吸されるべきだ」: 呼吸は体の働きで、権利の文脈では意味が通らない。"}, "sentence_index": 6, "correct_answer": "保障"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事故の被害者に損害の保障をした。", "explanation": "〈補償〉（損害の弁償）と取り違えた。損害の埋め合わせは〈補償〉で表す。"}, {"text": "この土地を保障にして、お金を借りた。", "explanation": "〈担保〉（借金の保証として差し出す物）と取り違えた。借金の担保は〈担保〉で表す。"}, {"text": "この水筒は中身を保障する。", "explanation": "〈保温〉（温度を保つ）と取り違えた。温度を保つ意味には〈保障〉を使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38211, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校は、通学路の安全を保障ている責任がある。", "corrected_sentence": "学校は、通学路の安全を保障している責任がある。", "error_description": "〈保障〉の後は〈して〉の活用が必要。〈保障ている〉は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38211, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は市に、子どもの教育に保障を求めた。", "corrected_sentence": "彼は市に、子どもの教育の保障を求めた。", "error_description": "〈保障〉は〈〜の保障〉の形で名詞を修飾するので〈の〉が正しい。〈に〉では『教育に保障』となり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38212, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「強化の」で、強化を次の「ために」に続く名詞として結ぶ連体の形。"}, {"text": "が", "is_correct": false, "explanation": "「強化がために」は主語の形になり、「ために」と続かない。"}, {"text": "を", "is_correct": false, "explanation": "「強化をために」は目的語の形になり、「ために」の前に置けない。"}, {"text": "で", "is_correct": false, "explanation": "「強化でために」は手段の意味だが、「ために」と続かない。"}], "correct_answer": "の", "explanations": {"の": "「強化の」で、強化を次の「ために」に続く名詞として結ぶ連体の形。", "が": "「強化がために」は主語の形になり、「ために」と続かない。", "を": "「強化をために」は目的語の形になり、「ために」の前に置けない。", "で": "「強化でために」は手段の意味だが、「ために」と続かない。"}, "error_tags": {"の": "連体", "が": "主語", "を": "目的語", "で": "手段"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱化", "is_correct": true, "explanation": "「弱化」は弱くすることで、強める「強化」の対義語として辞書に並ぶ。"}, {"text": "維持", "is_correct": false, "explanation": "「維持」は今の状態を保つ意味で、強めることの反対語ではない。"}, {"text": "中断", "is_correct": false, "explanation": "「中断」は途中でやめる意味で、強化の対義語ではない。"}, {"text": "普及", "is_correct": false, "explanation": "「普及」は広く行き渡る意味で、強化の対義語ではない。"}], "correct_answer": "弱化", "explanations": {"弱化": "「弱化」は弱くすることで、強める「強化」の対義語として辞書に並ぶ。", "維持": "「維持」は今の状態を保つ意味で、強めることの反対語ではない。", "中断": "「中断」は途中でやめる意味で、強化の対義語ではない。", "普及": "「普及」は広く行き渡る意味で、強化の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
