INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38212, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを、もっと強くしっかりしたものにすること。", "primary_collocate": null, "pronunciation": "きょうか", "ipa": "kʲoːka", "syllable_count": 3, "sentences": [{"text": "事故が続いたので、工場は安全の強化を決めた。", "target_word": "強化", "complexity_tier": "T3", "furigana": "事故[じこ]が続[つづ]いたので、工場[こうじょう]は安全[あんぜん]の強化[きょうか]を決[き]めた。", "sentence_source": "generated"}, {"text": "筋力の強化のために、毎朝走っている。", "target_word": "強化", "complexity_tier": "T3", "furigana": "筋力[きんりょく]の強化[きょうか]のために、毎朝[まいあさ]走[はし]っている。", "sentence_source": "generated"}, {"text": "試合に負けて、チームは守りの強化に取り組んだ。", "target_word": "強化", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けて、チームは守[まも]りの強化[きょうか]に取[と]り組[く]んだ。", "sentence_source": "generated"}, {"text": "町は地震に備えて、橋の強化を進めている。", "target_word": "強化", "complexity_tier": "T3", "furigana": "町[まち]は地震[じしん]に備[そな]えて、橋[はし]の強化[きょうか]を進[すす]めている。", "sentence_source": "generated"}, {"text": "夏までに体力の強化を目指して、ジムに通っている。", "target_word": "強化", "complexity_tier": "T3", "furigana": "夏[なつ]までに体力[たいりょく]の強化[きょうか]を目指[めざ]して、ジム[じむ]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "空港では、入口の検査が強化された。", "target_word": "強化", "complexity_tier": "T3", "furigana": "空港[くうこう]では、入口[いりぐち]の検査[けんさ]が強化[きょうか]された。", "sentence_source": "generated"}, {"text": "彼は体を強化するために、食事を見直した。", "target_word": "強化", "complexity_tier": "T3", "furigana": "彼[かれ]は体[からだ]を強化[きょうか]するために、食事[しょくじ]を見直[みなお]した。", "sentence_source": "generated"}, {"text": "防犯カメラを増やして、駅の警備を強化する。", "target_word": "強化", "complexity_tier": "T3", "furigana": "防犯[ぼうはん]カメラを増[ふ]やして、駅[えき]の警備[けいび]を強化[きょうか]する。", "sentence_source": "generated"}, {"text": "古い建物は、壁の強化が必要だ。", "target_word": "強化", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]は、壁[かべ]の強化[きょうか]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "弱った床の強化を続ければ、きっと長く使える。", "target_word": "強化", "complexity_tier": "T3", "furigana": "弱[よわ]った床[ゆか]の強化[きょうか]を続[つづ]ければ、きっと長[なが]く使[つか]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強化する", "label": "辞書形(する動詞)"}, {"form": "強化した", "label": "過去形"}, {"form": "強化される", "label": "受身形"}, {"form": "強化しない", "label": "否定形"}], "register": "中立(普通体)", "sense_fingerprint": "体・建物・守りなど具体的なものを、より強く丈夫にすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38212, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強化", "is_correct": true, "explanation": "「安全の強化」は安全性を高めることを指し、文の『決めた』とも合う。"}, {"text": "延期", "is_correct": false, "explanation": "「延期」は日時を先に延ばす意味で、『安全の延期』とは言えない。"}, {"text": "解除", "is_correct": false, "explanation": "「解除」は止める・外す意味で、安全を対象にした決定としては不自然。"}, {"text": "撤回", "is_correct": false, "explanation": "「撤回」は取り消す意味で、『安全の撤回』は文の内容と合わない。"}], "explanations": {"強化": "「安全の強化」は安全性を高めることを指し、文の『決めた』とも合う。", "延期": "「延期」は日時を先に延ばす意味で、『安全の延期』とは言えない。", "解除": "「解除」は止める・外す意味で、安全を対象にした決定としては不自然。", "撤回": "「撤回」は取り消す意味で、『安全の撤回』は文の内容と合わない。"}, "sentence_index": 0, "correct_answer": "強化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はその一文を強化して、声を大きくして読んだ。", "explanation": "ここは〈強調〉の意味。強化は物を丈夫にする意味で、要点を際立たせる用法はない。"}, {"text": "在庫が減ったので、棚の商品を強化した。", "explanation": "ここは〈補充〉の意味。強化は力を強める意味で、品物を足す用法ではない。"}, {"text": "警察は容疑者に自白を強化した。", "explanation": "ここは〈強要〉の意味。強化は力や体制を強くすることで、相手に無理に求める意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38212, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強化", "is_correct": true, "explanation": "「体を強化するために」で、体を丈夫にする意味になる。"}, {"text": "中断", "is_correct": false, "explanation": "「体を中断するために」は意味が通らない。"}, {"text": "放棄", "is_correct": false, "explanation": "「体を放棄するために」は体を捨てる意味になり、文脈と合わない。"}, {"text": "普及", "is_correct": false, "explanation": "「体を普及させるために」は意味が合わない。"}], "explanations": {"強化": "「体を強化するために」で、体を丈夫にする意味になる。", "中断": "「体を中断するために」は意味が通らない。", "放棄": "「体を放棄するために」は体を捨てる意味になり、文脈と合わない。", "普及": "「体を普及させるために」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "強化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湿気で菌を強化させてしまった。", "explanation": "ここは〈増殖〉の意味。菌が増えることを強化とは言わない。"}, {"text": "会議の時間を強化した。", "explanation": "ここは〈延長〉の意味。強化は力を強める意味で、時間を長くする意味は持たない。"}, {"text": "冷凍の肉を強化した。", "explanation": "ここは〈解凍〉の意味。強化は力を強めることで、凍った物を溶かす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38212, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の大会に向けて、チームは守りの強化が急いでいる。", "corrected_sentence": "夏の大会に向けて、チームは守りの強化を急いでいる。", "error_description": "「強化を急ぐ」の助詞は「を」。「が」にすると、「急ぐ」の対象として不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38212, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は橋の強化に急ぎ、業者を増やした。", "corrected_sentence": "町は橋の強化を急ぎ、業者を増やした。", "error_description": "「強化を急ぐ」の助詞は「を」。「に」にすると、「急ぐ」の対象として誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38213, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「強化で合意した」で、合意の内容を示す。"}, {"text": "を", "is_correct": false, "explanation": "「強化を合意した」は他動詞の目的語のように続き、不自然。"}, {"text": "が", "is_correct": false, "explanation": "「強化が合意した」は主語の形で、文の意味が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「強化の合意した」は連体の形が動詞に続かず誤り。"}], "correct_answer": "で", "explanations": {"で": "「強化で合意した」で、合意の内容を示す。", "を": "「強化を合意した」は他動詞の目的語のように続き、不自然。", "が": "「強化が合意した」は主語の形で、文の意味が合わない。", "の": "「強化の合意した」は連体の形が動詞に続かず誤り。"}, "error_tags": {"で": "内容", "を": "目的語", "が": "主語", "の": "連体"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱化", "is_correct": true, "explanation": "「弱化」は力を弱めることで、力を強める「強化」の対義語として辞書に並ぶ。"}, {"text": "維持", "is_correct": false, "explanation": "「維持」は今の状態を保つ意味で、強化の対義語ではない。"}, {"text": "停滞", "is_correct": false, "explanation": "「停滞」は進まなくなる意味で、強化の対義語としては並ばない。"}, {"text": "普及", "is_correct": false, "explanation": "「普及」は広く行き渡る意味で、強化の対義語ではない。"}], "correct_answer": "弱化", "explanations": {"弱化": "「弱化」は力を弱めることで、力を強める「強化」の対義語として辞書に並ぶ。", "維持": "「維持」は今の状態を保つ意味で、強化の対義語ではない。", "停滞": "「停滞」は進まなくなる意味で、強化の対義語としては並ばない。", "普及": "「普及」は広く行き渡る意味で、強化の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38213, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「強化を目的に」で、強化を目的語として示す。"}, {"text": "で", "is_correct": false, "explanation": "「強化で目的に」は手段の形になり、目的を示す文と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「強化へ目的に」は方向を示すが、目的を表す文では不自然。"}, {"text": "から", "is_correct": false, "explanation": "「強化から目的に」は起点を示すので、目的を表す文と合わない。"}], "correct_answer": "を", "explanations": {"を": "「強化を目的に」で、強化を目的語として示す。", "で": "「強化で目的に」は手段の形になり、目的を示す文と合わない。", "へ": "「強化へ目的に」は方向を示すが、目的を表す文では不自然。", "から": "「強化から目的に」は起点を示すので、目的を表す文と合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱化", "is_correct": true, "explanation": "「弱化」は力を弱めることで、強める「強化」の対義語として辞書に並ぶ。"}, {"text": "継続", "is_correct": false, "explanation": "「継続」は続けることで、強化の対義語ではない。"}, {"text": "縮小", "is_correct": false, "explanation": "「縮小」は規模を小さくする意味で、強化の対義語としては並ばない。"}, {"text": "廃止", "is_correct": false, "explanation": "「廃止」はやめてなくす意味で、強化の対義語ではない。"}], "correct_answer": "弱化", "explanations": {"弱化": "「弱化」は力を弱めることで、強める「強化」の対義語として辞書に並ぶ。", "継続": "「継続」は続けることで、強化の対義語ではない。", "縮小": "「縮小」は規模を小さくする意味で、強化の対義語としては並ばない。", "廃止": "「廃止」はやめてなくす意味で、強化の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38213, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の力を、より強く、しっかりしたものにすること。", "primary_collocate": null, "pronunciation": "きょうか", "ipa": "kʲoːka", "syllable_count": 3, "sentences": [{"text": "会社は、新しい商品の開発力の強化を急いでいる。", "target_word": "強化", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、新[あたら]しい商品[しょうひん]の開発力[かいはつりょく]の強化[きょうか]を急[いそ]いでいる。", "sentence_source": "generated"}, {"text": "両国は、協力関係の強化で合意した。", "target_word": "強化", "complexity_tier": "T3", "furigana": "両国[りょうこく]は、協力[きょうりょく]関係[かんけい]の強化[きょうか]で合意[ごうい]した。", "sentence_source": "generated"}, {"text": "先生は、基礎の強化が大切だと言った。", "target_word": "強化", "complexity_tier": "T3", "furigana": "先生[せんせい]は、基礎[きそ]の強化[きょうか]が大切[たいせつ]だと言[い]った。", "sentence_source": "generated"}, {"text": "市は子育て支援の強化を発表した。", "target_word": "強化", "complexity_tier": "T3", "furigana": "市[し]は子育[こそだ]て支援[しえん]の強化[きょうか]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "規則の強化で、不正はかなり減った。", "target_word": "強化", "complexity_tier": "T3", "furigana": "規則[きそく]の強化[きょうか]で、不正[ふせい]はかなり減[へ]った。", "sentence_source": "generated"}, {"text": "夜の警戒体制を強化したところ、犯罪が減った。", "target_word": "強化", "complexity_tier": "T3", "furigana": "夜[よる]の警戒[けいかい]体制[たいせい]を強化[きょうか]したところ、犯罪[はんざい]が減[へ]った。", "sentence_source": "generated"}, {"text": "輸出を伸ばすため、国は研究の強化に力を入れている。", "target_word": "強化", "complexity_tier": "T3", "furigana": "輸出[ゆしゅつ]を伸[の]ばすため、国[くに]は研究[けんきゅう]の強化[きょうか]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "チームワークの強化を目的に、合宿を行った。", "target_word": "強化", "complexity_tier": "T3", "furigana": "チームワークの強化[きょうか]を目的[もくてき]に、合宿[がっしゅく]を行[おこな]った。", "sentence_source": "generated"}, {"text": "弱かった連携を強化して、今季は勝てるようになった。", "target_word": "強化", "complexity_tier": "T3", "furigana": "弱[よわ]かった連携[れんけい]を強化[きょうか]して、今季[こんき]は勝[か]てるようになった。", "sentence_source": "generated"}, {"text": "環境を守る法律が強化され、工場は排水に気をつけている。", "target_word": "強化", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]る法律[ほうりつ]が強化[きょうか]され、工場[こうじょう]は排水[はいすい]に気[き]をつけている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強化する", "label": "辞書形(する動詞)"}, {"form": "強化した", "label": "過去形"}, {"form": "強化される", "label": "受身形"}, {"form": "強化しない", "label": "否定形"}], "register": "中立(普通体)", "sense_fingerprint": "関係・制度・取り組みなど抽象的な物事の力や体制を強めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38213, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強化", "is_correct": true, "explanation": "「開発力の強化」は能力を高める意味で、文の内容と合う。"}, {"text": "延期", "is_correct": false, "explanation": "「開発力の延期」は能力を後回しにする意味で、文の内容と合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "「撤回」は取り消す意味で、開発力には使わない。"}, {"text": "放棄", "is_correct": false, "explanation": "「放棄」は手放す意味で、開発力を急ぐ文脈と逆になる。"}], "explanations": {"強化": "「開発力の強化」は能力を高める意味で、文の内容と合う。", "延期": "「開発力の延期」は能力を後回しにする意味で、文の内容と合わない。", "撤回": "「撤回」は取り消す意味で、開発力には使わない。", "放棄": "「放棄」は手放す意味で、開発力を急ぐ文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "強化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市は給食の分量を強化した。", "explanation": "ここは〈減量〉の意味。強化は力を強める意味で、分量を減らす意味は持たない。"}, {"text": "市は古いデータを強化して、すべて消した。", "explanation": "ここは〈削除〉の意味。強化は力を強める意味で、データを消す意味にはならない。"}, {"text": "先生は答案の強化を終えた。", "explanation": "ここは〈採点〉の意味。強化は力を強める意味で、答案に点数をつける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38213, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強化", "is_correct": true, "explanation": "「研究の強化に力を入れている」で、研究を強める意味になり文脈と合う。"}, {"text": "中止", "is_correct": false, "explanation": "「研究の中止に力を入れる」は意味が逆になり不自然。"}, {"text": "廃止", "is_correct": false, "explanation": "「研究の廃止に力を入れる」は文脈の輸出促進と逆になる。"}, {"text": "軽視", "is_correct": false, "explanation": "「研究の軽視に力を入れる」は矛盾し、不自然。"}], "explanations": {"強化": "「研究の強化に力を入れている」で、研究を強める意味になり文脈と合う。", "中止": "「研究の中止に力を入れる」は意味が逆になり不自然。", "廃止": "「研究の廃止に力を入れる」は文脈の輸出促進と逆になる。", "軽視": "「研究の軽視に力を入れる」は矛盾し、不自然。"}, "sentence_index": 6, "correct_answer": "強化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友人に急いでメールを強化した。", "explanation": "ここは〈送信〉の意味。強化は力を強める意味で、メールを相手に送る意味にはならない。"}, {"text": "レストランの席を強化した。", "explanation": "ここは〈予約〉の意味。強化は力を強める意味で、席を取っておく意味はない。"}, {"text": "本を英語に強化した。", "explanation": "ここは〈翻訳〉の意味。強化は力を強める意味で、ほかの言語に訳す意味は持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38213, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "両国は協力関係の強化が約束した。", "corrected_sentence": "両国は協力関係の強化を約束した。", "error_description": "「約束する」は「を」を取る。「が」にすると、「約束した」の目的語として誤りになる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38213, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "町は子育て支援の強化に急ぎ、予算を増やした。", "corrected_sentence": "町は子育て支援の強化を急ぎ、予算を増やした。", "error_description": "「強化を急ぐ」の助詞は「を」。「に」にすると、「急ぐ」の対象として誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38214, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「政府の人」の「の」は所属を表し、「政府の人が」という主語を作る。"}, {"text": "を", "is_correct": false, "explanation": "「政府を人が」は「を」が目的語になり、人が政府に何かをするという文になって不自然。"}, {"text": "に", "is_correct": false, "explanation": "「政府に人が」は相手や帰着を表す「に」で、所属を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「政府より人が」は比較の「より」で比べる対象が必要だが、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「政府の人」の「の」は所属を表し、「政府の人が」という主語を作る。", "を": "「政府を人が」は「を」が目的語になり、人が政府に何かをするという文になって不自然。", "に": "「政府に人が」は相手や帰着を表す「に」で、所属を示せない。", "より": "「政府より人が」は比較の「より」で比べる対象が必要だが、文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "相手・帰着", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38214, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「政府が〜発表した」の主語を示す「が」。政府が発表する主体になる。"}, {"text": "を", "is_correct": false, "explanation": "「政府をお米の値段について発表した」は発表の対象が政府になり、主語として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「政府のお米の値段について発表した」は述語の主語が立たず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「政府でお米の値段について発表した」は場所や手段を示し、発表の主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「政府が〜発表した」の主語を示す「が」。政府が発表する主体になる。", "を": "「政府をお米の値段について発表した」は発表の対象が政府になり、主語として成り立たない。", "の": "「政府のお米の値段について発表した」は述語の主語が立たず、文が成り立たない。", "で": "「政府でお米の値段について発表した」は場所や手段を示し、発表の主語にならない。"}, "error_tags": {"を": "目的語", "へ": "方向・相手", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38214, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くにの しくみを うごかす たくさんの ひとの グループです。", "primary_collocate": null, "pronunciation": "せいふ", "ipa": "seːɸɯ", "syllable_count": 3, "sentences": [{"text": "政府は、国のために新しい道を作ると決めた。", "target_word": "政府", "complexity_tier": "T3", "furigana": "政府(せいふ)は、国(くに)のために新(あたら)しい道(みち)を作(つく)ると決(き)めた。", "sentence_source": "generated"}, {"text": "政府の人が、テレビで大切な話をした。", "target_word": "政府", "complexity_tier": "T3", "furigana": "政府(せいふ)の人(ひと)が、テレビで大切(たいせつ)な話(はなし)をした。", "sentence_source": "generated"}, {"text": "日本の政府の中心は、東京にある。", "target_word": "政府", "complexity_tier": "T3", "furigana": "日本(にほん)の政府(せいふ)の中心(ちゅうしん)は、東京(とうきょう)にある。", "sentence_source": "generated"}, {"text": "政府が学校にお金を出すので、子どもは安心して勉強できる。", "target_word": "政府", "complexity_tier": "T3", "furigana": "政府(せいふ)が学校(がっこう)にお金(かね)を出(だ)すので、子(こ)どもは安心(あんしん)して勉強(べんきょう)できる。", "sentence_source": "generated"}, {"text": "大雨のとき、政府は人々に早くにげるよう伝えた。", "target_word": "政府", "complexity_tier": "T3", "furigana": "大雨(おおあめ)のとき、政府(せいふ)は人々(ひとびと)に早(はや)くにげるよう伝(つた)えた。", "sentence_source": "generated"}, {"text": "政府で働く人たちは、国のしくみを動かしている。", "target_word": "政府", "complexity_tier": "T3", "furigana": "政府(せいふ)で働(はたら)く人(ひと)たちは、国(くに)のしくみを動(うご)かしている。", "sentence_source": "generated"}, {"text": "兄は将来、政府で働きたいと言っている。", "target_word": "政府", "complexity_tier": "T3", "furigana": "兄(あに)は将来(しょうらい)、政府(せいふ)で働(はたら)きたいと言(い)っている。", "sentence_source": "generated"}, {"text": "政府がお米の値段について発表した。", "target_word": "政府", "complexity_tier": "T3", "furigana": "政府(せいふ)がお米(こめ)の値段(ねだん)について発表(はっぴょう)した。", "sentence_source": "generated"}, {"text": "新しい政府ができてから、町の様子が少し変わった。", "target_word": "政府", "complexity_tier": "T3", "furigana": "新(あたら)しい政府(せいふ)ができてから、町(まち)の様子(ようす)が少(すこ)し変(か)わった。", "sentence_source": "generated"}, {"text": "先生は、政府が何をしているのかを、教室で教えてくれた。", "target_word": "政府", "complexity_tier": "T3", "furigana": "先生(せんせい)は、政府(せいふ)が何(なに)をしているのかを、教室(きょうしつ)で教(おし)えてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "政府", "label": "基本形"}], "register": "中立（やさしい説明・普通体）", "sense_fingerprint": "国を動かす人々の集まりとしての政府", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: contains vocabulary far above tier T1: にげる (Zipf 2.35)']::text[], '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38214, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政府", "is_correct": true, "explanation": "「決めた」の主語になれるのは、国の政策を決める組織である政府だけ。文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は道を作る決定をしないので、「決めた」の主語にならない。"}, {"text": "果物", "is_correct": false, "explanation": "果物は決断する主体ではないため、「国のために新しい道を作ると決めた」が成り立たない。"}, {"text": "写真", "is_correct": false, "explanation": "写真は意思を持って決めることができず、主語として不自然。"}], "explanations": {"政府": "「決めた」の主語になれるのは、国の政策を決める組織である政府だけ。文の意味に合う。", "天気": "天気は道を作る決定をしないので、「決めた」の主語にならない。", "果物": "果物は決断する主体ではないため、「国のために新しい道を作ると決めた」が成り立たない。", "写真": "写真は意思を持って決めることができず、主語として不自然。"}, "sentence_index": 0, "correct_answer": "政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選挙で勝った党が政府を握り、首相を選んだ。", "explanation": "ここは〈政権〉の意味。権力を得ることは政権を握ると言い、政府は組織なので握るとは言わず合わない。"}, {"text": "日本という政府は、四季の美しさで知られる。", "explanation": "ここは〈国家〉の意味。国家は国土と国民を含むので四季の景色で知られる。政府は統治組織で、土地の特徴を持たないので合わない。"}, {"text": "その政府は、私が大学時代から付き合っている友人だ。", "explanation": "ここは〈知人〉の意味。付き合いの相手になるのは人だが、政府は人ではなく組織なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38214, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政府", "is_correct": true, "explanation": "「働きたい」の勤め先になれるのは組織である政府。文の意味に合う。"}, {"text": "卵", "is_correct": false, "explanation": "卵は働く場所にならないので、「政府で働きたい」の空所に入らない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は勤め先にならず、「働きたい」の場所として成り立たない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは働く場所を表さないので、文として成り立たない。"}], "explanations": {"政府": "「働きたい」の勤め先になれるのは組織である政府。文の意味に合う。", "卵": "卵は働く場所にならないので、「政府で働きたい」の空所に入らない。", "花瓶": "花瓶は勤め先にならず、「働きたい」の場所として成り立たない。", "夕焼け": "夕焼けは働く場所を表さないので、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府の議員は、国民の選挙で選ばれる。", "explanation": "ここは〈国会〉の意味。議員は国会に属し、政府には議員がいないので合わない。"}, {"text": "あの政府は、築五十年の古い木造住宅だ。", "explanation": "ここは〈家〉の意味。政府は建物ではないので、住宅を指す文には合わない。"}, {"text": "政府は、子どもが静かに本を読める場所だ。", "explanation": "ここは〈図書館〉の意味。図書館は本を読む場所だが、政府は読書をする施設ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38214, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府に人が、テレビで大切な話をしたそうだ。", "corrected_sentence": "政府の人が、テレビで大切な話をしたそうだ。", "error_description": "「政府の人」は政府に所属する人を表すので「の」が必要。「に」にすると『政府に人が』となり、所属の意味が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38214, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は将来、政府を働きたいと言っているそうだ。", "corrected_sentence": "兄は将来、政府で働きたいと言っているそうだ。", "error_description": "働く場所や勤め先は「で」で示す。「を」にすると『政府を働く』となり、働く場所として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38215, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「政府の外交方針」の「の」は所属を表し、政府の方針という意味になる。"}, {"text": "を", "is_correct": false, "explanation": "「政府を外交方針をめぐって」は『を』が目的語になり、政府を対象とする意味になって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「政府へ外交方針をめぐって」は向かう先を示すが、方針を修飾する形にならない。"}, {"text": "より", "is_correct": false, "explanation": "「政府より外交方針をめぐって」は比較の「より」で比べる対象がなく、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「政府の外交方針」の「の」は所属を表し、政府の方針という意味になる。", "を": "「政府を外交方針をめぐって」は『を』が目的語になり、政府を対象とする意味になって不自然。", "へ": "「政府へ外交方針をめぐって」は向かう先を示すが、方針を修飾する形にならない。", "より": "「政府より外交方針をめぐって」は比較の「より」で比べる対象がなく、文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38215, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「政府が法律を定めることで」の主語を示す「が」。政府が法律を定める主体になる。"}, {"text": "に", "is_correct": false, "explanation": "「政府に法律を定めることで」は相手や対象を示し、政府が法律を定める主体にならない。"}, {"text": "を", "is_correct": false, "explanation": "「政府を法律を定める」は目的語が二つ重なり、文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「政府へ法律を定める」は向かう先を示すが、政府が法律を定める主体にはならない。"}], "correct_answer": "が", "explanations": {"が": "「政府が法律を定めることで」の主語を示す「が」。政府が法律を定める主体になる。", "に": "「政府に法律を定めることで」は相手や対象を示し、政府が法律を定める主体にならない。", "を": "「政府を法律を定める」は目的語が二つ重なり、文として不自然。", "へ": "「政府へ法律を定める」は向かう先を示すが、政府が法律を定める主体にはならない。"}, "error_tags": {"に": "相手・対象", "を": "目的語", "へ": "方向・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38215, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や地域の政治を行う組織。法律や税金、外交など、社会全体のルールを決めたり、公共のサービスを提供したりする仕組み。", "primary_collocate": null, "pronunciation": "せいふ", "ipa": "seːɸɯ", "syllable_count": 3, "sentences": [{"text": "政府は来年度から、新しい税制を導入する方針を発表した。", "target_word": "政府", "complexity_tier": "T4", "furigana": "政府(せいふ)は来年度(らいねんど)から、新(あたら)しい税制(ぜいせい)を導入(どうにゅう)する方針(ほうしん)を発表(はっぴょう)した。", "sentence_source": "generated"}, {"text": "政府の外交方針をめぐって、国会で議論が続いている。", "target_word": "政府", "complexity_tier": "T4", "furigana": "政府(せいふ)の外交(がいこう)方針(ほうしん)をめぐって、国会(こっかい)で議論(ぎろん)が続(つづ)いている。", "sentence_source": "generated"}, {"text": "政府が公共サービスを提供するためには、税金が欠かせない。", "target_word": "政府", "complexity_tier": "T4", "furigana": "政府(せいふ)が公共(こうきょう)サービスを提供(ていきょう)するためには、税金(ぜいきん)が欠(か)かせない。", "sentence_source": "generated"}, {"text": "災害が起きた地域に、政府は支援金を送ることを決めた。", "target_word": "政府", "complexity_tier": "T4", "furigana": "災害(さいがい)が起(お)きた地域(ちいき)に、政府(せいふ)は支援金(しえんきん)を送(おく)ることを決(き)めた。", "sentence_source": "generated"}, {"text": "政府と地方自治体が協力して、人口減少への対策を進めている。", "target_word": "政府", "complexity_tier": "T4", "furigana": "政府(せいふ)と地方(ちほう)自治体(じちたい)が協力(きょうりょく)して、人口(じんこう)減少(げんしょう)への対策(たいさく)を進(すす)めている。", "sentence_source": "generated"}, {"text": "政府の政策に賛成する人もいれば、反対する人もいる。", "target_word": "政府", "complexity_tier": "T4", "furigana": "政府(せいふ)の政策(せいさく)に賛成(さんせい)する人(ひと)もいれば、反対(はんたい)する人(ひと)もいる。", "sentence_source": "generated"}, {"text": "各国の政府は、環境問題を解決するために会議を開いた。", "target_word": "政府", "complexity_tier": "T4", "furigana": "各国(かっこく)の政府(せいふ)は、環境(かんきょう)問題(もんだい)を解決(かいけつ)するために会議(かいぎ)を開(ひら)いた。", "sentence_source": "generated"}, {"text": "政府が法律を定めることで、社会のルールが守られる。", "target_word": "政府", "complexity_tier": "T4", "furigana": "政府(せいふ)が法律(ほうりつ)を定(さだ)めることで、社会(しゃかい)のルールが守(まも)られる。", "sentence_source": "generated"}, {"text": "政府の予算案は、国会で審議されてから決まる。", "target_word": "政府", "complexity_tier": "T4", "furigana": "政府(せいふ)の予算案(よさんあん)は、国会(こっかい)で審議(しんぎ)されてから決(き)まる。", "sentence_source": "generated"}, {"text": "隣国の政府との話し合いは、来月から始まる。", "target_word": "政府", "complexity_tier": "T4", "furigana": "隣国(りんごく)の政府(せいふ)との話(はな)し合(あ)いは、来月(らいげつ)から始(はじ)まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "政府", "label": "基本形"}], "register": "文章語（硬め・報道や政治の文脈）", "sense_fingerprint": "法律・税・外交・公共サービスを担う統治組織・仕組みとしての政府", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38215, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政府", "is_correct": true, "explanation": "税制の方針を発表する主体になれるのは政府。文の意味に合う。"}, {"text": "花火", "is_correct": false, "explanation": "花火は方針を発表する主体にならないので、文として成り立たない。"}, {"text": "電車", "is_correct": false, "explanation": "電車は税制の方針を発表しないので、主語として合わない。"}, {"text": "味噌", "is_correct": false, "explanation": "味噌は方針を発表する主体ではないため、文の主語にならない。"}], "explanations": {"政府": "税制の方針を発表する主体になれるのは政府。文の意味に合う。", "花火": "花火は方針を発表する主体にならないので、文として成り立たない。", "電車": "電車は税制の方針を発表しないので、主語として合わない。", "味噌": "味噌は方針を発表する主体ではないため、文の主語にならない。"}, "sentence_index": 0, "correct_answer": "政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その政府は、毎年新しい商品を発売している。", "explanation": "ここは〈企業〉の意味。商品を売り出す主体は企業で、政府は商品を発売しないので合わない。"}, {"text": "政府は、選挙で投票して政治に参加する。", "explanation": "ここは〈国民〉の意味。投票して政治に参加するのは国民で、政府が投票の主体になるとは言わない。"}, {"text": "政府は、朝早く役所に出勤する。", "explanation": "ここは〈公務員〉の意味。役所に出勤するのは人で、組織である政府には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38215, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政府", "is_correct": true, "explanation": "環境問題の会議を開く主体になれるのは政府。文の意味に合う。"}, {"text": "梅干し", "is_correct": false, "explanation": "梅干しは会議を開く主体にならないので、文として成り立たない。"}, {"text": "本棚", "is_correct": false, "explanation": "本棚は会議を開かないので、主語として合わない。"}, {"text": "祭り", "is_correct": false, "explanation": "祭りは環境問題の会議を開く主体ではないので、文の意味が通らない。"}], "explanations": {"政府": "環境問題の会議を開く主体になれるのは政府。文の意味に合う。", "梅干し": "梅干しは会議を開く主体にならないので、文として成り立たない。", "本棚": "本棚は会議を開かないので、主語として合わない。", "祭り": "祭りは環境問題の会議を開く主体ではないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日の政府は、午後から雨が降るらしい。", "explanation": "ここは〈天気〉の意味。空模様を述べる語で、組織である政府には合わない。"}, {"text": "政府は川に沿って細長く広がっている。", "explanation": "ここは〈町〉の意味。町は地域として川沿いに広がるが、統治組織の政府は地面を持たないので合わない。"}, {"text": "政府は、夜も開いている救急の窓口がある。", "explanation": "ここは〈病院〉の意味。救急の窓口を持つのは医療機関で、政府は窓口を持つ施設ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38215, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府を方針は、来年度から新しい税制を導入することだ。", "corrected_sentence": "政府の方針は、来年度から新しい税制を導入することだ。", "error_description": "「政府の方針」の「の」を「を」にすると『政府を方針』となり、方針を修飾できない。「の」で所属を示す必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38215, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "隣国の政府を話し合いは、来月から始まるそうだ。", "corrected_sentence": "隣国の政府との話し合いは、来月から始まるそうだ。", "error_description": "話し合いの相手は「との」で示す。「を」にすると『政府を話し合い』となり、話し合う相手として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
