INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38216, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "これは、人々が一緒に仕事をしたり、何かを作ったりするための計画や活動のことです。", "primary_collocate": null, "pronunciation": "ぷろじぇくと", "ipa": "puɾod͡ʑekɯto", "syllable_count": 5, "sentences": [{"text": "学校でプロジェクトをしました。", "target_word": "プロジェクト", "complexity_tier": "T2", "furigana": "学校[がっこう]でプロジェクトをしました。", "sentence_source": "generated"}, {"text": "みんなでプロジェクトを作ります。", "target_word": "プロジェクト", "complexity_tier": "T2", "furigana": "みんなでプロジェクトを作[つく]ります。", "sentence_source": "generated"}, {"text": "このプロジェクトは楽しいです。", "target_word": "プロジェクト", "complexity_tier": "T2", "furigana": "このプロジェクトは楽[たの]しいです。", "sentence_source": "generated"}, {"text": "友だちと一緒に、新しいプロジェクトを考えた。", "target_word": "プロジェクト", "complexity_tier": "T3", "furigana": "友[とも]だちと一緒[いっしょ]に、新[あたら]しいプロジェクトを考[かんが]えた。", "sentence_source": "generated"}, {"text": "夏休みに、クラスでプロジェクトを始めた。", "target_word": "プロジェクト", "complexity_tier": "T3", "furigana": "夏休[なつやす]みに、クラスでプロジェクトを始[はじ]めた。", "sentence_source": "generated"}, {"text": "プロジェクトに参加して、いろいろなことを学んだ。", "target_word": "プロジェクト", "complexity_tier": "T3", "furigana": "プロジェクトに参加[さんか]して、いろいろなことを学[まな]んだ。", "sentence_source": "generated"}, {"text": "このプロジェクトでは、住民が協力して公園を作る。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "このプロジェクトでは、住民[じゅうみん]が協力[きょうりょく]して公園[こうえん]を作[つく]る。", "sentence_source": "generated"}, {"text": "プロジェクトが成功したのは、みんなが助け合ったからだ。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "プロジェクトが成功[せいこう]したのは、みんなが助[たす]け合[あ]ったからだ。", "sentence_source": "generated"}, {"text": "私はプロジェクトのメンバーになりたい。", "target_word": "プロジェクト", "complexity_tier": "T3", "furigana": "私[わたし]はプロジェクトのメンバーになりたい。", "sentence_source": "generated"}, {"text": "小さなプロジェクトから始めて、少しずつ仲間を増やしていった。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "小[ちい]さなプロジェクトから始[はじ]めて、少[すこ]しずつ仲間[なかま]を増[ふ]やしていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プロジェクトチーム", "label": "派生"}, {"form": "プロジェクトリーダー", "label": "派生"}, {"form": "プロジェクト名", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人々が協力して進める計画や活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
