INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38217, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の目標を達成するために計画された一連の作業や活動のこと。", "primary_collocate": null, "pronunciation": "ぷろじぇくと", "ipa": "puɾod͡ʑekɯto", "syllable_count": 5, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "プロジェクト", "complexity_tier": "T6", "furigana": "近年[きんねん]、都市[とし]の無秩序[むちつじょ]な拡大[かくだい]に伴[ともな]う緑[みどり]の希薄化[きはくか]に歯止[はど]めをかけるべく、地域[ちいき]コミュニティガーデンプロジェクトが各地[かくち]で顕在化[けんざいか]している。", "sentence_source": "mined"}, {"text": "新しいプロジェクトが始まります。", "target_word": "プロジェクト", "complexity_tier": "T2", "furigana": "新[あたら]しいプロジェクトが始[はじ]まります。", "sentence_source": "generated"}, {"text": "私もそのプロジェクトに入りました。", "target_word": "プロジェクト", "complexity_tier": "T2", "furigana": "私[わたし]もそのプロジェクトに入[はい]りました。", "sentence_source": "generated"}, {"text": "彼はプロジェクトのリーダーを任されている。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "彼[かれ]はプロジェクトのリーダーを任[まか]されている。", "sentence_source": "generated"}, {"text": "プロジェクトを成功させて、皆で喜んだ。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "プロジェクトを成功[せいこう]させて、皆[みな]で喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "町の人たちと、緑を増やすプロジェクトに参加した。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "町[まち]の人[ひと]たちと、緑[みどり]を増[ふ]やすプロジェクトに参加[さんか]した。", "sentence_source": "generated"}, {"text": "プロジェクトの予算が足りなくなってきた。", "target_word": "プロジェクト", "complexity_tier": "T3", "furigana": "プロジェクトの予算[よさん]が足[た]りなくなってきた。", "sentence_source": "generated"}, {"text": "このプロジェクトが終われば、少し休めるだろう。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "このプロジェクトが終[お]われば、少[すこ]し休[やす]めるだろう。", "sentence_source": "generated"}, {"text": "地域の若者が中心となって進めてきたプロジェクトが、ようやく実を結んだ。", "target_word": "プロジェクト", "complexity_tier": "T5", "furigana": "地域[ちいき]の若者[わかもの]が中心[ちゅうしん]となって進[すす]めてきたプロジェクトが、ようやく実[み]を結[むす]んだ。", "sentence_source": "generated"}, {"text": "プロジェクトは予定より遅れていたが、無事に完了した。", "target_word": "プロジェクト", "complexity_tier": "T4", "furigana": "プロジェクトは予定[よてい]より遅[おく]れていたが、無事[ぶじ]に完了[かんりょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プロジェクトチーム", "label": "派生"}, {"form": "プロジェクトリーダー", "label": "派生"}, {"form": "プロジェクト名", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目標のために計画された一連の作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)']::text[], 'e3446334-3278-4fc4-9bdd-c73ba1cb63db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38217, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プロジェクト", "is_correct": true, "explanation": "各地で広がる計画的な活動を指し、文脈に合う。"}, {"text": "試験", "is_correct": false, "explanation": "形は合うが、ガーデン試験が顕在化するのは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、ガーデン天気では意味が合わない。"}, {"text": "住所", "is_correct": false, "explanation": "形は合うが、ガーデン住所では意味が合わない。"}], "explanations": {"プロジェクト": "各地で広がる計画的な活動を指し、文脈に合う。", "試験": "形は合うが、ガーデン試験が顕在化するのは意味が合わない。", "天気": "形は合うが、ガーデン天気では意味が合わない。", "住所": "形は合うが、ガーデン住所では意味が合わない。"}, "sentence_index": 0, "correct_answer": "プロジェクト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は昨日プロジェクトを飲んで、ぐっすり眠った。", "explanation": "プロジェクトは飲めるものではなく、意味が合わない。"}, {"text": "プロジェクトは大きくて、赤い色をした犬だ。", "explanation": "プロジェクトは計画や活動で、動物ではない。"}, {"text": "駅のプロジェクトに乗って、会社へ行った。", "explanation": "プロジェクトは乗り物ではなく、使い方が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdd1eb35-6239-471f-aa8a-a57685d69515') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
