INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38218, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを自分から進んで行うこと。", "primary_collocate": null, "pronunciation": "せっきょく", "ipa": "sekkʲoku", "syllable_count": 4, "sentences": [{"text": "消極ではなく積極の姿勢で臨むことが、成功への近道だ。", "target_word": "積極", "complexity_tier": "T3", "furigana": "消極[しょうきょく]ではなく積極[せっきょく]の姿勢[しせい]で臨[のぞ]むことが、成功[せいこう]への近道[ちかみち]だ。", "sentence_source": "generated"}, {"text": "守りの戦い方から積極の姿勢に転じて、試合の流れを変えた。", "target_word": "積極", "complexity_tier": "T3", "furigana": "守[まも]りの戦[たたか]い方[かた]から積極[せっきょく]の姿勢[しせい]に転[てん]じて、試合[しあい]の流[なが]れを変[か]えた。", "sentence_source": "generated"}, {"text": "会議では積極の姿勢で意見を出すようにしている。", "target_word": "積極", "complexity_tier": "T3", "furigana": "会議[かいぎ]では積極[せっきょく]の姿勢[しせい]で意見[いけん]を出[だ]すようにしている。", "sentence_source": "generated"}, {"text": "新入社員は、わからないことを積極の姿勢で質問するべきだ。", "target_word": "積極", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]は、わからないことを積極[せっきょく]の姿勢[しせい]で質問[しつもん]するべきだ。", "sentence_source": "generated"}, {"text": "彼は消極でも積極でもなく、いつも様子を見ている。", "target_word": "積極", "complexity_tier": "T3", "furigana": "彼[かれ]は消極[しょうきょく]でも積極[せっきょく]でもなく、いつも様子[ようす]を見[み]ている。", "sentence_source": "generated"}, {"text": "試験前は積極の姿勢で先生に質問して、不安をなくした。", "target_word": "積極", "complexity_tier": "T3", "furigana": "試験前[しけんまえ]は積極[せっきょく]の姿勢[しせい]で先生[せんせい]に質問[しつもん]して、不安[ふあん]をなくした。", "sentence_source": "generated"}, {"text": "地域の行事に積極の姿勢で参加して、友達が増えた。", "target_word": "積極", "complexity_tier": "T3", "furigana": "地域[ちいき]の行事[ぎょうじ]に積極[せっきょく]の姿勢[しせい]で参加[さんか]して、友達[ともだち]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "積極と消極を比べると、積極のほうが失敗を恐れない。", "target_word": "積極", "complexity_tier": "T3", "furigana": "積極[せっきょく]と消極[しょうきょく]を比[くら]べると、積極[せっきょく]のほうが失敗[しっぱい]を恐[おそ]れない。", "sentence_source": "generated"}, {"text": "受け身をやめて、積極の姿勢で仕事を探し始めた。", "target_word": "積極", "complexity_tier": "T3", "furigana": "受[う]け身[み]をやめて、積極[せっきょく]の姿勢[しせい]で仕事[しごと]を探[さが]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "積極の姿勢で挨拶をしたら、近所の人とすぐ親しくなった。", "target_word": "積極", "complexity_tier": "T3", "furigana": "積極[せっきょく]の姿勢[しせい]で挨拶[あいさつ]をしたら、近所[きんじょ]の人[ひと]とすぐ親[した]しくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "積極的", "label": "形容動詞的な形"}, {"form": "積極に", "label": "連用の形"}, {"form": "積極と消極", "label": "対にした形"}], "register": "中立(普通体)", "sense_fingerprint": "消極の反対。ためらわず自分から進んで行動に出ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38218, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "積極", "is_correct": true, "explanation": "「積極の姿勢で臨む」で、自分から進んで取り組む態度の意味に合う。"}, {"text": "積極的", "is_correct": false, "explanation": "「積極的の姿勢」と連体で続けるのは誤り。"}, {"text": "積極に", "is_correct": false, "explanation": "「積極に姿勢」は副詞の形で、姿勢に続かない。"}, {"text": "無謀", "is_correct": false, "explanation": "「無謀の姿勢で臨む」は向こう見ずの意味になり、成功への近道とは合わない。"}], "explanations": {"積極": "「積極の姿勢で臨む」で、自分から進んで取り組む態度の意味に合う。", "積極的": "「積極的の姿勢」と連体で続けるのは誤り。", "積極に": "「積極に姿勢」は副詞の形で、姿勢に続かない。", "無謀": "「無謀の姿勢で臨む」は向こう見ずの意味になり、成功への近道とは合わない。"}, "sentence_index": 0, "correct_answer": "積極"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日の積極が力になった。", "explanation": "ここは〈積み重ね〉の意味。積極は自分から進んで行う態度で、日々の蓄積の意味にはならない。"}, {"text": "机の上の積極を片付けた。", "explanation": "ここは〈書類〉などの物を指す語ではない。積極は行動の態度を表すので、物には使わない。"}, {"text": "昨日の積極は雨で、一日中家にいた。", "explanation": "ここは〈天気〉の意味。積極は態度を表す語で、天候には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38218, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "積極", "is_correct": true, "explanation": "「地域の行事に積極の姿勢で参加して」で、進んで取り組む態度の意味に合う。"}, {"text": "無関心", "is_correct": false, "explanation": "「無関心の姿勢で参加して友達が増えた」は、関心のない態度と結果が合わず不自然。"}, {"text": "消極的", "is_correct": false, "explanation": "「消極的の姿勢」と連体で続けるのは誤り。"}, {"text": "受動的", "is_correct": false, "explanation": "「受動的の姿勢」と連体で続けるのは誤り。"}], "explanations": {"積極": "「地域の行事に積極の姿勢で参加して」で、進んで取り組む態度の意味に合う。", "無関心": "「無関心の姿勢で参加して友達が増えた」は、関心のない態度と結果が合わず不自然。", "消極的": "「消極的の姿勢」と連体で続けるのは誤り。", "受動的": "「受動的の姿勢」と連体で続けるのは誤り。"}, "sentence_index": 6, "correct_answer": "積極"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の積極の値段は高すぎて、誰も買えない。", "explanation": "ここは〈値段〉の意味。積極は態度を表す語で、値段を表す語ではない。"}, {"text": "寝坊して、彼は積極の時間に遅刻した。", "explanation": "ここは〈時刻〉の意味。積極は態度を表す語で、時間を指す語ではない。"}, {"text": "食べ過ぎを防ぐため、彼は積極の量を減らした。", "explanation": "ここは〈量〉を表す語ではない。積極は態度を表すので、食べる量には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38218, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "失敗を恐れず、積極を姿勢で新しい仕事に挑戦した。", "corrected_sentence": "失敗を恐れず、積極の姿勢で新しい仕事に挑戦した。", "error_description": "「積極の姿勢」の「の」が正しい。「を」にすると、「積極」が「姿勢」を修飾できず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38218, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "転職を考えて、積極が姿勢で面接を受けた。", "corrected_sentence": "転職を考えて、積極の姿勢で面接を受けた。", "error_description": "「積極の姿勢」の「の」が正しい。「が」にすると、「積極」が主語のように続き姿勢を修飾できず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38219, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消極", "is_correct": true, "explanation": "「消極」は自分から進んで行わない性格や態度を表し、「積極」の対義語として辞書に並ぶ。"}, {"text": "怠慢", "is_correct": false, "explanation": "「怠慢」は怠ける意味で、積極の対義語としては並ばない。"}, {"text": "放任", "is_correct": false, "explanation": "「放任」は任せて干渉しない意味で、積極の対義語ではない。"}, {"text": "中断", "is_correct": false, "explanation": "「中断」は途中でやめる意味で、積極の対義語ではない。"}], "correct_answer": "消極", "explanations": {"消極": "「消極」は自分から進んで行わない性格や態度を表し、「積極」の対義語として辞書に並ぶ。", "怠慢": "「怠慢」は怠ける意味で、積極の対義語としては並ばない。", "放任": "「放任」は任せて干渉しない意味で、積極の対義語ではない。", "中断": "「中断」は途中でやめる意味で、積極の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38219, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消極", "is_correct": true, "explanation": "「消極」は自分から進んで行わない態度を表し、「積極」の対義語として辞書に並ぶ。"}, {"text": "惰性", "is_correct": false, "explanation": "「惰性」は習慣で続ける意味で、積極の対義語ではない。"}, {"text": "静観", "is_correct": false, "explanation": "「静観」は動かずに見守る意味で、積極の対義語としては並ばない。"}, {"text": "停滞", "is_correct": false, "explanation": "「停滞」は進まなくなる意味で、積極の対義語としては並ばない。"}], "correct_answer": "消極", "explanations": {"消極": "「消極」は自分から進んで行わない態度を表し、「積極」の対義語として辞書に並ぶ。", "惰性": "「惰性」は習慣で続ける意味で、積極の対義語ではない。", "静観": "「静観」は動かずに見守る意味で、積極の対義語としては並ばない。", "停滞": "「停滞」は進まなくなる意味で、積極の対義語としては並ばない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38219, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "自分から進んで物事を行おうとする態度や行動のこと。", "primary_collocate": null, "pronunciation": "せっきょく", "ipa": "sekkʲoku", "syllable_count": 4, "sentences": [{"text": "彼の積極の姿勢を見て、周りの人も頑張ろうと思った。", "target_word": "積極", "complexity_tier": "T3", "furigana": "彼[かれ]の積極[せっきょく]の姿勢[しせい]を見[み]て、周[まわ]りの人[ひと]も頑張[がんば]ろうと思[おも]った。", "sentence_source": "generated"}, {"text": "積極の姿勢が見えない態度では、仕事は任せられない。", "target_word": "積極", "complexity_tier": "T3", "furigana": "積極[せっきょく]の姿勢[しせい]が見[み]えない態度[たいど]では、仕事[しごと]は任[まか]せられない。", "sentence_source": "generated"}, {"text": "面接では、積極の姿勢を見せることが大切だ。", "target_word": "積極", "complexity_tier": "T3", "furigana": "面接[めんせつ]では、積極[せっきょく]の姿勢[しせい]を見[み]せることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "失敗を恐れない積極の姿勢こそ、彼の一番の長所だ。", "target_word": "積極", "complexity_tier": "T3", "furigana": "失敗[しっぱい]を恐[おそ]れない積極[せっきょく]の姿勢[しせい]こそ、彼[かれ]の一番[いちばん]の長所[ちょうしょ]だ。", "sentence_source": "generated"}, {"text": "積極と慎重の両方があるから、彼女はよい上司だ。", "target_word": "積極", "complexity_tier": "T3", "furigana": "積極[せっきょく]と慎重[しんちょう]の両方[りょうほう]があるから、彼女[かのじょ]はよい上司[じょうし]だ。", "sentence_source": "generated"}, {"text": "子どもの積極の姿勢を育てるため、親は口を出しすぎない。", "target_word": "積極", "complexity_tier": "T3", "furigana": "子[こ]どもの積極[せっきょく]の姿勢[しせい]を育[そだ]てるため、親[おや]は口[くち]を出[だ]しすぎない。", "sentence_source": "generated"}, {"text": "最初は消極だったが、いまは積極の姿勢に変わった。", "target_word": "積極", "complexity_tier": "T3", "furigana": "最初[さいしょ]は消極[しょうきょく]だったが、いまは積極[せっきょく]の姿勢[しせい]に変[か]わった。", "sentence_source": "generated"}, {"text": "彼女は積極の姿勢で手を挙げて、発表を引き受けた。", "target_word": "積極", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は積極[せっきょく]の姿勢[しせい]で手[て]を挙[あ]げて、発表[はっぴょう]を引[ひ]き受[う]けた。", "sentence_source": "generated"}, {"text": "積極の姿勢を示す社員ほど、会社で高く評価される。", "target_word": "積極", "complexity_tier": "T3", "furigana": "積極[せっきょく]の姿勢[しせい]を示[しめ]す社員[しゃいん]ほど、会社[かいしゃ]で高[たか]く評価[ひょうか]される。", "sentence_source": "generated"}, {"text": "病気の後も、彼の積極の姿勢は少しも変わらなかった。", "target_word": "積極", "complexity_tier": "T3", "furigana": "病気[びょうき]の後[あと]も、彼[かれ]の積極[せっきょく]の姿勢[しせい]は少[すこ]しも変[か]わらなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "積極的", "label": "形容動詞的な形"}, {"form": "積極に", "label": "連用の形"}, {"form": "積極と慎重", "label": "対にした形"}], "register": "中立(普通体)", "sense_fingerprint": "消極の反対。人の性格や姿勢として表れる、進んで取り組む態度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '967a9b28-2bdb-40b0-b501-a0eb8c8ff352') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38219, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "積極", "is_correct": true, "explanation": "「彼の積極の姿勢」で、前向きな態度を表す性格の語として合う。"}, {"text": "積極的", "is_correct": false, "explanation": "「彼の積極的の姿勢」と連体で続けるのは誤り。"}, {"text": "積極に", "is_correct": false, "explanation": "「積極に姿勢」は副詞の形で、姿勢に続かない。"}, {"text": "無気力", "is_correct": false, "explanation": "「無気力の姿勢を見て、周りも頑張ろうと思った」は前向きさと合わず、文脈と逆になる。"}], "explanations": {"積極": "「彼の積極の姿勢」で、前向きな態度を表す性格の語として合う。", "積極的": "「彼の積極的の姿勢」と連体で続けるのは誤り。", "積極に": "「積極に姿勢」は副詞の形で、姿勢に続かない。", "無気力": "「無気力の姿勢を見て、周りも頑張ろうと思った」は前向きさと合わず、文脈と逆になる。"}, "sentence_index": 0, "correct_answer": "積極"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の積極の声は小さくて、よく聞こえない。", "explanation": "ここは声の大きさを表す語ではない。積極は態度や性格を表す語なので、声には使わない。"}, {"text": "彼の積極の味は濃くて、料理が引き立つ。", "explanation": "ここは〈味〉の意味。積極は態度や性格を表す語で、料理の味を表す語ではない。"}, {"text": "彼の積極の顔色は悪く、熱があるようだ。", "explanation": "ここは〈顔色〉の意味。積極は態度や性格を表す語で、顔色を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38219, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "積極", "is_correct": true, "explanation": "「いまは積極の姿勢に変わった」で、最初の消極と対比する意味になる。"}, {"text": "無関心", "is_correct": false, "explanation": "「いまは無関心の姿勢に変わった」は、消極から前向きに変わったという文脈と逆になる。"}, {"text": "消極的", "is_correct": false, "explanation": "「消極的の姿勢」と連体で続けるのは誤り。"}, {"text": "受動的", "is_correct": false, "explanation": "「受動的の姿勢」と連体で続けるのは誤り。"}], "explanations": {"積極": "「いまは積極の姿勢に変わった」で、最初の消極と対比する意味になる。", "無関心": "「いまは無関心の姿勢に変わった」は、消極から前向きに変わったという文脈と逆になる。", "消極的": "「消極的の姿勢」と連体で続けるのは誤り。", "受動的": "「受動的の姿勢」と連体で続けるのは誤り。"}, "sentence_index": 6, "correct_answer": "積極"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は積極の食べ物が好きで、毎日同じ料理を選ぶ。", "explanation": "ここは〈食べ物の好み〉の意味。積極は進んで行動する態度を表す語で、好みには使わない。"}, {"text": "この箱の積極を数えたら、三十個あった。", "explanation": "ここは〈個数〉の意味。積極は態度を表す語で、数えられる物ではない。"}, {"text": "雨で道が滑りやすくて、彼は積極の足取りで歩いた。", "explanation": "ここは歩き方の様子を表す語ではない。積極は進んで行う態度で、足取りの描写には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38219, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は積極を姿勢で、新しい仕事を引き受けた。", "corrected_sentence": "彼女は積極の姿勢で、新しい仕事を引き受けた。", "error_description": "「積極の姿勢」の「の」が正しい。「を」にすると、「積極」が「姿勢」を修飾できず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38219, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもたちは、積極に姿勢で遊びに参加する。", "corrected_sentence": "子どもたちは、積極の姿勢で遊びに参加する。", "error_description": "「積極の姿勢」の「の」が正しい。「に」は副詞の形なので、姿勢を修飾できず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ebc6983-5192-4d23-8837-d40b4a2b1f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38220, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「強くする」の対象を示す格助詞で、結び付きを強くするという関係を作る。"}, {"text": "が", "is_correct": false, "explanation": "「強くする」は対象に「を」を取るため、「が」では目的語にならず不自然になる。"}, {"text": "に", "is_correct": false, "explanation": "「強くする」に「に」は続かず、強くする対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点や理由を表すため、「強くする」の対象を示す役割は果たせない。"}], "correct_answer": "を", "explanations": {"を": "「強くする」の対象を示す格助詞で、結び付きを強くするという関係を作る。", "が": "「強くする」は対象に「を」を取るため、「が」では目的語にならず不自然になる。", "に": "「強くする」に「に」は続かず、強くする対象を示せない。", "から": "起点や理由を表すため、「強くする」の対象を示す役割は果たせない。"}, "error_tags": {"が": "主語・主格", "に": "相手・位置", "から": "起点・理由"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38220, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「確かめる」の対象を示す格助詞で、結び付きを確かめるという関係を作る。"}, {"text": "が", "is_correct": false, "explanation": "「確かめる」は対象に「を」を取るため、「が」では目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「確かめる」に「に」は続かず、確かめる対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すため、確かめる対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「確かめる」の対象を示す格助詞で、結び付きを確かめるという関係を作る。", "が": "「確かめる」は対象に「を」を取るため、「が」では目的語にならない。", "に": "「確かめる」に「に」は続かず、確かめる対象を示せない。", "と": "相手や並列を表すため、確かめる対象にはならない。"}, "error_tags": {"が": "主語・主格", "に": "相手・位置", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38220, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものが、くっついたり、つながったりすることです。", "primary_collocate": null, "pronunciation": "むすびつき", "ipa": "musɯbitsɯki", "syllable_count": 5, "sentences": [{"text": "二つの部品の結び付きが弱くて、すぐ外れてしまった。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "二[ふた]つの部品[ぶひん]の結[むす]び付[つ]きが弱[よわ]くて、すぐ外[はず]れてしまった。", "sentence_source": "generated"}, {"text": "糸と糸の結び付きを強くするために、もう一度結んだ。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "糸[いと]と糸[いと]の結[むす]び付[つ]きを強[つよ]くするために、もう一度[いちど]結[むす]んだ。", "sentence_source": "generated"}, {"text": "原子の結び付きが切れると、別の物質ができる。", "target_word": "結び付き", "complexity_tier": "T4", "furigana": "原子[げんし]の結[むす]び付[つ]きが切[き]れると、別[べつ]の物質[ぶっしつ]ができる。", "sentence_source": "generated"}, {"text": "この接着剤は、金属と木の結び付きが弱い。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "この接着剤[せっちゃくざい]は、金属[きんぞく]と木[き]の結[むす]び付[つ]きが弱[よわ]い。", "sentence_source": "generated"}, {"text": "磁石と鉄の結び付きは、とても強い。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "磁石[じしゃく]と鉄[てつ]の結[むす]び付[つ]きは、とても強[つよ]い。", "sentence_source": "generated"}, {"text": "この接着剤を使うと、金属と樹脂の結び付きがとても強くなる。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "この接着剤[せっちゃくざい]を使[つか]うと、金属[きんぞく]と樹脂[じゅし]の結[むす]び付[つ]きがとても強[つよ]くなる。", "sentence_source": "generated"}, {"text": "木と木の結び付きが緩んで、小屋が少し傾いた。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "木[き]と木[き]の結[むす]び付[つ]きが緩[ゆる]んで、小屋[こや]が少[すこ]し傾[かたむ]いた。", "sentence_source": "generated"}, {"text": "部品どうしの結び付きを確かめてから、機械を動かした。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "部品[ぶひん]どうしの結[むす]び付[つ]きを確[たし]かめてから、機械[きかい]を動[うご]かした。", "sentence_source": "generated"}, {"text": "のりは、紙と紙の結び付きを作る。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "のりは、紙[かみ]と紙[かみ]の結[むす]び付[つ]きを作[つく]る。", "sentence_source": "generated"}, {"text": "この橋は鉄骨どうしの結び付きが強く、大きな地震にも耐えられる。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "この橋[はし]は鉄骨[てっこつ]どうしの結[むす]び付[つ]きが強[つよ]く、大[おお]きな地震[じしん]にも耐[た]えられる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結び付き", "label": "基本形"}, {"form": "結び付く", "label": "動詞基本形"}, {"form": "結び付いた", "label": "動詞過去形"}], "register": "neutral", "sense_fingerprint": "二つのものが実際にくっつき、つながっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38220, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結び付き", "is_correct": true, "explanation": "二つの部品がくっついている状態を指し、「弱くて外れた」という文脈に合う。"}, {"text": "温度", "is_correct": false, "explanation": "物の熱さの程度を表すので、部品の接合が弱いことの説明にならず、外れた理由とも結びつかない。"}, {"text": "色合い", "is_correct": false, "explanation": "見た目の色の調子を表すため、部品が弱くて外れるという内容には当てはまらない。"}, {"text": "明るさ", "is_correct": false, "explanation": "光の強さを表すので、部品どうしの接合の弱さを述べる主語には当てはまらない。"}], "explanations": {"結び付き": "二つの部品がくっついている状態を指し、「弱くて外れた」という文脈に合う。", "温度": "物の熱さの程度を表すので、部品の接合が弱いことの説明にならず、外れた理由とも結びつかない。", "色合い": "見た目の色の調子を表すため、部品が弱くて外れるという内容には当てはまらない。", "明るさ": "光の強さを表すので、部品どうしの接合の弱さを述べる主語には当てはまらない。"}, "sentence_index": 0, "correct_answer": "結び付き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "靴の結び付きをまだ覚えていないので、ひもを結べない。", "explanation": "ここは〈結び方〉（結ぶ技術）の意味。結び付きは二つのものがくっついた状態を指し、ひもを結ぶ技術や方法を言うときには使わない。"}, {"text": "この帯は、結び付きが後ろにあるので、座ると痛い。", "explanation": "ここは〈結び目〉の意味。結び付きは二つのものが結ばれてつながる状態を指し、帯の結び目の位置を言うときには使わない。"}, {"text": "ネジの結び付きが強すぎて、ねじ山がつぶれた。", "explanation": "ここは〈締め付け〉の意味。ねじを回して押さえる力を指すので、二つのものがくっつく状態を表す結び付きとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38220, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結び付き", "is_correct": true, "explanation": "二つの木がつながった状態を指し、緩んで小屋が傾いた原因として合う。"}, {"text": "香り", "is_correct": false, "explanation": "木の匂いを表すので、接合が緩んで小屋が傾く説明にはならない。"}, {"text": "重さ", "is_correct": false, "explanation": "物の質量を表すため、木どうしの接合が緩むという内容には当てはまらない。"}, {"text": "手触り", "is_correct": false, "explanation": "表面の感触を表すので、接合が緩んだことは表せない。"}], "explanations": {"結び付き": "二つの木がつながった状態を指し、緩んで小屋が傾いた原因として合う。", "香り": "木の匂いを表すので、接合が緩んで小屋が傾く説明にはならない。", "重さ": "物の質量を表すため、木どうしの接合が緩むという内容には当てはまらない。", "手触り": "表面の感触を表すので、接合が緩んだことは表せない。"}, "sentence_index": 6, "correct_answer": "結び付き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日の結び付きは、この場所で一番盛り上がる取組だ。", "explanation": "ここは相撲の〈結び〉（最後の取組）の意味。結び付きにはこの用法がなく、物や人がつながる状態を表す語義とも違う。"}, {"text": "この手紙は、結び付きの挨拶がとても丁寧で、読むと心が温まる。", "explanation": "ここは〈結び〉（手紙の末尾の挨拶）の意味。結び付きは二つのものがくっつく状態を指し、手紙の締めくくりの挨拶を言うときには使わない。"}, {"text": "この和歌は、結び付きの五音がとても美しく、余韻が残る。", "explanation": "ここは〈結び〉（和歌の最後の句）の意味。結び付きは二つのものがつながる状態を指し、和歌の最後の句を言うときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38220, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この接着剤は、木と金属の結び付きがとても強くする。", "corrected_sentence": "この接着剤は、木と金属の結び付きをとても強くする。", "error_description": "「強くする」の対象を示すには「を」が必要。「が」では他動詞「強くする」の目的語にならず、不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38220, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鉄骨どうしの結び付きに強くすると、建物は地震に耐えやすくなる。", "corrected_sentence": "鉄骨どうしの結び付きを強くすると、建物は地震に耐えやすくなる。", "error_description": "「強くする」の対象には「を」が必要。「に」では「強くする」の目的語にならず、文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38221, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「役立った」の主語を示す格助詞で、結び付きが役に立った主体になる。"}, {"text": "を", "is_correct": false, "explanation": "「役立つ」は目的語を取らないため、「を」は続かない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表すため、「役立った」の主語としては成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「役立つ」は方向の「へ」を取らず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「役立った」の主語を示す格助詞で、結び付きが役に立った主体になる。", "を": "「役立つ」は目的語を取らないため、「を」は続かない。", "と": "相手や並列を表すため、「役立った」の主語としては成り立たない。", "へ": "「役立つ」は方向の「へ」を取らず、文が成り立たない。"}, "error_tags": {"を": "目的語（役立つは取らない）", "と": "相手・並列", "へ": "方向（役立つは取らない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38221, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「強まる」の主語を示す格助詞で、国どうしの結び付きが強まった主体になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「強まる」の主語を示すことはできない。"}, {"text": "に", "is_correct": false, "explanation": "「強まる」に「に」は続かず、主語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すので、「強まる」の主語としては成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「強まる」の主語を示す格助詞で、国どうしの結び付きが強まった主体になる。", "へ": "方向を表すため、「強まる」の主語を示すことはできない。", "に": "「強まる」に「に」は続かず、主語として成り立たない。", "より": "比較を表すので、「強まる」の主語としては成り立たない。"}, "error_tags": {"へ": "方向", "に": "位置・相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38221, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事や人と人との間にある、強い関係やつながりのこと。", "primary_collocate": null, "pronunciation": "むすびつき", "ipa": "musɯbitsɯki", "syllable_count": 5, "sentences": [{"text": "親子の結び付きは、とても強い。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "親子[おやこ]の結[むす]び付[つ]きは、とても強[つよ]い。", "sentence_source": "generated"}, {"text": "地域の人との結び付きが、災害のときに役立った。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "地域[ちいき]の人[ひと]との結[むす]び付[つ]きが、災害[さいがい]のときに役立[やくだ]った。", "sentence_source": "generated"}, {"text": "兄弟の結び付きを大切にしている。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]の結[むす]び付[つ]きを大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "食べ物と健康の結び付きを、医者が説明した。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "食[た]べ物[もの]と健康[けんこう]の結[むす]び付[つ]きを、医者[いしゃ]が説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この会社は、大学との結び付きが深い。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、大学[だいがく]との結[むす]び付[つ]きが深[ふか]い。", "sentence_source": "generated"}, {"text": "事件と彼の結び付きは、まだ証明されていない。", "target_word": "結び付き", "complexity_tier": "T4", "furigana": "事件[じけん]と彼[かれ]の結[むす]び付[つ]きは、まだ証明[しょうめい]されていない。", "sentence_source": "generated"}, {"text": "祭りは、町の人々の結び付きを強くする。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "祭[まつ]りは、町[まち]の人々[ひとびと]の結[むす]び付[つ]きを強[つよ]くする。", "sentence_source": "generated"}, {"text": "国と国の結び付きが強まり、貿易が増えた。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "国[くに]と国[くに]の結[むす]び付[つ]きが強[つよ]まり、貿易[ぼうえき]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "友達との結び付きは、長い年月で深くなった。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "友達[ともだち]との結[むす]び付[つ]きは、長[なが]い年月[ねんげつ]で深[ふか]くなった。", "sentence_source": "generated"}, {"text": "言葉と文化には、切れない結び付きがある。", "target_word": "結び付き", "complexity_tier": "T3", "furigana": "言葉[ことば]と文化[ぶんか]には、切[き]れない結[むす]び付[つ]きがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "結び付き", "label": "基本形"}, {"form": "結び付く", "label": "動詞基本形"}, {"form": "結び付いた", "label": "動詞過去形"}], "register": "neutral", "sense_fingerprint": "人や物事の間にある強い関係やつながり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38221, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "結び付き", "is_correct": true, "explanation": "親子の間の強い関係を指し、「とても強い」と合う。"}, {"text": "血液型", "is_correct": false, "explanation": "血液の型の分類で、親子の関係の強さは表せない。"}, {"text": "身長", "is_correct": false, "explanation": "体の高さを表すので、人と人との関係の強さとは結びつかない。"}, {"text": "色合い", "is_correct": false, "explanation": "見た目の色の調子を表すため、関係の強さの説明には合わない。"}], "explanations": {"結び付き": "親子の間の強い関係を指し、「とても強い」と合う。", "血液型": "血液の型の分類で、親子の関係の強さは表せない。", "身長": "体の高さを表すので、人と人との関係の強さとは結びつかない。", "色合い": "見た目の色の調子を表すため、関係の強さの説明には合わない。"}, "sentence_index": 0, "correct_answer": "結び付き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "靴ひもの結び付きがほどけて、転びそうになった。", "explanation": "ここは〈結び目〉の意味。靴ひもの結び目を指す語で、人や物事の強い関係を表す結び付きの用法とは合わない。"}, {"text": "ネクタイの結び付きを、朝は鏡を見ずに一度で済ませる。", "explanation": "ここは〈結び方〉（結ぶ手順や技術）の意味。結び付きは物事や人の強い関係を指し、ネクタイの結び方を言うときには使わない。"}, {"text": "今日の結び付きは、本場所で一番盛り上がる取組だ。", "explanation": "ここは相撲の〈結び〉（最後の取組）の意味。結び付きにはこの用法がなく、関係の強さを言う語義とも違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38221, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "結び付き", "is_correct": true, "explanation": "町の人々の間の強い関係を指し、「強くする」の対象として合う。"}, {"text": "年齢", "is_correct": false, "explanation": "生まれてからの年数を表すので、人々の関係を強くする対象にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "体の重さを表すため、人々の関係を強くするという文には当てはまらない。"}, {"text": "背丈", "is_correct": false, "explanation": "身長のことで、人々の関係の強さは表せない。"}], "explanations": {"結び付き": "町の人々の間の強い関係を指し、「強くする」の対象として合う。", "年齢": "生まれてからの年数を表すので、人々の関係を強くする対象にはならない。", "体重": "体の重さを表すため、人々の関係を強くするという文には当てはまらない。", "背丈": "身長のことで、人々の関係の強さは表せない。"}, "sentence_index": 6, "correct_answer": "結び付き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一日の結び付きに、家族そろって夕食を食べる。", "explanation": "ここは〈締めくくり〉（一日の終わり）の意味。結び付きは物事や人の強い関係を表し、時間の終わりを言うときには使わない。"}, {"text": "ベルトの結び付きが弱くて、荷物が落ちた。", "explanation": "ここは〈締め付け〉の意味。ベルトで押さえる力を指し、人や物事の関係を表す結び付きとは別の用法になる。"}, {"text": "この小説は、結び付きが感動的で、読後に涙が出る。", "explanation": "ここは〈結び〉（文章の最後の部分）の意味。物事や人の強い関係を表す結び付きは、文章の終わりには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38221, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地域との結び付きが大切にする人は、困ったときに助けられる。", "corrected_sentence": "地域との結び付きを大切にする人は、困ったときに助けられる。", "error_description": "「大切にする」の対象を示すには「を」が必要。「が」では目的語にならず、文として不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38221, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い友人との結び付きを、年を重ねても変わらない。", "corrected_sentence": "古い友人との結び付きは、年を重ねても変わらない。", "error_description": "「変わらない」は自動詞なので目的語の「を」は取れない。主題を示す「は」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38222, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38222, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「山全体の景観が赤や黄色に染まる」の主語として〈景観〉に「が」がつく。"}, {"text": "を", "is_correct": false, "explanation": "「染まる」は自動詞なので、目的語の「を」は取らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や原因を示すが、景観が染まる主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すが、ここでは主語の位置に入らない。"}], "correct_answer": "が", "explanations": {"が": "正解。「山全体の景観が赤や黄色に染まる」の主語として〈景観〉に「が」がつく。", "を": "「染まる」は自動詞なので、目的語の「を」は取らない。", "で": "「で」は手段や原因を示すが、景観が染まる主語にはならない。", "と": "「と」は並列や相手を示すが、ここでは主語の位置に入らない。"}, "error_tags": {"を": "目的語", "で": "手段・原因", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38222, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "見える場所全体の、外のようす。", "primary_collocate": null, "pronunciation": "けいかん", "ipa": "keːkaɴ", "syllable_count": 4, "sentences": [{"text": "山の上から見ると、町の景観がまるで絵のようだった。", "target_word": "景観", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]から見[み]ると、町[まち]の景観[けいかん]がまるで絵[え]のようだった。", "sentence_source": "generated"}, {"text": "新しい橋ができて、川沿いの景観が明るくなった。", "target_word": "景観", "complexity_tier": "T3", "furigana": "新[あたら]しい橋[はし]ができて、川沿[かわぞ]いの景観[けいかん]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "この宿は、窓から見える海の景観が自慢だ。", "target_word": "景観", "complexity_tier": "T3", "furigana": "この宿[やど]は、窓[まど]から見[み]える海[うみ]の景観[けいかん]が自慢[じまん]だ。", "sentence_source": "generated"}, {"text": "雪が降ると、村の景観は真っ白に変わる。", "target_word": "景観", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]ると、村[むら]の景観[けいかん]は真[ま]っ白[しろ]に変[か]わる。", "sentence_source": "generated"}, {"text": "高い建物が増えて、駅前の景観はすっかり変わった。", "target_word": "景観", "complexity_tier": "T3", "furigana": "高[たか]い建物[たてもの]が増[ふ]えて、駅前[えきまえ]の景観[けいかん]はすっかり変[か]わった。", "sentence_source": "generated"}, {"text": "祖父は、田んぼが広がる景観が好きで、毎朝散歩している。", "target_word": "景観", "complexity_tier": "T3", "furigana": "祖父[そふ]は、田[た]んぼが広[ひろ]がる景観[けいかん]が好[す]きで、毎朝[まいあさ]散歩[さんぽ]している。", "sentence_source": "generated"}, {"text": "ごみが捨てられていると、公園の景観が悪くなる。", "target_word": "景観", "complexity_tier": "T3", "furigana": "ごみが捨[す]てられていると、公園[こうえん]の景観[けいかん]が悪[わる]くなる。", "sentence_source": "generated"}, {"text": "秋になると、紅葉で山全体の景観が赤や黄色に染まる。", "target_word": "景観", "complexity_tier": "T3", "furigana": "秋[あき]になると、紅葉[こうよう]で山[やま]全体[ぜんたい]の景観[けいかん]が赤[あか]や黄色[きいろ]に染[そ]まる。", "sentence_source": "generated"}, {"text": "外国の街を歩いて、日本とは違う景観に驚いた。", "target_word": "景観", "complexity_tier": "T3", "furigana": "外国[がいこく]の街[まち]を歩[ある]いて、日本[にほん]とは違[ちが]う景観[けいかん]に驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "海沿いの道を走ると、すばらしい景観が次々に現れる。", "target_word": "景観", "complexity_tier": "T3", "furigana": "海沿[うみぞ]いの道[みち]を走[はし]ると、すばらしい景観[けいかん]が次々[つぎつぎ]に現[あらわ]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "景観", "label": "基本形"}], "register": "plain", "sense_fingerprint": "目に見える場所全体の外観・ようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38222, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "〈人口〉は住民の数で、町を見て絵のようだと感じる対象ではない。"}, {"text": "財産", "is_correct": false, "explanation": "〈財産〉は所有する資産で、見た目を「絵のよう」と言う文脈に合わない。"}, {"text": "景観", "is_correct": true, "explanation": "正解。「山の上から見ると、町の＿がまるで絵のようだった」の主語は、見える場所全体の外観を指す〈景観〉。"}, {"text": "寿命", "is_correct": false, "explanation": "〈寿命〉は生きている期間で、町の見え方を述べる文には合わない。"}], "explanations": {"人口": "〈人口〉は住民の数で、町を見て絵のようだと感じる対象ではない。", "財産": "〈財産〉は所有する資産で、見た目を「絵のよう」と言う文脈に合わない。", "景観": "正解。「山の上から見ると、町の＿がまるで絵のようだった」の主語は、見える場所全体の外観を指す〈景観〉。", "寿命": "〈寿命〉は生きている期間で、町の見え方を述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "景観"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい鞄は、景観が気に入って買った。", "explanation": "ここは〈外観〉の意味（物の外側の見た目）。〈景観〉は土地の眺めなので、鞄の見た目には合わない。"}, {"text": "遠くの寺から、夕方の鐘の景観が聞こえてくる。", "explanation": "ここは〈音〉の意味。〈景観〉は目で見る眺めで、鐘の音のように聞こえるものには使わないので合わない。"}, {"text": "久しぶりに会った友人の景観がずいぶん変わっていた。", "explanation": "ここは〈様子〉の意味（人の状態）。〈景観〉は場所の眺めを指すので、人には使わないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38222, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "機嫌", "is_correct": false, "explanation": "〈機嫌〉は人の気分で、公園の見た目が悪くなる文には合わない。"}, {"text": "体力", "is_correct": false, "explanation": "〈体力〉は人の身体の力で、公園の状態を表さない。"}, {"text": "景観", "is_correct": true, "explanation": "正解。「ごみが捨てられていると、公園の＿が悪くなる」の主語は、見える場所全体の外観を指す〈景観〉。"}, {"text": "生地", "is_correct": false, "explanation": "〈生地〉は布や菓子の材料で、公園の見た目を表す語としては使わない。"}], "explanations": {"機嫌": "〈機嫌〉は人の気分で、公園の見た目が悪くなる文には合わない。", "体力": "〈体力〉は人の身体の力で、公園の状態を表さない。", "景観": "正解。「ごみが捨てられていると、公園の＿が悪くなる」の主語は、見える場所全体の外観を指す〈景観〉。", "生地": "〈生地〉は布や菓子の材料で、公園の見た目を表す語としては使わない。"}, "sentence_index": 6, "correct_answer": "景観"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その画家は、心の中の景観をキャンバスに映した。", "explanation": "ここは〈風景〉の比喩的な意味（心の中の情景）。〈景観〉は実際の土地の見え方を指すので、心の中の情景には使わないため合わない。"}, {"text": "全国の景観は、輸出の伸びで三か月連続の改善を見せた。", "explanation": "ここは〈景況〉の意味（経済の状態）。〈景観〉は土地の眺めなので、輸出や景気の動きには合わない。"}, {"text": "試合の終わりに、選手が喜び合う景観が広がった。", "explanation": "ここは〈光景〉の意味（出来事の場面）。〈景観〉は土地の眺めで、人の動作が起きる場面には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38222, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谷の向こうに広がる景観に、一枚の写真に収めた。", "corrected_sentence": "谷の向こうに広がる景観を、一枚の写真に収めた。", "error_description": "「景観に、写真に収めた」は誤り。「収める」は目的語に「を」をとるので、正しくは「景観を、一枚の写真に収めた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38222, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高台の展望デッキからは、町の景観で見下ろすことができる。", "corrected_sentence": "高台の展望デッキからは、町の景観を見下ろすことができる。", "error_description": "「景観で見下ろす」は誤り。「見下ろす」は目的語に「を」をとるので、正しくは「景観を見下ろす」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
