INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38224, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "見た目がきれいなこと。", "primary_collocate": null, "pronunciation": "びてき", "ipa": "biteki", "syllable_count": 3, "sentences": [{"text": "この庭は美的で、毎日見ても飽きない。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この庭[にわ]は美的[びてき]で、毎日[まいにち]見[み]ても飽[あ]きない。", "sentence_source": "generated"}, {"text": "この写真は構図が美的で、雑誌の表紙に使われた。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この 写真[しゃしん]は 構図[こうず]が 美的[びてき]で、雑誌[ざっし]の 表紙[ひょうし]に 使[つか]われた。", "sentence_source": "generated"}, {"text": "この店は包装紙まで美的で、贈り物に人気がある。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この 店[みせ]は 包装紙[ほうそうし]まで 美的[びてき]で、贈[おく]り物[もの]に 人気[にんき]が ある。", "sentence_source": "generated"}, {"text": "この皿は形が美的だから、料理がおいしそうに見える。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この皿[さら]は形[かたち]が美的[びてき]だから、料理[りょうり]がおいしそうに見[み]える。", "sentence_source": "generated"}, {"text": "色数を三色に絞ると、部屋全体が美的にまとまって見える。", "target_word": "美的", "complexity_tier": "T3", "furigana": "色数[いろかず]を 三色[さんしょく]に 絞[しぼ]ると、部屋[へや]全体[ぜんたい]が 美的[びてき]に まとまって 見[み]える。", "sentence_source": "generated"}, {"text": "美的な建物が多いので、この町を歩くのが楽しい。", "target_word": "美的", "complexity_tier": "T3", "furigana": "美的[びてき]な建物[たてもの]が多[おお]いので、この町[まち]を歩[ある]くのが楽[たの]しい。", "sentence_source": "generated"}, {"text": "兄は実用的より、美的なかばんを選んだ。", "target_word": "美的", "complexity_tier": "T3", "furigana": "兄[あに]は実用的[じつようてき]より、美的[びてき]なかばんを選[えら]んだ。", "sentence_source": "generated"}, {"text": "雪をかぶった山は、とても美的な景色だった。", "target_word": "美的", "complexity_tier": "T3", "furigana": "雪[ゆき]をかぶった山[やま]は、とても美的[びてき]な景色[けしき]だった。", "sentence_source": "generated"}, {"text": "このケーキは、飾りの配置まで美的で、切るのがもったいない。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この ケーキは、飾[かざ]りの 配置[はいち]まで 美的[びてき]で、切[き]るのが もったいない。", "sentence_source": "generated"}, {"text": "この服は色も形も美的で、写真によく映える。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この服[ふく]は色[いろ]も形[かたち]も美的[びてき]で、写真[しゃしん]によく映[は]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "美的だ", "label": "終止形"}, {"form": "美的な", "label": "連体形"}, {"form": "美的に", "label": "連用形"}, {"form": "美的で", "label": "連用形（で）"}, {"form": "美的だった", "label": "過去形"}], "register": "plain", "sense_fingerprint": "見た目がきれいな様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38224, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美的", "is_correct": true, "explanation": "『この庭は美的で、毎日見ても飽きない』で、見た目がきれいな様子を表し文に合う。"}, {"text": "寝具的", "is_correct": false, "explanation": "寝具に関わる性質を表し、庭の見た目を評価する文には合わない。"}, {"text": "湿気的", "is_correct": false, "explanation": "湿り気に関する性質を表し、庭の見た目を評価する文脈とは結びつかない。"}, {"text": "乾燥的", "is_correct": false, "explanation": "乾いた状態を表し、庭がきれいに見えることを述べる文には合わない。"}], "explanations": {"美的": "『この庭は美的で、毎日見ても飽きない』で、見た目がきれいな様子を表し文に合う。", "寝具的": "寝具に関わる性質を表し、庭の見た目を評価する文には合わない。", "湿気的": "湿り気に関する性質を表し、庭の見た目を評価する文脈とは結びつかない。", "乾燥的": "乾いた状態を表し、庭がきれいに見えることを述べる文には合わない。"}, "sentence_index": 0, "correct_answer": "美的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この皿は衛生が美的だから、料理がおいしそうに見える。", "explanation": "ここは〈清潔〉の意味。美的は見た目の美しさを指すので、衛生の状態には使わない。"}, {"text": "この皿は値段が美的だから、料理がおいしそうに見える。", "explanation": "ここは〈高級〉の意味。美的は見た目の美しさで、値段の高さは指さない。"}, {"text": "この皿は重さが美的だから、料理がおいしそうに見える。", "explanation": "ここは〈軽い〉の意味。美的は見た目の美しさで、重さは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38224, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美的", "is_correct": true, "explanation": "『実用的より、美的なかばんを選んだ』で、見た目のきれいさを重視する意味になり文に合う。"}, {"text": "電動的", "is_correct": false, "explanation": "電気で動く性質を表し、かばんの見た目を選ぶ文脈には合わない。"}, {"text": "食用的", "is_correct": false, "explanation": "食べ物として使えることを表し、かばんを選ぶ文とは関係がない。"}, {"text": "寒冷的", "is_correct": false, "explanation": "気温の低さに関する語で、かばんの見た目を選ぶ文脈には入らない。"}], "explanations": {"美的": "『実用的より、美的なかばんを選んだ』で、見た目のきれいさを重視する意味になり文に合う。", "電動的": "電気で動く性質を表し、かばんの見た目を選ぶ文脈には合わない。", "食用的": "食べ物として使えることを表し、かばんを選ぶ文とは関係がない。", "寒冷的": "気温の低さに関する語で、かばんの見た目を選ぶ文脈には入らない。"}, "sentence_index": 6, "correct_answer": "美的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この服は防水が美的で、雨の日も使える。", "explanation": "ここは〈水を通さない性能〉の意味。美的は見た目の美しさを指すので、雨に強いことは表さない。"}, {"text": "この服は流行に美的で、若い人に人気がある。", "explanation": "ここは〈時代の好み〉の意味。美的は見た目の美しさで、その時々の好みの移り変わりは指さない。"}, {"text": "この服は丈夫さも美的で、何年も着られる。", "explanation": "ここは〈長持ち〉の意味。美的は見た目の美しさで、長く使える耐久性は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38224, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この箱は色が美的な、贈り物に向いている。", "corrected_sentence": "この箱は色が美的で、贈り物に向いている。", "error_description": "『美的だ』の中止の形は『美的で』。連体形の『美的な』を後に読点で続けるのは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "美的", "is_correct": true, "explanation": "anchor文で『構図が美的で』と使われる語幹の形で、見た目の美しさを表す。"}, {"text": "美的だ", "is_correct": false, "explanation": "終止形で、『構図が』に続けて名詞の性質を並べる形にはならない。"}, {"text": "美的な", "is_correct": false, "explanation": "連体形で、後ろに名詞が続く必要があり、この文の形には合わない。"}, {"text": "美的に", "is_correct": false, "explanation": "連用形で、『構図が』に続けて述語を修飾する形にはならない。"}], "correct_form": "美的", "base_form": "美的だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"美的": "anchor文で『構図が美的で』と使われる語幹の形で、見た目の美しさを表す。", "美的だ": "終止形で、『構図が』に続けて名詞の性質を並べる形にはならない。", "美的な": "連体形で、後ろに名詞が続く必要があり、この文の形には合わない。", "美的に": "連用形で、『構図が』に続けて述語を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38224, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺の花瓶は形が美的を、部屋が華やぐ。", "corrected_sentence": "窓辺の花瓶は形が美的で、部屋が華やぐ。", "error_description": "『美的で』の『で』を『を』に変えると文が壊れる。『形が美的で』と続けるのが正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "美的", "is_correct": true, "explanation": "『美的な景色』の語幹の形で、見た目の美しさを表す。"}, {"text": "美的で", "is_correct": false, "explanation": "連用形で、中止の形として使うが、この位置では名詞を修飾しない。"}, {"text": "美的だった", "is_correct": false, "explanation": "過去形で、文の述語になり、名詞を修飾する位置には入らない。"}, {"text": "美的だ", "is_correct": false, "explanation": "終止形で、名詞を修飾する形にはならない。"}], "correct_form": "美的", "base_form": "美的だ", "form_label": "語幹", "sentence_index": 7, "explanations": {"美的": "『美的な景色』の語幹の形で、見た目の美しさを表す。", "美的で": "連用形で、中止の形として使うが、この位置では名詞を修飾しない。", "美的だった": "過去形で、文の述語になり、名詞を修飾する位置には入らない。", "美的だ": "終止形で、名詞を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
