INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38225, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の外見や形が美しいこと。また、その様子。", "primary_collocate": null, "pronunciation": "びてき", "ipa": "biteki", "syllable_count": 3, "sentences": [{"text": "オートクチュールの歴史は、単なる服飾の変遷を超え、人類の美的探究と技術革新の軌跡そのものである。", "target_word": "美的", "complexity_tier": "T4", "furigana": "オートクチュールの歴史[れきし]は、単[たん]なる服飾[ふくしょく]の変遷[へんせん]を超[こ]え、人類[じんるい]の美的[びてき]探究[たんきゅう]と技術[ぎじゅつ]革新[かくしん]の軌跡[きせき]そのものである。", "sentence_source": "mined"}, {"text": "この橋は丈夫なだけでなく、形も美的で、観光客に人気がある。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この橋[はし]は丈夫[じょうぶ]なだけでなく、形[かたち]も美的[びてき]で、観光客[かんこうきゃく]に人気[にんき]がある。", "sentence_source": "generated"}, {"text": "彼は料理の味だけでなく、盛りつけの美的な面にもこだわる。", "target_word": "美的", "complexity_tier": "T3", "furigana": "彼[かれ]は料理[りょうり]の味[あじ]だけでなく、盛[も]りつけの美的[びてき]な面[めん]にもこだわる。", "sentence_source": "generated"}, {"text": "美的な外観を重視して、設計者は窓の形を何度も描き直した。", "target_word": "美的", "complexity_tier": "T3", "furigana": "美的[びてき]な外観[がいかん]を重視[じゅうし]して、設計者[せっけいしゃ]は窓[まど]の形[かたち]を何度[なんど]も描[か]き直[なお]した。", "sentence_source": "generated"}, {"text": "この車は性能より、流れるような線が美的だと評価された。", "target_word": "美的", "complexity_tier": "T3", "furigana": "この車[くるま]は性能[せいのう]より、流[なが]れるような線[せん]が美的[びてき]だと評価[ひょうか]された。", "sentence_source": "generated"}, {"text": "工場の建物も、周りの景色に合わせて美的に整えられている。", "target_word": "美的", "complexity_tier": "T3", "furigana": "工場[こうじょう]の建物[たてもの]も、周[まわ]りの景色[けしき]に合[あ]わせて美的[びてき]に整[ととの]えられている。", "sentence_source": "generated"}, {"text": "実用性を優先したので、この机は美的には少し物足りない。", "target_word": "美的", "complexity_tier": "T3", "furigana": "実用性[じつようせい]を優先[ゆうせん]したので、この机[つくえ]は美的[びてき]には少[すこ]し物足[ものた]りない。", "sentence_source": "generated"}, {"text": "美的な形をしたガラスの器が、店の入り口に並べられていた。", "target_word": "美的", "complexity_tier": "T3", "furigana": "美的[びてき]な形[かたち]をしたガラスの器[うつわ]が、店[みせ]の入[い]り口[ぐち]に並[なら]べられていた。", "sentence_source": "generated"}, {"text": "値段が高いのは、素材だけでなく美的な仕上がりも優れているからだ。", "target_word": "美的", "complexity_tier": "T3", "furigana": "値段[ねだん]が高[たか]いのは、素材[そざい]だけでなく美的[びてき]な仕上[しあ]がりも優[すぐ]れているからだ。", "sentence_source": "generated"}, {"text": "古い街並みが美的だという理由で、住民は建て替えに反対した。", "target_word": "美的", "complexity_tier": "T3", "furigana": "古[ふる]い街並[まちな]みが美的[びてき]だという理由[りゆう]で、住民[じゅうみん]は建[た]て替[か]えに反対[はんたい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "美的だ", "label": "終止形"}, {"form": "美的な", "label": "連体形"}, {"form": "美的に", "label": "連用形"}, {"form": "美的で", "label": "連用形（で）"}, {"form": "美的だった", "label": "過去形"}], "register": "formal", "sense_fingerprint": "物事の外見や形の美しさに関わる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38225, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美的", "is_correct": true, "explanation": "『人類の美的探究』は、美しさを追い求める営みを表し、文脈に合う。"}, {"text": "寒冷的", "is_correct": false, "explanation": "気温の低さに関する語で、人類の探究の対象としては意味が通らない。"}, {"text": "食用的", "is_correct": false, "explanation": "食べ物として使えることを表し、美を探究する文脈とは結びつかない。"}, {"text": "電動的", "is_correct": false, "explanation": "電気で動く性質を表し、芸術や美を探究する文には合わない。"}], "explanations": {"美的": "『人類の美的探究』は、美しさを追い求める営みを表し、文脈に合う。", "寒冷的": "気温の低さに関する語で、人類の探究の対象としては意味が通らない。", "食用的": "食べ物として使えることを表し、美を探究する文脈とは結びつかない。", "電動的": "電気で動く性質を表し、芸術や美を探究する文には合わない。"}, "sentence_index": 0, "correct_answer": "美的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この機械は部品の精度が美的で、ほとんどずれがない。", "explanation": "ここは〈正確さ〉の意味。美的は見た目の美しさを指すので、部品の精度は表さない。"}, {"text": "この電車は美的で、いつも定刻に着く。", "explanation": "ここは〈運行の正確さ〉の意味。美的は見た目の美しさを指すので、時刻どおりに走る正確さは表さない。"}, {"text": "このスープは美的で、ちょうど良い塩加減だ。", "explanation": "ここは味の評価の意味。美的は見た目について使うので、味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38225, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美的", "is_correct": true, "explanation": "『この机は美的には少し物足りない』で、見た目の美しさが足りないことを表し文に合う。"}, {"text": "寝具的", "is_correct": false, "explanation": "寝具に関わる性質を表し、机の見た目の評価には当てはまらない。"}, {"text": "湿気的", "is_correct": false, "explanation": "湿り気に関する性質を表し、机の外観を評価する文には合わない。"}, {"text": "乾燥的", "is_correct": false, "explanation": "乾いた状態を表し、見た目の美しさを評価する文脈とは関係がない。"}], "explanations": {"美的": "『この机は美的には少し物足りない』で、見た目の美しさが足りないことを表し文に合う。", "寝具的": "寝具に関わる性質を表し、机の見た目の評価には当てはまらない。", "湿気的": "湿り気に関する性質を表し、机の外観を評価する文には合わない。", "乾燥的": "乾いた状態を表し、見た目の美しさを評価する文脈とは関係がない。"}, "sentence_index": 6, "correct_answer": "美的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この町は美的な由緒があり、旧跡として指定された。", "explanation": "ここは〈歴史的〉の意味。美的は見た目の美しさを指すので、由緒や歴史の価値には使わない。"}, {"text": "この会議は美的な議論で、結論がまとまった。", "explanation": "ここは〈論理的〉の意味。美的は見た目の美しさを指すので、話の筋道の良さには使わず『論理的な議論』と言う。"}, {"text": "この町は美的な利便性が高く、住民は車を手放した。", "explanation": "ここは〈便利〉の意味。美的は見た目の美しさで、利便性は指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38225, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この建物は外観が美的に、人が集まる。", "corrected_sentence": "この建物は外観が美的で、人が集まる。", "error_description": "『美的だ』の中止・連用の形は『美的で』。『美的に』は文が続かない誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "美的", "is_correct": true, "explanation": "anchor文で『形も美的で』と使われる語幹の形で、見た目の美しさを表す。"}, {"text": "美的だ", "is_correct": false, "explanation": "終止形で、文中で『形も』に続けて名詞を修飾する形にはならない。"}, {"text": "美的な", "is_correct": false, "explanation": "連体形で、後ろに名詞が続く必要があり、この文の並列の形には合わない。"}, {"text": "美的に", "is_correct": false, "explanation": "連用形で、『形も』に続けて述語を修飾する形にはならない。"}], "correct_form": "美的", "base_form": "美的だ", "form_label": "語幹", "sentence_index": 1, "explanations": {"美的": "anchor文で『形も美的で』と使われる語幹の形で、見た目の美しさを表す。", "美的だ": "終止形で、文中で『形も』に続けて名詞を修飾する形にはならない。", "美的な": "連体形で、後ろに名詞が続く必要があり、この文の並列の形には合わない。", "美的に": "連用形で、『形も』に続けて述語を修飾する形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38225, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部屋は色が美的だくつろげる。", "corrected_sentence": "この部屋は色が美的で、くつろげる。", "error_description": "『美的だ』は後ろに続けられない。並べる・続けるときは連用形の『美的で』を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "美的な", "is_correct": true, "explanation": "「美的な形」と名詞「形」を修飾する連体形で、anchor文の形と一致する。"}, {"text": "美的さ", "is_correct": false, "explanation": "名詞形で、名詞「形」を直接修飾できず、文が成り立たない。"}, {"text": "美的で", "is_correct": false, "explanation": "連用形（で）で、名詞を修飾する形にはならない。"}, {"text": "美的ならば", "is_correct": false, "explanation": "仮定の形で、名詞「形」を修飾できず、文が成り立たない。"}], "correct_form": "美的な", "base_form": "美的だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"美的な": "「美的な形」と名詞「形」を修飾する連体形で、anchor文の形と一致する。", "美的さ": "名詞形で、名詞「形」を直接修飾できず、文が成り立たない。", "美的で": "連用形（で）で、名詞を修飾する形にはならない。", "美的ならば": "仮定の形で、名詞「形」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
