INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38226, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38226, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人の気持ちやようすを考えて、気をつけること。", "primary_collocate": null, "pronunciation": "はいりょ", "ipa": "haiɾʲo", "syllable_count": 3, "sentences": [{"text": "先生は生徒の気持ちに配慮して、やさしく話しました。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]の気持[きも]ちに配慮[はいりょ]して、やさしく話[はな]しました。", "sentence_source": "generated"}, {"text": "病気の人に配慮して、部屋の音を小さくした。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "病気[びょうき]の人[ひと]に配慮[はいりょ]して、部屋[へや]の音[おと]を小[ちい]さくした。", "sentence_source": "generated"}, {"text": "彼は相手への配慮が足りず、友だちを怒らせてしまった。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]への配慮[はいりょ]が足[た]りず、友[とも]だちを怒[おこ]らせてしまった。", "sentence_source": "generated"}, {"text": "小さな子どもに配慮して、ゆっくり歩いた。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "小[ちい]さな子[こ]どもに配慮[はいりょ]して、ゆっくり歩[ある]いた。", "sentence_source": "generated"}, {"text": "配慮のある言い方だったので、みんな安心した。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "配慮[はいりょ]のある言[い]い方[かた]だったので、みんな安心[あんしん]した。", "sentence_source": "generated"}, {"text": "会議では、外国から来た人に配慮してやさしい日本語を使った。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、外国[がいこく]から来[き]た人[ひと]に配慮[はいりょ]してやさしい日本語[にほんご]を使[つか]った。", "sentence_source": "generated"}, {"text": "隣の家に配慮して、夜は洗濯をしないようにしている。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]に配慮[はいりょ]して、夜[よる]は洗濯[せんたく]をしないようにしている。", "sentence_source": "generated"}, {"text": "気持ちに配慮せずに質問したので、彼女は黙ってしまった。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "気持[きも]ちに配慮[はいりょ]せずに質問[しつもん]したので、彼女[かのじょ]は黙[だま]ってしまった。", "sentence_source": "generated"}, {"text": "店員の細かい配慮がうれしくて、また来たいと思った。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "店員[てんいん]の細[こま]かい配慮[はいりょ]がうれしくて、また来[き]たいと思[おも]った。", "sentence_source": "generated"}, {"text": "目の悪い人に配慮して、大きな字で書いた。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "目[め]の悪[わる]い人[ひと]に配慮[はいりょ]して、大[おお]きな字[じ]で書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配慮する", "label": "辞書形"}, {"form": "配慮して", "label": "て形"}, {"form": "配慮した", "label": "た形"}, {"form": "配慮しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "相手の気持ちやようすを考えて注意すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38226, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配慮", "is_correct": true, "explanation": "「生徒の気持ちに配慮して」の形で、相手の気持ちを考えることを表す。文の意味に合う。"}, {"text": "果物", "is_correct": false, "explanation": "果物は気持ちを考えて行動する対象にならず、「気持ちに果物して」は成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は相手の気持ちに対する行動として成り立たず、文が不自然になる。"}, {"text": "写真", "is_correct": false, "explanation": "写真は気持ちに対して気を配る行為を表さず、文の意味が通らない。"}], "explanations": {"配慮": "「生徒の気持ちに配慮して」の形で、相手の気持ちを考えることを表す。文の意味に合う。", "果物": "果物は気持ちを考えて行動する対象にならず、「気持ちに果物して」は成り立たない。", "天気": "天気は相手の気持ちに対する行動として成り立たず、文が不自然になる。", "写真": "写真は気持ちに対して気を配る行為を表さず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "配慮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "悩みを友だちに配慮した。", "explanation": "ここは〈相談〉の意味。悩みを打ち明ける行為が相談で、相手の気持ちを考える配慮とは合わない。"}, {"text": "タクシーの配慮を頼んだ。", "explanation": "ここは〈配車〉の意味。車を手配して迎えに来させることで、気づかいの配慮とは合わない。"}, {"text": "泥棒を警戒して、窓の鍵をかけた。", "explanation": "ここは〈用心〉の意味。泥棒を警戒する行為は用心で、相手の気持ちを思いやる配慮とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38226, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配慮", "is_correct": true, "explanation": "「隣の家に配慮して」の形で、相手の状況を考えて気を配る意味になる。文の意味に合う。"}, {"text": "卵", "is_correct": false, "explanation": "卵は相手に対して気を配る行為を表さず、「隣の家に卵して」は成り立たない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は気を配る対象や行為にならず、文が不自然になる。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは相手に対する行為を表さないので、文の意味が通らない。"}], "explanations": {"配慮": "「隣の家に配慮して」の形で、相手の状況を考えて気を配る意味になる。文の意味に合う。", "卵": "卵は相手に対して気を配る行為を表さず、「隣の家に卵して」は成り立たない。", "花瓶": "花瓶は気を配る対象や行為にならず、文が不自然になる。", "夕焼け": "夕焼けは相手に対する行為を表さないので、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "配慮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家の配慮を点検してもらった。", "explanation": "ここは〈配線〉の意味。電気の線を指す語で、気づかいの配慮は合わない。"}, {"text": "食料が足りないので、配慮が始まった。", "explanation": "ここは〈配給〉の意味。物資を分け配ることを指すので、気づかいの配慮は合わない。"}, {"text": "机の配慮を変えて、部屋を広く使った。", "explanation": "ここは〈配置〉の意味。物を並べる位置の話で、気づかいを指す配慮は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38226, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、生徒の気持ちへの配慮に忘れなかった。", "corrected_sentence": "先生は、生徒の気持ちへの配慮を忘れなかった。", "error_description": "「配慮を忘れる」の「を」は目的語を表す。「に」にすると『配慮に忘れなかった』となり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38226, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "相手の気持ちに配慮で話すことが大切だ。", "corrected_sentence": "相手の気持ちに配慮して話すことが大切だ。", "error_description": "「配慮して話す」は「て形」で続けて話すことを表す。「配慮で」では文が続かず、て形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38227, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「配慮として」の「と」は立場や資格を表し、「配慮として、短い勤務時間を認めている」となり文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「配慮にして」は「に」で続けても不自然で、「として」の形にならない。"}, {"text": "で", "is_correct": false, "explanation": "「配慮でして」は「で」で続けても文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「配慮へして」は方向を示す「へ」で、立場を表す形にならない。"}], "correct_answer": "と", "explanations": {"と": "「配慮として」の「と」は立場や資格を表し、「配慮として、短い勤務時間を認めている」となり文が成り立つ。", "に": "「配慮にして」は「に」で続けても不自然で、「として」の形にならない。", "で": "「配慮でして」は「で」で続けても文が成り立たない。", "へ": "「配慮へして」は方向を示す「へ」で、立場を表す形にならない。"}, "error_tags": {"に": "相手・対象", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38227, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38227, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手の立場や状況を思いやり、気をくばること。また、その気づかい。", "primary_collocate": null, "pronunciation": "はいりょ", "ipa": "haiɾʲo", "syllable_count": 3, "sentences": [{"text": "部長は私の事情に配慮して、仕事の時間を変えてくれた。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は私[わたし]の事情[じじょう]に配慮[はいりょ]して、仕事[しごと]の時間[じかん]を変[か]えてくれた。", "sentence_source": "generated"}, {"text": "子育て中の社員への配慮として、短い勤務時間を認めている。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "子育[こそだ]て中[ちゅう]の社員[しゃいん]への配慮[はいりょ]として、短[みじか]い勤務時間[きんむじかん]を認[みと]めている。", "sentence_source": "generated"}, {"text": "お客様への配慮を忘れないよう、新人に教えている。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "お客様[きゃくさま]への配慮[はいりょ]を忘[わす]れないよう、新人[しんじん]に教[おし]えている。", "sentence_source": "generated"}, {"text": "忙しい時期だったので、上司の配慮がありがたかった。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "忙[いそが]しい時期[じき]だったので、上司[じょうし]の配慮[はいりょ]がありがたかった。", "sentence_source": "generated"}, {"text": "家族の立場に配慮した結果、引っ越しは来年にした。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "家族[かぞく]の立場[たちば]に配慮[はいりょ]した結果[けっか]、引[ひ]っ越[こ]しは来年[らいねん]にした。", "sentence_source": "generated"}, {"text": "彼女は何も言わなかったが、それは私への配慮だった。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は何[なに]も言[い]わなかったが、それは私[わたし]への配慮[はいりょ]だった。", "sentence_source": "generated"}, {"text": "高齢の方に配慮した席が、駅に新しく作られた。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "高齢[こうれい]の方[かた]に配慮[はいりょ]した席[せき]が、駅[えき]に新[あたら]しく作[つく]られた。", "sentence_source": "generated"}, {"text": "相手の状況に配慮せず急に電話するのは、失礼だ。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "相手[あいて]の状況[じょうきょう]に配慮[はいりょ]せず急[きゅう]に電話[でんわ]するのは、失礼[しつれい]だ。", "sentence_source": "generated"}, {"text": "学校は食べ物のアレルギーがある子に配慮した給食を出す。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "学校[がっこう]は食[た]べ物[もの]のアレルギーがある子[こ]に配慮[はいりょ]した給食[きゅうしょく]を出[だ]す。", "sentence_source": "generated"}, {"text": "細かい配慮のおかげで、初めての出張も安心して過ごせた。", "target_word": "配慮", "complexity_tier": "T3", "furigana": "細[こま]かい配慮[はいりょ]のおかげで、初[はじ]めての出張[しゅっちょう]も安心[あんしん]して過[す]ごせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配慮する", "label": "辞書形"}, {"form": "配慮して", "label": "て形"}, {"form": "配慮した", "label": "た形"}, {"form": "配慮しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "相手の立場や事情を思いやる気づかい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38227, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配慮", "is_correct": true, "explanation": "「事情に配慮して」の形で、相手の事情を考えて気を配る意味になる。文の意味に合う。"}, {"text": "煮物", "is_correct": false, "explanation": "煮物は相手の事情に対して行動する語ではなく、「事情に煮物して」は成り立たない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は事情に対して気を配る行為を表さず、文が不自然になる。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は相手の事情を考える行為にならず、文の意味が通らない。"}], "explanations": {"配慮": "「事情に配慮して」の形で、相手の事情を考えて気を配る意味になる。文の意味に合う。", "煮物": "煮物は相手の事情に対して行動する語ではなく、「事情に煮物して」は成り立たない。", "切符": "切符は事情に対して気を配る行為を表さず、文が不自然になる。", "鉛筆": "鉛筆は相手の事情を考える行為にならず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "配慮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は株主に利益を五パーセント配慮した。", "explanation": "ここは〈配当〉の意味。利益を株主に分けて渡すことで、気づかいの配慮とは合わない。"}, {"text": "荷物が朝早く配慮された。", "explanation": "ここは〈配達〉の意味。品物を届けることを指すので、気づかいの配慮は合わない。"}, {"text": "映画の配慮を決めた。", "explanation": "ここは〈配役〉の意味。役者に役を割り当てることで、気づかいの配慮とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38227, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配慮", "is_correct": true, "explanation": "「高齢の方に配慮した席」の形で、相手の状況を考えて作られた席を表す。文の意味に合う。"}, {"text": "雨具", "is_correct": false, "explanation": "雨具は高齢の方への気づかいを表さず、「高齢の方に雨具した」は成り立たない。"}, {"text": "白菜", "is_correct": false, "explanation": "白菜は気づかいの行為を表さず、「高齢の方に白菜した」は文が通らない。"}, {"text": "押し入れ", "is_correct": false, "explanation": "押し入れは気づかいの対象や行為にならず、文の意味が通らない。"}], "explanations": {"配慮": "「高齢の方に配慮した席」の形で、相手の状況を考えて作られた席を表す。文の意味に合う。", "雨具": "雨具は高齢の方への気づかいを表さず、「高齢の方に雨具した」は成り立たない。", "白菜": "白菜は気づかいの行為を表さず、「高齢の方に白菜した」は文が通らない。", "押し入れ": "押し入れは気づかいの対象や行為にならず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "配慮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台所の配慮が古くなった。", "explanation": "ここは〈配管〉の意味。水道や排水の管を指す語で、気づかいの配慮は合わない。"}, {"text": "タクシーを配慮した。", "explanation": "ここは〈配車〉の意味。車を手配して向かわせることで、気づかいの配慮は合わない。"}, {"text": "学校でプリントを配慮した。", "explanation": "ここは〈配布〉の意味。印刷物を配ることを指すので、気づかいの配慮は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38227, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上司は私の立場と配慮して、休みを認めてくれた。", "corrected_sentence": "上司は私の立場に配慮して、休みを認めてくれた。", "error_description": "「配慮する」は「に」で対象を示す。「と」にすると『立場と配慮して』となり、配慮の相手として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38227, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は社員の健康が配慮した制度を作った。", "corrected_sentence": "会社は社員の健康に配慮した制度を作った。", "error_description": "「配慮する」は「に」で対象を示す。「が」は主語を表すので、『健康が配慮した』は配慮の主体にならず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
