INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38228, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが外に見えること。", "primary_collocate": null, "pronunciation": "あらわれ", "ipa": "aɾawaɾe", "syllable_count": 4, "sentences": [{"text": "笑顔は、彼の優しさの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "笑顔[えがお]は、彼[かれ]の優[やさ]しさの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "赤い顔は、恥ずかしい気持ちの表われでしょう。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "赤[あか]い顔[かお]は、恥[は]ずかしい気持[きも]ちの表[あらわ]れでしょう。", "sentence_source": "generated"}, {"text": "試合での落ち着いた動きは、自信の表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "試合[しあい]での落[お]ち着[つ]いた動[うご]きは、自信[じしん]の表[あらわ]れです。", "sentence_source": "generated"}, {"text": "子どもが泣くのは、さびしい気持ちの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "子[こ]どもが泣[な]くのは、さびしい気持[きも]ちの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "彼が早く来たのは、やる気の表われだと思います。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "彼[かれ]が早[はや]く来[き]たのは、やる気[き]の表[あらわ]れだと思[おも]います。", "sentence_source": "generated"}, {"text": "手紙を何度も書くのは、愛情の表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "手紙[てがみ]を何度[なんど]も書[か]くのは、愛情[あいじょう]の表[あらわ]れです。", "sentence_source": "generated"}, {"text": "顔色が悪いのは、疲れの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "顔色[かおいろ]が悪[わる]いのは、疲[つか]れの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "小さな親切は、人の心の広さの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "小[ちい]さな親切[しんせつ]は、人[ひと]の心[こころ]の広[ひろ]さの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "髪型を変えたのは、気持ちの変化の表われだと思います。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "髪型[かみがた]を変[か]えたのは、気持[きも]ちの変化[へんか]の表[あらわ]れだと思[おも]います。", "sentence_source": "generated"}, {"text": "遅刻が続くのは、気がゆるんでいる表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "遅刻[ちこく]が続[つづ]くのは、気[き]がゆるんでいる表[あらわ]れです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表われ", "label": "名詞形"}, {"form": "表われの", "label": "連体（の）"}, {"form": "表われだ", "label": "断定"}, {"form": "表われです", "label": "丁寧な断定"}], "register": "中立（丁寧体）", "sense_fingerprint": "心や性質などが、行動や様子として外に見えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38228, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表われ", "is_correct": true, "explanation": "「優しさの表われ」は、内側の性質が笑顔として外に見えることを表し、文脈に合う。"}, {"text": "計画", "is_correct": false, "explanation": "「優しさの計画」は意味が通らない。計画は前もって立てる予定で、笑顔の説明には合わない。"}, {"text": "注文", "is_correct": false, "explanation": "「優しさの注文」は不自然。注文は品物などを頼む行為で、性質の現れには使わない。"}, {"text": "請求", "is_correct": false, "explanation": "金銭などを求める行為で、性質の現れには使わない。「優しさの請求」は意味が通らない。"}], "explanations": {"表われ": "「優しさの表われ」は、内側の性質が笑顔として外に見えることを表し、文脈に合う。", "計画": "「優しさの計画」は意味が通らない。計画は前もって立てる予定で、笑顔の説明には合わない。", "注文": "「優しさの注文」は不自然。注文は品物などを頼む行為で、性質の現れには使わない。", "請求": "金銭などを求める行為で、性質の現れには使わない。「優しさの請求」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "表われ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "実験の表われは、この薬に効果がないということです。", "explanation": "ここは〈結論〉の意味。表われは内側の状態が外に見えることで、判断の結論を示す語ではないので合わない。"}, {"text": "この物語の表われは、主人公が旅に出ることです。", "explanation": "ここは〈結末〉の意味。表われは外に見える形やしるしを指し、物語の終わり方は表さないので合わない。"}, {"text": "この辞書は、単語の表われを正確に述べている。", "explanation": "ここは〈定義〉の意味。表われは外に見えるものを指し、語の意味を述べることは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38228, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表われ", "is_correct": true, "explanation": "「疲れの表われ」は、体の状態が顔色として外に見えることを表し、文脈に合う。"}, {"text": "外出", "is_correct": false, "explanation": "「疲れの外出」は不自然。外出は家の外に出かける行為で、体調の現れには使わない。"}, {"text": "順番", "is_correct": false, "explanation": "「疲れの順番」は意味が通らない。順番は並ぶ順序を指し、体調の説明には合わない。"}, {"text": "出発", "is_correct": false, "explanation": "「疲れの出発」は不自然。出発は出かけることで、疲れが外に見えることは表さない。"}], "explanations": {"表われ": "「疲れの表われ」は、体の状態が顔色として外に見えることを表し、文脈に合う。", "外出": "「疲れの外出」は不自然。外出は家の外に出かける行為で、体調の現れには使わない。", "順番": "「疲れの順番」は意味が通らない。順番は並ぶ順序を指し、体調の説明には合わない。", "出発": "「疲れの出発」は不自然。出発は出かけることで、疲れが外に見えることは表さない。"}, "sentence_index": 6, "correct_answer": "表われ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の表われは、英語を話せるようになることです。", "explanation": "ここは〈目標〉の意味。表われは内側の状態が外に見えることで、これから目指す目標を指す語ではないので合わない。"}, {"text": "この表われは、毎朝九時に出社することです。", "explanation": "ここは〈規則〉の意味。表われは気持ちや性質が見えることで、従うべき決まりは指さないので合わない。"}, {"text": "今日の表われは、午後に会議があることです。", "explanation": "ここは〈予定〉の意味。表われは見えてくる状態のしるしで、これから行う予定は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38228, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その汗は、緊張を表われです。", "corrected_sentence": "その汗は、緊張の表われです。", "error_description": "「表われ」の前には連体修飾の「の」が入る。「を」は動詞の目的語に付くので、名詞「表われ」の前では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38228, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その涙は、悲しみな表われです。", "corrected_sentence": "その涙は、悲しみの表われです。", "error_description": "名詞「表われ」の前の連体修飾は「の」を使う。「な」は形容動詞などに付くので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
