INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38229, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の形や状態が外に現れること。また、その現れた形。", "primary_collocate": null, "pronunciation": "あらわれ", "ipa": "aɾawaɾe", "syllable_count": 4, "sentences": [{"text": "背が三センチ伸びたのは、成長の表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "背[せ]が三[さん]センチ伸[の]びたのは、成長[せいちょう]の表[あらわ]れです。", "sentence_source": "generated"}, {"text": "彼の言葉づかいは、育ちの良さの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]づかいは、育[そだ]ちの良[よ]さの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "この絵は、作者の悲しみの表われだと言われています。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "この絵[え]は、作者[さくしゃ]の悲[かな]しみの表[あらわ]れだと言[い]われています。", "sentence_source": "generated"}, {"text": "部屋が散らかっているのは、心の疲れの表われかもしれません。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "部屋[へや]が散[ち]らかっているのは、心[こころ]の疲[つか]れの表[あらわ]れかもしれません。", "sentence_source": "generated"}, {"text": "この作品は、画家の強い思いの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "この作品[さくひん]は、画家[がか]の強[つよ]い思[おも]いの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "手のあれは、水仕事の多さの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "手[て]のあれは、水仕事[みずしごと]の多[おお]さの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "町の祭りは、人々の結びつきの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "町[まち]の祭[まつ]りは、人々[ひとびと]の結[むす]びつきの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "彼女の細かい字は、まじめな性格の表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の細[こま]かい字[じ]は、まじめな性格[せいかく]の表[あらわ]れです。", "sentence_source": "generated"}, {"text": "食欲がないのは、体の弱りの表われです。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "食欲[しょくよく]がないのは、体[からだ]の弱[よわ]りの表[あらわ]れです。", "sentence_source": "generated"}, {"text": "立派な建物は、その国の力の表われでした。", "target_word": "表われ", "complexity_tier": "T3", "furigana": "立派[りっぱ]な建物[たてもの]は、その国[くに]の力[ちから]の表[あらわ]れでした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "表われ", "label": "名詞形"}, {"form": "表われの", "label": "連体（の）"}, {"form": "表われだ", "label": "断定"}, {"form": "表われです", "label": "丁寧な断定"}], "register": "中立（丁寧体）", "sense_fingerprint": "内側の状態が外に出た結果の形・しるし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T3: contains vocabulary far above tier T3: 水仕事 (Zipf 1.51)']::text[], '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38229, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表われ", "is_correct": true, "explanation": "「成長の表われ」は、体の変化として結果が外に見えることを表し、文脈に合う。"}, {"text": "注文", "is_correct": false, "explanation": "「成長の注文」は意味が通らない。注文は品物などを頼む行為で、体の変化とは結びつかない。"}, {"text": "締め切り", "is_correct": false, "explanation": "「成長の締め切り」は不自然。締め切りは期限のことで、成長の結果の現れは表さない。"}, {"text": "献立", "is_correct": false, "explanation": "「成長の献立」は合わない。献立は料理の予定表で、体の変化を示す語ではない。"}], "explanations": {"表われ": "「成長の表われ」は、体の変化として結果が外に見えることを表し、文脈に合う。", "注文": "「成長の注文」は意味が通らない。注文は品物などを頼む行為で、体の変化とは結びつかない。", "締め切り": "「成長の締め切り」は不自然。締め切りは期限のことで、成長の結果の現れは表さない。", "献立": "「成長の献立」は合わない。献立は料理の予定表で、体の変化を示す語ではない。"}, "sentence_index": 0, "correct_answer": "表われ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この紙の表われは、提出の締め切りを守ることです。", "explanation": "ここは〈期限〉の意味。表われは外に現れる形や状態を指し、締め切りの日時を示す語ではないので合わない。"}, {"text": "来年の表われを、この資料にまとめました。", "explanation": "ここは〈計画〉の意味。表われは見えてくる状態のしるしで、これから進める計画は指さないので合わない。"}, {"text": "映画を見終えた私の表われは、三つ星の評価です。", "explanation": "ここは〈評価〉の意味。表われは外に見える形を指し、点数や等級で作品を判断することは表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38229, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表われ", "is_correct": true, "explanation": "「結びつきの表われ」は、人と人の関係が祭りとして外に見えることを表し、文脈に合う。"}, {"text": "順番", "is_correct": false, "explanation": "「結びつきの順番」は意味が通らない。順番は並ぶ順序で、人と人の関係の現れを表さない。"}, {"text": "出発", "is_correct": false, "explanation": "「結びつきの出発」は不自然。出発は出かけることで、関係が見えることは表さない。"}, {"text": "外出", "is_correct": false, "explanation": "「結びつきの外出」は合わない。外出は家を出ることで、結びつきの現れには使わない。"}], "explanations": {"表われ": "「結びつきの表われ」は、人と人の関係が祭りとして外に見えることを表し、文脈に合う。", "順番": "「結びつきの順番」は意味が通らない。順番は並ぶ順序で、人と人の関係の現れを表さない。", "出発": "「結びつきの出発」は不自然。出発は出かけることで、関係が見えることは表さない。", "外出": "「結びつきの外出」は合わない。外出は家を出ることで、結びつきの現れには使わない。"}, "sentence_index": 6, "correct_answer": "表われ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この靴の表われは、三千円です。", "explanation": "ここは〈値段〉の意味。表われは外に現れる形や状態を指し、代金の額は表さないので合わない。"}, {"text": "このクラスの表われは、三十人です。", "explanation": "ここは〈人数〉の意味。表われは外に見える形を指し、集まっている人の数は表さないので合わない。"}, {"text": "この会議の表われは、駅前の喫茶店です。", "explanation": "ここは〈場所〉の意味。表われは外に現れる形や状態を指し、集まる場所を示す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38229, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの笑い声は、喜びを表われです。", "corrected_sentence": "あの笑い声は、喜びの表われです。", "error_description": "連体修飾には「の」を使う。「を」は動詞の目的語に付くので、名詞「表われ」の前では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38229, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の頬は、照れな表われです。", "corrected_sentence": "彼の頬は、照れの表われです。", "error_description": "名詞「表われ」の前の連体修飾は「の」を使う。「な」は形容動詞などに付くので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
