INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38230, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「考え方の転換」の連体修飾を表し、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「考え方が転換には」は主語として不自然で、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「考え方から転換には」は起点になり、名詞句として文が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「考え方より転換には」は比較の意味になり、文の意味が合わない。"}], "correct_answer": "の", "explanations": {"の": "「考え方の転換」の連体修飾を表し、正しい。", "が": "「考え方が転換には」は主語として不自然で、文が成り立たない。", "から": "「考え方から転換には」は起点になり、名詞句として文が通らない。", "より": "「考え方より転換には」は比較の意味になり、文の意味が合わない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38230, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものから別のものに変わること。", "primary_collocate": null, "pronunciation": "てんかん", "ipa": "teɴkaɴ", "syllable_count": 4, "sentences": [{"text": "社長は、会社の方針を大きく転換した。", "target_word": "転換", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は、会社[かいしゃ]の方針[ほうしん]を大[おお]きく転換[てんかん]した。", "sentence_source": "generated"}, {"text": "不況をきっかけに、国の政策は転換を迫られた。", "target_word": "転換", "complexity_tier": "T4", "furigana": "不況[ふきょう]をきっかけに、国[くに]の政策[せいさく]は転換[てんかん]を迫[せま]られた。", "sentence_source": "generated"}, {"text": "発想の転換で、問題はすぐに解決した。", "target_word": "転換", "complexity_tier": "T3", "furigana": "発想[はっそう]の転換[てんかん]で、問題[もんだい]はすぐに解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "工場は、石油から電気への転換を進めている。", "target_word": "転換", "complexity_tier": "T3", "furigana": "工場[こうじょう]は、石油[せきゆ]から電気[でんき]への転換[てんかん]を進[すす]めている。", "sentence_source": "generated"}, {"text": "試合の流れは、あの一点で大きく転換した。", "target_word": "転換", "complexity_tier": "T3", "furigana": "試合[しあい]の流[なが]れは、あの一点[いってん]で大[おお]きく転換[てんかん]した。", "sentence_source": "generated"}, {"text": "彼は文系から理系へ進路を転換した。", "target_word": "転換", "complexity_tier": "T3", "furigana": "彼[かれ]は文系[ぶんけい]から理系[りけい]へ進路[しんろ]を転換[てんかん]した。", "sentence_source": "generated"}, {"text": "この映画は、中盤で話が大きく転換する。", "target_word": "転換", "complexity_tier": "T3", "furigana": "この映画[えいが]は、中盤[ちゅうばん]で話[はなし]が大[おお]きく転換[てんかん]する。", "sentence_source": "generated"}, {"text": "考え方の転換には、時間がかかる。", "target_word": "転換", "complexity_tier": "T3", "furigana": "考[かんが]え方[かた]の転換[てんかん]には、時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "農家は米から野菜への転換を決めた。", "target_word": "転換", "complexity_tier": "T3", "furigana": "農家[のうか]は米[こめ]から野菜[やさい]への転換[てんかん]を決[き]めた。", "sentence_source": "generated"}, {"text": "景気が悪くなったので、店は経営の方向を転換することを考えている。", "target_word": "転換", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなったので、店[みせ]は経営[けいえい]の方向[ほうこう]を転換[てんかん]することを考[かんが]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "転換", "label": "基本形"}, {"form": "転換する", "label": "サ変動詞"}, {"form": "転換した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "方向や状態が別のものへ切り替わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1f5796-cc68-46b6-b5e8-fc44afd0652e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38230, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "転換", "is_correct": true, "explanation": "「大きく転換した」で、方針が別の方向へ切り替わったという意味になり正しい。"}, {"text": "必然", "is_correct": false, "explanation": "「大きく必然した」とは言えず、「方針を大きく」の後に続かない。"}, {"text": "偶然", "is_correct": false, "explanation": "「大きく偶然した」とは言えず、文の動作として成り立たない。"}, {"text": "忍耐", "is_correct": false, "explanation": "「大きく忍耐した」とは言えず、方針の変化を表す文に合わない。"}], "explanations": {"転換": "「大きく転換した」で、方針が別の方向へ切り替わったという意味になり正しい。", "必然": "「大きく必然した」とは言えず、「方針を大きく」の後に続かない。", "偶然": "「大きく偶然した」とは言えず、文の動作として成り立たない。", "忍耐": "「大きく忍耐した」とは言えず、方針の変化を表す文に合わない。"}, "sentence_index": 0, "correct_answer": "転換"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は来月、本社へ転換する。", "explanation": "ここは〈転勤〉の意味。勤務地が変わることは転勤と言い、転換とは言わない。"}, {"text": "会議の日時を転換した。", "explanation": "ここは〈変更〉の意味。転換は大きな方向の切り替えを指すので、日時を少し変える場合には合わない。"}, {"text": "失敗の責任を部下に転換した。", "explanation": "ここは〈転嫁〉の意味。責任を他人に押しつける場合は転嫁を使い、転換とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38230, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "転換", "is_correct": true, "explanation": "「中盤で話が大きく転換する」で、話の流れが切り替わるという意味になり正しい。"}, {"text": "出席", "is_correct": false, "explanation": "「大きく出席する」とは言えず、話の流れを表す文に合わない。"}, {"text": "停電", "is_correct": false, "explanation": "「大きく停電する」は不自然で、話の変化を表す文には合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「大きく散歩する」とは言えず、話の変化を表す文に合わない。"}], "explanations": {"転換": "「中盤で話が大きく転換する」で、話の流れが切り替わるという意味になり正しい。", "出席": "「大きく出席する」とは言えず、話の流れを表す文に合わない。", "停電": "「大きく停電する」は不自然で、話の変化を表す文には合わない。", "散歩": "「大きく散歩する」とは言えず、話の変化を表す文に合わない。"}, "sentence_index": 6, "correct_answer": "転換"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "扇風機の羽根を転換させた。", "explanation": "ここは〈回転〉の意味。回る動きには回転を使い、転換とは言わない。"}, {"text": "一家は来年、郊外へ転換した。", "explanation": "ここは〈転居〉の意味。住まいを移すことは転居と言い、転換とは言わない。"}, {"text": "彼は階段から転換した。", "explanation": "ここは〈転落〉の意味。階段から落ちる出来事には転落を使い、転換とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38230, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の部署は、新しい業務への転換を進んでいる。", "corrected_sentence": "私の部署は、新しい業務への転換を進めている。", "error_description": "「転換を進める」と他動詞を使うのが正しい。「進む」は自動詞なので、「転換を進む」とは言えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38230, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村は、畑を果樹園の転換した。", "corrected_sentence": "村は、畑を果樹園に転換した。", "error_description": "「畑を果樹園に転換する」と移る先を「に」で示すのが正しい。「の」では移る先を示せず、誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40cdadc0-f16f-4ff9-9dd8-e5755fa8c338') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38232, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「インフラの大切さ」で、名詞「インフラ」と「大切さ」をつなぐ「の」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「を」が二つ重なり、他動詞の目的語が重複するため文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「インフラへ大切さ」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「インフラで大切さ」は名詞をつなぐ働きをしない。"}], "correct_answer": "の", "explanations": {"の": "「インフラの大切さ」で、名詞「インフラ」と「大切さ」をつなぐ「の」が入る。", "を": "「を」が二つ重なり、他動詞の目的語が重複するため文が成り立たない。", "へ": "「へ」は方向を示すため、「インフラへ大切さ」は意味が通らない。", "で": "「で」は手段や場所を示すため、「インフラで大切さ」は名詞をつなぐ働きをしない。"}, "error_tags": {"を": "目的語", "へ": "方向", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38232, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38232, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "暮らしや経済を支えるための、道路や水道などの大切な設備や仕組みのことです。", "primary_collocate": null, "pronunciation": "いんふら", "ipa": "iɴɸɯɾa", "syllable_count": 4, "sentences": [{"text": "道路や水道などのインフラは、私たちの暮らしを支えています。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "道路(どうろ)や水道(すいどう)などのインフラは、私(わたし)たちの暮(く)らしを支(ささ)えています。", "sentence_source": "generated"}, {"text": "台風で停電になり、インフラの大切さを感じました。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "台風(たいふう)で停電(ていでん)になり、インフラの大切(たいせつ)さを感(かん)じました。", "sentence_source": "generated"}, {"text": "この国では、インフラが足りなくて、きれいな水が使えない地域もあります。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "この国(くに)では、インフラが足(た)りなくて、きれいな水(みず)が使(つか)えない地域(ちいき)もあります。", "sentence_source": "generated"}, {"text": "町は、橋や道を直して、インフラを整えました。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "町(まち)は、橋(はし)や道(みち)を直(なお)して、インフラを整(ととの)えました。", "sentence_source": "generated"}, {"text": "古い水道管が多く、インフラの工事が毎年続いています。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "古(ふる)い水道管(すいどうかん)が多(おお)く、インフラの工事(こうじ)が毎年(まいとし)続(つづ)いています。", "sentence_source": "generated"}, {"text": "地震のあと、電気とガスのインフラが一日も早く直るように、作業員ががんばりました。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "地震(じしん)のあと、電気(でんき)とガスのインフラが一日(いちにち)も早(はや)く直(なお)るように、作業員(さぎょういん)ががんばりました。", "sentence_source": "generated"}, {"text": "新しい町をつくるときは、家を建てる前にインフラを作らなければなりません。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "新(あたら)しい町(まち)をつくるときは、家(いえ)を建(た)てる前(まえ)にインフラを作(つく)らなければなりません。", "sentence_source": "generated"}, {"text": "雪が多い地方では、冬でも使えるインフラが大切です。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "雪(ゆき)が多(おお)い地方(ちほう)では、冬(ふゆ)でも使(つか)えるインフラが大切(たいせつ)です。", "sentence_source": "generated"}, {"text": "市は、古くなったインフラを直すために、お金を使うと発表しました。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "市(し)は、古(ふる)くなったインフラを直(なお)すために、お金(かね)を使(つか)うと発表(はっぴょう)しました。", "sentence_source": "generated"}, {"text": "山の村はインフラが弱く、病院へ行くのに二時間かかります。", "target_word": "インフラ", "complexity_tier": "T3", "furigana": "山(やま)の村(むら)はインフラが弱(よわ)く、病院(びょういん)へ行(い)くのに二時間(にじかん)かかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "インフラ", "label": "基本形"}], "register": "中立", "sense_fingerprint": "道路・水道・電気など、暮らしを支える身近な設備", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28112226-414a-4178-b164-437d856c5eba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38232, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "インフラ", "is_correct": true, "explanation": "「道路や水道などの」と並ぶ、暮らしを支える社会の設備を指す語で、文の主語に入る。"}, {"text": "家具", "is_correct": false, "explanation": "家具は室内で使う家財で、道路や水道と並べて暮らしを支えるものとは言えない。"}, {"text": "文房具", "is_correct": false, "explanation": "文房具は学習や事務で使う小物で、道路や水道の仲間にはならない。"}, {"text": "食品", "is_correct": false, "explanation": "食品は食べるもので、道路や水道のように暮らしを支える社会の設備にはならない。"}], "explanations": {"インフラ": "「道路や水道などの」と並ぶ、暮らしを支える社会の設備を指す語で、文の主語に入る。", "家具": "家具は室内で使う家財で、道路や水道と並べて暮らしを支えるものとは言えない。", "文房具": "文房具は学習や事務で使う小物で、道路や水道の仲間にはならない。", "食品": "食品は食べるもので、道路や水道のように暮らしを支える社会の設備にはならない。"}, "sentence_index": 0, "correct_answer": "インフラ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妹は大切なインフラを抱いて寝ています。", "explanation": "ここは〈人形〉の意味。インフラは社会の基盤を指すので、子どもの人形には使わない。"}, {"text": "週末、家族で遊園地というインフラに出かけました。", "explanation": "ここは〈施設〉の意味。インフラは社会を支える基盤で、遊園地のような娯楽施設には使わないので合わない。"}, {"text": "映画の撮影で、機材のインフラを車に積んで運びました。", "explanation": "ここは〈機材〉の意味。インフラは持ち運ぶものではなく社会の基盤を指すので、撮影機材には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38232, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "インフラ", "is_correct": true, "explanation": "建設の前に整える社会の基盤を指すので、「作らなければなりません」の対象になる。"}, {"text": "感想", "is_correct": false, "explanation": "感想は作るものではなく、家を建てる前に整える対象にならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は人が作れるものではないので、「作らなければなりません」に合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は作るものではなく、家を建てる前に作る対象にならない。"}], "explanations": {"インフラ": "建設の前に整える社会の基盤を指すので、「作らなければなりません」の対象になる。", "感想": "感想は作るものではなく、家を建てる前に整える対象にならない。", "天気": "天気は人が作れるものではないので、「作らなければなりません」に合わない。", "寿命": "寿命は作るものではなく、家を建てる前に作る対象にならない。"}, "sentence_index": 6, "correct_answer": "インフラ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大工さんは、自分のインフラを大切に手入れして仕事に向かう。", "explanation": "ここは〈道具〉の意味。インフラは個人が持つものではなく社会の基盤を指すので、大工の道具には合わない。"}, {"text": "この店は新しいインフラを次々と出して、お客さんを増やしている。", "explanation": "ここは〈商品〉の意味。インフラは売り出すものではなく社会を支える基盤なので、店が出す商品には合わない。"}, {"text": "料理人は新鮮なインフラを選んで、店の料理を作る。", "explanation": "ここは〈食材〉の意味。インフラは食べられる物ではないので、料理の材料には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38232, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台風のあと、インフラを一日も早く直ることが大切です。", "corrected_sentence": "台風のあと、インフラが一日も早く直ることが大切です。", "error_description": "「直る」は自動詞なので、主語のインフラは「が」で示す。「を」は他動詞の目的語に使うため、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38232, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "インフラがよく整えて、住みやすくなった。", "corrected_sentence": "インフラがよく整って、住みやすくなった。", "error_description": "「整う」は自動詞で、主語のインフラに続くのは「整って」。「整えて」は他動詞で、目的語が必要なため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9b4cc7b-e47a-40e1-bc9d-42d927ac4359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38234, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減る", "is_correct": true, "explanation": "「増す」（量や程度が大きくなる）の対義語として辞書に挙がる語。"}, {"text": "進む", "is_correct": false, "explanation": "程度の増減を表さず、「増す」と対義語の関係にない。"}, {"text": "冷める", "is_correct": false, "explanation": "温度が下がる意味で、量や程度の反対語ではない。"}, {"text": "残る", "is_correct": false, "explanation": "変化せず残るという意味で、「増す」の対義語として挙がる語ではない。"}], "correct_answer": "減る", "explanations": {"減る": "「増す」（量や程度が大きくなる）の対義語として辞書に挙がる語。", "進む": "程度の増減を表さず、「増す」と対義語の関係にない。", "冷める": "温度が下がる意味で、量や程度の反対語ではない。", "残る": "変化せず残るという意味で、「増す」の対義語として挙がる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38234, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「痛み」が「増す」の主語を示す「が」で、文の意味が通る。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「痛み」が増すという主語関係を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、「痛み」を主語にできない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、主語を表す位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "「痛み」が「増す」の主語を示す「が」で、文の意味が通る。", "で": "「で」は手段や場所を示し、「痛み」が増すという主語関係を表せない。", "と": "「と」は並列や引用を示し、「痛み」を主語にできない。", "へ": "「へ」は方向を示し、主語を表す位置には入らない。"}, "error_tags": {"で": "手段・場所", "と": "並列・引用", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "減る", "is_correct": true, "explanation": "「増す」（量や程度が大きくなる）の対義語として辞書に挙がる語。危険さが小さくなる意味で対応する。"}, {"text": "広がる", "is_correct": false, "explanation": "範囲が広がる意味で、程度の増減の反対語ではない。"}, {"text": "深まる", "is_correct": false, "explanation": "程度が深くなる意味で、「増す」の反対語ではない。"}, {"text": "上がる", "is_correct": false, "explanation": "程度が高まる意味で、「増す」の対義語にはならない。"}], "correct_answer": "減る", "explanations": {"減る": "「増す」（量や程度が大きくなる）の対義語として辞書に挙がる語。危険さが小さくなる意味で対応する。", "広がる": "範囲が広がる意味で、程度の増減の反対語ではない。", "深まる": "程度が深くなる意味で、「増す」の反対語ではない。", "上がる": "程度が高まる意味で、「増す」の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38234, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが、前よりももっと大きくなることです。", "primary_collocate": null, "pronunciation": "ます", "ipa": "masɯ", "syllable_count": 2, "sentences": [{"text": "雨が降り続いて、川の水かさが増した。", "target_word": "増した", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]り続[つづ]いて、川[かわ]の水[みず]かさが増[ま]した。", "sentence_source": "generated"}, {"text": "秋になると、夜の寒さが日に日に増す。", "target_word": "増す", "complexity_tier": "T3", "furigana": "秋[あき]になると、夜[よる]の寒[さむ]さが日[ひ]に日[ひ]に増[ま]す。", "sentence_source": "generated"}, {"text": "試験が近づくにつれて、不安が増していった。", "target_word": "増して", "complexity_tier": "T3", "furigana": "試験[しけん]が近[ちか]づくにつれて、不安[ふあん]が増[ま]していった。", "sentence_source": "generated"}, {"text": "この店は味がよいので、人気が年々増している。", "target_word": "増して", "complexity_tier": "T3", "furigana": "この店[みせ]は味[あじ]がよいので、人気[にんき]が年々[ねんねん]増[ま]している。", "sentence_source": "generated"}, {"text": "台風が近づき、風の勢いが増してきた。", "target_word": "増して", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づき、風[かぜ]の勢[いきお]いが増[ま]してきた。", "sentence_source": "generated"}, {"text": "運動をしたら食欲が増して、ご飯を二杯食べた。", "target_word": "増して", "complexity_tier": "T3", "furigana": "運動[うんどう]をしたら食欲[しょくよく]が増[ま]して、ご飯[はん]を二杯[にはい]食[た]べた。", "sentence_source": "generated"}, {"text": "坂を下りるにつれて、自転車の速さが増した。", "target_word": "増した", "complexity_tier": "T3", "furigana": "坂[さか]を下[お]りるにつれて、自転車[じてんしゃ]の速[はや]さが増[ま]した。", "sentence_source": "generated"}, {"text": "薬を飲まないと、痛みが増すかもしれない。", "target_word": "増す", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]まないと、痛[いた]みが増[ま]すかもしれない。", "sentence_source": "generated"}, {"text": "冬は日が短く、夜の長さが増す。", "target_word": "増す", "complexity_tier": "T3", "furigana": "冬[ふゆ]は日[ひ]が短[みじか]く、夜[よる]の長[なが]さが増[ま]す。", "sentence_source": "generated"}, {"text": "雪が降って、道の危険さが増した。", "target_word": "増した", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]って、道[みち]の危険[きけん]さが増[ま]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "増す", "label": "辞書形"}, {"form": "増します", "label": "丁寧形"}, {"form": "増した", "label": "過去形"}, {"form": "増して", "label": "て形"}, {"form": "増さない", "label": "否定形"}, {"form": "増せば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "量や程度が前より大きくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 水かさ (Zipf 1.84)']::text[], 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38234, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "増した", "is_correct": true, "explanation": "「増す」の過去形で、降り続く雨によって水かさが大きくなったという結果を述べ、文の述語として正しい。"}, {"text": "減った", "is_correct": false, "explanation": "雨が降り続けば水かさは増えるはずなので、「減った」は文脈と逆になり合わない。"}, {"text": "増して", "is_correct": false, "explanation": "連用形で、文を終えることができず述語として使えない。"}, {"text": "増される", "is_correct": false, "explanation": "「増す」は自動詞なので受け身の「増される」は作れず、文として成り立たない。"}], "explanations": {"増した": "「増す」の過去形で、降り続く雨によって水かさが大きくなったという結果を述べ、文の述語として正しい。", "減った": "雨が降り続けば水かさは増えるはずなので、「減った」は文脈と逆になり合わない。", "増して": "連用形で、文を終えることができず述語として使えない。", "増される": "「増す」は自動詞なので受け身の「増される」は作れず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "増した"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の計算力は、ずっと先輩を増している。", "explanation": "ここは〈勝る〉（上回る・優れている）の意味。「増す」は量や程度が大きくなることで、人の優劣は表せないので合わない。"}, {"text": "品不足で野菜の値段が増した。", "explanation": "ここは〈上がる〉の意味。値段が高くなる場合は「上がる」を使い、「増す」は量や程度が大きくなることを表すので合わない。"}, {"text": "ぼんやりしていると、時間が増していった。", "explanation": "ここは〈経つ〉（時間が過ぎる）の意味。時間は量が大きくなるものではなく過ぎていくものなので、「増す」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38234, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "増した", "is_correct": true, "explanation": "「増す」の過去形で、坂を下りるにつれて速さが大きくなったことを述べ、文の述語として正しい。"}, {"text": "落ちた", "is_correct": false, "explanation": "速さが下がる意味になり、「下りるにつれて」の流れと逆で文脈に合わない。"}, {"text": "止まった", "is_correct": false, "explanation": "速さが止まる意味になり、坂を下る流れと合わない。"}, {"text": "減らした", "is_correct": false, "explanation": "他動詞の過去形で、主語が「速さ」の自動詞文に使えず、文脈とも逆になる。"}], "explanations": {"増した": "「増す」の過去形で、坂を下りるにつれて速さが大きくなったことを述べ、文の述語として正しい。", "落ちた": "速さが下がる意味になり、「下りるにつれて」の流れと逆で文脈に合わない。", "止まった": "速さが止まる意味になり、坂を下る流れと合わない。", "減らした": "他動詞の過去形で、主語が「速さ」の自動詞文に使えず、文脈とも逆になる。"}, "sentence_index": 6, "correct_answer": "増した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "締め切りが増して、仕事が残り少なくなった。", "explanation": "ここは〈迫る〉（近づく）の意味。締め切りは量や程度が増えるものではないので、「増す」は合わない。"}, {"text": "二人の関係が増して、よく話すようになった。", "explanation": "ここは〈深まる〉の意味。「増す」は量や程度の大きさを表すので、関係の親密さの変化には〈深まる〉を使う。"}, {"text": "出発の時刻が増して、もう待てなくなった。", "explanation": "ここは〈近づく〉の意味。時刻は増えるものではないので、「増す」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38234, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明け方から川の水位が増すた。", "corrected_sentence": "明け方から川の水位が増した。", "error_description": "「増す」の過去形は「増した」。「増すた」は語尾の活用を誤っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "増す", "is_correct": true, "explanation": "「日に日に」で続く現在の傾向を述べるので、辞書形で文を終える形が正しい。"}, {"text": "増せ", "is_correct": false, "explanation": "命令形で、説明文の述語として成り立たず、文の意味が通らない。"}, {"text": "増さない", "is_correct": false, "explanation": "否定形になり、寒さが増えるという内容が打ち消されて文の意味が変わる。"}, {"text": "増せば", "is_correct": false, "explanation": "仮定形で、「〜ば」の条件節が続かず文を終えられない。"}], "correct_form": "増す", "base_form": "増す", "form_label": "辞書形", "sentence_index": 1, "explanations": {"増す": "「日に日に」で続く現在の傾向を述べるので、辞書形で文を終える形が正しい。", "増せ": "命令形で、説明文の述語として成り立たず、文の意味が通らない。", "増さない": "否定形になり、寒さが増えるという内容が打ち消されて文の意味が変わる。", "増せば": "仮定形で、「〜ば」の条件節が続かず文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38234, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交通事故の件数が増しるだろう。", "corrected_sentence": "交通事故の件数が増すだろう。", "error_description": "「増す」の辞書形は「増す」で、「増しる」は存在しない。語尾に余計な「る」が付いている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "増す", "is_correct": true, "explanation": "「かもしれない」の前に置く辞書形で、可能性を述べる文として正しい。"}, {"text": "増して", "is_correct": false, "explanation": "連用形で、文を終えられず述語にならない。"}, {"text": "増し", "is_correct": false, "explanation": "連用形の語幹で、単独では述語として使えない。"}, {"text": "増させる", "is_correct": false, "explanation": "使役形になり、「痛み」が増やす側の意味になるため文の主語と合わない。"}], "correct_form": "増す", "base_form": "増す", "form_label": "辞書形", "sentence_index": 7, "explanations": {"増す": "「かもしれない」の前に置く辞書形で、可能性を述べる文として正しい。", "増して": "連用形で、文を終えられず述語にならない。", "増し": "連用形の語幹で、単独では述語として使えない。", "増させる": "使役形になり、「痛み」が増やす側の意味になるため文の主語と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38236, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "〈集積で〉の〈で〉は原因・手段を表し、長い年月が積み重なって地層ができた、という文に合う。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は動作の対象を示すが、この文は〈〜で地層ができた〉の形で原因を示すので合わない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞をつなぐだけで、この位置では〈この地層ができた〉の述語に続かない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列を示すが、〈集積と、この地層ができた〉では文がつながらない。"}], "correct_answer": "で", "explanations": {"で": "〈集積で〉の〈で〉は原因・手段を表し、長い年月が積み重なって地層ができた、という文に合う。", "を": "〈を〉は動作の対象を示すが、この文は〈〜で地層ができた〉の形で原因を示すので合わない。", "の": "〈の〉は名詞をつなぐだけで、この位置では〈この地層ができた〉の述語に続かない。", "と": "〈と〉は並列を示すが、〈集積と、この地層ができた〉では文がつながらない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
