INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38236, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "小さなものがたくさん集まって、一つの大きなものになること。", "primary_collocate": null, "pronunciation": "しゅうせき", "ipa": "ɕɯːseki", "syllable_count": 4, "sentences": [{"text": "小さな努力の集積が、大きな成果になった。", "target_word": "集積", "complexity_tier": "T3", "furigana": "小[ちい]さな努力[どりょく]の集積[しゅうせき]が、大[おお]きな成果[せいか]になった。", "sentence_source": "generated"}, {"text": "長い年月の集積で、この地層ができた。", "target_word": "集積", "complexity_tier": "T3", "furigana": "長[なが]い年月[ねんげつ]の集積[しゅうせき]で、この地層[ちそう]ができた。", "sentence_source": "generated"}, {"text": "毎日の経験の集積が、彼の自信になっている。", "target_word": "集積", "complexity_tier": "T3", "furigana": "毎日[まいにち]の経験[けいけん]の集積[しゅうせき]が、彼[かれ]の自信[じしん]になっている。", "sentence_source": "generated"}, {"text": "小さな部品の集積でできた機械は、とても複雑だ。", "target_word": "集積", "complexity_tier": "T3", "furigana": "小[ちい]さな部品[ぶひん]の集積[しゅうせき]でできた機械[きかい]は、とても複雑[ふくざつ]だ。", "sentence_source": "generated"}, {"text": "町の文化は、人々の知恵の集積だと言える。", "target_word": "集積", "complexity_tier": "T3", "furigana": "町[まち]の文化[ぶんか]は、人々[ひとびと]の知恵[ちえ]の集積[しゅうせき]だと言[い]える。", "sentence_source": "generated"}, {"text": "毎月の小さな入金が集積して、旅行の資金になった。", "target_word": "集積", "complexity_tier": "T3", "furigana": "毎月[まいげつ]の小[ちい]さな入金[にゅうきん]が集積[しゅうせき]して、旅行[りょこう]の資金[しきん]になった。", "sentence_source": "generated"}, {"text": "この辞書は、多くの学者の研究の集積だ。", "target_word": "集積", "complexity_tier": "T3", "furigana": "この辞書[じしょ]は、多[おお]くの学者[がくしゃ]の研究[けんきゅう]の集積[しゅうせき]だ。", "sentence_source": "generated"}, {"text": "毎年降る雪の集積によって、山の上に氷河ができた。", "target_word": "集積", "complexity_tier": "T3", "furigana": "毎年[まいとし]降[ふ]る雪[ゆき]の集積[しゅうせき]によって、山[やま]の上[うえ]に氷河[ひょうが]ができた。", "sentence_source": "generated"}, {"text": "一つ一つは小さい力でも、集積すれば大きな力になる。", "target_word": "集積", "complexity_tier": "T3", "furigana": "一[ひと]つ一[ひと]つは小[ちい]さい力[ちから]でも、集積[しゅうせき]すれば大[おお]きな力[ちから]になる。", "sentence_source": "generated"}, {"text": "長い歴史の集積が、この伝統を作り上げた。", "target_word": "集積", "complexity_tier": "T3", "furigana": "長[なが]い歴史[れきし]の集積[しゅうせき]が、この伝統[でんとう]を作[つく]り上[あ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集積する", "label": "辞書形"}, {"form": "集積して", "label": "て形"}, {"form": "集積した", "label": "た形"}, {"form": "集積すれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "小さなものが積み重なって大きなものになること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38236, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集積", "is_correct": true, "explanation": "「小さな努力が積み重なって大きな成果になる」の意味に合う。"}, {"text": "遠慮", "is_correct": false, "explanation": "遠慮は控えめにふるまうことで、努力が成果になる文の主語として合わない。"}, {"text": "解散", "is_correct": false, "explanation": "解散は集まりを解くことで、努力の積み重ねを表す文には入らない。"}, {"text": "謝罪", "is_correct": false, "explanation": "謝罪は詫びることで、努力が成果になったという文の主語として合わない。"}], "explanations": {"集積": "「小さな努力が積み重なって大きな成果になる」の意味に合う。", "遠慮": "遠慮は控えめにふるまうことで、努力が成果になる文の主語として合わない。", "解散": "解散は集まりを解くことで、努力の積み重ねを表す文には入らない。", "謝罪": "謝罪は詫びることで、努力が成果になったという文の主語として合わない。"}, "sentence_index": 0, "correct_answer": "集積"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は試験の前に、勉強に集積した。", "explanation": "ここは〈集中〉の意味。〈集積〉は小さなものが積み重なることで、注意を一点に向ける意味では使わない。"}, {"text": "大きな岩を一つ集積して、小さな石に変えた。", "explanation": "ここは〈分割〉の意味。〈集積〉は小さなものが寄り集まって大きくなることで、大きなものを小さく分ける意味では使わない。"}, {"text": "彼は一瞬で大きな成果を集積した。", "explanation": "ここは〈達成〉の意味。〈集積〉は少しずつ積み重なることなので、一瞬で成し遂げる〈達成〉とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38236, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集積", "is_correct": true, "explanation": "多くの学者の研究が積み重なって一つになった、という意味に合う。"}, {"text": "休憩", "is_correct": false, "explanation": "休憩は休むことで、研究の積み重ねを表す文には入らない。"}, {"text": "告白", "is_correct": false, "explanation": "告白は打ち明けることで、この文の述語名詞として合わない。"}, {"text": "給料", "is_correct": false, "explanation": "給料は報酬のことで、研究の積み重ねという意味には合わない。"}], "explanations": {"集積": "多くの学者の研究が積み重なって一つになった、という意味に合う。", "休憩": "休憩は休むことで、研究の積み重ねを表す文には入らない。", "告白": "告白は打ち明けることで、この文の述語名詞として合わない。", "給料": "給料は報酬のことで、研究の積み重ねという意味には合わない。"}, "sentence_index": 6, "correct_answer": "集積"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は夢を集積して、ついに舞台に立った。", "explanation": "ここは〈実現〉の意味。〈集積〉は物や要素が積もることで、〈夢〉を対象にはできない。"}, {"text": "彼らは仕事を集積して、三人で分けた。", "explanation": "ここは〈分担〉の意味。〈集積〉は小さなものが寄り集まって大きくなることで、仕事を分ける意味では使わない。"}, {"text": "鳥たちが空に集積して、ねぐらへ戻った。", "explanation": "ここは〈集まる〉の意味。〈集積〉は物や情報が積もることで、生き物の群れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38236, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の練習が集積した、確かな実力になった。", "corrected_sentence": "毎日の練習が集積して、確かな実力になった。", "error_description": "誤りは〈集積した〉の形。〈集積して〉と連用形にして後ろの文につなぐ必要がある。〈集積した〉で文を切ると、〈確かな実力になった〉が続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38236, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨のしずくの集積を、やがて大きな川になった。", "corrected_sentence": "雨のしずくの集積が、やがて大きな川になった。", "error_description": "誤りは〈集積を〉の〈を〉。〈集積が〉の〈が〉が主語として正しい。〈集積を〉では〈大きな川になった〉の主語が立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38237, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "〈集積が〉の〈が〉は主語を示し、〈進んでいる〉と続いて文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "〈集積を〉は目的語になるが、〈進んでいる〉は目的語をとらないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈集積に〉は方向や対象を示すが、〈進んでいる〉と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "〈集積で〉は手段を示すが、〈進んでいる〉の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "〈集積が〉の〈が〉は主語を示し、〈進んでいる〉と続いて文が成り立つ。", "を": "〈集積を〉は目的語になるが、〈進んでいる〉は目的語をとらないので合わない。", "に": "〈集積に〉は方向や対象を示すが、〈進んでいる〉と結びつかない。", "で": "〈集積で〉は手段を示すが、〈進んでいる〉の主語にはならない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
