INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38237, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物や情報などが一か所にたくさん集まること。また、集めること。", "primary_collocate": null, "pronunciation": "しゅうせき", "ipa": "ɕɯːseki", "syllable_count": 4, "sentences": [{"text": "工場の集積が進んだこの地域は、とても豊かだ。", "target_word": "集積", "complexity_tier": "T3", "furigana": "工場[こうじょう]の集積[しゅうせき]が進[すす]んだこの地域[ちいき]は、とても豊[ゆた]かだ。", "sentence_source": "generated"}, {"text": "港には世界中の荷物の集積が進んでいる。", "target_word": "集積", "complexity_tier": "T3", "furigana": "港[みなと]には世界中[せかいじゅう]の荷物[にもつ]の集積[しゅうせき]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "大きな倉庫に、商品を集積して全国へ送る。", "target_word": "集積", "complexity_tier": "T3", "furigana": "大[おお]きな倉庫[そうこ]に、商品[しょうひん]を集積[しゅうせき]して全国[ぜんこく]へ送[おく]る。", "sentence_source": "generated"}, {"text": "図書館は、本や資料が集積されている場所でもある。", "target_word": "集積", "complexity_tier": "T3", "furigana": "図書館[としょかん]は、本[ほん]や資料[しりょう]が集積[しゅうせき]されている場所[ばしょ]でもある。", "sentence_source": "generated"}, {"text": "町内のごみを一か所に集積して、毎朝車が取りに来る。", "target_word": "集積", "complexity_tier": "T3", "furigana": "町内[ちょうない]のごみを一[いっ]か所[しょ]に集積[しゅうせき]して、毎朝[まいあさ]車[くるま]が取[と]りに来[く]る。", "sentence_source": "generated"}, {"text": "インターネット上には、情報の集積が増え続けている。", "target_word": "集積", "complexity_tier": "T3", "furigana": "インターネット上[じょう]には、情報[じょうほう]の集積[しゅうせき]が増[ふ]え続[つづ]けている。", "sentence_source": "generated"}, {"text": "駅の近くに会社の集積が進んで、ビルが増えた。", "target_word": "集積", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに会社[かいしゃ]の集積[しゅうせき]が進[すす]んで、ビルが増[ふ]えた。", "sentence_source": "generated"}, {"text": "研究所では、データを集積して、毎日分析している。", "target_word": "集積", "complexity_tier": "T3", "furigana": "研究所[けんきゅうじょ]では、データを集積[しゅうせき]して、毎日[まいにち]分析[ぶんせき]している。", "sentence_source": "generated"}, {"text": "災害に備えて、水と食料を一か所に集積しておく。", "target_word": "集積", "complexity_tier": "T3", "furigana": "災害[さいがい]に備[そな]えて、水[みず]と食料[しょくりょう]を一[いっ]か所[しょ]に集積[しゅうせき]しておく。", "sentence_source": "generated"}, {"text": "古い本の集積が、この古本屋の自慢だ。", "target_word": "集積", "complexity_tier": "T3", "furigana": "古[ふる]い本[ほん]の集積[しゅうせき]が、この古本屋[ふるほんや]の自慢[じまん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集積する", "label": "辞書形"}, {"form": "集積して", "label": "て形"}, {"form": "集積した", "label": "た形"}, {"form": "集積しておく", "label": "準備の形"}], "register": "neutral", "sense_fingerprint": "物や情報が一か所に集まる、または集めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38237, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集積", "is_correct": true, "explanation": "工場が一か所に集まって増えるという意味で、文の主語として合う。"}, {"text": "雑談", "is_correct": false, "explanation": "雑談は世間話のことで、工場が集まる文脈には合わない。"}, {"text": "感謝", "is_correct": false, "explanation": "感謝は礼を言うことで、工場が進むという文には入らない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は歩くことで、工場の進み具合を表す文には合わない。"}], "explanations": {"集積": "工場が一か所に集まって増えるという意味で、文の主語として合う。", "雑談": "雑談は世間話のことで、工場が集まる文脈には合わない。", "感謝": "感謝は礼を言うことで、工場が進むという文には入らない。", "散歩": "散歩は歩くことで、工場の進み具合を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "集積"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はライバルを集積して、一気に打ち負かした。", "explanation": "ここは〈打ち負かす〉の意味。〈集積〉は物や情報が積もることで、相手を負かす意味では使わない。"}, {"text": "部屋の本を、あちこちに集積した。", "explanation": "ここは〈分散〉の意味。〈集積〉は一か所に集めることで、物を散らして置く〈分散〉の意味では使わない。"}, {"text": "彼女はみんなの注目を集積した。", "explanation": "ここは〈関心を引く〉の意味。〈集積〉は物や情報が積もることで、人の関心を引く意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38237, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集積", "is_correct": true, "explanation": "会社が一か所に集まって増えるという意味で、文の主語として合う。"}, {"text": "冗談", "is_correct": false, "explanation": "冗談は軽い戯れ言で、会社が集まる文脈には合わない。"}, {"text": "失恋", "is_correct": false, "explanation": "失恋は恋が終わることで、会社の集まりを表す文には入らない。"}, {"text": "寝不足", "is_correct": false, "explanation": "寝不足は睡眠が足りないことで、会社が増える話には合わない。"}], "explanations": {"集積": "会社が一か所に集まって増えるという意味で、文の主語として合う。", "冗談": "冗談は軽い戯れ言で、会社が集まる文脈には合わない。", "失恋": "失恋は恋が終わることで、会社の集まりを表す文には入らない。", "寝不足": "寝不足は睡眠が足りないことで、会社が増える話には合わない。"}, "sentence_index": 6, "correct_answer": "集積"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は相手の攻撃を集積して、一気に受け止めた。", "explanation": "ここは〈受け止める〉の意味。〈集積〉は物や情報が積もることで、攻撃を受け止める意味では使わない。"}, {"text": "彼は本当の気持ちを集積して、誰にも言わなかった。", "explanation": "ここは〈隠す〉の意味。〈集積〉は物や要素が積もることで、本心を人から隠す意味では使わない。"}, {"text": "彼は約束を集積して、守らなかった。", "explanation": "ここは〈履行〉の意味。〈集積〉は物や要素が積もることで、約束を果たす〈履行〉の意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38237, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港の荷物を一か所に集積する、船で運ぶ。", "corrected_sentence": "港の荷物を一か所に集積して、船で運ぶ。", "error_description": "誤りは〈集積する〉の形。連用形の〈集積して〉が正しく、終止形では後ろの〈船で運ぶ〉と文がつながらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38237, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "使わない雑誌の集積に、場所を取っている。", "corrected_sentence": "使わない雑誌の集積が、場所を取っている。", "error_description": "誤りは〈集積に〉の〈に〉。〈集積が〉の〈が〉が主語として正しい。〈集積に〉では〈場所を取っている〉の主語が立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38238, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈空き地になった〉の〈に〉は、変化の先を示して文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "〈空き地を〉は目的語になり、〈なった〉の変化の意味に合わない。"}, {"text": "の", "is_correct": false, "explanation": "〈空き地の〉は連体修飾だが、〈なった〉に続く形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "〈空き地へ〉は方向を示すが、〈なった〉と結びつかない。"}], "correct_answer": "に", "explanations": {"に": "〈空き地になった〉の〈に〉は、変化の先を示して文が成り立つ。", "を": "〈空き地を〉は目的語になり、〈なった〉の変化の意味に合わない。", "の": "〈空き地の〉は連体修飾だが、〈なった〉に続く形にならない。", "へ": "〈空き地へ〉は方向を示すが、〈なった〉と結びつかない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38238, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈空き地に〉の〈に〉は、車を止める場所を示して〈止めて〉に続く。"}, {"text": "が", "is_correct": false, "explanation": "〈空き地が〉は主語になるが、〈車を止めて〉と続かない。"}, {"text": "と", "is_correct": false, "explanation": "〈空き地と〉は並列になり、〈車を止めて〉の場所を示さない。"}, {"text": "より", "is_correct": false, "explanation": "〈空き地より〉は比較を示し、場所を表さないので文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "〈空き地に〉の〈に〉は、車を止める場所を示して〈止めて〉に続く。", "が": "〈空き地が〉は主語になるが、〈車を止めて〉と続かない。", "と": "〈空き地と〉は並列になり、〈車を止めて〉の場所を示さない。", "より": "〈空き地より〉は比較を示し、場所を表さないので文が成り立たない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38238, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物がなくて、何も使われていない土地のこと。", "primary_collocate": null, "pronunciation": "あきち", "ipa": "akitɕi", "syllable_count": 3, "sentences": [{"text": "家の隣の空き地で、子どもたちが野球をしている。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "家[いえ]の隣[となり]の空[あ]き地[ち]で、子[こ]どもたちが野球[やきゅう]をしている。", "sentence_source": "generated"}, {"text": "古い家をこわしたあとは、ただの空き地になった。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]をこわしたあとは、ただの空[あ]き地[ち]になった。", "sentence_source": "generated"}, {"text": "空き地には草が高く生えていた。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]には草[くさ]が高[たか]く生[は]えていた。", "sentence_source": "generated"}, {"text": "駅の近くの空き地に、新しいマンションが建つそうだ。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くの空[あ]き地[ち]に、新[あたら]しいマンションが建[た]つそうだ。", "sentence_source": "generated"}, {"text": "空き地に猫が集まって、昼寝をしていた。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]に猫[ねこ]が集[あつ]まって、昼寝[ひるね]をしていた。", "sentence_source": "generated"}, {"text": "町には、まだ何も建っていない空き地が多い。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "町[まち]には、まだ何[なに]も建[た]っていない空[あ]き地[ち]が多[おお]い。", "sentence_source": "generated"}, {"text": "公園がないので、近所の空き地でボール遊びをする。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "公園[こうえん]がないので、近所[きんじょ]の空[あ]き地[ち]でボール遊[あそ]びをする。", "sentence_source": "generated"}, {"text": "空き地に車を止めて、友だちを待った。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]に車[くるま]を止[と]めて、友[とも]だちを待[ま]った。", "sentence_source": "generated"}, {"text": "雨がふったあと、空き地に大きな水たまりができた。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "雨[あめ]がふったあと、空[あ]き地[ち]に大[おお]きな水[みず]たまりができた。", "sentence_source": "generated"}, {"text": "昔ここにあった店は、今は空き地になっている。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "昔[むかし]ここにあった店[みせ]は、今[いま]は空[あ]き地[ち]になっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空き地", "label": "基本形"}, {"form": "空地", "label": "送り仮名を省いた形"}], "register": "neutral", "sense_fingerprint": "建物がなく何にも使われていない土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38238, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空き地", "is_correct": true, "explanation": "建物がなく、子どもが遊ぶ場所として合う。"}, {"text": "返事", "is_correct": false, "explanation": "返事は応答のことで、野球をする場所を表す文には入らない。"}, {"text": "心配", "is_correct": false, "explanation": "心配は気がかりのことで、遊ぶ場所を表す文には合わない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車券で、野球をする場所にはならない。"}], "explanations": {"空き地": "建物がなく、子どもが遊ぶ場所として合う。", "返事": "返事は応答のことで、野球をする場所を表す文には入らない。", "心配": "心配は気がかりのことで、遊ぶ場所を表す文には合わない。", "切符": "切符は乗車券で、野球をする場所にはならない。"}, "sentence_index": 0, "correct_answer": "空き地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "アパートの空き地は来月から入居できる。", "explanation": "ここは〈空室〉の意味。〈空き地〉は土地なので、入居できる部屋の空きとは合わない。"}, {"text": "午後の予定に空き地ができた。", "explanation": "ここは〈空き時間〉の意味。〈空き地〉は土地なので、予定の空いた時間を表す〈空き時間〉とは合わない。"}, {"text": "この計画には、まだ改善の空き地がある。", "explanation": "ここは〈余地〉の意味。〈空き地〉は土地そのものなので、抽象的な余裕には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38238, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空き地", "is_correct": true, "explanation": "建物がない土地で、ボール遊びをする場所として合う。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は寝ている間の言葉で、遊ぶ場所を表す文には合わない。"}, {"text": "割引", "is_correct": false, "explanation": "割引は値段を下げることで、場所を表す文には入らない。"}, {"text": "挨拶", "is_correct": false, "explanation": "挨拶はあいさつの言葉で、遊び場所を表す文には合わない。"}], "explanations": {"空き地": "建物がない土地で、ボール遊びをする場所として合う。", "寝言": "寝言は寝ている間の言葉で、遊ぶ場所を表す文には合わない。", "割引": "割引は値段を下げることで、場所を表す文には入らない。", "挨拶": "挨拶はあいさつの言葉で、遊び場所を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "空き地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ノートの空き地に答えを書いた。", "explanation": "ここは〈空白〉の意味。〈空き地〉は土地なので、紙の余白には使わない。"}, {"text": "電車の空き地に座った。", "explanation": "ここは〈空席〉の意味。〈空き地〉は土地なので、座席の空きには使わない。"}, {"text": "このアパートの空き地は、三部屋とも埋まった。", "explanation": "ここは〈空き部屋〉の意味。〈空き地〉は土地なので、部屋が埋まるという話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38238, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町はずれの空き地を、ごみが捨てられている。", "corrected_sentence": "町はずれの空き地に、ごみが捨てられている。", "error_description": "誤りは〈空き地を〉の〈を〉。〈空き地に〉の〈に〉が正しい。〈ごみが捨てられている〉の場所を示すには場所の〈に〉が必要で、〈を〉では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38238, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空き地を車が止まっていて、通りにくい。", "corrected_sentence": "空き地に車が止まっていて、通りにくい。", "error_description": "誤りは〈空き地を〉の〈を〉。〈空き地に〉の〈に〉が正しい。〈空き地を〉では〈車が止まっている〉の場所として文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38239, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "〈空き地のまま〉の〈の〉は状態を表す形で、〈まま〉に続いて文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "〈空き地をまま〉は目的語にならず、〈まま〉と続かない。"}, {"text": "が", "is_correct": false, "explanation": "〈空き地がまま〉は主語になるが、〈まま〉と結びつかない。"}, {"text": "に", "is_correct": false, "explanation": "〈空き地にまま〉は場所を示す形にならず、〈まま〉とつながらない。"}], "correct_answer": "の", "explanations": {"の": "〈空き地のまま〉の〈の〉は状態を表す形で、〈まま〉に続いて文が成り立つ。", "を": "〈空き地をまま〉は目的語にならず、〈まま〉と続かない。", "が": "〈空き地がまま〉は主語になるが、〈まま〉と結びつかない。", "に": "〈空き地にまま〉は場所を示す形にならず、〈まま〉とつながらない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "場所・帰着"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
