INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38239, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物が建てられておらず、活用されていない土地。", "primary_collocate": null, "pronunciation": "あきち", "ipa": "akitɕi", "syllable_count": 3, "sentences": [{"text": "市は使われていない空き地を、畑として貸し出している。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "市[し]は使[つか]われていない空[あ]き地[ち]を、畑[はたけ]として貸[か]し出[だ]している。", "sentence_source": "generated"}, {"text": "空き地のままでは税金がもったいないと、持ち主は言った。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]のままでは税金[ぜいきん]がもったいないと、持[も]ち主[ぬし]は言[い]った。", "sentence_source": "generated"}, {"text": "駅前の空き地を活用して、小さな広場を作る計画だ。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "駅前[えきまえ]の空[あ]き地[ち]を活用[かつよう]して、小[ちい]さな広場[ひろば]を作[つく]る計画[けいかく]だ。", "sentence_source": "generated"}, {"text": "空き地が増えると、町の雰囲気が暗くなる。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]が増[ふ]えると、町[まち]の雰囲気[ふんいき]が暗[くら]くなる。", "sentence_source": "generated"}, {"text": "祖父は、空き地を借りて野菜を育てている。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "祖父[そふ]は、空[あ]き地[ち]を借[か]りて野菜[やさい]を育[そだ]てている。", "sentence_source": "generated"}, {"text": "売れない空き地を、駐車場にして貸すことにした。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "売[う]れない空[あ]き地[ち]を、駐車場[ちゅうしゃじょう]にして貸[か]すことにした。", "sentence_source": "generated"}, {"text": "空き地の管理が悪く、ごみが捨てられて困っている。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]の管理[かんり]が悪[わる]く、ごみが捨[す]てられて困[こま]っている。", "sentence_source": "generated"}, {"text": "この空き地は、来月から工事が始まる予定だ。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "この空[あ]き地[ち]は、来月[らいげつ]から工事[こうじ]が始[はじ]まる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "空き地を持っているが、使い道がまだ決まらない。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "空[あ]き地[ち]を持[も]っているが、使[つか]い道[みち]がまだ決[き]まらない。", "sentence_source": "generated"}, {"text": "災害のとき、空き地は避難する場所としても役に立つ。", "target_word": "空き地", "complexity_tier": "T3", "furigana": "災害[さいがい]のとき、空[あ]き地[ち]は避難[ひなん]する場所[ばしょ]としても役[やく]に立[た]つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "空き地", "label": "基本形"}, {"form": "空地", "label": "送り仮名を省いた形"}], "register": "neutral", "sense_fingerprint": "建物がなく活用されていない土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bc004d3-f258-44c1-8a58-5f93c3344954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38239, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空き地", "is_correct": true, "explanation": "使われていない土地を畑として貸すという文に合う。"}, {"text": "返信", "is_correct": false, "explanation": "返信は返事の手紙のことで、畑として貸す対象にはならない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様のことで、貸し出す対象として合わない。"}, {"text": "罰金", "is_correct": false, "explanation": "罰金は罰として払う金のことで、貸す土地の文には合わない。"}], "explanations": {"空き地": "使われていない土地を畑として貸すという文に合う。", "返信": "返信は返事の手紙のことで、畑として貸す対象にはならない。", "天気": "天気は空模様のことで、貸し出す対象として合わない。", "罰金": "罰金は罰として払う金のことで、貸す土地の文には合わない。"}, "sentence_index": 0, "correct_answer": "空き地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "使わなくなった空き地を解体して、新しい建物を建てた。", "explanation": "ここは〈空き家〉の意味。〈空き地〉は建物がない土地なので、解体する対象にはならない。"}, {"text": "飲み終わった空き地をリサイクルに出した。", "explanation": "ここは〈空き缶〉の意味。〈空き地〉は土地で、飲み終えた容器には使わない。"}, {"text": "用紙の空き地に記入してください。", "explanation": "ここは〈空欄〉の意味。〈空き地〉は土地で、紙の余白には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38239, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空き地", "is_correct": true, "explanation": "建物がない土地の管理が悪い、という文に合う。"}, {"text": "給料", "is_correct": false, "explanation": "給料は報酬のことで、管理の対象として文の意味が通らない。"}, {"text": "食欲", "is_correct": false, "explanation": "食欲は食べたい気持ちのことで、ごみが捨てられる文には合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は芸術のことで、土地の管理を表す文には合わない。"}], "explanations": {"空き地": "建物がない土地の管理が悪い、という文に合う。", "給料": "給料は報酬のことで、管理の対象として文の意味が通らない。", "食欲": "食欲は食べたい気持ちのことで、ごみが捨てられる文には合わない。", "音楽": "音楽は芸術のことで、土地の管理を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "空き地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大事な空き地を読んで、内容を理解した。", "explanation": "ここは〈本〉の意味。〈空き地〉は土地なので、読むものではない。"}, {"text": "この会議室には、まだ空き地がある。", "explanation": "ここは〈空きスペース〉の意味。〈空き地〉は建物がない土地なので、室内の余裕には使わない。"}, {"text": "この歌の空き地が好きだ。", "explanation": "ここは〈間〉の意味。〈空き地〉は土地のことで、歌の中の空白の部分を指す〈間〉の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38239, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の空き地と、新しい公園を作る予定だ。", "corrected_sentence": "町の空き地に、新しい公園を作る予定だ。", "error_description": "誤りは〈空き地と〉の〈と〉。〈空き地に〉の〈に〉が正しい。〈空き地と〉では並列になり、〈作る予定だ〉の場所を示せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38239, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この空き地に、来年から売る予定になっている。", "corrected_sentence": "この空き地は、来年から売る予定になっている。", "error_description": "誤りは〈空き地に〉の〈に〉。〈空き地は〉の〈は〉が正しい。〈売る予定になっている〉の主題を示すには〈は〉が必要で、〈に〉では場所を表すことになり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e10ce0c2-6d03-4dd8-b21f-e7e90e31ab87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38240, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「屋上」に付いて、存在する場所を示す「に」で、「ある」の文に正しく合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語や経路を示し、存在場所を表す文には合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、「屋上が」では存在の場所として文が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、存在を表す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「屋上」に付いて、存在する場所を示す「に」で、「ある」の文に正しく合う。", "を": "「を」は目的語や経路を示し、存在場所を表す文には合わない。", "が": "「が」は主語を示し、「屋上が」では存在の場所として文が合わない。", "へ": "「へ」は方向を示し、存在を表す文には合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38240, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「屋上」に付いて、遊園地が存在する場所を示す「に」で、文が正しく成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、「屋上が」では存在の場所として文が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしを結ぶ働きで、場所を示す「に」の代わりにはならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示し、存在の場所を表せない。"}], "correct_answer": "に", "explanations": {"に": "「屋上」に付いて、遊園地が存在する場所を示す「に」で、文が正しく成り立つ。", "が": "「が」は主語を示し、「屋上が」では存在の場所として文が合わない。", "の": "「の」は名詞どうしを結ぶ働きで、場所を示す「に」の代わりにはならない。", "を": "「を」は目的語を示し、存在の場所を表せない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38240, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物のてっぺんの、平らな場所です。", "primary_collocate": null, "pronunciation": "おくじょう", "ipa": "okɯdʑoː", "syllable_count": 4, "sentences": [{"text": "昼休みに、友だちと屋上でお弁当を食べた。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "昼休[ひるやす]みに、友[とも]だちと屋上[おくじょう]でお弁当[べんとう]を食[た]べた。", "sentence_source": "generated"}, {"text": "このビルの屋上には、小さな花壇がある。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "このビルの屋上[おくじょう]には、小[ちい]さな花壇[かだん]がある。", "sentence_source": "generated"}, {"text": "屋上に上がると、町全体がよく見える。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]に上[あ]がると、町全体[まちぜんたい]がよく見[み]える。", "sentence_source": "generated"}, {"text": "雨の日は屋上が滑りやすいので、行かないでください。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は屋上[おくじょう]が滑[すべ]りやすいので、行[い]かないでください。", "sentence_source": "generated"}, {"text": "学校の屋上で、夜に星を観察した。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "学校[がっこう]の屋上[おくじょう]で、夜[よる]に星[ほし]を観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "屋上のドアは鍵がかかっていて、開かなかった。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]のドアは鍵[かぎ]がかかっていて、開[あ]かなかった。", "sentence_source": "generated"}, {"text": "洗濯物を屋上に干したら、すぐに乾いた。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]を屋上[おくじょう]に干[ほ]したら、すぐに乾[かわ]いた。", "sentence_source": "generated"}, {"text": "デパートの屋上には、子ども向けの遊園地がある。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "デパートの屋上[おくじょう]には、子[こ]ども向[む]けの遊園地[ゆうえんち]がある。", "sentence_source": "generated"}, {"text": "屋上から見える夕焼けは、とてもきれいだった。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]から見[み]える夕焼[ゆうや]けは、とてもきれいだった。", "sentence_source": "generated"}, {"text": "風が強い日は、屋上に出ると帽子が飛ばされる。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]い日[ひ]は、屋上[おくじょう]に出[で]ると帽子[ぼうし]が飛[と]ばされる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屋上", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "建物の一番上にある平らな場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38240, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋上", "is_correct": true, "explanation": "昼食をとる場所として自然で、「友だちと〜でお弁当を食べた」の文脈に合う。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食事をする場所ではないので、文として成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "食事をする場所にはならず、文の意味が通らない。"}, {"text": "鍵", "is_correct": false, "explanation": "食事をする場所にはならず、文が成り立たない。"}], "explanations": {"屋上": "昼食をとる場所として自然で、「友だちと〜でお弁当を食べた」の文脈に合う。", "冷蔵庫": "食事をする場所ではないので、文として成り立たない。", "財布": "食事をする場所にはならず、文の意味が通らない。", "鍵": "食事をする場所にはならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "屋上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家は屋上が急な斜面なので、雨が流れ落ちる。", "explanation": "ここは〈屋根〉の意味。屋上は平らで人が使える場所を指すので、傾斜した屋根の説明には合わない。"}, {"text": "屋上の車道を通って、駅へ向かった。", "explanation": "ここは〈車道〉の意味。車が通る道路は屋上にはなく、屋上は建物のてっぺんの平らな場所を指すので合わない。"}, {"text": "屋上が低いので、頭をぶつけた。", "explanation": "ここは〈天井〉の意味。屋上は高い場所を指すので、低いものとして使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38240, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋上", "is_correct": true, "explanation": "洗濯物を干す場所として自然で、「洗濯物を〜に干した」の文が成り立つ。"}, {"text": "手紙", "is_correct": false, "explanation": "洗濯物を干す場所にはならず、文が成立しない。"}, {"text": "植木鉢", "is_correct": false, "explanation": "洗濯物を干す場所にはならず、文の意味が通らない。"}, {"text": "箱", "is_correct": false, "explanation": "洗濯物を干す場所にはならず、文が成り立たない。"}], "explanations": {"屋上": "洗濯物を干す場所として自然で、「洗濯物を〜に干した」の文が成り立つ。", "手紙": "洗濯物を干す場所にはならず、文が成立しない。", "植木鉢": "洗濯物を干す場所にはならず、文の意味が通らない。", "箱": "洗濯物を干す場所にはならず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "屋上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山の屋上まで登って、景色を見た。", "explanation": "ここは〈頂上〉の意味。山の一番上は頂上で、屋上は建物のてっぺんの平らな場所を指すので合わない。"}, {"text": "屋上で靴を脱いで、家に上がった。", "explanation": "ここは〈玄関〉の意味。家に上がる前に靴を脱ぐ場所は玄関で、屋上は屋外の平らな場所なので合わない。"}, {"text": "屋上の押し入れに布団をしまった。", "explanation": "ここは〈押し入れ〉の意味。押し入れは建物の中の収納で、屋上は屋外の平らな場所なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38240, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展望台へ行くため、ビルの屋上で上がった。", "corrected_sentence": "展望台へ行くため、ビルの屋上に上がった。", "error_description": "「上がる」の移動先は「に」で示す。「で」は動作の場所を示すので、「屋上で上がった」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38240, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の夜、屋上に出りると、涼しい風が気持ちいい。", "corrected_sentence": "夏の夜、屋上に出ると、涼しい風が気持ちいい。", "error_description": "「出る」の活用は「出ると」。「出りる」は存在しない形で、活用を誤っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38241, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「屋上が」の形で、「広く」の主語を示す「が」で、文の意味が通る。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示し、「広く」の主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する働きで、「広く」の主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示し、主語の役割は果たせない。"}], "correct_answer": "が", "explanations": {"が": "「屋上が」の形で、「広く」の主語を示す「が」で、文の意味が通る。", "を": "「を」は目的語を示し、「広く」の主語にはならない。", "の": "「の」は名詞を修飾する働きで、「広く」の主語を示せない。", "で": "「で」は場所や手段を示し、主語の役割は果たせない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38241, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「屋上」に付いて、水がたまる場所を示す「に」で、文が正しく成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、「屋上が水がたまる」の形では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、水がたまる場所を表す文には使わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、場所を表せない。"}], "correct_answer": "に", "explanations": {"に": "「屋上」に付いて、水がたまる場所を示す「に」で、文が正しく成り立つ。", "が": "「が」は主語を示し、「屋上が水がたまる」の形では文が成り立たない。", "へ": "「へ」は方向を示し、水がたまる場所を表す文には使わない。", "と": "「と」は並列や引用を示し、場所を表せない。"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38241, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の屋根の上。特に、平らで利用できる部分を指すことが多い。", "primary_collocate": null, "pronunciation": "おくじょう", "ipa": "okɯdʑoː", "syllable_count": 4, "sentences": [{"text": "会社の屋上を開放して、社員が休める場所にした。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の屋上[おくじょう]を開放[かいほう]して、社員[しゃいん]が休[やす]める場所[ばしょ]にした。", "sentence_source": "generated"}, {"text": "このマンションは屋上が広く、住人がバーベキューに使える。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "このマンションは屋上[おくじょう]が広[ひろ]く、住人[じゅうにん]がバーベキューに使[つか]える。", "sentence_source": "generated"}, {"text": "屋上に太陽光パネルを付けて、電気を作っている。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]に太陽光[たいようこう]パネルを付[つ]けて、電気[でんき]を作[つく]っている。", "sentence_source": "generated"}, {"text": "屋上で野菜を育てる学校が増えている。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]で野菜[やさい]を育[そだ]てる学校[がっこう]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "屋上が利用できるので、夏はビアガーデンを開く。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]が利用[りよう]できるので、夏[なつ]はビアガーデンを開[ひら]く。", "sentence_source": "generated"}, {"text": "工事のため、今月は屋上を使うことができません。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、今月[こんげつ]は屋上[おくじょう]を使[つか]うことができません。", "sentence_source": "generated"}, {"text": "ホテルの屋上にあるプールは、夜になると明かりがつく。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "ホテルの屋上[おくじょう]にあるプールは、夜[よる]になると明[あ]かりがつく。", "sentence_source": "generated"}, {"text": "屋上に水がたまらないように、定期的に掃除をする。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]に水[みず]がたまらないように、定期的[ていきてき]に掃除[そうじ]をする。", "sentence_source": "generated"}, {"text": "この病院は屋上にヘリポートがある。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "この病院[びょういん]は屋上[おくじょう]にヘリポートがある。", "sentence_source": "generated"}, {"text": "屋上を緑にすると、夏の室内が涼しくなる。", "target_word": "屋上", "complexity_tier": "T3", "furigana": "屋上[おくじょう]を緑[みどり]にすると、夏[なつ]の室内[しつない]が涼[すず]しくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "屋上", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "人が利用できる建物の屋根の上の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38241, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "屋上", "is_correct": true, "explanation": "建物の屋根の上を休める場所として開放する文脈に合い、「〜を開放して」の対象になる。"}, {"text": "名簿", "is_correct": false, "explanation": "開放の対象にならず、施設を指さないので文が合わない。"}, {"text": "鍵", "is_correct": false, "explanation": "開放の対象にならず、文の意味が通らない。"}, {"text": "書類", "is_correct": false, "explanation": "開放の対象にならず、休める場所の話として成り立たない。"}], "explanations": {"屋上": "建物の屋根の上を休める場所として開放する文脈に合い、「〜を開放して」の対象になる。", "名簿": "開放の対象にならず、施設を指さないので文が合わない。", "鍵": "開放の対象にならず、文の意味が通らない。", "書類": "開放の対象にならず、休める場所の話として成り立たない。"}, "sentence_index": 0, "correct_answer": "屋上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山の屋上で、昼食を食べた。", "explanation": "ここは〈頂上〉の意味。山の一番上は頂上で、屋上は建物の上の平らな部分を指すので合わない。"}, {"text": "屋上の車道を通って、駅へ向かった。", "explanation": "ここは〈車道〉の意味。車が通る道路は屋上にはなく、屋上は建物の上の平らな部分なので合わない。"}, {"text": "屋上の床の間に、花を飾った。", "explanation": "ここは〈床の間〉の意味。床の間は和室に設ける飾りの場所で、屋上は屋外の平らな部分なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38241, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屋上", "is_correct": true, "explanation": "ホテルの建物の上にあるプールとして自然で、文が成り立つ。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "プールの場所にはならず、文が成り立たない。"}, {"text": "財布", "is_correct": false, "explanation": "プールの場所にはならず、文の意味が通らない。"}, {"text": "手紙", "is_correct": false, "explanation": "プールの場所にはならず、文が成立しない。"}], "explanations": {"屋上": "ホテルの建物の上にあるプールとして自然で、文が成り立つ。", "冷蔵庫": "プールの場所にはならず、文が成り立たない。", "財布": "プールの場所にはならず、文の意味が通らない。", "手紙": "プールの場所にはならず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "屋上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋上の地下に、ワインを貯蔵した。", "explanation": "ここは〈地下室〉の意味。ワインを貯蔵する地下室は建物の下にあるもので、屋上は建物の一番上の平らな部分なので合わない。"}, {"text": "屋上の玄関で、靴を脱いだ。", "explanation": "ここは〈玄関〉の意味。靴を脱ぐ場所は建物の出入口の玄関で、屋上は出入口ではなく平らな部分なので合わない。"}, {"text": "屋上の本棚に、本を並べた。", "explanation": "ここは〈本棚〉の意味。本棚は室内で本を並べる家具で、屋上は屋外の平らな場所なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38241, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の夜、屋上に上がりて、星を眺めた。", "corrected_sentence": "夏の夜、屋上に上がって、星を眺めた。", "error_description": "「上がる」の連用形は「上がって」。「上がりて」は活用を誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38241, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の夜、屋上を寝転がって、星を眺めた。", "corrected_sentence": "夏の夜、屋上で寝転がって、星を眺めた。", "error_description": "「寝転がる」は場所を「で」で示す。「を」は移動の対象を示すので、「屋上を寝転がって」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38242, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「壁面は」の形で、古い家の壁面を主題として取り上げる「は」で、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示し、主題の役割は果たせない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示し、主題にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、主題の役割は果たせない。"}], "correct_answer": "は", "explanations": {"は": "「壁面は」の形で、古い家の壁面を主題として取り上げる「は」で、文が成り立つ。", "を": "「を」は目的語を示し、主題の役割は果たせない。", "に": "「に」は位置や相手を示し、主題にはならない。", "で": "「で」は手段や場所を示し、主題の役割は果たせない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38242, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「壁面」に付いて、落書きがついている場所を示す「に」で、文が正しく成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示し、「壁面が」では落書きの場所を表せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、場所を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞修飾の働きで、場所を示す役割を果たさない。"}], "correct_answer": "に", "explanations": {"に": "「壁面」に付いて、落書きがついている場所を示す「に」で、文が正しく成り立つ。", "が": "「が」は主語を示し、「壁面が」では落書きの場所を表せない。", "と": "「と」は並列や引用を示し、場所を表せない。", "の": "「の」は名詞修飾の働きで、場所を示す役割を果たさない。"}, "error_tags": {"が": "主語", "と": "並列・引用", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38242, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "かべのひょうめんのことです。", "primary_collocate": null, "pronunciation": "へきめん", "ipa": "çekimeɴ", "syllable_count": 4, "sentences": [{"text": "壁面に子どもたちの絵が飾ってある。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "壁面[へきめん]に子[こ]どもたちの絵[え]が飾[かざ]ってある。", "sentence_source": "generated"}, {"text": "古い家の壁面は、雨で汚れてしまった。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]の壁面[へきめん]は、雨[あめ]で汚[よご]れてしまった。", "sentence_source": "generated"}, {"text": "壁面にペンキを塗って、部屋を明るくした。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "壁面[へきめん]にペンキを塗[ぬ]って、部屋[へや]を明[あか]るくした。", "sentence_source": "generated"}, {"text": "この部屋は壁面が白いので、広く見える。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "この部屋[へや]は壁面[へきめん]が白[しろ]いので、広[ひろ]く見[み]える。", "sentence_source": "generated"}, {"text": "壁面に大きな時計がかかっている。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "壁面[へきめん]に大[おお]きな時計[とけい]がかかっている。", "sentence_source": "generated"}, {"text": "教室の壁面には、季節の飾りがはってある。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "教室[きょうしつ]の壁面[へきめん]には、季節[きせつ]の飾[かざ]りがはってある。", "sentence_source": "generated"}, {"text": "壁面がでこぼこしているので、絵をかけにくい。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "壁面[へきめん]がでこぼこしているので、絵[え]をかけにくい。", "sentence_source": "generated"}, {"text": "壁面についた落書きを、みんなで消した。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "壁面[へきめん]についた落書[らくが]きを、みんなで消[け]した。", "sentence_source": "generated"}, {"text": "夏になると、壁面にツタがのびてくる。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "夏[なつ]になると、壁面[へきめん]にツタがのびてくる。", "sentence_source": "generated"}, {"text": "地震のあと、壁面に細いひびが見つかった。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "地震[じしん]のあと、壁面[へきめん]に細[ほそ]いひびが見[み]つかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "壁面", "label": "辞書形"}], "register": "neutral", "sense_fingerprint": "部屋などのかべの表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38242, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "壁面", "is_correct": true, "explanation": "絵を飾る場所として自然で、「〜に子どもたちの絵が飾ってある」の文が成り立つ。"}, {"text": "名簿", "is_correct": false, "explanation": "絵を飾る場所にならず、文の意味が通らない。"}, {"text": "切符", "is_correct": false, "explanation": "絵を飾る場所にはならず、文が成立しない。"}, {"text": "名札", "is_correct": false, "explanation": "絵を飾る場所として使えず、文の意味が通らない。"}], "explanations": {"壁面": "絵を飾る場所として自然で、「〜に子どもたちの絵が飾ってある」の文が成り立つ。", "名簿": "絵を飾る場所にならず、文の意味が通らない。", "切符": "絵を飾る場所にはならず、文が成立しない。", "名札": "絵を飾る場所として使えず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "壁面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁面に寝転がって、昼寝をした。", "explanation": "ここは〈床〉の意味。寝転がるのは床の上で、壁面は立った面なので合わない。"}, {"text": "壁面を閉めて、日差しを防いだ。", "explanation": "ここは〈カーテン〉の意味。カーテンは窓を覆って日差しを防ぐもので、壁面は閉めるものではないので合わない。"}, {"text": "壁面を並べて、本をたくさん置いた。", "explanation": "ここは〈本棚〉の意味。本棚は本を並べる家具で、壁面は並べて使うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38242, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壁面", "is_correct": true, "explanation": "でこぼこしている対象として自然で、絵をかけにくい理由になる。"}, {"text": "食器", "is_correct": false, "explanation": "でこぼこしていても絵をかけにくい理由にならず、文の意味が通らない。"}, {"text": "財布", "is_correct": false, "explanation": "でこぼこしている対象にならず、文が成り立たない。"}, {"text": "鍵", "is_correct": false, "explanation": "でこぼこしている対象にならず、絵をかけにくい理由として合わない。"}], "explanations": {"壁面": "でこぼこしている対象として自然で、絵をかけにくい理由になる。", "食器": "でこぼこしていても絵をかけにくい理由にならず、文の意味が通らない。", "財布": "でこぼこしている対象にならず、文が成り立たない。", "鍵": "でこぼこしている対象にならず、絵をかけにくい理由として合わない。"}, "sentence_index": 6, "correct_answer": "壁面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "壁面を回して、部屋に風を送った。", "explanation": "ここは〈扇風機〉の意味。扇風機は羽を回して風を送るもので、壁面は回すものではないので合わない。"}, {"text": "壁面を引いて、中の物を取り出した。", "explanation": "ここは〈引き出し〉の意味。引き出しは引いて中の物を出す収納で、壁面は引いて開けるものではないので合わない。"}, {"text": "壁面を一本増やして、屋根を支えた。", "explanation": "ここは〈柱〉の意味。柱は本数で数えて屋根を支える構造材で、壁面は本数で数えず支える役割もない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38242, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "廊下の壁面で、子どもの作品がはってある。", "corrected_sentence": "廊下の壁面に、子どもの作品がはってある。", "error_description": "「はってある」の場所は「に」で示す。「で」は動作の場所を示すので、「壁面で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38242, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風の後、壁面がはがしてしまった。", "corrected_sentence": "台風の後、壁面がはがれてしまった。", "error_description": "「壁面がはがれる」は自動詞。「はがしてしまった」は他動詞で、主語の「壁面」と合わないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38243, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「掃除する」の目的語を示す「を」で、「壁面を掃除している」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」を置くと「壁面が、作業員が」と主語が二つ並び、壁面が掃除の目的語にならず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「掃除する」は「に」を目的語に取らないので、「壁面に掃除している」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は掃除の対象を表せないので、「壁面へ掃除している」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「掃除する」の目的語を示す「を」で、「壁面を掃除している」の形になる。", "が": "主語を示す「が」を置くと「壁面が、作業員が」と主語が二つ並び、壁面が掃除の目的語にならず不自然。", "に": "「掃除する」は「に」を目的語に取らないので、「壁面に掃除している」は成り立たない。", "へ": "方向を示す「へ」は掃除の対象を表せないので、「壁面へ掃除している」は成り立たない。"}, "error_tags": {"が": "主語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38243, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「壁面は、レンガでできている」の主題を示す「は」。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」を置くと「壁面を、レンガでできている」となり、文の形が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「壁面より、レンガでできている」の形で文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」の後には名詞が続く必要があり、「壁面の、レンガでできている」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「壁面は、レンガでできている」の主題を示す「は」。", "を": "目的語の「を」を置くと「壁面を、レンガでできている」となり、文の形が成り立たない。", "より": "比較の「より」は「壁面より、レンガでできている」の形で文として成り立たない。", "の": "「の」の後には名詞が続く必要があり、「壁面の、レンガでできている」は成り立たない。"}, "error_tags": {"を": "対象", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38243, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物などの壁の表面。", "primary_collocate": null, "pronunciation": "へきめん", "ipa": "çekimeɴ", "syllable_count": 4, "sentences": [{"text": "あのビルの壁面は、全部ガラスでできている。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "あのビルの壁面[へきめん]は、全部[ぜんぶ]ガラスでできている。", "sentence_source": "generated"}, {"text": "高層ビルの壁面を、作業員が掃除している。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "高層[こうそう]ビルの壁面[へきめん]を、作業員[さぎょういん]が掃除[そうじ]している。", "sentence_source": "generated"}, {"text": "駅前のビルの壁面に、大きな広告が出ている。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "駅前[えきまえ]のビルの壁面[へきめん]に、大[おお]きな広告[こうこく]が出[で]ている。", "sentence_source": "generated"}, {"text": "外壁の工事で、建物の壁面に足場が組まれた。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "外壁[がいへき]の工事[こうじ]で、建物[たてもの]の壁面[へきめん]に足場[あしば]が組[く]まれた。", "sentence_source": "generated"}, {"text": "この美術館は壁面が曲線で、とても目立つ。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "この美術館[びじゅつかん]は壁面[へきめん]が曲線[きょくせん]で、とても目立[めだ]つ。", "sentence_source": "generated"}, {"text": "夜になると、壁面に映像がうつし出される。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "夜[よる]になると、壁面[へきめん]に映像[えいぞう]がうつし出[だ]される。", "sentence_source": "generated"}, {"text": "壁面に太陽の光が当たって、まぶしいほど光っている。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "壁面[へきめん]に太陽[たいよう]の光[ひかり]が当[あ]たって、まぶしいほど光[ひか]っている。", "sentence_source": "generated"}, {"text": "古い倉庫の壁面は、レンガでできている。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "古[ふる]い倉庫[そうこ]の壁面[へきめん]は、レンガでできている。", "sentence_source": "generated"}, {"text": "壁面を緑にするため、ビルの外にツタを植えた。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "壁面[へきめん]を緑[みどり]にするため、ビルの外[そと]にツタを植[う]えた。", "sentence_source": "generated"}, {"text": "高いビルの壁面は、年に一度、専門の人が洗う。", "target_word": "壁面", "complexity_tier": "T3", "furigana": "高[たか]いビルの壁面[へきめん]は、年[とし]に一度[いちど]、専門[せんもん]の人[ひと]が洗[あら]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "壁面", "label": "辞書形"}], "register": "written", "sense_fingerprint": "建物の外側などの壁の面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38243, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "壁面", "is_correct": true, "explanation": "「建物の壁の表面」を指し、ビルの壁面がガラスでできているという文に合う。"}, {"text": "歩道", "is_correct": false, "explanation": "道路脇の通路を指すため、ビルの材質を説明する文には入らない。"}, {"text": "水面", "is_correct": false, "explanation": "水の表面を指す語なので、建物の材質の説明には入らない。"}, {"text": "会議", "is_correct": false, "explanation": "人が集まる行事を指すため、建物の材質を述べる文の主語にはならない。"}], "explanations": {"壁面": "「建物の壁の表面」を指し、ビルの壁面がガラスでできているという文に合う。", "歩道": "道路脇の通路を指すため、ビルの材質を説明する文には入らない。", "水面": "水の表面を指す語なので、建物の材質の説明には入らない。", "会議": "人が集まる行事を指すため、建物の材質を述べる文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "壁面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "言葉の壁面を乗り越えるには、毎日の練習が必要だ。", "explanation": "ここは〈比喩的な障害〉の意味。壁面は建物の壁の表面を指す具体語なので、抽象的な障害には使わない。"}, {"text": "机の壁面に、コーヒーのしみがついてしまった。", "explanation": "ここは〈表面〉の意味。壁面は建物の壁にだけ使い、机の面には使わない。"}, {"text": "このパンは壁面がふわふわで、とてもおいしい。", "explanation": "ここは〈中身〉の意味。壁面は建物の壁の表面で、食べ物の中身の状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38243, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "壁面", "is_correct": true, "explanation": "「建物の壁の表面」を指し、太陽の光が当たって光るという文に合う。"}, {"text": "評判", "is_correct": false, "explanation": "人の評価を表す語で、太陽の光が当たるものにはならない。"}, {"text": "週末", "is_correct": false, "explanation": "時の区切りを表す語で、光が当たる対象にはならない。"}, {"text": "試験", "is_correct": false, "explanation": "学校の評価の場面を表す語で、光が当たる対象にはならない。"}], "explanations": {"壁面": "「建物の壁の表面」を指し、太陽の光が当たって光るという文に合う。", "評判": "人の評価を表す語で、太陽の光が当たるものにはならない。", "週末": "時の区切りを表す語で、光が当たる対象にはならない。", "試験": "学校の評価の場面を表す語で、光が当たる対象にはならない。"}, "sentence_index": 6, "correct_answer": "壁面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の日に壁面を歩くと、靴がすぐ汚れてしまう。", "explanation": "ここは〈地面〉の意味。壁面は建物の壁の表面で、人が歩く場所としては使わない。"}, {"text": "湖の壁面が、風で大きく波立った。", "explanation": "ここは〈水面〉の意味。壁面は建物の壁の表面で、波立つ水の面には使わない。"}, {"text": "パソコンの壁面に、新しいメールが表示された。", "explanation": "ここは〈画面〉の意味。壁面は建物の壁の表面で、機器の表示面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38243, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この建物の壁面を、ガラスでできている。", "corrected_sentence": "この建物の壁面は、ガラスでできている。", "error_description": "「壁面」に続く助詞が誤り。主題を示す「は」を使うべきところを、目的語の「を」にしている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38243, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山のふもとの壁面を夕日が映った。", "corrected_sentence": "山のふもとの壁面に夕日が映った。", "error_description": "「映る」は場所を「に」で示す。「を」にしたのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
