INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38244, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "その場所（地域）に合っていること。", "primary_collocate": null, "pronunciation": "ろーかる", "ipa": "ɾoːkaɾɯ", "syllable_count": 4, "sentences": [{"text": "この店は、地元の人の好みに合わせたローカルな味付けです。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "この店[みせ]は、地元[じもと]の人[ひと]の好[この]みに合[あ]わせたローカルな味付[あじつ]けです。", "sentence_source": "generated"}, {"text": "外国のサービスをそのまま使わず、ローカルな形に直しました。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "外国[がいこく]のサービスをそのまま使[つか]わず、ローカルな形[かたち]に直[なお]しました。", "sentence_source": "generated"}, {"text": "旅行では、その土地に合ったローカルな食べ物を選びたいです。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "旅行[りょこう]では、その土地[とち]に合[あ]ったローカルな食[た]べ物[もの]を選[えら]びたいです。", "sentence_source": "generated"}, {"text": "この商品は、各地の習慣に合わせてローカルに作り変えられています。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "この商品[しょうひん]は、各地[かくち]の習慣[しゅうかん]に合[あ]わせてローカルに作[つく]り変[か]えられています。", "sentence_source": "generated"}, {"text": "海外の店では、現地に合ったローカルな方法を取り入れました。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "海外[かいがい]の店[みせ]では、現地[げんち]に合[あ]ったローカルな方法[ほうほう]を取[と]り入[い]れました。", "sentence_source": "generated"}, {"text": "日本の漫画は、その国のローカルな言葉づかいに直して売られます。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "日本[にほん]の漫画[まんが]は、その国[くに]のローカルな言葉[ことば]づかいに直[なお]して売[う]られます。", "sentence_source": "generated"}, {"text": "この地域の暮らしに合ったローカルな売り方をしたので、よく売れました。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "この地域[ちいき]の暮[く]らしに合[あ]ったローカルな売[う]り方[かた]をしたので、よく売[う]れました。", "sentence_source": "generated"}, {"text": "新しい店は町の暮らしに合ったローカルなメニューを増やしました。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]は町[まち]の暮[く]らしに合[あ]ったローカルなメニューを増[ふ]やしました。", "sentence_source": "generated"}, {"text": "外国の映画は、その国の笑いに合わせてローカルに変えることがあります。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "外国[がいこく]の映画[えいが]は、その国[くに]の笑[わら]いに合[あ]わせてローカルに変[か]えることがあります。", "sentence_source": "generated"}, {"text": "先生は地域の子どもに合ったローカルな教え方を考えています。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "先生[せんせい]は地域[ちいき]の子[こ]どもに合[あ]ったローカルな教[おし]え方[かた]を考[かんが]えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ローカルだ", "label": "終止形"}, {"form": "ローカルな", "label": "連体形"}, {"form": "ローカルに", "label": "連用形（に）"}, {"form": "ローカルで", "label": "連用形（で）"}], "register": "中立（丁寧体）", "sense_fingerprint": "その土地・地域に合わせてあること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38244, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ローカル", "is_correct": true, "explanation": "「地元の人の好みに合わせた味付け」という文脈に合う形状詞。"}, {"text": "グローバル", "is_correct": false, "explanation": "世界向けという意味で、地元の好みに合わせるという文脈と逆になる。"}, {"text": "無国籍", "is_correct": false, "explanation": "どの国の色もないという意味で、特定の地元に合わせる文脈と合わない。"}, {"text": "本格的", "is_correct": false, "explanation": "本場風の味を指すので、地元の人の好みに合わせるという文脈とずれる。"}], "explanations": {"ローカル": "「地元の人の好みに合わせた味付け」という文脈に合う形状詞。", "グローバル": "世界向けという意味で、地元の好みに合わせるという文脈と逆になる。", "無国籍": "どの国の色もないという意味で、特定の地元に合わせる文脈と合わない。", "本格的": "本場風の味を指すので、地元の人の好みに合わせるという文脈とずれる。"}, "sentence_index": 0, "correct_answer": "ローカル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この特急は駅を飛ばすので、ローカルの電車に乗り換えます。", "explanation": "ここは〈各駅停車〉の意味。〈その場所に合っている〉の意味では使わないので誤り。"}, {"text": "この店は全店で同じ味を出すため、味をローカルにそろえています。", "explanation": "ここは〈画一的〉の意味との混同。ローカルは地域ごとに合わせることを表し、画一化の意味では使わないので誤り。"}, {"text": "この会社は、世界中どこでも同じ製品を売るローカルな戦略を取っています。", "explanation": "ここは〈グローバル〉の意味との混同。ローカルは地域に合わせることを表すので、どこでも同じ製品として売るという意味では使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38244, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ローカル", "is_correct": true, "explanation": "「地域の暮らしに合った売り方」という文脈に合う形状詞。"}, {"text": "世界的", "is_correct": false, "explanation": "世界規模という意味で、地域の暮らしに合わせるという文脈と逆になる。"}, {"text": "過激", "is_correct": false, "explanation": "極端なやり方を指すので、暮らしに合わせた売り方とは噛み合わない。"}, {"text": "豪華", "is_correct": false, "explanation": "派手で贅沢という意味で、暮らしに合わせた売り方とずれる。"}], "explanations": {"ローカル": "「地域の暮らしに合った売り方」という文脈に合う形状詞。", "世界的": "世界規模という意味で、地域の暮らしに合わせるという文脈と逆になる。", "過激": "極端なやり方を指すので、暮らしに合わせた売り方とは噛み合わない。", "豪華": "派手で贅沢という意味で、暮らしに合わせた売り方とずれる。"}, "sentence_index": 6, "correct_answer": "ローカル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜のローカル番組で、この店の味が紹介されていました。", "explanation": "ここは〈地方局の番組〉の意味。〈その場所に合っている〉の意味では使わないので誤り。"}, {"text": "先生は全員にローカルな教え方を考えています。", "explanation": "ここは〈一律〉の意味との混同。ローカルは地域に合うことを表し、全員に同じという意味では使わないので誤り。"}, {"text": "この教え方はローカルなので、どの国でも同じように通用します。", "explanation": "ここは〈世界標準〉の意味との混同。ローカルは地域に限ることを表すので、どの国でも通用するという文脈と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38244, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は、地元の人の好みに合わせた、ローカルだ味付けを出しています。", "corrected_sentence": "この店は、地元の人の好みに合わせた、ローカルな味付けを出しています。", "error_description": "名詞「味付け」を修飾する連体形は「ローカルな」。「ローカルだ」は終止形なので、名詞の前には置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ローカルな", "is_correct": true, "explanation": "連体形。名詞「形」を修飾する正しい形。"}, {"text": "ローカルだ", "is_correct": false, "explanation": "終止形。名詞の前に直接置けないので不可。"}, {"text": "ローカルに", "is_correct": false, "explanation": "連用形（に）。「形」を修飾できないので、名詞修飾の位置には合わない。"}, {"text": "ローカルで", "is_correct": false, "explanation": "連用形（で）。名詞「形」を修飾できないので不可。"}], "correct_form": "ローカルな", "base_form": "ローカル", "form_label": "連体形", "sentence_index": 1, "explanations": {"ローカルな": "連体形。名詞「形」を修飾する正しい形。", "ローカルだ": "終止形。名詞の前に直接置けないので不可。", "ローカルに": "連用形（に）。「形」を修飾できないので、名詞修飾の位置には合わない。", "ローカルで": "連用形（で）。名詞「形」を修飾できないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38244, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この鍋は、その地域の人の好みに合わせた、ローカルなで味付けにしてあります。", "corrected_sentence": "この鍋は、その地域の人の好みに合わせた、ローカルな味付けにしてあります。", "error_description": "名詞「味付け」を修飾するには「ローカルな」が必要。「ローカルなで」は「な」に「で」が続いた形で、どの活用にもならないので不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ローカルな", "is_correct": true, "explanation": "連体形。名詞「メニュー」を修飾する正しい形。"}, {"text": "ローカルだった", "is_correct": false, "explanation": "過去の終止形。名詞「メニュー」の前に直接置けないので不可。"}, {"text": "ローカルだろう", "is_correct": false, "explanation": "推量の形。名詞を修飾できないので不可。"}, {"text": "ローカルなら", "is_correct": false, "explanation": "仮定形。名詞「メニュー」を直接修飾できないので不可。"}], "correct_form": "ローカルな", "base_form": "ローカル", "form_label": "連体形", "sentence_index": 7, "explanations": {"ローカルな": "連体形。名詞「メニュー」を修飾する正しい形。", "ローカルだった": "過去の終止形。名詞「メニュー」の前に直接置けないので不可。", "ローカルだろう": "推量の形。名詞を修飾できないので不可。", "ローカルなら": "仮定形。名詞「メニュー」を直接修飾できないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
