INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38245, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "特定の地域に限定された、またはその地域特有の性質を持つこと。", "primary_collocate": null, "pronunciation": "ろーかる", "ipa": "ɾoːkaɾɯ", "syllable_count": 4, "sentences": [{"text": "このお祭りはローカルなもので、他の町では行われません。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "このお祭[まつ]りはローカルなもので、他[ほか]の町[まち]では行[おこな]われません。", "sentence_source": "generated"}, {"text": "地元の人だけが知っているローカルな店を教えてもらいました。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "地元[じもと]の人[ひと]だけが知[し]っているローカルな店[みせ]を教[おし]えてもらいました。", "sentence_source": "generated"}, {"text": "ローカルな話題なので、他の県の人には分かりません。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "ローカルな話題[わだい]なので、他[ほか]の県[けん]の人[ひと]には分[わ]かりません。", "sentence_source": "generated"}, {"text": "この料理は、この島だけで食べられるローカルな味です。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "この料理[りょうり]は、この島[しま]だけで食[た]べられるローカルな味[あじ]です。", "sentence_source": "generated"}, {"text": "ローカルな方言は、旅行者にはとても難しいです。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "ローカルな方言[ほうげん]は、旅行者[りょこうしゃ]にはとても難[むずか]しいです。", "sentence_source": "generated"}, {"text": "彼は地元で人気のローカルなバンドで歌っています。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "彼[かれ]は地元[じもと]で人気[にんき]のローカルなバンドで歌[うた]っています。", "sentence_source": "generated"}, {"text": "この習慣はとてもローカルで、隣の町にはありません。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "この習慣[しゅうかん]はとてもローカルで、隣[となり]の町[まち]にはありません。", "sentence_source": "generated"}, {"text": "ローカルな情報を集めて、町のガイドブックを作りました。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "ローカルな情報[じょうほう]を集[あつ]めて、町[まち]のガイドブックを作[つく]りました。", "sentence_source": "generated"}, {"text": "駅の近くにある、観光客が少ないローカルな市場へ行きました。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くにある、観光客[かんこうきゃく]が少[すく]ないローカルな市場[いちば]へ行[い]きました。", "sentence_source": "generated"}, {"text": "このルールは学校だけのローカルなものです。", "target_word": "ローカル", "complexity_tier": "T3", "furigana": "このルールは学校[がっこう]だけのローカルなものです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ローカルだ", "label": "終止形"}, {"form": "ローカルな", "label": "連体形"}, {"form": "ローカルで", "label": "連用形（で）"}, {"form": "ローカルに", "label": "連用形（に）"}], "register": "中立（丁寧体）", "sense_fingerprint": "特定の地域だけのもの、その地域特有であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38245, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ローカル", "is_correct": true, "explanation": "特定の地域に限られたという意味で、他の町では行われないという文脈と合う。"}, {"text": "全国的", "is_correct": false, "explanation": "全国規模という意味で、他の町では行われないという文脈と矛盾する。"}, {"text": "普遍的", "is_correct": false, "explanation": "どこにでもあるという意味で、他の町では行われないという文脈と矛盾する。"}, {"text": "国際的", "is_correct": false, "explanation": "世界規模という意味で、限られた町の祭りという文脈と噛み合わない。"}], "explanations": {"ローカル": "特定の地域に限られたという意味で、他の町では行われないという文脈と合う。", "全国的": "全国規模という意味で、他の町では行われないという文脈と矛盾する。", "普遍的": "どこにでもあるという意味で、他の町では行われないという文脈と矛盾する。", "国際的": "世界規模という意味で、限られた町の祭りという文脈と噛み合わない。"}, "sentence_index": 0, "correct_answer": "ローカル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ファイルは、このパソコンのローカルディスクに保存されています。", "explanation": "ここは〈パソコン内部の記憶域〉の意味。〈特定の地域に限られる〉の意味では使わないので誤り。"}, {"text": "この菓子はローカルなので、来月には販売が終わります。", "explanation": "ここは〈期間が限られる〉の意味との混同。ローカルは地域に限ることを表し、期間を表すものではないので誤り。"}, {"text": "この料理はローカルに知られ、世界中で食べられています。", "explanation": "ここは〈国際的〉の意味との混同。ローカルは地域に限られることを表すので、世界中で食べられるという文脈とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38245, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ローカル", "is_correct": true, "explanation": "特定の地域に限られるという意味で、隣の町にはないという文脈と合う。"}, {"text": "一般的", "is_correct": false, "explanation": "広く見られるという意味で、隣の町にはないという文脈と矛盾する。"}, {"text": "世界的", "is_correct": false, "explanation": "世界規模という意味で、隣の町にないという文脈と噛み合わない。"}, {"text": "代表的", "is_correct": false, "explanation": "その分野を代表するという意味で、隣の町にないという文脈と矛盾する。"}], "explanations": {"ローカル": "特定の地域に限られるという意味で、隣の町にはないという文脈と合う。", "一般的": "広く見られるという意味で、隣の町にはないという文脈と矛盾する。", "世界的": "世界規模という意味で、隣の町にないという文脈と噛み合わない。", "代表的": "その分野を代表するという意味で、隣の町にないという文脈と矛盾する。"}, "sentence_index": 6, "correct_answer": "ローカル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このルールはローカルなもので、全国の学校で守られています。", "explanation": "ここは〈どこにでも通用する〉の意味との混同。ローカルは限られた地域のものを表すので、広く守られるという文脈と矛盾する。"}, {"text": "このルールは全員にローカルなものです。", "explanation": "ここは〈一律〉の意味との混同。ローカルは地域に限られることを表し、全員に同じという意味では使わないので誤り。"}, {"text": "この麻酔はローカルなので、手術する部分だけがしびれます。", "explanation": "ここは〈体の一部に限る・局所〉の意味。〈特定の地域に限られる〉の意味では使わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38245, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この祭りは地域だけのローカルにもので、よそでは見られません。", "corrected_sentence": "この祭りは地域だけのローカルなもので、よそでは見られません。", "error_description": "名詞「もの」を修飾する形状詞は「ローカルな」。「ローカルに」は副詞形なので、「もの」を修飾できない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ローカルな", "is_correct": true, "explanation": "連体形。名詞「店」を修飾する正しい形。"}, {"text": "ローカルだ", "is_correct": false, "explanation": "終止形。名詞の前に直接置けないので不可。"}, {"text": "ローカルに", "is_correct": false, "explanation": "連用形（に）。名詞「店」を修飾できないので不可。"}, {"text": "ローカルで", "is_correct": false, "explanation": "連用形（で）。名詞「店」を修飾できないので不可。"}], "correct_form": "ローカルな", "base_form": "ローカル", "form_label": "連体形", "sentence_index": 1, "explanations": {"ローカルな": "連体形。名詞「店」を修飾する正しい形。", "ローカルだ": "終止形。名詞の前に直接置けないので不可。", "ローカルに": "連用形（に）。名詞「店」を修飾できないので不可。", "ローカルで": "連用形（で）。名詞「店」を修飾できないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38245, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域だけのローカルに祭りの衣装を、ぜひ見てください。", "corrected_sentence": "この地域だけのローカルな祭りの衣装を、ぜひ見てください。", "error_description": "名詞「祭り」を修飾するには「ローカルな」が必要。「ローカルに」は副詞形なので、名詞の前には置けない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ローカルな", "is_correct": true, "explanation": "連体形。名詞「情報」を修飾する正しい形。"}, {"text": "ローカルだ", "is_correct": false, "explanation": "終止形。名詞「情報」の前に直接置けないので不可。"}, {"text": "ローカルだろう", "is_correct": false, "explanation": "推量の形。名詞を修飾できないので不可。"}, {"text": "ローカルだが", "is_correct": false, "explanation": "接続の形。名詞「情報」の前には置けないので不可。"}], "correct_form": "ローカルな", "base_form": "ローカル", "form_label": "連体形", "sentence_index": 7, "explanations": {"ローカルな": "連体形。名詞「情報」を修飾する正しい形。", "ローカルだ": "終止形。名詞「情報」の前に直接置けないので不可。", "ローカルだろう": "推量の形。名詞を修飾できないので不可。", "ローカルだが": "接続の形。名詞「情報」の前には置けないので不可。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38246, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抑制", "is_correct": true, "explanation": "「推進」が前へ進めることであるのに対し、勢いを抑えて止めるという反対の意味になる。"}, {"text": "維持", "is_correct": false, "explanation": "現状を保つ意味で、推進の反対語にはならない。"}, {"text": "推薦", "is_correct": false, "explanation": "人や物を強く勧める意味で、推進と反対の関係にはならない。"}, {"text": "支援", "is_correct": false, "explanation": "助けて支える意味で、推進と反対の関係にはならない。"}], "correct_answer": "抑制", "explanations": {"抑制": "「推進」が前へ進めることであるのに対し、勢いを抑えて止めるという反対の意味になる。", "維持": "現状を保つ意味で、推進の反対語にはならない。", "推薦": "人や物を強く勧める意味で、推進と反対の関係にはならない。", "支援": "助けて支える意味で、推進と反対の関係にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38246, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「工事を推進する」の目的語を示す「を」で、文が成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "並列の「と」では「工事と推進する」となり、推進の目的語にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では、推進の対象を表せず文が不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では、推進の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「工事を推進する」の目的語を示す「を」で、文が成り立つ。", "と": "並列の「と」では「工事と推進する」となり、推進の目的語にならない。", "から": "起点の「から」では、推進の対象を表せず文が不自然になる。", "へ": "方向の「へ」では、推進の対象を表せない。"}, "error_tags": {"と": "並列", "から": "起点", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抑制", "is_correct": true, "explanation": "「推進」の反対で、勢いを抑えて止めるという意味になる。"}, {"text": "継続", "is_correct": false, "explanation": "続けるという意味で、推進の反対語にはならない。"}, {"text": "準備", "is_correct": false, "explanation": "事前に整えるという意味で、推進とは反対の関係にはならない。"}, {"text": "調整", "is_correct": false, "explanation": "ぶつからないよう整える意味で、推進の反対語にはならない。"}], "correct_answer": "抑制", "explanations": {"抑制": "「推進」の反対で、勢いを抑えて止めるという意味になる。", "継続": "続けるという意味で、推進の反対語にはならない。", "準備": "事前に整えるという意味で、推進とは反対の関係にはならない。", "調整": "ぶつからないよう整える意味で、推進の反対語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38246, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを前に進めること。", "primary_collocate": null, "pronunciation": "すいしん", "ipa": "sɯiɕiɴ", "syllable_count": 4, "sentences": [{"text": "市は新しい道路の建設を推進している。", "target_word": "推進", "complexity_tier": "T3", "furigana": "市[し]は新[あたら]しい道路[どうろ]の建設[けんせつ]を推進[すいしん]している。", "sentence_source": "generated"}, {"text": "会社は環境を守る活動を推進する方針だ。", "target_word": "推進", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は環境[かんきょう]を守[まも]る活動[かつどう]を推進[すいしん]する方針[ほうしん]だ。", "sentence_source": "generated"}, {"text": "計画を推進するために、新しいチームが作られた。", "target_word": "推進", "complexity_tier": "T3", "furigana": "計画[けいかく]を推進[すいしん]するために、新[あたら]しいチームが作[つく]られた。", "sentence_source": "generated"}, {"text": "政府は電気自動車の普及を推進している。", "target_word": "推進", "complexity_tier": "T3", "furigana": "政府[せいふ]は電気自動車[でんきじどうしゃ]の普及[ふきゅう]を推進[すいしん]している。", "sentence_source": "generated"}, {"text": "彼は地域の活動を推進した中心人物だ。", "target_word": "推進", "complexity_tier": "T3", "furigana": "彼[かれ]は地域[ちいき]の活動[かつどう]を推進[すいしん]した中心人物[ちゅうしんじんぶつ]だ。", "sentence_source": "generated"}, {"text": "資金が足りなくて、事業の推進が難しくなった。", "target_word": "推進", "complexity_tier": "T3", "furigana": "資金[しきん]が足[た]りなくて、事業[じぎょう]の推進[すいしん]が難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "学校では、読書の推進に力を入れている。", "target_word": "推進", "complexity_tier": "T3", "furigana": "学校[がっこう]では、読書[どくしょ]の推進[すいしん]に力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "工事を推進するには、近所の人の理解が必要だ。", "target_word": "推進", "complexity_tier": "T3", "furigana": "工事[こうじ]を推進[すいしん]するには、近所[きんじょ]の人[ひと]の理解[りかい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "市長は町の観光を推進すると約束した。", "target_word": "推進", "complexity_tier": "T3", "furigana": "市長[しちょう]は町[まち]の観光[かんこう]を推進[すいしん]すると約束[やくそく]した。", "sentence_source": "generated"}, {"text": "皆で協力して、計画を推進していきましょう。", "target_word": "推進", "complexity_tier": "T3", "furigana": "皆[みな]で協力[きょうりょく]して、計画[けいかく]を推進[すいしん]していきましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "推進", "label": "辞書形"}, {"form": "推進する", "label": "サ変動詞"}, {"form": "推進します", "label": "丁寧形"}, {"form": "推進した", "label": "過去形"}, {"form": "推進して", "label": "て形"}, {"form": "推進しない", "label": "否定形"}], "register": "formal", "sense_fingerprint": "計画や事業を前へ進めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38246, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推進", "is_correct": true, "explanation": "「建設を前へ進める」の意味で、道路建設の文に合う。"}, {"text": "道路", "is_correct": false, "explanation": "名詞の道路は「建設を」の後に動詞として続かず、「道路している」は成り立たない。"}, {"text": "雑談", "is_correct": false, "explanation": "「雑談している」は建設の対象にならず、文として成り立たない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は建設の対象ではなく、「天候している」は文の動詞として合わない。"}], "explanations": {"推進": "「建設を前へ進める」の意味で、道路建設の文に合う。", "道路": "名詞の道路は「建設を」の後に動詞として続かず、「道路している」は成り立たない。", "雑談": "「雑談している」は建設の対象にならず、文として成り立たない。", "天候": "天候は建設の対象ではなく、「天候している」は文の動詞として合わない。"}, "sentence_index": 0, "correct_answer": "推進"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターのボタンを推進して、ドアを閉めた。", "explanation": "ここは〈押す〉の意味。推進は計画などを前へ進める語で、ボタンを押す動作には使わない。"}, {"text": "証拠を見て、犯人を推進した。", "explanation": "ここは〈推理〉の意味。推進は物事を前に進めることで、犯人を言い当てる意味では使わない。"}, {"text": "彼の気持ちを推進して、答えを当てた。", "explanation": "ここは〈推測〉の意味。推進は前へ進める意味で、人の気持ちを推し量る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38246, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推進", "is_correct": true, "explanation": "「読書の推進に力を入れる」で、読書を前へ進める活動の文に合う。"}, {"text": "雨", "is_correct": false, "explanation": "「読書の雨に力を入れる」は成り立たず、文の意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「読書の天気に力を入れる」は意味が通らず、文として成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "「読書の体重」は意味が通らず、文として成り立たない。"}], "explanations": {"推進": "「読書の推進に力を入れる」で、読書を前へ進める活動の文に合う。", "雨": "「読書の雨に力を入れる」は成り立たず、文の意味が通らない。", "天気": "「読書の天気に力を入れる」は意味が通らず、文として成り立たない。", "体重": "「読書の体重」は意味が通らず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "推進"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭にいたねずみを推進して、追い払った。", "explanation": "ここは〈退去させる〉の意味。推進は物事を前へ進める語で、動物を立ち退かせる意味では使わない。"}, {"text": "机の上のごみを推進して、取り除いた。", "explanation": "ここは〈除去〉の意味。推進は物事を前へ進める語で、ごみを片付ける動作には使わない。"}, {"text": "明日の天気を推進した。", "explanation": "ここは〈予想〉の意味。推進は計画などを前へ進める語で、天気を言い当てる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38246, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は駅前の再開発に推進している。", "corrected_sentence": "市は駅前の再開発を推進している。", "error_description": "「推進する」の目的語には「を」を使う。「に」にしたのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38246, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国は再生可能エネルギーの導入を推進するだった。", "corrected_sentence": "国は再生可能エネルギーの導入を推進した。", "error_description": "「推進するだった」は誤り。過去の動作を表すなら「推進した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38247, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「計画を推進する」の目的語を示す「を」で、文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "「推進する」は「に」を目的語に取らないので、「計画に推進するために」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」の後には名詞が必要で、「計画の推進するために」は文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「計画より推進するために」となり、文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「計画を推進する」の目的語を示す「を」で、文が成り立つ。", "に": "「推進する」は「に」を目的語に取らないので、「計画に推進するために」は成り立たない。", "の": "「の」の後には名詞が必要で、「計画の推進するために」は文として成り立たない。", "より": "比較の「より」では「計画より推進するために」となり、文の意味が通らない。"}, "error_tags": {"に": "位置", "の": "連体修飾", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "抑制", "is_correct": true, "explanation": "「推進」の反対で、勢いを抑えて止めるという意味になる。"}, {"text": "維持", "is_correct": false, "explanation": "現状を保つ意味で、推進の反対語にはならない。"}, {"text": "継続", "is_correct": false, "explanation": "続けるという意味で、推進の反対語にはならない。"}, {"text": "支援", "is_correct": false, "explanation": "助けて支える意味で、推進と反対の関係にはならない。"}], "correct_answer": "抑制", "explanations": {"抑制": "「推進」の反対で、勢いを抑えて止めるという意味になる。", "維持": "現状を保つ意味で、推進の反対語にはならない。", "継続": "続けるという意味で、推進の反対語にはならない。", "支援": "助けて支える意味で、推進と反対の関係にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
