INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38247, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を前へ進めたり、促したりすること。", "primary_collocate": null, "pronunciation": "すいしん", "ipa": "sɯiɕiɴ", "syllable_count": 4, "sentences": [{"text": "市は再生可能エネルギーの利用を推進している。", "target_word": "推進", "complexity_tier": "T3", "furigana": "市[し]は再生可能[さいせいかのう]エネルギーの利用[りよう]を推進[すいしん]している。", "sentence_source": "generated"}, {"text": "会社は新しい計画を推進するために、専門の担当者を置いた。", "target_word": "推進", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は新[あたら]しい計画[けいかく]を推進[すいしん]するために、専門[せんもん]の担当者[たんとうしゃ]を置[お]いた。", "sentence_source": "generated"}, {"text": "政府が少子化対策を推進した結果、保育所の数が増えた。", "target_word": "推進", "complexity_tier": "T3", "furigana": "政府[せいふ]が少子化[しょうしか]対策[たいさく]を推進[すいしん]した結果[けっか]、保育所[ほいくしょ]の数[かず]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "反対意見が多かったので、計画の推進は一時止まった。", "target_word": "推進", "complexity_tier": "T3", "furigana": "反対[はんたい]意見[いけん]が多[おお]かったので、計画[けいかく]の推進[すいしん]は一時[いちじ]止[と]まった。", "sentence_source": "generated"}, {"text": "町は観光を推進したいが、宿泊できる場所が足りない。", "target_word": "推進", "complexity_tier": "T3", "furigana": "町[まち]は観光[かんこう]を推進[すいしん]したいが、宿泊[しゅくはく]できる場所[ばしょ]が足[た]りない。", "sentence_source": "generated"}, {"text": "学校では読書活動を推進し、毎朝十分間本を読む時間を作っている。", "target_word": "推進", "complexity_tier": "T4", "furigana": "学校[がっこう]では読書[どくしょ]活動[かつどう]を推進[すいしん]し、毎朝[まいあさ]十分間[じゅっぷんかん]本[ほん]を読[よ]む時間[じかん]を作[つく]っている。", "sentence_source": "generated"}, {"text": "彼は環境保護を推進する団体で働いている。", "target_word": "推進", "complexity_tier": "T3", "furigana": "彼[かれ]は環境[かんきょう]保護[ほご]を推進[すいしん]する団体[だんたい]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "資金が集まらず、工事を推進することができなかった。", "target_word": "推進", "complexity_tier": "T3", "furigana": "資金[しきん]が集[あつ]まらず、工事[こうじ]を推進[すいしん]することができなかった。", "sentence_source": "generated"}, {"text": "国際協力を推進するには、各国の理解が必要だ。", "target_word": "推進", "complexity_tier": "T3", "furigana": "国際[こくさい]協力[きょうりょく]を推進[すいしん]するには、各国[かっこく]の理解[りかい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "社長は海外進出を強く推進したが、社員の準備は間に合わなかった。", "target_word": "推進", "complexity_tier": "T4", "furigana": "社長[しゃちょう]は海外[かいがい]進出[しゅっしゅつ]を強[つよ]く推進[すいしん]したが、社員[しゃいん]の準備[じゅんび]は間[ま]に合[あ]わなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "推進する", "label": "辞書形"}, {"form": "推進した", "label": "過去形"}, {"form": "推進して", "label": "て形"}, {"form": "推進しない", "label": "否定形"}], "register": "neutral written (plain form)", "sense_fingerprint": "計画や政策などを前へ進めて実現させること(する動詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a411dfe7-5f42-41f9-bd10-5cac4844963d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38247, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推進", "is_correct": true, "explanation": "「利用を前へ進める」の意味で、再生可能エネルギーを広める文に合う。"}, {"text": "雑談", "is_correct": false, "explanation": "「利用を雑談している」は成り立たず、文の動詞として合わない。"}, {"text": "天候", "is_correct": false, "explanation": "天候は利用の対象にならず、「利用を天候している」は文が成り立たない。"}, {"text": "休暇", "is_correct": false, "explanation": "「利用を休暇している」は意味が通らず、文として成り立たない。"}], "explanations": {"推進": "「利用を前へ進める」の意味で、再生可能エネルギーを広める文に合う。", "雑談": "「利用を雑談している」は成り立たず、文の動詞として合わない。", "天候": "天候は利用の対象にならず、「利用を天候している」は文が成り立たない。", "休暇": "「利用を休暇している」は意味が通らず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "推進"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターの階のボタンを推進して、ドアを閉めた。", "explanation": "ここは〈押す〉の意味。推進は計画などを前へ進める語で、ボタンを押す動作には使わない。"}, {"text": "来週の勝敗を推進した。", "explanation": "ここは〈予想〉の意味。推進は計画などを前へ進める語で、勝敗を見積もる意味では使わない。"}, {"text": "床のごみを推進して、きれいにした。", "explanation": "ここは〈取り除く〉の意味。推進は物事を前へ進める語で、ごみを取り除く動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38247, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推進", "is_correct": true, "explanation": "「環境保護を推進する団体」の形で、環境保護を前へ進める団体の文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「環境保護を天気する」は成り立たず、文の動詞として合わない。"}, {"text": "写真", "is_correct": false, "explanation": "「環境保護を写真する」は意味が通らず、文として成り立たない。"}, {"text": "道路", "is_correct": false, "explanation": "「環境保護を道路する」は成り立たず、文の動詞として合わない。"}], "explanations": {"推進": "「環境保護を推進する団体」の形で、環境保護を前へ進める団体の文に合う。", "天気": "「環境保護を天気する」は成り立たず、文の動詞として合わない。", "写真": "「環境保護を写真する」は意味が通らず、文として成り立たない。", "道路": "「環境保護を道路する」は成り立たず、文の動詞として合わない。"}, "sentence_index": 6, "correct_answer": "推進"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家の周りの猫を推進して、追い払った。", "explanation": "ここは〈退去させる〉の意味。推進は物事を前へ進める語で、猫を立ち退かせる意味では使わない。"}, {"text": "証拠から犯人を推進した。", "explanation": "ここは〈推理〉の意味。推進は物事を前に進めることで、犯人を言い当てる意味では使わない。"}, {"text": "友人の年齢を推進して、当てた。", "explanation": "ここは〈推測〉の意味。推進は前へ進める意味で、人の年齢を推し量る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38247, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町は公園の整備に推進している。", "corrected_sentence": "町は公園の整備を推進している。", "error_description": "「推進する」の目的語には「を」を使う。「に」にしたのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38247, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は子育て支援を推進するだった。", "corrected_sentence": "市は子育て支援を推進した。", "error_description": "「推進するだった」は誤り。過去の動作を表すなら「推進した」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b12cc6a-cfa8-46c5-b56b-3b6e83bd4348') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
