INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38248, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格。「ロスがなく」の形で、形容詞「なく」に続く。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。「ロスへなく」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「ロスのなく」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す格。「ロスになく」は不自然。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格。「ロスがなく」の形で、形容詞「なく」に続く。", "へ": "方向を示す格。「ロスへなく」は文が成り立たない。", "の": "連体修飾の「の」。「ロスのなく」は成り立たない。", "に": "位置や相手を示す格。「ロスになく」は不自然。"}, "error_tags": {"へ": "方向を示す格で、ここでは意味が通らない", "の": "連体修飾で、主語や目的語を示さない", "に": "位置や相手を示す格で、「なく」と結びつかない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38248, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間や材料などが無駄になって失われること。また、その損失。", "primary_collocate": null, "pronunciation": "ろす", "ipa": "ɾosɯ", "syllable_count": 2, "sentences": [{"text": "残った材料は次の日に使い切り、ロスを防ぐ。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "残[のこ]った材料[ざいりょう]は次[つぎ]の日[ひ]に使[つか]い切[き]り、ロスを防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "準備が足りず、作業にロスが出た。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "準備[じゅんび]が足[た]りず、作業[さぎょう]にロスが出[で]た。", "sentence_source": "generated"}, {"text": "無駄な動きを減らして、ロスをなくそう。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "無駄[むだ]な動[うご]きを減[へ]らして、ロスをなくそう。", "sentence_source": "generated"}, {"text": "材料を切るとき、ロスが出ないように気をつける。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "材料[ざいりょう]を切[き]るとき、ロスが出[で]ないように気[き]をつける。", "sentence_source": "generated"}, {"text": "使わなくなった物を整理して、ロスをなくした。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "使[つか]わなくなった物[もの]を整理[せいり]して、ロスをなくした。", "sentence_source": "generated"}, {"text": "紙を使いすぎると、ロスが増えて、ごみも多くなる。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "紙[かみ]を使[つか]いすぎると、ロスが増[ふ]えて、ごみも多[おお]くなる。", "sentence_source": "generated"}, {"text": "使い切れない布は小物に作り直して、ロスをなくす。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "使[つか]い切[き]れない布[ぬの]は小物[こもの]に作[つく]り直[なお]して、ロスをなくす。", "sentence_source": "generated"}, {"text": "彼は動きにロスがなく、作業が早い。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "彼[かれ]は動[うご]きにロスがなく、作業[さぎょう]が早[はや]い。", "sentence_source": "generated"}, {"text": "まだ使える部品を再利用して、ロスを減らす。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "まだ使[つか]える部品[ぶひん]を再利用[さいりよう]して、ロスを減[へ]らす。", "sentence_source": "generated"}, {"text": "布を型どおりに切ると、余りのロスが少なくなる。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "布[ぬの]を型[かた]どおりに切[き]ると、余[あま]りのロスが少[すく]なくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロス", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "時間や材料などを無駄にすること、損失(一般的な用法)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 使い切り (Zipf 2.41)','sentence 9 above tier T2: contains vocabulary far above tier T2: 型どおり (Zipf 1.82)']::text[], 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38248, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ロス", "is_correct": true, "explanation": "正解。材料や時間の無駄を指し、「防ぐ」の目的語として文が成り立つ。"}, {"text": "ゆとり", "is_correct": false, "explanation": "余裕のこと。「ゆとりを防ぐ」は意味が通らず、無駄を防ぐ文脈に合わない。"}, {"text": "ユーモア", "is_correct": false, "explanation": "面白さのこと。材料の無駄を防ぐという文には入らない。"}, {"text": "ブーム", "is_correct": false, "explanation": "一時的な流行のこと。「ブームを防ぐ」は材料の文脈で意味が通らない。"}], "explanations": {"ロス": "正解。材料や時間の無駄を指し、「防ぐ」の目的語として文が成り立つ。", "ゆとり": "余裕のこと。「ゆとりを防ぐ」は意味が通らず、無駄を防ぐ文脈に合わない。", "ユーモア": "面白さのこと。材料の無駄を防ぐという文には入らない。", "ブーム": "一時的な流行のこと。「ブームを防ぐ」は材料の文脈で意味が通らない。"}, "sentence_index": 0, "correct_answer": "ロス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "残ったロスは、次の日に使い切る。", "explanation": "ここは〈残り物〉の意味。ロスは捨てられる無駄を指し、使い切る対象にはならない。"}, {"text": "この機械を使えば、手間をロスして作業が速く終わる。", "explanation": "ここは〈手間を省く〉の意味。ロスは無駄になることを指し、手間を省く働きは表さない。"}, {"text": "無駄な動きを増やして、ロスを強化しよう。", "explanation": "ここは〈強化〉の意味。ロスは減らすものであり、強める対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38248, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ロス", "is_correct": true, "explanation": "正解。無駄や損失を指し、「なくす」の目的語になる。"}, {"text": "ボリューム", "is_correct": false, "explanation": "量感や音量のこと。「ボリュームをなくす」は無駄をなくす文脈に合わない。"}, {"text": "カラー", "is_correct": false, "explanation": "色のこと。布の無駄を減らす文には入らない。"}, {"text": "ダンス", "is_correct": false, "explanation": "踊りのこと。「ダンスをなくす」は布を作り直す文脈に合わない。"}], "explanations": {"ロス": "正解。無駄や損失を指し、「なくす」の目的語になる。", "ボリューム": "量感や音量のこと。「ボリュームをなくす」は無駄をなくす文脈に合わない。", "カラー": "色のこと。布の無駄を減らす文には入らない。", "ダンス": "踊りのこと。「ダンスをなくす」は布を作り直す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "ロス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "忙しい時こそ、心にロスを持つことが大切だ。", "explanation": "〈余裕〉の意味。心の余裕には使えず、ロスは無駄や損失を指すので合わない。"}, {"text": "雨水を集めて洗車に使うと、水道のロスを節水できる。", "explanation": "〈節水〉の意味。水の使用を減らす行為はロスとは別で、ロスを節水するとは言わない。"}, {"text": "試合の終盤にロスをして、一点差で負けた。", "explanation": "ここは〈負け〉の意味。ロスは無駄や損失を指すので、試合に負けることは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38248, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議が長引いて、時間のロスを増えた。", "corrected_sentence": "会議が長引いて、時間のロスが増えた。", "error_description": "助詞の誤り。「ロスが増える」の「が」を「を」に変えている。「増える」は自動詞なので目的語の「を」は取れない。正しくは「時間のロスが増えた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38248, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "型紙に合わせて布を切れば、余りのロスが少なくなれる。", "corrected_sentence": "型紙に合わせて布を切れば、余りのロスが少なくなる。", "error_description": "活用の誤り。「少なくなる」が正しい。「少なくなれる」は可能の形で、結果を述べる文の意味に合わず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
