INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38249, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を示す格。「パンのロスを防ぐ」の形で、他動詞「防ぐ」に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語の格。「防ぐ」の目的語にはならないため不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格。「防ぐ」の目的語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。目的語を示さない。"}], "correct_answer": "を", "explanations": {"を": "目的語を示す格。「パンのロスを防ぐ」の形で、他動詞「防ぐ」に続く。", "が": "主語の格。「防ぐ」の目的語にはならないため不自然。", "へ": "方向を示す格。「防ぐ」の目的語にはならない。", "の": "連体修飾の「の」。目的語を示さない。"}, "error_tags": {"が": "主語の格で、「防ぐ」の目的語にはならない", "へ": "方向を示す格で、「防ぐ」の目的語にはならない", "の": "連体修飾で、目的語を示さない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38249, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "損失や無駄。特に、利用できるものが無駄になること。また、ビジネスや物流で、在庫や資源が使われずにすてられてしまうこと。", "primary_collocate": null, "pronunciation": "ろす", "ipa": "ɾosɯ", "syllable_count": 2, "sentences": [{"text": "売れ残りによる在庫のロスが、店の悩みだ。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "売[う]れ残[のこ]りによる在庫[ざいこ]のロスが、店[みせ]の悩[なや]みだ。", "sentence_source": "generated"}, {"text": "期限が切れた弁当を捨てて、店は大きなロスを出した。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "期限[きげん]が切[き]れた弁当[べんとう]を捨[す]てて、店[みせ]は大[おお]きなロスを出[だ]した。", "sentence_source": "generated"}, {"text": "工場では、材料のロスを減らす工夫が進んでいる。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、材料[ざいりょう]のロスを減[へ]らす工夫[くふう]が進[すす]んでいる。", "sentence_source": "generated"}, {"text": "発注数を見直して、売れ残りのロスを減らした。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "発注数[はっちゅうすう]を見直[みなお]して、売[う]れ残[のこ]りのロスを減[へ]らした。", "sentence_source": "generated"}, {"text": "輸送中に商品がいたんで、店でロスが出た。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "輸送中[ゆそうちゅう]に商品[しょうひん]がいたんで、店[みせ]でロスが出[で]た。", "sentence_source": "generated"}, {"text": "在庫の管理が甘いと、ロスが利益を減らす。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "在庫[ざいこ]の管理[かんり]が甘[あま]いと、ロスが利益[りえき]を減[へ]らす。", "sentence_source": "generated"}, {"text": "倉庫では、使われないまま捨てられる部品のロスが問題だ。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "倉庫[そうこ]では、使[つか]われないまま捨[す]てられる部品[ぶひん]のロスが問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "閉店前に値引きして、パンのロスを防ぐ。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "閉店前[へいてんまえ]に値引[ねび]きして、パンのロスを防[ふせ]ぐ。", "sentence_source": "generated"}, {"text": "この店はロスが少なく、毎月の利益が安定している。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "この店[みせ]はロスが少[すく]なく、毎月[まいつき]の利益[りえき]が安定[あんてい]している。", "sentence_source": "generated"}, {"text": "計画が正確なので、物流のロスが年々小さくなっている。", "target_word": "ロス", "complexity_tier": "T3", "furigana": "計画[けいかく]が正確[せいかく]なので、物流[ぶつりゅう]のロスが年々[ねんねん]小[ちい]さくなっている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロス", "label": "基本形"}], "register": "business", "sense_fingerprint": "在庫・材料・商品が使われず廃棄される損失(ビジネス・物流)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fb64f-2b7d-47f2-a572-4d369e136007') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38249, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ロス", "is_correct": true, "explanation": "正解。在庫の損失を指し、「在庫の〜が店の悩み」に入る。"}, {"text": "メロディー", "is_correct": false, "explanation": "旋律のこと。在庫の文脈では意味が通らない。"}, {"text": "ユーモア", "is_correct": false, "explanation": "面白さのこと。在庫の悩みという文には入らない。"}, {"text": "ロマン", "is_correct": false, "explanation": "夢や理想のこと。在庫の話題には合わない。"}], "explanations": {"ロス": "正解。在庫の損失を指し、「在庫の〜が店の悩み」に入る。", "メロディー": "旋律のこと。在庫の文脈では意味が通らない。", "ユーモア": "面白さのこと。在庫の悩みという文には入らない。", "ロマン": "夢や理想のこと。在庫の話題には合わない。"}, "sentence_index": 0, "correct_answer": "ロス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新商品をロスして、店は利益を守った。", "explanation": "ここは〈仕入れ〉の意味。ロスは無駄になった分を指し、仕入れる対象にはならない。"}, {"text": "新商品でロスを伸ばし、店は赤字から抜け出した。", "explanation": "〈売り上げ〉の意味。売り上げは伸ばすが、ロスは減らすもので伸ばすとは言えない。"}, {"text": "経費を増やしてロスを積み、利益を守った。", "explanation": "ここは〈積み立て〉の意味。ロスは無駄を指し、積み立てる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38249, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ロス", "is_correct": true, "explanation": "正解。使われずに捨てられる部品の損失を指し、「〜が問題だ」に入る。"}, {"text": "レジ", "is_correct": false, "explanation": "会計の場所のこと。部品の文脈では意味が通らない。"}, {"text": "ベンチ", "is_correct": false, "explanation": "腰掛けのこと。部品の話題には入らない。"}, {"text": "ケチャップ", "is_correct": false, "explanation": "調味料のこと。倉庫の部品の文脈には合わない。"}], "explanations": {"ロス": "正解。使われずに捨てられる部品の損失を指し、「〜が問題だ」に入る。", "レジ": "会計の場所のこと。部品の文脈では意味が通らない。", "ベンチ": "腰掛けのこと。部品の話題には入らない。", "ケチャップ": "調味料のこと。倉庫の部品の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "ロス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "倉庫の棚卸しで、部品をロスの数に合わせた。", "explanation": "ここは〈在庫の数〉の意味。ロスは無駄になった分を指すので、数を合わせる対象にはならない。"}, {"text": "ロスを保つため、商品を冷蔵して運んだ。", "explanation": "〈品質〉の意味。品質は保つものだが、ロスは保つ対象にならない。"}, {"text": "新商品でロスを上げ、店の売り場は活気づいた。", "explanation": "〈回転率〉の意味。回転率は上げるが、ロスを上げるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38249, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在庫の管理が甘いと、ロスを増えやすい。", "corrected_sentence": "在庫の管理が甘いと、ロスが増えやすい。", "error_description": "助詞の誤り。「ロスが増える」の「が」を「を」に変えている。「増える」は自動詞なので「を」は取れず、正しくは「ロスが増えやすい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38249, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場の改善で、材料のロスが年々減るている。", "corrected_sentence": "工場の改善で、材料のロスが年々減っている。", "error_description": "活用の誤り。「減っている」が正しく、「減るている」という形はない。「〜ている」の形にするには「減っている」と書く。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6864b72e-f0e7-4acd-96ac-21235c8469f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
